// --- Batch buffer: coalesces leasedialer_client_status upserts every 5s ---
const pendingClientStatusUpserts = new Map<string, { count: number; leadId: string | null }>();
async function flushClientStatusBuffer() {
  if (pendingClientStatusUpserts.size === 0) return;
  const entries = [...pendingClientStatusUpserts.entries()];
  pendingClientStatusUpserts.clear();
  try {
    await ensureLeasedialerClientStatusTable();
    // Batch all upserts into a single VALUES list to avoid per-row pool checkouts
    const vals: unknown[] = [];
    const placeholders = entries.map(([email, { count, leadId }], i) => {
      vals.push(email, count, leadId);
      const b = i * 3;
      return `($${b+1}, $${b+2}, $${b+3}, NOW())`;
    });
    void pool.query(
      `INSERT INTO leasedialer_client_status (agent_email, local_leased_lead_count, current_lead_id, updated_at)
       VALUES ${placeholders.join(',')}
       ON CONFLICT (agent_email)
       DO UPDATE SET local_leased_lead_count = EXCLUDED.local_leased_lead_count,
                     current_lead_id = EXCLUDED.current_lead_id,
                     updated_at = NOW()`,
      vals,
    ).catch((e: any) => console.warn('client status batch upsert failed:', e?.message));
  } catch (e: any) {
    console.warn('flushClientStatusBuffer error:', e?.message);
  }
}
setInterval(flushClientStatusBuffer, 5000);

