const PRODUCTION_BASE_URL = WEBHOOK_BASE_URL;

function canSendZapierWebhooksFromThisRuntime(): boolean {
  if (String(process.env.ALLOW_NON_PROD_ZAPIER_WEBHOOKS || '').toLowerCase() === 'true') {
    return true;
  }
  const envMarker = `${process.env.RAILWAY_ENVIRONMENT || ''} ${process.env.RAILWAY_ENVIRONMENT_NAME || ''} ${process.env.NODE_ENV || ''}`.toLowerCase();
  const hostMarker = `${process.env.RAILWAY_PUBLIC_DOMAIN || ''} ${process.env.RAILWAY_STATIC_URL || ''} ${process.env.RAILWAY_SERVICE_NAME || ''} ${WEBHOOK_BASE_URL || ''}`.toLowerCase();
  const hasProdEnv = envMarker.includes('production') || envMarker.includes('prod');
  const hasProdHost = hostMarker.includes('aoirail-production') || hostMarker.includes('production-baa2');
  const hasNonProdHost = hostMarker.includes('staging') || hostMarker.includes('beta') || hostMarker.includes('preview');
  return (hasProdEnv || hasProdHost) && !hasNonProdHost;
}

function extractTwilioAgentEmail(endpoint: unknown): string | null {
  const raw = String(endpoint || "").trim().toLowerCase();
  if (!raw) return null;
  if (raw.startsWith("client:")) {
    const identity = raw.slice("client:".length).trim().toLowerCase();
    return identity.includes("@") ? identity : null;
  }
  return raw.includes("@") ? raw : null;
}

// ------------------------------------------------------------
// Helper: look up MGA/RGA team from Supabase
// PRIORITY: 1. agent_profiles (what agent entered), 2. agent_hierarchy (fallback)
// ------------------------------------------------------------
async function getAgentHierarchyFromSupabase(associateId?: string | null, email?: string | null) {
  if (!supabaseAdmin) {
    return null;
  }
  try {
    const identifier = associateId || email;
    if (!identifier) {
      return null;
    }
    
    // FIRST: Try agent_profiles table (what agent entered themselves)
    if (email) {
      const { data: profileData, error: profileError } = await supabaseAdmin
        .from("agent_profiles")
        .select("email, mga_team, rga_team")
        .eq("email", email.toLowerCase())
        .maybeSingle();
      
      if (!profileError && profileData && (profileData.mga_team || profileData.rga_team)) {
        // Found in agent_profiles with MGA/RGA data
        return {
          associateId: associateId || null,
          email: profileData.email,
          mga: profileData.mga_team || null,
          rga: profileData.rga_team || null,
        };
      }
    }
    
    // FALLBACK: Try agent_hierarchy table
    const query = supabaseAdmin
      .from("agent_hierarchy")
      .select("agent_associate_id, agent_name, agent_email, mga_name, rga_name")
      .limit(1);
    const supabaseQuery = associateId
      ? query.eq("agent_associate_id", associateId)
      : query.eq("agent_email", email!.toLowerCase());
    const { data, error } = await supabaseQuery.single();
    if (error || !data) {
      return null;
    }
    return {
      associateId: data.agent_associate_id,
      email: data.agent_email,
      mga: data.mga_name,
      rga: data.rga_name,
    };
  } catch (error) {
    console.error("❌ Supabase hierarchy lookup failed:", error);
    return null;
  }
}

// ------------------------------------------------------------
// ✅ GLOBAL STANDARD: ALL user-facing string comparisons MUST be case-insensitive
// Helper: Case-insensitive email/string comparison for Supabase queries
// Use this for ALL email, team, name comparisons
// ------------------------------------------------------------
function caseInsensitiveEq(column: string, value: string | null | undefined): any {
  if (!value) return null;
  // Use ilike for case-insensitive exact match (no wildcards)
  return { column, operator: 'ilike', value: value.trim() };
}

// Helper to normalize email for comparisons (always lowercase, trimmed)
function normalizeEmail(email: string | null | undefined): string {
  if (!email) return '';
  return email.toLowerCase().trim();
}

