// Resolve associate_id from logged-in/agent email — customers table is source of truth.
// Then agent_profiles, agent_hierarchy, mga_rga_directory, producerlist.
// ------------------------------------------------------------
// Cache for resolveAssociateIdForZapier — avoids 7 sequential DB queries on every page load
const resolveAssociateIdCache = new Map<string, { value: string | number | null; ts: number }>();
const RESOLVE_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

type LeadPackJobStatus = 'queued' | 'running' | 'ready' | 'failed';
type LeadPackJob = {
  id: string;
  agentEmail: string;
  status: LeadPackJobStatus;
  progress: number;
  stage: string;
  leadCount: number;
  targetCount: number;
  createdAt: number;
  updatedAt: number;
  result?: any;
  error?: string;
};

// Leadsync assignment can exceed 10s under load; keep server timeout above observed p95.
const LEADSYNC_ASSIGNMENT_TIMEOUT_MS = 90_000;
const LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS = 3;
const LEADSYNC_ASSIGNMENT_RETRY_BASE_MS = 1200;
const LEADSYNC_ASSIGNMENT_DISABLED = process.env.LEADSYNC_ASSIGNMENT_ENABLED !== "true";

const leadPackJobs = new Map<string, LeadPackJob>();
const leadPackJobByAgent = new Map<string, string>();

function isRetryableLeadsyncStatus(status: number): boolean {
  return status === 408 || status === 429 || status >= 500;
}

function isRetryableLeadsyncError(error: unknown): boolean {
  const name = String((error as { name?: string })?.name || "").toLowerCase();
  const message = String((error as { message?: string })?.message || "").toLowerCase();
  return (
    name.includes("timeout") ||
    name.includes("abort") ||
    message.includes("timeout") ||
    message.includes("aborted") ||
    message.includes("network")
  );
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function resolveTaalkLeadIdForWebhook(input: {
  lead?: any;
  taalkLeadId?: unknown;
}): Promise<string | null> {
  const explicit = String(input.taalkLeadId || "").trim();
  if (explicit) return explicit;

  const fromLead = String(input.lead?.taalk_lead_id || input.lead?.taalkLeadId || "").trim();
  if (fromLead) return fromLead;
  return null;
}

async function postLeadsyncAssignmentWithRetry(
  webhookPayload: Record<string, unknown>,
  contextLabel: string,
): Promise<{
  ok: boolean;
  status?: number;
  text?: string;
  json?: any;
  attempts: number;
  error?: string;
}> {
  if (LEADSYNC_ASSIGNMENT_DISABLED) {
    const agentEmail = String(webhookPayload.agentEmail || webhookPayload.agent_email || "").trim().toLowerCase();
    console.warn(
      `LEADSYNC ASSIGNMENT DISABLED (${contextLabel})${agentEmail ? ` for ${agentEmail}` : ""}; skipping old bulk assignment`,
    );
    return {
      ok: true,
      status: 200,
      json: {
        ok: true,
        assigned: 0,
        disabled: true,
        message: "Old Leadsync bulk assignment is disabled; leasedialer buffer owns routing.",
      },
      attempts: 0,
    };
  }

  let attempts = 0;
  while (attempts < LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS) {
    attempts += 1;
    try {
      const response = await fetch(getLeadSyncAssignmentTriggerUrl(), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(webhookPayload),
        signal: AbortSignal.timeout(LEADSYNC_ASSIGNMENT_TIMEOUT_MS),
      });

      if (response.ok) {
        const json = await response.json().catch(() => ({}));
        if (attempts > 1) {
          console.log(
            `✅ LEADSYNC RETRY RECOVERED (${contextLabel}) on attempt ${attempts}/${LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS}`,
          );
        }
        return { ok: true, status: response.status, json, attempts };
      }

      const text = await response.text();
      const retryable = isRetryableLeadsyncStatus(response.status);
      if (retryable && attempts < LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS) {
        const waitMs = LEADSYNC_ASSIGNMENT_RETRY_BASE_MS * attempts;
        console.warn(
          `⚠️ LEADSYNC RETRY (${contextLabel}) attempt ${attempts}/${LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS} HTTP ${response.status}; retrying in ${waitMs}ms`,
        );
        await sleep(waitMs);
        continue;
      }
      return { ok: false, status: response.status, text, attempts };
    } catch (error: any) {
      const retryable = isRetryableLeadsyncError(error);
      if (retryable && attempts < LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS) {
        const waitMs = LEADSYNC_ASSIGNMENT_RETRY_BASE_MS * attempts;
        console.warn(
          `⚠️ LEADSYNC RETRY (${contextLabel}) attempt ${attempts}/${LEADSYNC_ASSIGNMENT_MAX_ATTEMPTS} ${error?.name || "Error"}: ${error?.message || String(error)}; retrying in ${waitMs}ms`,
        );
        await sleep(waitMs);
        continue;
      }
      return {
        ok: false,
        attempts,
        error: error?.message || String(error),
      };
    }
  }
  return { ok: false, attempts, error: "Assignment retry loop exhausted" };
}

function leadPackJobPublic(job: LeadPackJob) {
  return {
    jobId: job.id,
    agentEmail: job.agentEmail,
    status: job.status,
    progress: job.progress,
    stage: job.stage,
    leadCount: job.leadCount,
    targetCount: job.targetCount,
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
    error: job.error || null,
    result: job.result || null,
  };
}

async function resolveAssociateIdForZapier(agentEmail: string | null | undefined): Promise<string | number | null> {
  if (!supabaseAdmin || !agentEmail || !agentEmail.includes('@')) return null;
  const email = agentEmail.trim().toLowerCase();
  const cached = resolveAssociateIdCache.get(email);
  if (cached && Date.now() - cached.ts < RESOLVE_CACHE_TTL_MS) return cached.value;
  const result = await _resolveAssociateIdUncached(email);
  resolveAssociateIdCache.set(email, { value: result, ts: Date.now() });
  return result;
}

async function _resolveAssociateIdUncached(email: string): Promise<string | number | null> {
  try {
    // 1) customers: match company_email OR personal_email (exact lowercase, then ilike) — one round-trip each
    const { data: byEq } = await supabaseAdmin
      .from('customers')
      .select('associate_id')
      .or(`company_email.eq.${email},personal_email.eq.${email}`)
      .not('associate_id', 'is', null)
      .limit(1)
      .maybeSingle();
    if (byEq?.associate_id != null) return byEq.associate_id;

    const { data: custRows } = await supabaseAdmin
      .from('customers')
      .select('associate_id')
      .or(`company_email.ilike.${email},personal_email.ilike.${email}`)
      .not('associate_id', 'is', null)
      .limit(3);
    const custHit = (custRows || []).find((r: { associate_id?: unknown }) => r.associate_id != null);
    if (custHit?.associate_id != null) return custHit.associate_id;

    const { data: custAny } = await supabaseAdmin
      .from('customers')
      .select('associate_id')
      .or(`company_email.ilike.${email},personal_email.ilike.${email}`)
      .limit(1)
      .maybeSingle();
    if (custAny && (custAny as { associate_id?: unknown }).associate_id == null) {
      console.warn(`resolveAssociateIdForZapier: customers row exists for ${email} but associate_id is null — fix Customer record`);
    }

    const { data: profileEmail } = await supabaseAdmin
      .from('agent_profiles')
      .select('agent_associate_id')
      .ilike('email', email)
      .maybeSingle();
    if (profileEmail?.agent_associate_id != null) return profileEmail.agent_associate_id;

    const { data: profileAgentEmail } = await supabaseAdmin
      .from('agent_profiles')
      .select('agent_associate_id')
      .ilike('agent_email', email)
      .maybeSingle();
    if (profileAgentEmail?.agent_associate_id != null) return profileAgentEmail.agent_associate_id;

    const { data: hierarchy } = await supabaseAdmin
      .from('agent_hierarchy')
      .select('agent_associate_id')
      .ilike('agent_email', email)
      .limit(1)
      .maybeSingle();
    if (hierarchy?.agent_associate_id != null) return hierarchy.agent_associate_id;

    const { data: mgaRga } = await supabaseAdmin
      .from('mga_rga_directory')
      .select('associate_id')
      .ilike('email', email)
      .maybeSingle();
    if (mgaRga?.associate_id != null) return mgaRga.associate_id;

    const { data: producerRow } = await supabaseAdmin
      .from('producerlist')
      .select('associate_id')
      .ilike('company_email', email)
      .maybeSingle();
    if (producerRow?.associate_id != null) return producerRow.associate_id;

    return null;
  } catch (e) {
    console.warn('resolveAssociateIdForZapier error:', e);
    return null;
  }
}

/**
 * Zapier / Planet associate_id: customers table wins whenever we know the agent email.
 * Request body and masterlead.associate_id are fallbacks only (never trust 999).
 */
async function resolveAssociateForOutboundZapier(
  reqAssociateId: unknown,
  leadAssociateId: unknown,
  agentEmailNorm: string
): Promise<string | number | null> {
  const isBad = (v: unknown) =>
    v == null ||
    v === '' ||
    (typeof v === 'number' && v === 999) ||
    (typeof v === 'string' && String(v).trim() === '999');
  const coerce = (v: unknown): string | number | null => {
    if (isBad(v)) return null;
    const n = Number(v);
    return Number.isFinite(n) && n > 0 ? n : (v as string | number);
  };
  const fromBody = coerce(reqAssociateId);
  const fromLead = coerce(leadAssociateId);

  if (agentEmailNorm) {
    const fromCustomer = await resolveAssociateIdForZapier(agentEmailNorm);
    if (fromCustomer != null) return fromCustomer;
  }
  if (fromBody != null) return fromBody;
  if (fromLead != null) return fromLead;
  return null;
}

async function sendPlanetBookedWebhookOnce(input: {
  leadId?: number | string | null;
  taalkLeadId: string;
  associateId: string | number;
  payload?: Record<string, unknown>;
  force?: boolean;
}): Promise<{ ok: boolean; status?: number; skipped?: boolean; reason?: string; error?: string }> {
  if (!canSendZapierWebhooksFromThisRuntime()) {
    return { ok: true, skipped: true, reason: "zapier_webhooks_blocked_non_production_runtime" };
  }
  const taalkLeadId = String(input.taalkLeadId || "").trim();
  if (!taalkLeadId || !input.associateId) {
    return { ok: false, skipped: true, reason: "missing_taalk_lead_id_or_associate_id" };
  }

  let claimQuery = masterleadClient
    .from("masterlead")
    .update({ webhook_sent_at: new Date().toISOString() })
    .select("id, taalk_lead_id");

  if (input.leadId != null && String(input.leadId).trim()) {
    claimQuery = claimQuery.eq("id", input.leadId);
  } else {
    claimQuery = claimQuery.eq("taalk_lead_id", taalkLeadId);
  }

  if (!input.force) {
    claimQuery = claimQuery.is("webhook_sent_at", null);
  }

  const { data: claimedRows, error: claimError } = await claimQuery.limit(1);
  if (claimError) {
    return { ok: false, error: claimError.message };
  }
  if (!input.force && (!claimedRows || claimedRows.length === 0)) {
    return { ok: true, skipped: true, reason: "already_sent_or_not_found" };
  }

  const payload = {
    lead_id: taalkLeadId,
    taalk_lead_id: taalkLeadId,
    associate_id: input.associateId,
    ...(input.payload || {}),
  };

  try {
    const webhookResponse = await fetch("https://hooks.zapier.com/hooks/catch/2467580/uifcmkd/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(8000),
    });

    if (!webhookResponse.ok) {
      try {
        await masterleadClient
          .from("masterlead")
          .update({ webhook_sent_at: null })
          .eq("taalk_lead_id", taalkLeadId);
      } catch {
        // best-effort unlock for retry
      }
    }

    return { ok: webhookResponse.ok, status: webhookResponse.status };
  } catch (error: any) {
    try {
      await masterleadClient
        .from("masterlead")
        .update({ webhook_sent_at: null })
        .eq("taalk_lead_id", taalkLeadId);
    } catch {
      // best-effort unlock for retry
    }
    return { ok: false, error: error?.message || String(error) };
  }
}

function normalizePhone10ForRouting(value: unknown): string {
  return String(value || "").replace(/\D/g, "").slice(-10);
}

async function autoResolveFailedOutboundCall(input: {
  ownerEmail?: string | null;
  leadId?: string | number | null;
  taalkLeadId?: string | null;
  toNumber?: string | null;
  status?: string | null;
  callSid?: string | null;
}): Promise<void> {
  const status = String(input.status || "").trim().toLowerCase();
  if (!["failed", "no-answer", "no_answer", "busy", "canceled", "cancelled"].includes(status)) return;

  const ownerEmail = String(input.ownerEmail || "").trim().toLowerCase();
  if (!ownerEmail || !ownerEmail.includes("@")) return;

  const phone10 = normalizePhone10ForRouting(input.toNumber);
  const rawLeadId = String(input.leadId ?? "").trim();
  const numericLeadId = Number(rawLeadId);
  const taalkLeadId = String(input.taalkLeadId || "").trim();

  let lead: {
    id: number;
    taalk_lead_id: string | null;
    cnresolution: string | null;
    associate_id: string | number | null;
    cn_email: string | null;
  } | null = null;

  if (Number.isFinite(numericLeadId) && numericLeadId > 0) {
    const byId = await dispositionWritePool.query(
      `SELECT id, taalk_lead_id, cnresolution, associate_id, cn_email
       FROM masterlead
       WHERE id = $1
       LIMIT 1`,
      [numericLeadId],
    );
    lead = (byId.rows[0] as any) || null;
  }

  if (!lead && taalkLeadId) {
    const byTaalk = await dispositionWritePool.query(
      `SELECT id, taalk_lead_id, cnresolution, associate_id, cn_email
       FROM masterlead
       WHERE taalk_lead_id = $1
       ORDER BY updated_at DESC NULLS LAST, id DESC
       LIMIT 1`,
      [taalkLeadId],
    );
    lead = (byTaalk.rows[0] as any) || null;
  }

  if (!lead && phone10.length === 10) {
    const byPhone = await dispositionWritePool.query(
      `SELECT id, taalk_lead_id, cnresolution, associate_id, cn_email
       FROM masterlead
       WHERE phone_last10 = $1
       ORDER BY
         CASE WHEN lower(COALESCE(cn_email, '')) = lower($2) THEN 0 ELSE 1 END,
         updated_at DESC NULLS LAST,
         id DESC
       LIMIT 1`,
      [phone10, ownerEmail],
    );
    lead = (byPhone.rows[0] as any) || null;
  }

  if (!lead?.id) return;

  // Escalate repeat failures to wrong_number; otherwise mark no_answer to stop re-presentation.
  let nextResolution = "no_answer";
  if (phone10.length === 10) {
    const repeat = await dispositionWritePool.query<{ attempts: number }>(
      `
        SELECT COUNT(*)::int AS attempts
        FROM twilio_call_logs
        WHERE lower(COALESCE(owner_email, '')) = lower($1)
          AND lower(COALESCE(call_direction, '')) LIKE 'outbound%'
          AND lower(COALESCE(call_status, '')) IN ('failed', 'no-answer', 'no_answer')
          AND call_started_at >= NOW() - INTERVAL '7 days'
          AND RIGHT(REGEXP_REPLACE(COALESCE(to_number, ''), '\\D', '', 'g'), 10) = $2
      `,
      [ownerEmail, phone10],
    );
    const attempts = Number(repeat.rows[0]?.attempts || 0);
    if (attempts >= 3) nextResolution = "wrong_number";
  }

  const updateResult = await dispositionWritePool.query(
    `
      UPDATE masterlead
      SET cnresolution = $1,
          updated_at = NOW(),
          cn_email = CASE
            WHEN $2::text IS NULL OR $2::text = '' THEN cn_email
            ELSE $2::text
          END
      WHERE id = $3
        AND lower(trim(COALESCE(cnresolution, 'pending'))) IN ('pending', 'new', '', 'null', 'called', 'no_answer_vm', 'failed', 'busy')
      RETURNING id, taalk_lead_id, cnresolution
    `,
    [nextResolution, ownerEmail, lead.id],
  );

  if ((updateResult.rowCount || 0) <= 0) return;

  // Remove from active/queued assignments immediately so it cannot re-show.
  await dispositionWritePool.query(
    `
      UPDATE leasedialer_assignments
      SET status = 'released',
          released_at = NOW(),
          release_reason = 'auto_failed_call_resolution',
          updated_at = NOW()
      WHERE lead_id = $1
        AND status IN ('queued', 'active')
    `,
    [lead.id],
  );

  if (ownerEmail) {
    await releaseLeaseDialerAssignmentByLeadAndAgent({
      leadId: Number(lead.id),
      agentEmail: ownerEmail,
      reason: "auto_failed_call_resolution",
    }).catch(() => undefined);
  }

  console.log(
    `♻️ auto-failed-resolution leadId=${lead.id} taalk_lead_id=${lead.taalk_lead_id || "n/a"} resolution=${nextResolution} owner=${ownerEmail} callSid=${input.callSid || "n/a"}`,
  );
}

// ------------------------------------------------------------
// Helper: Send Producer Resolutions webhook to Zapier
// Called whenever masterlead.cnresolution is updated with a valid disposition
// ------------------------------------------------------------
async function sendProducerResolutionsWebhook(
  lead: any,
  disposition: string,
  options?: {
    agentEmail?: string;
    associateId?: string;
    callDuration?: number;
    notes?: string;
  }
): Promise<void> {
  try {
    if (!canSendZapierWebhooksFromThisRuntime()) {
      console.log('⏭️ Producer Resolutions webhook skipped (non-production runtime)');
      return;
    }
    // Map dispositions to Producer Resolutions format
    // 1 = Pres, No Sale | 2 = Pres Refused | 3 = Bad Phone | 4 = Duplicate | 5 = Over Age | 6 = DNC
    const dispositionMap: Record<string, number | null> = {
      'booked': 1, // Pres, No Sale - presentation resulted in booking
      'appointment': 1, // Pres, No Sale - appointment booked
      'appointment_set': 1, // Pres, No Sale - appointment booked
      'set_appointment': 1, // Pres, No Sale - appointment booked
      'meet': 1, // Pres, No Sale - meet treated as booked
      'instant_presentation': 1, // Pres, No Sale - presentation happened
      'sale': 1, // Pres, No Sale - presentation happened, resulted in sale
      'call_back': 1, // Pres, No Sale - likely had a presentation, requesting callback
      'callback': 1, // Pres, No Sale - callback requested (alternative spelling)
      'already_been_sold': 1, // Pres, No Sale - presentation happened but already sold
      'not_interested': 2, // Pres Refused - refused presentation
      'spanish': 2, // Pres Refused - client doesn't speak English, no Spanish speakers
      'wrong_number': 3, // Bad Phone - wrong/bad phone number
      'duplicate': 4, // Duplicate - duplicate lead
      'over_age': 5, // Over Age - over age limit
      'do_not_call': 6, // DNC - do not call
      'dnc': 6, // DNC - do not call (alternative spelling)
    };

    const producerResolution = dispositionMap[disposition?.toLowerCase()];
    
    // Only send webhook if disposition maps to a Producer Resolution (exclude no_answer_vm, pending, etc.)
    if (producerResolution === undefined || producerResolution === null) {
      return; // Skip silently - not all dispositions need webhooks
    }

    const webhookUrl = 'https://hooks.zapier.com/hooks/catch/15730596/um82e8j/';
    
    const trackingPhone = lead.phone || lead.phone_number || '';
    const leadState = lead.state || lead.taalk_state || 'Unknown';
    
    const normalizedCallDuration = Number(options?.callDuration ?? lead.duration ?? 0);
    const taalkLeadIdForWebhook = await resolveTaalkLeadIdForWebhook({
      lead,
    });
    if (!taalkLeadIdForWebhook) {
      console.warn(`⚠️ Skipping Producer Resolutions webhook: no taalk_lead_id resolved for lead ${lead.id || trackingPhone || 'unknown'}`);
      return;
    }
    const webhookPayload = {
      taalk_lead_id: taalkLeadIdForWebhook,
      code: producerResolution, // Producer Resolution code (1, 2, 3, 4, 5, 6)
      phone: trackingPhone,
      leadId: taalkLeadIdForWebhook,
      lead_id: taalkLeadIdForWebhook,
      firstName: lead.first_name || lead.firstname || '',
      lastName: lead.last_name || lead.lastname || '',
      email: lead.email || lead.taalk_email || '',
      city: lead.city || lead.taalk_city || '',
      state: leadState,
      zip: lead.zip || lead.taalk_zip || '',
      disposition: disposition,
      producerResolution: producerResolution, // Keep for backward compatibility
      agentEmail: options?.agentEmail || lead.cn_email || lead.agent_email || '',
      associateId: (options?.associateId ?? lead.associate_id) ?? '',
      associate_id: (options?.associateId ?? lead.associate_id) ?? '',
      callDuration: Number.isFinite(normalizedCallDuration) ? normalizedCallDuration : 0,
      notes: options?.notes || lead.disposition_notes || lead.resolution_notes || '',
      market: lead?.market || lead?.taalk_market || lead?.taalk_groupname || 'Unknown',
      timestamp: new Date().toISOString(),
    };

    console.log(`📤 Sending Producer Resolutions webhook for disposition ${disposition} (resolution ${producerResolution}) for lead ${lead.id}`);

    const webhookResponse = await fetch(webhookUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(webhookPayload),
    });

    if (webhookResponse.ok) {
      console.log(`✅ Producer Resolutions webhook sent successfully for lead ${lead.id} (resolution ${producerResolution})`);
    } else {
      const errorText = await webhookResponse.text();
      console.error(`❌ Producer Resolutions webhook failed: ${webhookResponse.status} ${webhookResponse.statusText}`, errorText.substring(0, 200));
    }
  } catch (webhookError) {
    console.error('❌ Error sending Producer Resolutions webhook (non-blocking):', webhookError);
    // Don't throw - webhook failures shouldn't block resolution updates
  }
}

// ------------------------------------------------------------
// Helper: Check CCPRO access - Uses SubscriptionService to check ALL access methods
// Priority: 1) SubscriptionService.getEffectiveSubscription (checks outboundEnabled, trials, etc.)
//           2) customers.CCPRO flag (fallback)
// ------------------------------------------------------------
async function checkCCProAccess(agentEmail: string): Promise<boolean> {
  if (!supabaseAdmin) {
    return false;
  }
  
  const normalizedEmail = agentEmail.toLowerCase().trim();
  
  // 🔥 HARDCODED: Force CCPro access for these emails - BYPASSES ALL CHECKS
  const bypassEmails = [
    'richiealtig@aoglobelife.com',
    'coopertyler@aoglobelife.com',
    'jacobnavarre@aoglobelife.com',
    'kaylar@aoglobelife.com',
    'ryancarrion@aoglobelife.com',
    'makelaoutlawalexander@aoglobelife.com',
    'langjames@aoglobelife.com',
    'vernawillbur@aoglobelife.com',
    'nicolasmahaffy@aoglobelife.com',
    'chrislafond@aoglobelife.com'
  ];
  if (bypassEmails.includes(normalizedEmail)) {
    console.log(`✅ CCPRO ACCESS: ${normalizedEmail} HARDCODED - FULL ACCESS - BYPASSES ALL CHECKS`);
    return true;
  }
  
  try {
    // STEP 1: Use SubscriptionService to get effective subscription - this checks ALL access methods
    // including outboundEnabled, trials, active subscriptions, etc.
    const subscription = await SubscriptionService.getEffectiveSubscription(normalizedEmail);
    
    // Check if user has CCPro access through subscription service
    // CRITICAL: Only grant access if subscription is ACTIVE (hasActiveSubscription = true)
    // This includes: professional/elite plans with ACTIVE subscriptions, outboundEnabled flag, active trials, etc.
    const hasSubscriptionCCPro = 
      subscription.outboundEnabled || 
      (subscription.plan === 'professional' && subscription.hasActiveSubscription) ||
      (subscription.plan === 'elite' && subscription.hasActiveSubscription);
    
    if (hasSubscriptionCCPro) {
      console.log(`✅ CCPRO ACCESS: ${normalizedEmail} has subscription access (plan: ${subscription.plan}, outboundEnabled: ${subscription.outboundEnabled}, hasActive: ${subscription.hasActiveSubscription}) - ENABLED`);
      return true;
    }

    // STEP 2: FALLBACK to customers.CCPRO flag if subscription service doesn't have it
    const { data: customerData } = await supabaseAdmin
      .from('customers')
      .select('company_email, personal_email, CCPRO')
      .or(`company_email.eq.${normalizedEmail},personal_email.eq.${normalizedEmail}`)
      .maybeSingle();

    if (customerData) {
      const hasCustomerCCPro = 
        customerData.CCPRO === true || 
        customerData.CCPRO === 'true' || 
        customerData.CCPRO === 1;
      
      if (hasCustomerCCPro) {
        console.log(`✅ CCPRO ACCESS: ${normalizedEmail} has customers.CCPRO flag - ENABLED`);
        return true;
      }
    }

    // No CCPRO access found
    console.log(`🚫 CCPRO ACCESS: ${normalizedEmail} DENIED (plan: ${subscription.plan}, outboundEnabled: ${subscription.outboundEnabled}, hasActive: ${subscription.hasActiveSubscription})`);
    return false;
  } catch (error) {
    console.error(`❌ Error checking CCPRO access for ${normalizedEmail}:`, error);
    return false;
  }
}

// Module-scope WebSocket server and state for video conferencing
let videoWebSocketServer: WebSocketServer | null = null;
const videoRooms = new Map<string, Set<WebSocket>>();

/**
 * 🚨 CRITICAL: Trigger instant display for AOIntel leads
 * This function is called whenever a lead with cnresolution='AOIntel' is detected
 * It supercedes all queue filters and displays the lead instantly via WebSocket
 */
// Export trigger function for use by AOIntel VDP poller
export async function triggerAOIntelLeadDisplay(lead: any, agentEmail: string) {
  try {
    // Check for AOIntel - check aointel column first, then cnresolution (backward compatibility)
    const isAOIntel = lead?.aointel === true || 
                     lead?.aointel === 1 || 
                     String(lead?.cnresolution || '').toLowerCase() === 'aointel';
    if (!lead || !isAOIntel || !agentEmail) {
      return; // Not an AOIntel lead or missing agent email
    }

    const normalizedEmail = agentEmail.toLowerCase();
    const now = new Date();
    const leadName = `${lead.first_name || ''} ${lead.last_name || ''}`.trim() || 'AOIntel Lead';
    const callerPhone = lead.phone || 'Unknown';

    // Single line - avoid log spam when scanner runs with many leads
    console.log(`🚨 AOIntel lead display: ${leadName} (${callerPhone}) → ${normalizedEmail}`);

    // 1. Update agent_live_call_status to 'in_call' - this signals the frontend to pause dialing
    if (supabaseAdmin) {
      const { error: statusError } = await supabaseAdmin
        .from('agent_live_call_status')
        .upsert({
          agent_email: normalizedEmail,
          status: 'in_call',
          last_heartbeat_at: now.toISOString(),
          updated_at: now.toISOString(),
        }, {
          onConflict: 'agent_email'
        });

      if (statusError) {
        console.error('❌ Failed to update agent_live_call_status for AOIntel call:', statusError);
      }

      // REMOVED: live_call_boardt doesn't exist and we don't need it
    }

    // 3. Send WebSocket message to agent to instantly display AOIntel lead
    if (!videoWebSocketServer) {
      console.error('❌ WebSocket server not initialized - cannot send AOIntel lead');
      return;
    }

    const aoiLeadMessage = {
      type: 'aoi-lead-arrived',
      lead: {
        id: lead.id || lead.taalk_lead_id,
        taalk_lead_id: lead.taalk_lead_id || String(lead.id),
        first_name: lead.first_name,
        last_name: lead.last_name,
        name: leadName,
        phone: callerPhone,
        state: lead.state || lead.taalk_state,
        market: lead.market || lead.taalk_market || 'AOIntel',
        cn_email: normalizedEmail,
        cnresolution: lead.cnresolution || 'AOIntel',
        source_table: lead.source_table || 'ao_intel_inbound',
        updated_at: lead.updated_at || now.toISOString(),
        is_hot_lead: true,
        priority: 'urgent'
      },
      agentEmail: normalizedEmail,
      timestamp: now.toISOString()
    };

    // Broadcast to all connected clients - they'll filter by agentEmail on frontend
    // Do NOT log per-client (causes Railway 500 logs/sec rate limit when many clients connected)
    let sentCount = 0;
    let totalClients = 0;
    videoWebSocketServer.clients.forEach((client) => {
      totalClients++;
      if (client.readyState === WebSocket.OPEN) {
        try {
          client.send(JSON.stringify(aoiLeadMessage));
          sentCount++;
        } catch (wsError) {
          console.error('❌ Error sending WebSocket message:', wsError);
        }
      }
    });
    console.log(`📡 AOIntel lead ${lead.id} broadcast to ${sentCount}/${totalClients} clients (target: ${normalizedEmail})`);

  } catch (error) {
    console.error('❌ Error triggering AOIntel lead display (non-blocking):', error);
  }
}

