const subscriptionPlans: SubscriptionPlan[] = ["starter", "professional", "elite"];

const isValidSubscriptionPlan = (plan: unknown): plan is SubscriptionPlan => {
  return typeof plan === "string" && subscriptionPlans.includes(plan as SubscriptionPlan);
};

const resolveUserEmail = (req: any): string | null => {
  const headerEmail =
    (req.headers && (req.headers["x-user-email"] || req.headers["user-email"])) ||
    undefined;
  const queryEmail = req.query?.userEmail || req.query?.agentEmail;
  const bodyEmail = req.body?.userEmail || req.body?.agentEmail;
  const email = (headerEmail || queryEmail || bodyEmail || null) as string | null;
  return email ? email.toLowerCase() : null;
};

const parseArrayField = (value: unknown): string[] => {
  if (!value) {
    return [];
  }

  if (Array.isArray(value)) {
    return value
      .filter((item): item is string => typeof item === "string")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) {
      return [];
    }

    if (trimmed.startsWith("[") && trimmed.endsWith("]")) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) {
          return parsed
            .filter((item): item is string => typeof item === "string")
            .map((item) => item.trim())
            .filter(Boolean);
        }
      } catch {
        // fall through to comma split
      }
    }

    return trimmed
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
};

const chunkArray = <T>(items: T[], chunkSize = 500): T[][] => {
  const chunks: T[][] = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    chunks.push(items.slice(i, i + chunkSize));
  }
  return chunks;
};

/** Agent emails whose customers.market or agent_profiles.authorized_markets matches the filter (substring match, case-insensitive). */
async function collectAgentEmailsForMarketScope(client: any, marketFilter: string): Promise<string[]> {
  const marketNorm = String(marketFilter || "").trim();
  if (!marketNorm || !client) return [];
  const emails = new Set<string>();
  const rowMatches = (labels: string[]) => {
    const n = marketNorm.toLowerCase();
    return labels.some((m) => {
      const x = String(m).toLowerCase().trim();
      return Boolean(x && (x.includes(n) || n.includes(x)));
    });
  };
  const { data: activeProfiles } = await client
    .from("agent_profiles")
    .select("email, authorized_markets")
    .eq("is_active", true);
  for (const a of activeProfiles || []) {
    const markets = parseArrayField(a.authorized_markets);
    if (rowMatches(markets) && a.email) emails.add(String(a.email).toLowerCase().trim());
  }
  const { data: customers } = await client.from("customers").select("company_email, personal_email, market");
  for (const c of customers || []) {
    const markets = parseArrayField((c as { market?: unknown }).market);
    if (rowMatches(markets)) {
      const ce = (c as { company_email?: string }).company_email;
      const pe = (c as { personal_email?: string }).personal_email;
      if (ce) emails.add(String(ce).toLowerCase().trim());
      if (pe) emails.add(String(pe).toLowerCase().trim());
    }
  }
  return Array.from(emails);
}

/** Build eligible agents for inbound by market + state (required), sorted by distribution_priority (1 first). */
async function getEligibleAgentsForInbound(leadMarket: string, leadState: string): Promise<{ eligibleSet: Set<string>; orderedEmails: string[] }> {
  const eligibleEmails = new Set<string>();
  const emailToPriority: Map<string, number> = new Map();
  const DEFAULT_PRIORITY = 5;
  if (!supabaseAdmin || !leadMarket || !leadState || leadMarket === 'Unknown' || leadState === 'Unknown') {
    return { eligibleSet: eligibleEmails, orderedEmails: [] };
  }
  const stateNorm = String(leadState).trim().toUpperCase();
  const marketNorm = String(leadMarket).trim();
  const { data: activeProfiles } = await supabaseAdmin
    .from('agent_profiles')
    .select('email, license_states, authorized_markets, distribution_priority')
    .eq('is_active', true);
  for (const a of activeProfiles || []) {
    const states = (Array.isArray(a.license_states) ? a.license_states : []).map((s: string) => String(s).trim().toUpperCase());
    const markets = (Array.isArray(a.authorized_markets) ? a.authorized_markets : []).map((m: string) => String(m).trim());
    const stateMatch = states.includes(stateNorm) || states.some((s: string) => s.includes(stateNorm) || stateNorm.includes(s));
    const marketMatch = markets.some((m: string) => m.toLowerCase().includes(marketNorm.toLowerCase()) || marketNorm.toLowerCase().includes(m.toLowerCase()));
    if (stateMatch && marketMatch && a.email) {
      const email = String(a.email).toLowerCase().trim();
      eligibleEmails.add(email);
      const prio = (a as any).distribution_priority != null ? Number((a as any).distribution_priority) : DEFAULT_PRIORITY;
      emailToPriority.set(email, prio);
    }
  }
  const { data: customers } = await supabaseAdmin
    .from('customers')
    .select('company_email, market, states');
  for (const c of customers || []) {
    const states = parseArrayField(c.states).map((s: string) => s.trim().toUpperCase()).filter(Boolean);
    const markets = parseArrayField(c.market).map((m: string) => m.trim()).filter(Boolean);
    const stateMatch = states.includes(stateNorm) || states.some((s: string) => s.includes(stateNorm) || stateNorm.includes(s));
    const marketMatch = markets.some((m: string) => m.toLowerCase().includes(marketNorm.toLowerCase()) || marketNorm.toLowerCase().includes(m.toLowerCase()));
    if (stateMatch && marketMatch && c.company_email) {
      const email = String(c.company_email).toLowerCase().trim();
      eligibleEmails.add(email);
      if (!emailToPriority.has(email)) emailToPriority.set(email, DEFAULT_PRIORITY);
    }
  }
  const { callConnectorTracker } = await import('./call-connector-tracker');
  let agentList = Array.from(eligibleEmails).filter((email) => callConnectorTracker.isAgentActive(email));
  try {
    const { twilioCallsPoller } = await import('./twilio-calls-poller.js');
    const onCall = new Set((twilioCallsPoller.getAllActiveCalls() || []).map((c: any) => (c.agentEmail || '').toLowerCase().trim()));
    agentList = agentList.filter((e) => !onCall.has(e));
  } catch (_) {}
  agentList.sort((a, b) => (emailToPriority.get(a) ?? DEFAULT_PRIORITY) - (emailToPriority.get(b) ?? DEFAULT_PRIORITY));
  return { eligibleSet: new Set(agentList), orderedEmails: agentList };
}

const getIsoDate = (date: Date): string => date.toISOString().slice(0, 10);

const getCurrentWeekStartIso = (): string => {
  const now = new Date();
  const utcYear = now.getUTCFullYear();
  const utcMonth = now.getUTCMonth();
  const utcDate = now.getUTCDate();
  const weekStart = new Date(Date.UTC(utcYear, utcMonth, utcDate));
  const day = weekStart.getUTCDay();
  const diff = day === 0 ? -6 : 1 - day; // Monday as start of week
  weekStart.setUTCDate(weekStart.getUTCDate() + diff);
  return getIsoDate(weekStart);
};

const getSubscriptionForRequest = async (
  req: express.Request,
  res: express.Response
) => {
  if ((req as any).subscription) {
    return (req as any).subscription;
  }

  const userEmail = resolveUserEmail(req);
  if (!userEmail) {
    res.status(401).json({
      success: false,
      error: "User email is required to evaluate subscription access.",
    });
    return null;
  }

  try {
    const subscription = await SubscriptionService.getEffectiveSubscription(userEmail);
    (req as any).subscription = subscription;
    return subscription;
  } catch (error) {
    console.error("❌ Subscription lookup failed:", error);
    res.status(500).json({
      success: false,
      error: "Failed to verify subscription access.",
    });
    return false;
  }
};

const requireActiveSubscription = async (
  req: express.Request,
  res: express.Response
): Promise<boolean> => {
  const subscription = await getSubscriptionForRequest(req, res);
  if (!subscription) {
    return false;
  }

  if (!subscription.hasActiveSubscription) {
    res.status(402).json({
      success: false,
      error: "An active Call Connector plan is required to access leads.",
      upgradeRequired: true,
      upgradeTarget: "professional",
      subscription,
    });
    return false;
  }

  return true;
};

