// Export function to setup Realtime WebSocket server
export function setupRealtimeWebSocket(server: Server): void {
  const realtimeWsServer = new WebSocketServer({ 
    noServer: true
  });
  
  server.on('upgrade', (request, socket, head) => {
    const pathname = url.parse(request.url || '').pathname;
    
    if (pathname === '/api/realtime/ws') {
      realtimeWsServer.handleUpgrade(request, socket, head, (ws) => {
        realtimeWsServer.emit('connection', ws, request);
      });
    }
  });

  realtimeWsServer.on('connection', async (clientWs, req) => {
    console.log('🔌 Client connected to Realtime proxy');
    
    const { OPENAI_API_KEY } = await import('./hardcoded-config');
    if (!OPENAI_API_KEY) {
      clientWs.close(1011, 'OpenAI API key not configured');
      return;
    }

    // Connect to OpenAI Realtime API
    const openaiWs = new WebSocket(
      'wss://api.openai.com/v1/realtime?model=gpt-4o-realtime-preview-2024-12-17',
      {
        headers: {
          'Authorization': `Bearer ${OPENAI_API_KEY}`,
          'OpenAI-Beta': 'realtime=v1'
        }
      }
    );

        // Send initial session configuration
        openaiWs.on('open', () => {
          console.log('✅ Connected to OpenAI Realtime API');
          // Send session update with configuration
          const sessionConfig = {
            type: 'session.update',
            session: {
              modalities: ['text', 'audio'],
              instructions: `You are "Alex" calling from AO Globe Life customer service.

Audience & Tone
You are speaking to older U.S. service members.
Use graceful, respectful, elegant language. Avoid slang, street language, or "young" phrasing.
Do not sound excited or high-energy. Calm, steady, and courteous.
Speak empathetically and sympathetically.
At the beginning of the call, speak very slowly and clearly so the caller can understand you.
It is acceptable to build light rapport at the start (1–2 short lines).

Training Disclosure
Early in the call, in a casual and natural tone, include: "I am in training."
(Say it once; do not repeat unless asked.)

Call Purpose
The caller requested a Veteran Will Kit online.
Your purpose is to confirm details and then WARM transfer them to their local representative.
You do not set appointments. You only warm transfer.
Do not promise any outcomes or make legal statements. Do not provide legal advice.

Conversation Rules
Ask one question at a time.
Keep each response 1–2 sentences maximum (except when repeating back an answer; still keep it short).
It is okay to repeat back answers politely and briefly expand on their response.
If the caller interrupts you, stop speaking immediately and listen.
If the caller is confused, calmly restate the purpose and continue.
If the caller says "stop calling," "do not call," "remove me," or is clearly not interested: apologize once and end the interaction politely.

Data
You may receive:
name = {name}
city = {city}
secret keyword = {secret}
If any are missing, speak naturally without inventing details (e.g., "the city we have on file").

Scripted Flow
Follow this flow closely. Do not skip steps unless the caller answers early.

Greeting + purpose (very slow, courteous):
"Hello, {name}. This is Alex with AO Globe Life customer service. I am calling about the Veteran Will Kit you recently requested. Can you hear me all right?"

Source confirmation:
"It appears the request was submitted online, through Facebook or Google. Does that ring a bell?"

Transfer framing + location check:
"Thank you. Your kit has been processed, and your local representative is standing by. You are still living in {city}, is that correct?"

Secret keyword confirmation:
"And the keyword we have on file is: {secret}. Does that sound correct?"

Prior experience question:
"Just so I may guide you properly—have you ever put documents like this in place before, or would this be your first time?"

Brief empathy + explanation (keep short):
"Many people are in the same position. Having these documents prepared can make matters far easier for your loved ones later. Does that seem reasonable?"

Program understanding check:
"This program is meant to ensure your family has the necessary documents to carry out your wishes. Does that make sense?"

Transfer Trigger
If they agree / say yes / show understanding and you have confirmed the key details:
Say exactly:
"Very good. I have your local representative standing by. I will connect you now."
After saying that, stop speaking (in this demo you cannot actually transfer, so do not continue the conversation).

Confusion Branch
If they do not understand at step 7:
Say:
"It sounds like there may be some confusion. You requested a Veteran Will Kit online recently, and I am simply confirming your details before connecting you to your local representative. May I ask you one quick question?"
Then continue with the next unanswered step.`,
          voice: 'alloy',
          input_audio_format: 'pcm16',
          output_audio_format: 'pcm16',
          input_audio_transcription: { model: 'whisper-1' },
          turn_detection: { type: 'server_vad', threshold: 0.5, prefix_padding_ms: 300, silence_duration_ms: 500 },
          temperature: 0.8,
          max_response_output_tokens: 4096
        }
      };
      openaiWs.send(JSON.stringify(sessionConfig));
    });

    // Forward messages from client to OpenAI
    clientWs.on('message', (data) => {
      if (openaiWs.readyState === WebSocket.OPEN) {
        openaiWs.send(data);
      }
    });

    // Forward messages from OpenAI to client
    openaiWs.on('message', (data) => {
      if (clientWs.readyState === WebSocket.OPEN) {
        clientWs.send(data);
      }
    });

    // Handle errors and cleanup
    const cleanup = () => {
      console.log('🔌 Closing Realtime proxy connection');
      if (openaiWs.readyState === WebSocket.OPEN) {
        openaiWs.close();
      }
      if (clientWs.readyState === WebSocket.OPEN) {
        clientWs.close();
      }
    };

    clientWs.on('close', cleanup);
    clientWs.on('error', (err) => {
      console.error('❌ Client WebSocket error:', err);
      cleanup();
    });

    openaiWs.on('close', cleanup);
    openaiWs.on('error', (err) => {
      console.error('❌ OpenAI WebSocket error:', err);
      cleanup();
    });
  });
}

/** platform_sales row timestamp for ALP windows — prefer SGA submit, then created/updated. */
function platformSaleEffectiveAt(r: Record<string, any>): Date | null {
  const raw =
    r.sga_submit ??
    r.created_at ??
    r.updated_at ??
    r.submit_date ??
    r.date_submitted;
  if (raw == null || raw === "") return null;
  const d = new Date(raw);
  return Number.isFinite(d.getTime()) ? d : null;
}

/** My Stats ALP: only AOI / Call Connector Pro style rows when product metadata is present. */
function isAoiOrCcproPlatformSaleRow(r: Record<string, any>): boolean {
  const parts = [
    r.product,
    r.platform,
    r.product_type,
    r.product_line,
    r.line_of_business,
    r.lob,
    r.source,
    r.sale_type,
    r.channel,
    r.program,
    r.market,
    r.carrier,
    r.writing_carrier,
    r.business_line,
    r.submission_type,
    r.product_name,
    r.line,
  ];
  const blob = parts
    .filter((x) => x != null && String(x).trim() !== "")
    .map((x) => String(x).toLowerCase())
    .join(" ");
  if (!blob.trim()) return true;
  const aoi =
    blob.includes("aoi") ||
    blob.includes("ao connect") ||
    blob.includes("ao-connect") ||
    blob.includes("aoiconnect");
  const ccpro =
    blob.includes("ccpro") ||
    blob.includes("call connector") ||
    blob.includes("call_connector") ||
    blob.includes("callconnector");
  return aoi || ccpro;
}

function sumPlatformSalesAlp(
  rows: any[],
  sinceMs: number,
  todayStartMs: number
): { alpRolling: number; alpToday: number } {
  let alpRolling = 0;
  let alpToday = 0;
  for (const r of rows) {
    if (!isAoiOrCcproPlatformSaleRow(r)) continue;
    const at = platformSaleEffectiveAt(r);
    if (!at || at.getTime() < sinceMs) continue;
    const alp = parseFloat(r.alp) || 0;
    alpRolling += alp;
    if (at.getTime() >= todayStartMs) alpToday += alp;
  }
  return { alpRolling, alpToday };
}

const PLATFORM_SALES_ALP_SELECT =
  "id, sga_submit, created_at, updated_at, product, platform, product_type, product_line, lob, source, sale_type, market, writing_carrier, business_line, product_name, line";

/** Last 30d platform_sales for My Stats ALP: SGA-dated rows; optional branch for null sga_submit + created_at. Tries string + numeric associate_id. */
async function loadPlatformSalesForAgentAlp(
  supabase: NonNullable<typeof supabaseAdmin>,
  assocId: string | number,
  sinceIso: string
): Promise<any[]> {
  const uniq: Array<string | number> = [assocId];
  const n = Number(assocId);
  if (typeof assocId !== "number" && Number.isFinite(n) && String(assocId).trim() !== "")
    uniq.push(n);

  const fetchWithSelect = async (sel: string, nullSubmitBranch: boolean): Promise<any[]> => {
    const merge = new Map<string, any>();
    for (const aid of uniq) {
      const r1 = await supabase
        .from("platform_sales")
        .select(sel)
        .eq("associate_id", aid)
        .gte("sga_submit", sinceIso);
      if (r1.error) throw r1.error;
      for (const r of r1.data || []) merge.set(String((r as any).id), r);
      if (nullSubmitBranch) {
        const r2 = await supabase
          .from("platform_sales")
          .select(sel)
          .eq("associate_id", aid)
          .is("sga_submit", null)
          .gte("created_at", sinceIso);
        if (r2.error) throw r2.error;
        for (const r of r2.data || []) merge.set(String((r as any).id), r);
      }
    }
    return [...merge.values()];
  };

  try {
    return await fetchWithSelect(PLATFORM_SALES_ALP_SELECT, true);
  } catch {
    try {
      return await fetchWithSelect("id, alp, sga_submit, created_at", true);
    } catch {
      try {
        return await fetchWithSelect(PLATFORM_SALES_ALP_SELECT, false);
      } catch {
        try {
          return await fetchWithSelect("id, alp, sga_submit, created_at", false);
        } catch {
          return [];
        }
      }
    }
  }
}

