async function withPostgrestTimeout<T extends { data: unknown }>(
  label: string,
  p: Promise<T>,
  ms: number = PANEL_DATA_SUPABASE_TIMEOUT_MS,
): Promise<T> {
  return new Promise((resolve) => {
    const t = setTimeout(() => {
      console.warn(`panel-data: ${label} timed out after ${ms}ms — empty partial`);
      resolve({ data: [] as any, error: { message: 'PANEL_DATA_QUERY_TIMEOUT' } } as T);
    }, ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        console.warn(`panel-data: ${label} failed:`, (e as Error)?.message || e);
        resolve({ data: [] as any, error: { message: String(e) } } as T);
      },
    );
  });
}

async function withTimeoutPick<T>(label: string, p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise((resolve) => {
    const t = setTimeout(() => {
      console.warn(`panel-data: ${label} timed out after ${ms}ms`);
      resolve(fallback);
    }, ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        console.warn(`panel-data: ${label}:`, (e as Error)?.message || e);
        resolve(fallback);
      },
    );
  });
}

