// Keep twilio_call_logs fresh from Twilio API for stats endpoints.
// This prevents stale AOI Command dials when log backfill jobs lag under load.
let twilioStatsBackfillInFlight: Promise<void> | null = null;
let twilioStatsBackfillLastMs = 0;
const TWILIO_STATS_BACKFILL_MIN_INTERVAL_MS = 2 * 60_000;
async function refreshTwilioLogsForStatsIfNeeded(ptDate: string): Promise<void> {
  const nowPt = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Los_Angeles",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date());
  if (ptDate !== nowPt) return;
  if (String(process.env.TWILIO_STATS_BACKFILL_ON_TEAM_STATS || "true").toLowerCase() === "false") return;

  const now = Date.now();
  if (now - twilioStatsBackfillLastMs < TWILIO_STATS_BACKFILL_MIN_INTERVAL_MS) return;
  if (twilioStatsBackfillInFlight) {
    await twilioStatsBackfillInFlight;
    return;
  }

  twilioStatsBackfillInFlight = (async () => {
    try {
      const { backfillTwilioCallsToLocal } = await import("./backfill-twilio-to-local.js");
      await Promise.race([
        backfillTwilioCallsToLocal(1),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error("twilio_stats_backfill_timeout")), 20_000),
        ),
      ]);
      twilioStatsBackfillLastMs = Date.now();
      console.error("[AOIrail] team-stats Twilio API pre-refresh complete");
    } catch (error: any) {
      console.error("[AOIrail] team-stats Twilio API pre-refresh skipped:", error?.message || error);
    } finally {
      twilioStatsBackfillInFlight = null;
    }
  })();

  await twilioStatsBackfillInFlight;
}

