      if (!leadPhone || !Taalk_LeadId) {
        // This webhook occasionally receives malformed payloads; treat as ignorable noise.
        console.warn('⚠️ Ignoring Taalk webhook payload missing phone or Taalk_LeadId');
        return res.status(202).json({ ignored: true, reason: 'Missing required fields: phone and Taalk_LeadId are required' });
      }
      
