  // Upload screenshot to S3 (Supabase) storage with AI validation
  app.post("/api/verification/session/:sessionId/screenshot", upload.single('screenshot'), async (req, res) => {
    try {
      const { sessionId } = req.params;
      
      // Debug: Log what we received
      console.log('🔍 SCREENSHOT UPLOAD DEBUG:', {
        sessionId,
        hasFile: !!req.file,
        contentType: req.headers['content-type'],
        bodyKeys: Object.keys(req.body),
        filesKeys: req.files ? Object.keys(req.files) : 'no files object'
      });

      if (!req.file) {
        console.log('❌ SCREENSHOT UPLOAD: No file received by multer');
        return res.status(400).json({ message: "No screenshot file provided" });
      }

      // Get session data for SMS
      const session = await storage.getVerificationSession(sessionId);
      if (!session) {
        return res.status(404).json({ message: "Verification session not found" });
      }

      // Read file buffer for upload and AI validation
      const fileBuffer = fsSync.readFileSync(req.file.path);
      
      // AI VALIDATION: Validate screenshot content (FLAG ONLY, don't reject)
      let validationResult = null;
      try {
        console.log('🤖 Starting AI validation of screenshot...');
        const base64Screenshot = fileBuffer.toString('base64');
        const { verificationScreenshotValidator } = await import('./verification-screenshot-validator');
        
        validationResult = await verificationScreenshotValidator.validateScreenshot(
          base64Screenshot,
          session.verificationMethod || 'zoom'
        );
        
        console.log(`🤖 AI Validation Result: ${validationResult.isValid ? '✅ VALID' : '⚠️ FLAGGED'}`);
        console.log(`   Confidence: ${validationResult.confidence}`);
        console.log(`   Reason: ${validationResult.reason}`);
        
        // Just flag it - don't reject!
        if (!validationResult.isValid) {
          console.log(`🚩 Screenshot FLAGGED for admin review (${(validationResult.confidence * 100).toFixed(0)}% confidence)`);
        }
        
      } catch (validationError: any) {
        console.error('⚠️ AI validation error (proceeding with upload):', validationError.message);
        // Continue with upload even if validation fails due to technical error
      }

      // Upload to Supabase Storage and generate 2-year signed URL
      let screenshotUrl = null;
      try {
        const fileName = `VER-${sessionId}-${Date.now()}.png`;
        
        // Upload to Supabase Storage
        const { data, error } = await supabaseAdmin!.storage
          .from(S3_BUCKET)
          .upload(fileName, fileBuffer, {
            contentType: 'image/png',
            cacheControl: '3600',
            upsert: false
          });

        if (error) {
          console.error('❌ Supabase upload error:', error);
          throw error;
        }

        // Generate 2-year signed URL
        const { data: signedUrlData, error: signUrlError } = await supabaseAdmin!.storage
          .from(S3_BUCKET)
          .createSignedUrl(fileName, 63072000); // 2 years

        if (signUrlError) {
          console.error('❌ Signed URL error:', signUrlError);
          throw signUrlError;
        }

        screenshotUrl = signedUrlData.signedUrl;
        console.log('✅ Screenshot uploaded with 2-year signed URL');
        
        // Clean up local file
        try {
          fsSync.unlinkSync(req.file.path);
        } catch (cleanupError) {
          console.warn('Could not delete local file:', cleanupError);
        }
      } catch (uploadError: any) {
        console.error('❌ Upload failed:', uploadError);
        throw uploadError;
      }

      // Store the signed URL and validation results in database
      const updateData: any = {
        screenshotPath: screenshotUrl,
      };
      
      // Add validation data to session if available
      if (validationResult) {
        updateData.screenshot_validation = {
          isValid: validationResult.isValid,
          confidence: validationResult.confidence,
          validationType: validationResult.validationType,
          reason: validationResult.reason,
          detectedElements: validationResult.detectedElements,
          issues: validationResult.issues,
          validatedAt: new Date().toISOString()
        };
      }
      
      const updatedSession = await storage.updateVerificationSession(sessionId, updateData);

      if (!updatedSession) {
        return res.status(404).json({ message: "Verification session not found" });
      }

      res.json({ 
        message: "Screenshot uploaded successfully", 
        session: updatedSession,
        screenshotUrl: screenshotUrl,
        validation: validationResult ? {
          isValid: validationResult.isValid,
          confidence: validationResult.confidence,
          reason: validationResult.reason
        } : null
      });
    } catch (error) {
      console.error('Screenshot upload error:', error);
      res.status(500).json({ message: "Failed to upload screenshot" });
    }
  });

  // Send SMS verification to client  
  app.post("/api/verification/session/:sessionId/send-sms", async (req, res) => {
    try {
      const { sessionId } = req.params;

      const session = await storage.getVerificationSession(sessionId);
      if (!session) {
        return res.status(404).json({ message: "Verification session not found" });
      }

      if (!session.phone) {
        return res.status(400).json({ message: "No phone number found for this session" });
      }

      const clientName = `${session.firstName} ${session.lastName}`;
      const verificationBaseUrl = process.env.VERIFICATION_BASE_URL || 'https://aoprecheck-production.up.railway.app';
      const clientApprovalUrl = `${verificationBaseUrl}/client-verify/${sessionId}`;
      const agentDashboardUrl = `${verificationBaseUrl}/agent-verify/${sessionId}`;
      const language = session.language || 'en';
      
      // Format phone to E.164 before sending to Twilio
      const formatE164 = (phone: string): string => {
        const digits = phone.replace(/\D/g, '');
        if (digits.length === 10) return `+1${digits}`;
        if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
        if (phone.startsWith('+')) return phone;
        return `+1${digits}`;
      };

      // Create language-specific SMS messages FOR CLIENT
      const smsMessageTemplates = {
        en: `AO Globe Life Verification for ${clientName}. Please visit: ${clientApprovalUrl} to start verification process.`,
        es: `Verificación AO Globe Life para ${clientName}. Por favor visite: ${clientApprovalUrl} para iniciar el proceso de verificación.`
      };
      
      const clientSmsMessage = smsMessageTemplates[language as keyof typeof smsMessageTemplates] || smsMessageTemplates.en;

      // Get agent phone from the session data (stored during session creation)
      const agentPhone = session.agentPhone;

      let smsResults = [];

      // 1. SMS to CLIENT for verification - SEND CLIENT APPROVAL URL TO CLIENT
      try {
        const clientPhone = formatE164(session.phone);
        console.log(`📱 Sending client SMS to ${session.phone} -> ${clientPhone} via ${TWILIO_PHONE_NUMBER}`);
        const clientSMS = await twilioClient.messages.create({
          body: clientSmsMessage,
          from: TWILIO_PHONE_NUMBER,
          to: clientPhone
        });
        smsResults.push({ type: 'client', sid: clientSMS.sid, to: clientPhone });
        console.log(`📱 CLIENT SMS sent: ${clientSMS.sid} to ${clientPhone}`);
      } catch (error: any) {
        console.error(`❌ Failed to send client SMS (code=${error?.code}):`, error?.message || error);
      }

      // 2. SMS to AGENT for notification - SEND AGENT DASHBOARD URL TO AGENT
      if (agentPhone) {
        try {
          const agentPhoneFormatted = formatE164(agentPhone);
          const agentMessage = `AO Precheck: New verification session for ${clientName}. Monitor at: ${agentDashboardUrl}`;
          const agentSMS = await twilioClient.messages.create({
            body: agentMessage,
            from: TWILIO_PHONE_NUMBER,
            to: agentPhoneFormatted
          });
          smsResults.push({ type: 'agent', sid: agentSMS.sid, to: agentPhoneFormatted });
          console.log(`📱 AGENT SMS sent: ${agentSMS.sid} to ${agentPhoneFormatted}`);
        } catch (error: any) {
          console.error(`❌ Failed to send agent SMS (code=${error?.code}):`, error?.message || error);
        }
      }

      if (smsResults.length === 0) {
        console.error('❌ No SMS were successfully sent — both client and agent SMS failed');
        return res.status(500).json({ message: 'Failed to send SMS — Twilio rejected all messages. Check server logs for error codes.' });
      }

      await storage.updateVerificationSession(sessionId, {
        smsVerificationSent: true,
      });

      res.json({ 
        message: `${smsResults.length} SMS sent via Twilio`,
        smsResults,
        provider: 'Twilio'
      });
    } catch (error: any) {
      console.error('SMS send error:', error);
      res.status(500).json({ message: "Failed to send SMS verification" });
    }
  });

