  // Approve verification session (client approval)
  app.post("/api/verification/session/:sessionId/approve", async (req, res) => {
    try {
      const { sessionId } = req.params;

      const session = await storage.getVerificationSession(sessionId);
      if (!session) {
        return res.status(404).json({ message: "Verification session not found" });
      }

      // Get client IP address and user agent
      const clientIp = req.ip || req.connection.remoteAddress || 'unknown';
      const userAgent = req.headers['user-agent'] || 'unknown';
      const approvalTime = new Date();

      // Get location data from IP address using IP-API.com (free, no key required)
      let locationData = null;
      try {
        if (clientIp && clientIp !== 'unknown' && clientIp !== '::1' && clientIp !== '127.0.0.1') {
          const geoResponse = await fetch(`http://ip-api.com/json/${clientIp}?fields=status,country,regionName,city,lat,lon,timezone,isp`);
          if (geoResponse.ok) {
            const geoData = await geoResponse.json();
            if (geoData.status === 'success') {
              locationData = geoData;
              console.log(`IP Geolocation for ${clientIp}:`, locationData);
            }
          }
        }
      } catch (geoError) {
        console.warn('IP geolocation lookup failed:', geoError);
      }

      const updatedSession = await storage.updateVerificationSession(sessionId, {
        clientApprovalStatus: 'approved',
        clientIpAddress: clientIp,
        clientUserAgent: userAgent,
        clientApprovalTime: approvalTime,
        // Location data from IP geolocation
        clientCountry: locationData?.country || null,
        clientRegion: locationData?.regionName || null,
        clientCity: locationData?.city || null,
        clientLatitude: locationData?.lat?.toString() || null,
        clientLongitude: locationData?.lon?.toString() || null,
        clientTimezone: locationData?.timezone || null,
        clientIsp: locationData?.isp || null,
      });

      if (!updatedSession) {
        return res.status(404).json({ message: "Failed to update verification session" });
      }

      res.json({ 
        message: "Disclaimer approved successfully",
        approvalTime: approvalTime.toISOString(),
        ipAddress: clientIp,
        location: locationData ? {
          country: locationData.country,
          region: locationData.regionName,
          city: locationData.city,
          coordinates: `${locationData.lat}, ${locationData.lon}`,
          timezone: locationData.timezone,
          isp: locationData.isp
        } : null,
        session: updatedSession 
      });
    } catch (error) {
      console.error('Approval error:', error);
      res.status(500).json({ message: "Failed to approve disclaimer" });
    }
  });

