  // Initiate ZOOM verification call using Taalk API with Zoom bridge dialing
  app.post("/api/verification/initiate-zoom-call", async (req, res) => {
    try {
      const { sessionId, clientInfo, agentPhone: bodyAgentPhone, producerPhone } = req.body;
      const agentPhone = bodyAgentPhone || producerPhone;

      console.log('🎥 ZOOM CALL: Initiating Taalk call via Zoom bridge for session:', sessionId);

      if (!sessionId) {
        return res.status(400).json({ 
          success: false, 
          error: "Session ID is required" 
        });
      }

      const session = await storage.getVerificationSession(sessionId);
      if (!session) {
        return res.status(404).json({ 
          success: false, 
          error: "Verification session not found" 
        });
      }

      // Get agent email from the authenticated session or headers (SAME LOGIC AS SESSION CREATION)
      let agentEmail = null;
      let sessionUser = null;
      
      // Method 1: Check Authorization header for Supabase JWT token
      const authHeader = req.headers.authorization;
      if (authHeader && authHeader.startsWith('Bearer ')) {
        try {
          const token = authHeader.substring(7);
          console.log('🔑 ZOOM: Verifying Supabase JWT token...');
          
          const { data: userResponse, error: authError } = await supabaseAdmin!.auth.getUser(token);
          if (!authError && userResponse?.user?.email) {
            agentEmail = userResponse.user.email;
            sessionUser = { id: userResponse.user.id, email: userResponse.user.email };
            console.log('✅ ZOOM JWT AUTH: Authenticated user via Supabase token:', agentEmail);
          } else {
            console.log('❌ ZOOM JWT AUTH: Token validation failed:', authError?.message);
          }
        } catch (jwtError) {
          console.log('❌ ZOOM JWT AUTH: Token parsing error:', jwtError);
        }
      }
      
      // Method 2: Fallback to session-based authentication  
      if (!agentEmail) {
        sessionUser = (req.session as any)?.user;
        agentEmail = sessionUser?.email;
        
        // Try alternative session paths if main session doesn't work
        if (!agentEmail) {
          console.log('⚠️ ZOOM: Main session.user not found, checking alternative paths');
          sessionUser = (req.session as any)?.passport?.user || req.session;
          agentEmail = sessionUser?.email || sessionUser?.user_email;
        }
        
        // Try headers as backup
        if (!agentEmail) {
          console.log('⚠️ ZOOM: No session email found, checking headers');
          agentEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
        }
        
        if (agentEmail) {
          console.log('✅ ZOOM SESSION AUTH: Authenticated user via session:', agentEmail);
        }
      }
      
      // Final fallback to session data (stored as companyEmail in DB)
      if (!agentEmail && (session as any)?.companyEmail) {
        agentEmail = (session as any).companyEmail;
        console.log('✅ ZOOM DB AUTH: Using email from verification session:', agentEmail);
      }
      
      console.log('🎥 ZOOM CALL: Using agent email:', agentEmail);
      // Get agent profile from Supabase using the authenticated user's email
      const agentProfile = await storage.getAgentProfileByEmail(agentEmail);
      console.log('🎥 ZOOM CALL: Agent profile found:', !!agentProfile);
      
      // Get agent data from session or profile - fix hardcoded defaults
      const realAgentFirstName = agentProfile?.firstName || 'michael';
      const realAgentLastName = agentProfile?.lastName || 'mandella';
      
      // Validate session data against placeholder strings
      const isValidAgentFirstName = session?.agentFirstName && 
                                    session.agentFirstName.toLowerCase() !== 'agent' && 
                                    session.agentFirstName.toLowerCase() !== 'agentfirstname' &&
                                    session.agentFirstName.toLowerCase() !== 'cnsysop' &&
                                    session.agentFirstName.trim().length > 0;
      
      const isValidAgentLastName = session?.agentLastName && 
                                  session.agentLastName.toLowerCase() !== 'name' && 
                                  session.agentLastName.toLowerCase() !== 'agentlastname' &&
                                  session.agentLastName.toLowerCase() !== 'agent' &&
                                  session.agentLastName.trim().length > 0;
      
      const agentFirstName = isValidAgentFirstName ? session.agentFirstName : realAgentFirstName;
      const agentLastName = isValidAgentLastName ? session.agentLastName : realAgentLastName;
      const finalAgentPhone = agentPhone || session?.agentPhone || agentProfile?.phone || '';

      // Prefer VERIFICATION_BASE_URL so Taalk completion callbacks hit new aoprecheck.
      const host = req.get('host');
      const baseUrl =
        process.env.VERIFICATION_BASE_URL ||
        (host ? `https://${host}` : 'https://aoprecheck-production.up.railway.app');
      
      const taalkApiKey = process.env.TAALK_API_KEY || "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJrZXkiOiJ0YWFsay4zN2RhMGU2NS1kMGVjLTQxYWYtOGQzYi03MWRjNTJiNGNiMmYiLCJuYW1lIjoidGFhbGsiLCJleHAiOjIwNTUwMzU2OTJ9.Ywh89Z0PvELHylJReZo8KPOiL7xX21BoBYe16OZfJw4";
      
      // Taalk agent ID based on language
      const TAALK_AGENT_ID_SPANISH = '66461a241e0b08270180af7a';
      const TAALK_AGENT_ID_ENGLISH = '68a5ff0fc8f1520e59acf3e6';
      const taalkAgentId = session?.language === 'es' ? TAALK_AGENT_ID_SPANISH : TAALK_AGENT_ID_ENGLISH;
      
      // Get zoom credentials: session first, then agent_profiles (camelCase from storage.getAgentProfileByEmail).
      // Also accept body zoom fields from the working startVerificationCall / unified payload.
      const zoomRoomId =
        session?.zoomRoomId ||
        req.body?.zoomRoomId ||
        clientInfo?.zoomRoomId ||
        agentProfile?.zoomId ||
        (agentProfile as any)?.zoom_id ||
        '';
      const zoomPassword =
        session?.zoomPassword ||
        req.body?.zoomPassword ||
        clientInfo?.zoomPassword ||
        agentProfile?.zoomPassword ||
        (agentProfile as any)?.zoom_password ||
        '1';
      
      // ZOOM BRIDGE PHONE FORMAT: calls Zoom bridge and auto-enters room credentials 
      const zoomBridgePhone = `6692192599,,${zoomRoomId}#,,#,,${zoomPassword}#`;
      
      console.log('🎥 ZOOM CALL: Using Zoom bridge phone:', zoomBridgePhone);
      console.log('🎥 ZOOM CALL: Zoom room ID:', zoomRoomId, 'Password:', zoomPassword);
      if (!zoomRoomId) {
        console.error('❌ ZOOM CALL: Missing zoomRoomId — Taalk bridge dial will fail');
        return res.status(400).json({
          success: false,
          error: 'Zoom Room ID is required. Save your Zoom Room ID in Producer Profile, then retry.',
        });
      }

      // Format agent phone for E.164 (for parameters)
      let formattedAgentPhone = finalAgentPhone;
      if (formattedAgentPhone && !formattedAgentPhone.startsWith('+')) {
        const digits = formattedAgentPhone.replace(/\D/g, '');
        if (digits.length === 10) {
          formattedAgentPhone = `+1${digits}`;
        } else if (digits.length === 11 && digits.startsWith('1')) {
          formattedAgentPhone = `+${digits}`;
        } else {
          formattedAgentPhone = `+1${digits}`;
        }
      }

      // For non-Zoom calls, format client phone number  
      const clientPhone = session?.phone || clientInfo?.phone || '';
      const cleanClientPhone = clientPhone.replace(/[^0-9]/g, '');
      
      // Use CORRECT Taalk API format with name, phone, agent, retryMethod, force, params
      const callParams = {
        name: `${session.firstName} ${session.lastName}`,
        phone: zoomBridgePhone,
        agent: taalkAgentId,
        retryMethod: 0,
        force: true,
        webhookUrl: `${baseUrl}/api/taalk/webhook`,
        params: {
          // All script variables as custom fields
          Taalk_AgentFirstName: agentFirstName,
          Taalk_AgentLastName: agentLastName,
          Taalk_AgentPhone: formattedAgentPhone || '',
          Taalk_AgentEmail: agentEmail,
          Taalk_ZoomId: zoomRoomId,
          Taalk_ZoomPassword: zoomPassword,
          Taalk_MemberFirstName: session.firstName,
          Taalk_MemberFiirstName: session.firstName, // Script typo version
          Taalk_MemberPhone: session.phone,
          Taalk_PMemberFirstName: session.firstName,
          MemberFirstName: session.firstName, // Used in script without Taalk_ prefix
          Taalk_ClientName: `${session.firstName} ${session.lastName}`,
          Taalk_ClientPhone: session.phone,
          Taalk_MonthlyPremium: session?.premium || '',
          Taalk_ALP: session?.premium || '', // Script uses {Taalk_ALP} for monthly amount
          Taalk_ACHdrawdate: session?.achDrawDate || '',
          Taalk_ACHdrawdateshort: session?.achDrawDateShort || '',
          Taalk_Location: `${session.city || ''}, ${session.state || ''}`.trim().replace(/^,\s*|,\s*$/g, ''),
          Taalk_ClientCountry: 'United States',
          Taalk_ClientRegion: session.state || '',
          Taalk_ClientCity: session.city || '',
          Taalk_SessionId: sessionId,
          Taalk_VerificationMethod: 'Zoom Call',
          Taalk_CallTimestamp: new Date().toISOString(),
          Taalk_CompanyName: process.env.COMPANY_NAME || agentProfile?.companyName || 'Globe Life AIL Division',
          Taalk_AssociateId: agentProfile?.associate_id?.toString() || ''
        }
      };

      console.log('🎥 ZOOM CALL: Using CORRECT Taalk API format (name/phone/agent/retryMethod/params):', JSON.stringify(callParams, null, 2));

      // Use the CORRECT endpoint: POST /call with db parameter  
      const taalkResponse = await fetch(`https://api.taalk.ai/api/call?db=michaelmandella`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${taalkApiKey}`
        },
        body: JSON.stringify(callParams)
      });

      const responseText = await taalkResponse.text();
      console.log('🎥 ZOOM CALL: Taalk API response:', taalkResponse.status, responseText);

      if (!taalkResponse.ok) {
        console.error('❌ ZOOM CALL: Taalk API error:', taalkResponse.status, responseText);
        console.error('🎥 ZOOM CALL: Full error response body:', responseText);
        console.error('🎥 ZOOM CALL: Request payload that failed:', JSON.stringify(callParams, null, 2));
        return res.status(500).json({
          success: false,
          error: `Taalk API error: ${taalkResponse.status} - ${responseText}`
        });
      }

      let taalkResult;
      try {
        taalkResult = JSON.parse(responseText);
        console.log('✅ ZOOM CALL: Taalk call initiated successfully via Zoom bridge', taalkResult);
        console.log('🔍 ZOOM TAALK RESPONSE DEBUG:', {
          hasPayload: !!taalkResult.payload,
          payloadId: taalkResult.payload?.id,
          callId: taalkResult.callId,
          id: taalkResult.id,
          fullResponse: JSON.stringify(taalkResult, null, 2)
        });
      } catch (parseError) {
        console.log('✅ ZOOM CALL: Taalk call initiated (non-JSON response):', responseText);
        taalkResult = { callId: `fallback_zoom_${Date.now()}`, status: 'initiated' };
      }

      // Extract the ACTUAL Taalk call ID from response (NEVER use verification sessionId!)
      const actualTaalkCallId = taalkResult.payload?.id || taalkResult.callId || taalkResult.id || null;
      
      // Generate a unique fallback ID that is clearly NOT the verification session ID
      const fallbackCallId = `taalk_zoom_${Date.now()}_${Math.random().toString(36).substring(7)}`;
      
      console.log('🔍 ZOOM TAALK CALL ID EXTRACTION:', {
        payloadId: taalkResult.payload?.id,
        callId: taalkResult.callId,
        responseId: taalkResult.id,
        extractedId: actualTaalkCallId,
        willUseFallback: !actualTaalkCallId,
        fallbackId: fallbackCallId
      });

      // Update session with call information
      await storage.updateVerificationSession(sessionId, {
        taalkCallId: actualTaalkCallId || fallbackCallId,
        taalkCallStatus: 'initiated',
        taalkCallInitiatedAt: new Date().toISOString(),
        callCompleted: false
      });

      res.json({
        success: true,
        message: "Zoom call initiated successfully via Taalk bridge",
        callId: taalkResult.callId || taalkResult.id || `zoom_${sessionId}_${Date.now()}`,
        sessionId,
        zoomRoomId,
        zoomPassword,
        taalkResult
      });

    } catch (error: any) {
      console.error('❌ ZOOM CALL: Failed to initiate Taalk Zoom call:', error);
      res.status(500).json({
        success: false,
        error: error.message || "Failed to initiate Zoom call"
      });
    }
  });

