  // Agent messaging endpoint for waiting room
  app.post('/api/agent-message', async (req, res) => {
    try {
      const { roomId, message, agentName } = req.body;
      
      if (!roomId || !message) {
        return res.status(400).json({
          success: false,
          error: 'roomId and message are required'
        });
      }
      
      console.log(`📢 Agent ${agentName || 'Unknown'} sending message to room ${roomId}: ${message}`);
      
      // Create message data
      const messageData = {
        type: 'agent_message',
        roomId: roomId.trim(),
        message: message.trim(),
        agentName: agentName || 'Agent',
        timestamp: new Date().toISOString()
      };
      
      // Send directly through WebSocket if available
      if (videoWebSocketServer && videoWebSocketServer.clients) {
        let messagesSent = 0;
        videoWebSocketServer.clients.forEach((client: any) => {
          if (client.readyState === 1) { // WebSocket.OPEN
            try {
              client.send(JSON.stringify(messageData));
              messagesSent++;
            } catch (error) {
              console.error('Error sending message to WebSocket client:', error);
            }
          }
        });
        console.log(`✅ Agent message sent to ${messagesSent} WebSocket clients`);
      } else {
        console.log('⚠️ WebSocket server not available, message stored for later delivery');
      }
      
      res.json({
        success: true,
        message: 'Agent message queued for delivery',
        roomId: roomId.trim(),
        agentName: agentName || 'Agent'
      });
      
    } catch (error) {
      console.error('❌ Failed to send agent message:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to send agent message',
        details: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // 🔥 NEW: Get agent notifications
  app.get("/api/notifications", async (req, res) => {
    try {
      // Try session first (for legacy auth)
      const sessionUser = (req.session as any).user;
      // Also check headers (for Supabase auth)
      const headerEmail = req.headers['user-email'] || req.headers['x-user-email'];
      
      let agentEmail: string | null = null;
      
      if (sessionUser?.email) {
        agentEmail = sessionUser.email.toLowerCase();
        console.log('🔔 /api/notifications - Using session email:', agentEmail);
      } else if (headerEmail) {
        agentEmail = (headerEmail as string).toLowerCase();
        console.log('🔔 /api/notifications - Using header email:', agentEmail);
      }
      
      if (!agentEmail) {
        console.log('❌ /api/notifications - No authentication found (session or header)');
        return res.status(401).json({ error: 'Not authenticated' });
      }
      console.log('🔔 /api/notifications - Fetching for:', agentEmail);
      
      const limit = parseInt(req.query.limit as string) || 50;
      const unreadOnly = req.query.unreadOnly === 'true';

      let query = supabaseAdmin
        .from('agent_notifications')
        .select('*')
        .eq('agent_email', agentEmail)
        .order('created_at', { ascending: false })
        .limit(limit);

      if (unreadOnly) {
        query = query.eq('read', false);
      }

      const { data: notifications, error } = await query;

      if (error) {
        console.error('❌ Error fetching notifications:', error);
        return res.status(500).json({ error: 'Failed to fetch notifications' });
      }

      const allNotifications = notifications || [];

      console.log('🔔 /api/notifications - Found', allNotifications.length, 'notifications for', agentEmail);

      const { data: allUnreadNotifications } = await supabaseAdmin
        .from('agent_notifications')
        .select('*')
        .eq('agent_email', agentEmail)
        .eq('read', false);

      const unreadCount = (allUnreadNotifications || []).length;

      console.log('🔔 /api/notifications - Unread count:', unreadCount);

      res.json({
        notifications: allNotifications,
        unreadCount: unreadCount || 0,
      });
    } catch (error) {
      console.error('Error in /api/notifications:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // 🔥 NEW: Mark notification as read
  app.post("/api/notifications/:id/read", async (req, res) => {
    try {
      const sessionUser = (req.session as any).user;
      if (!sessionUser?.email) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const notificationId = req.params.id;
      const agentEmail = sessionUser.email.toLowerCase();

      // Verify notification belongs to agent
      const { data: notification, error: fetchError } = await supabaseAdmin
        .from('agent_notifications')
        .select('agent_email')
        .eq('id', notificationId)
        .maybeSingle();

      if (fetchError || !notification) {
        return res.status(404).json({ error: 'Notification not found' });
      }

      if (notification.agent_email !== agentEmail) {
        return res.status(403).json({ error: 'Unauthorized' });
      }

      const { error: updateError } = await supabaseAdmin
        .from('agent_notifications')
        .update({
          read: true,
          read_at: new Date().toISOString(),
        })
        .eq('id', notificationId);

      if (updateError) {
        console.error('❌ Error marking notification as read:', updateError);
        return res.status(500).json({ error: 'Failed to update notification' });
      }

      res.json({ success: true });
    } catch (error) {
      console.error('Error in /api/notifications/:id/read:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

