  // Profile picture upload endpoint
  app.post("/api/agent/upload-profile-picture", upload.single('profilePicture'), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No file uploaded" });
      }

      const sessionEmail =
        (req as any)?.session?.user?.email ||
        (req as any)?.user?.email ||
        '';
      const userEmail = String((req.body?.userEmail || req.headers['x-user-email'] || sessionEmail || '') as string).toLowerCase().trim();
      if (!userEmail) {
        return res.status(400).json({ error: "userEmail is required" });
      }

      const ext = path.extname(req.file.originalname || '').toLowerCase() || '.jpg';
      const safeExt = ['.jpg', '.jpeg', '.png', '.webp'].includes(ext) ? ext : '.jpg';
      const objectPath = `profile-pictures/${encodeURIComponent(userEmail)}/${Date.now()}${safeExt}`;
      let profilePictureUrl = '';

      const fileBytes = req.file.path ? fsSync.readFileSync(req.file.path) : null;
      if (!fileBytes) {
        return res.status(500).json({ error: "Failed to read uploaded file" });
      }

      // Persist image in Supabase Storage so portraits survive restarts/deploys.
      const { error: uploadError } = await supabaseAdmin.storage
        .from('installers')
        .upload(objectPath, fileBytes, {
          contentType: req.file.mimetype || 'image/jpeg',
          upsert: true,
        });
      if (uploadError) {
        return res.status(500).json({ error: `Supabase upload failed: ${uploadError.message}` });
      }
      const { data: publicData } = supabaseAdmin.storage
        .from('installers')
        .getPublicUrl(objectPath);
      if (!publicData?.publicUrl) {
        return res.status(500).json({ error: "Supabase public URL unavailable after upload" });
      }
      profilePictureUrl = publicData.publicUrl;

      // Save the URL in agent_profiles (source of truth for card portraits).
      const updatedProfile = await storage.updateAgentProfileByEmail(userEmail, { profilePicture: profilePictureUrl });
      if (!updatedProfile) {
        return res.status(500).json({ error: "Uploaded image but failed to save profile_picture in Supabase profile row" });
      }
      if (req.file.path) {
        fsSync.unlink(req.file.path, () => {});
      }
      
      res.json({ 
        success: true, 
        profilePictureUrl,
        message: "Profile picture uploaded successfully"
      });
    } catch (error) {
      console.error("Profile picture upload error:", error);
      res.status(500).json({ error: "Failed to upload profile picture" });
    }
  });

