  // Direct agent profile PATCH endpoint (for Producer Setup modal)
  app.patch("/api/agent/profile-direct", async (req, res) => {
    try {
      const { userEmail, ...updates } = req.body;
      console.log('🔥 DIRECT PATCH - User email:', userEmail);
      console.log('🔥 DIRECT PATCH - Updates:', updates);
      
      if (!userEmail) {
        return res.status(400).json({ message: "Email required" });
      }

      // Map frontend field names to database field names
      const updateData: any = {};
      if (updates.firstName !== undefined) updateData.firstName = updates.firstName;
      if (updates.lastName !== undefined) updateData.lastName = updates.lastName;
      if (updates.phone !== undefined) updateData.phone = updates.phone;
      if (updates.zoomId !== undefined) updateData.zoomId = updates.zoomId;
      if (updates.zoomPassword !== undefined) updateData.zoomPassword = updates.zoomPassword;
      if (updates.mgaTeam !== undefined) updateData.mgaTeam = updates.mgaTeam;
      if (updates.rgaTeam !== undefined) updateData.rgaTeam = updates.rgaTeam;
      if (updates.profilePicture !== undefined) updateData.profilePicture = updates.profilePicture;

      // Try to update existing profile first
      let profile = await storage.getAgentProfileByEmail(userEmail);
      
      if (profile) {
        // Update existing
        const updatedProfile = await storage.updateAgentProfileByEmail(userEmail, updateData);
        console.log('🔥 DIRECT PATCH - Updated existing profile');
        if (!updatedProfile) {
          return res.status(500).json({ message: "Failed to update profile" });
        }
        const dupAfter = await storage.countAgentProfilesForEmail(userEmail);
        res.json({
          firstName: updatedProfile.firstName || '',
          lastName: updatedProfile.lastName || '',
          phone: updatedProfile.phone || '',
          zoomId: updatedProfile.zoomId || '',
          zoomPassword: updatedProfile.zoomPassword || '1',
          mgaTeam: updatedProfile.mgaTeam || '',
          rgaTeam: updatedProfile.rgaTeam || '',
          profilePicture: updatedProfile.profilePicture || '',
          duplicateProfileCount: dupAfter,
        });
      } else {
        // Create new profile
        const newProfile = await storage.createAgentProfileWithEmail({
          email: userEmail,
          firstName: updates.firstName || '',
          lastName: updates.lastName || '',
          phone: updates.phone || '',
          zoomId: updates.zoomId || '',
          zoomPassword: updates.zoomPassword || '1',
          mgaTeam: updates.mgaTeam || '',
          rgaTeam: updates.rgaTeam || ''
        });
        console.log('🔥 DIRECT PATCH - Created new profile');
        const dupAfterCreate = await storage.countAgentProfilesForEmail(userEmail);
        res.json({
          firstName: newProfile.firstName || '',
          lastName: newProfile.lastName || '',
          phone: newProfile.phone || '',
          zoomId: newProfile.zoomId || '',
          zoomPassword: newProfile.zoomPassword || '1',
          mgaTeam: newProfile.mgaTeam || '',
          rgaTeam: newProfile.rgaTeam || '',
          profilePicture: newProfile.profilePicture || '',
          duplicateProfileCount: dupAfterCreate,
        });
      }
    } catch (error) {
      console.error('Direct patch agent profile error:', error);
      res.status(500).json({ message: "Failed to update agent profile" });
    }
  });

