  // Alex AI / Help actions (Change Market, Add States, Fix VDP, etc.)
  app.post("/api/alex-ai/actions", express.json(), async (req, res) => {
    try {
      const { userEmail, action, parameters } = req.body || {};
      if (!userEmail || !action) {
        return res.status(400).json({ error: 'userEmail and action are required' });
      }
      const agentEmail = (parameters?.agentEmail || userEmail).toString().toLowerCase().trim();
      const requestEmail = userEmail.toString().toLowerCase().trim();
      const isSelf = requestEmail === agentEmail;
      const isSysop = [
        'cnsysop@aoglobelife.com',
        'nateschoot@aoglobelife.com',
        'chrislafond@aoglobelife.com',
        'michaelmandella@aoglobelife.com',
        'mmandella@ailpdx.com',
      ].includes(requestEmail);

      if (action === 'change_market') {
        const marketLabel = (parameters?.market || '').toString().trim();
        if (!marketLabel) {
          return res.status(400).json({ error: 'market is required for change_market' });
        }
        if (!isSelf && !isSysop) {
          return res.status(403).json({ error: 'You can only change your own market, or use a sysop account' });
        }
        if (!supabaseAdmin) {
          return res.status(500).json({ error: 'Database not available' });
        }
        const marketValue = marketLabel === 'AO Recruit' ? 'aorecruit' : marketLabel === 'Veteran' ? 'Veteran' : marketLabel === 'Globe' ? 'Globe Market' : marketLabel;
        const marketArray = Array.isArray(marketValue) ? marketValue : [marketValue];
        let customerId: number | null = null;
        const { data: byCompany } = await supabaseAdmin.from('customers').select('id').eq('company_email', agentEmail).limit(1).maybeSingle();
        if (byCompany?.id) customerId = byCompany.id;
        if (!customerId) {
          const { data: byPersonal } = await supabaseAdmin.from('customers').select('id').eq('personal_email', agentEmail).limit(1).maybeSingle();
          if (byPersonal?.id) customerId = byPersonal.id;
        }
        if (!customerId) {
          return res.status(404).json({ error: 'Customer record not found for this email' });
        }
        const { error: updateError } = await supabaseAdmin
          .from('customers')
          .update({
            market: marketArray,
            updated_at: new Date().toISOString()
          })
          .eq('id', customerId);
        if (updateError) {
          console.error('change_market update error:', updateError);
          return res.status(500).json({ error: 'Failed to update market', details: updateError.message });
        }
        console.log(`✅ Market updated for ${agentEmail} to ${JSON.stringify(marketArray)}`);
        return res.json({
          success: true,
          action: 'change_market',
          result: { message: `Market updated to ${marketLabel}. Log out and back in (or refresh) to see changes.` }
        });
      }

      if (action === 'add_licensed_states') {
        if (!isSelf && !isSysop) {
          return res.status(403).json({ error: 'You can only update your own licensed states, or use a sysop account' });
        }
        if (!supabaseAdmin) {
          return res.status(500).json({ error: 'Database not available' });
        }
        const rawStates = Array.isArray(parameters?.states) ? parameters.states : [];
        const normalizedStates = Array.from(new Set<string>(
          rawStates
            .map((s: any) => String(s || '').trim().toUpperCase())
            .filter((s: string) => /^[A-Z]{2}$/.test(s))
        )).sort();

        let customer: { id: number; states: unknown } | null = null;
        const { data: byCompany } = await supabaseAdmin
          .from('customers')
          .select('id, states')
          .eq('company_email', agentEmail)
          .limit(1)
          .maybeSingle();
        if (byCompany?.id) customer = byCompany as any;
        if (!customer) {
          const { data: byPersonal } = await supabaseAdmin
            .from('customers')
            .select('id, states')
            .eq('personal_email', agentEmail)
            .limit(1)
            .maybeSingle();
          if (byPersonal?.id) customer = byPersonal as any;
        }
        if (!customer) {
          return res.status(404).json({ error: 'Customer record not found for this email' });
        }

        const previousStates = Array.isArray(customer.states)
          ? customer.states.map((s: any) => String(s || '').trim().toUpperCase()).filter((s: string) => /^[A-Z]{2}$/.test(s))
          : [];
        const removed = previousStates.filter((s: string) => !normalizedStates.includes(s));
        const added = normalizedStates.filter((s: string) => !previousStates.includes(s));

        let { error: updateError } = await supabaseAdmin
          .from('customers')
          .update({
            states: normalizedStates,
            updated_at: new Date().toISOString(),
          })
          .eq('id', customer.id);

        // Some customer tables/environments may not have updated_at; retry with states-only.
        if (updateError && /updated_at/i.test(String(updateError.message || ''))) {
          console.warn('add_licensed_states: updated_at missing, retrying states-only update');
          const retry = await supabaseAdmin
            .from('customers')
            .update({
              states: normalizedStates,
            })
            .eq('id', customer.id);
          updateError = retry.error;
        }

        if (updateError) {
          console.error('add_licensed_states update error:', updateError);
          return res.status(500).json({ error: 'Failed to update states', details: updateError.message });
        }

        try {
          await pool.query(
            `
              INSERT INTO agent_routing_profiles (agent_email, states, source, updated_at)
              VALUES ($1, $2::text[], 'support_widget', NOW())
              ON CONFLICT (agent_email)
              DO UPDATE SET states = EXCLUDED.states,
                            source = EXCLUDED.source,
                            updated_at = NOW()
            `,
            [agentEmail, normalizedStates],
          );
        } catch (routingError) {
          console.warn('add_licensed_states routing profile mirror failed:', routingError);
        }

        return res.json({
          success: true,
          action: 'add_licensed_states',
          result: {
            message: `Licensed states updated. Added ${added.length}, removed ${removed.length}. Log out and back in (or refresh) to see changes.`,
            previous: previousStates,
            current: normalizedStates,
            added,
            removed,
          }
        });
      }

      if (action === 'fix_vdp_profile' || action === 'reset_agent_password') {
        return res.status(400).json({
          error: 'This action is not available here. Use support flow for VDP/profile or contact support for password reset.',
          action
        });
      }

      return res.status(400).json({ error: `Unknown action: ${action}` });
    } catch (e: any) {
      console.error('alex-ai/actions error:', e);
      return res.status(500).json({ error: e?.message || 'Action failed' });
    }
  });

  // Get agent team options (MGA/RGA)
  app.get("/api/agent/team-options", async (req, res) => {
    try {
      if (!supabase) {
        return res.status(500).json({ error: 'Database not available' });
      }

      console.log('🏢 Fetching unique MGA/RGA team options from producerlist table...');

      // Fetch all MGA values with pagination (10000 limit)
      const { data: mgaData, error: mgaError } = await supabase
        .from('producerlist')
        .select('mga')
        .not('mga', 'is', null)
        .neq('mga', '')
        .limit(10000);

      if (mgaError) {
        console.error('❌ Error fetching MGA teams from producerlist:', mgaError);
        return res.status(500).json({ error: 'Failed to fetch MGA teams' });
      }

      // Fetch all RGA values with pagination (10000 limit)
      const { data: rgaData, error: rgaError } = await supabase
        .from('producerlist')
        .select('rga')
        .not('rga', 'is', null)
        .neq('rga', '')
        .limit(10000);

      if (rgaError) {
        console.error('❌ Error fetching RGA teams from producerlist:', rgaError);
        return res.status(500).json({ error: 'Failed to fetch RGA teams' });
      }

      // Extract unique values and sort alphabetically
      const mgaOptions = [...new Set(mgaData?.map(item => item.mga).filter(Boolean) || [])].sort();
      const rgaOptions = [...new Set(rgaData?.map(item => item.rga).filter(Boolean) || [])].sort();

      console.log(`✅ Found ${mgaOptions.length} unique MGA teams and ${rgaOptions.length} unique RGA teams from producerlist`);

      res.json({
        mgaOptions,
        rgaOptions
      });

    } catch (error) {
      console.error('❌ Error fetching team options from producerlist:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Get agent's associate_id by email
  app.get("/api/agent/associate-id", async (req, res) => {
    try {
      const userEmail = req.query.email as string || (req.session as any)?.user?.email;
      
      if (!userEmail) {
        return res.status(400).json({ error: 'Email required' });
      }
      
      console.log(`🔍 Looking up associate_id for: ${userEmail}`);
      
      // Try producerlist table FIRST
      const { data: producerlistData, error: producerlistError } = await supabaseAdmin!
        .from('producerlist')
        .select('associate_id')
        .eq('company_email', userEmail)
        .single();
      
      if (producerlistData && producerlistData.associate_id) {
        console.log(`✅ Found in producerlist: ${producerlistData.associate_id} for ${userEmail}`);
        return res.json({ associate_id: producerlistData.associate_id, email: userEmail, found: true, source: 'producerlist' });
      }
      
      // Fallback to producers table
      const { data: producerData, error: producerError } = await supabaseAdmin!
        .from('producers')
        .select('associate_id')
        .eq('email', userEmail)
        .single();
      
      if (producerData && producerData.associate_id) {
        console.log(`✅ Found in producers: ${producerData.associate_id} for ${userEmail}`);
        return res.json({ associate_id: producerData.associate_id, email: userEmail, found: true, source: 'producers' });
      }
      
      console.log(`❌ No producer found for ${userEmail} in either table, returning default 999`);
      res.json({ associate_id: "999", email: userEmail, found: false });
      
    } catch (error) {
      console.error('❌ Error fetching associate_id:', error);
      res.status(500).json({ error: 'Internal server error', associate_id: "999" });
    }
  });

  // Agent Recent Connects — VDP END events + Twilio call logs >45s for the Recent Connects slide
  app.get("/api/agent/recent-connects", async (req, res) => {
    try {
      const email: string | undefined =
        (req.query.email as string) ||
        (req.headers['x-user-email'] as string) ||
        (req.session as any)?.user?.email;
      if (!email) return res.status(400).json({ events: [] });

      const limit = Math.min(15, parseInt(String(req.query.limit || 10), 10) || 10);

      // Resolve associate_id
      const { data: producer } = await supabaseAdmin!
        .from('producerlist')
        .select('associate_id, name, market')
        .eq('company_email', email)
        .maybeSingle();

      const assocId = producer?.associate_id;

      const todayStart = new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate()).toISOString();

      // VDP calls — END events today (only if we have associate_id)
      let vdpRows: any[] = [];
      if (assocId) {
        const { data } = await supabaseAdmin!
          .from('vdp_calls')
          .select('id, time, market, state, duration')
          .eq('agent', String(assocId))
          .or('event.eq.END,event.eq.end')
          .gte('time', todayStart)
          .order('time', { ascending: false })
          .limit(limit);
        vdpRows = data || [];
      }

      // Twilio call logs — outbound >45s today
      const { data: twilioRows } = await supabaseAdmin!
        .from('twilio_call_logs')
        .select('id, call_started_at, call_duration, market, state, lead_name')
        .eq('owner_email', email)
        .eq('call_direction', 'outbound')
        .gte('call_duration', 45)
        .gte('call_started_at', todayStart)
        .order('call_started_at', { ascending: false })
        .limit(limit);

      // Merge and sort by time desc
      const merged: any[] = [
        ...(vdpRows || []).map((r: any) => ({
          id: `vdp-${r.id}`,
          connectedAt: r.time,
          agentName: producer?.name || '',
          market: r.market || '',
          state: r.state || '',
          source: 'vdp',
          durationSeconds: Number(r.duration) || undefined,
        })),
        ...(twilioRows || []).map((r: any) => ({
          id: `twilio-${r.id}`,
          connectedAt: r.call_started_at,
          agentName: producer?.name || '',
          market: r.market || '',
          state: r.state || '',
          source: 'twilio',
          durationSeconds: Number(r.call_duration) || undefined,
          leadName: r.lead_name || null,
        })),
      ].sort((a, b) => new Date(b.connectedAt).getTime() - new Date(a.connectedAt).getTime())
       .slice(0, limit);

      res.json({ events: merged, lastHourCount: merged.length });
    } catch (err) {
      console.error('❌ /api/agent/recent-connects error:', err);
      res.json({ events: [] });
    }
  });

  // Debug: check raw vdp_calls data for an email
  app.get("/api/debug/vdp-calls", async (req, res) => {
    const email = req.query.email as string;
    if (!email) return res.json({ error: 'email required' });
    const { data: byEmail } = await supabaseAdmin!.from('vdp_calls').select('id, time, event, company_email, agent, market, duration').eq('company_email', email).order('time', { ascending: false }).limit(10);
    const { data: recent } = await supabaseAdmin!.from('vdp_calls').select('id, time, event, company_email, agent, market, duration').or('event.eq.END,event.eq.end').order('time', { ascending: false }).limit(5);
    res.json({ byEmail, recentGlobal: recent });
  });

  // ─── Consolidated panel data endpoint ────────────────────────────────────────
  // Returns both recent-connects events AND my-stats in one round-trip.
  // Frontend calls /api/agent/panel-data instead of two separate endpoints.
  app.get("/api/agent/panel-data", async (req, res) => {
    try {
      const email: string | undefined =
        (req.query.email as string) ||
        (req.headers['x-user-email'] as string) ||
        (req.session as any)?.user?.email;
      if (!email) return res.status(401).json({ error: 'Unauthorized' });

      const limit = Math.min(15, parseInt(String(req.query.limit || 10), 10) || 10);
      const now = new Date();
      // Use EST midnight (UTC-5) so "today" matches agent timezone, not server UTC
      const estOffset = 5 * 60 * 60 * 1000;
      const nowEst = new Date(now.getTime() - estOffset);
      const todayStart = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate()) + estOffset).toISOString();
      const weekStart  = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate() - nowEst.getUTCDay()) + estOffset).toISOString();
      // Recent connects look back 14 days (was 7 — too easy to look "dead")
      const connectsLookback = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString();
      const alp30dStartIso = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
      const alp30dStartMs = new Date(alp30dStartIso).getTime();
      const todayStartMs = new Date(todayStart).getTime();
      const normEmail = String(email).trim().toLowerCase();
      const marketParam = String(req.query.market || '').trim().toLowerCase();
      const recruitFeed =
        marketParam.includes('recruit') ||
        marketParam.includes('aorecruit') ||
        marketParam === 'ao recruit';

      const assocQueryOverrideRaw = req.query.associate_id ?? req.query.associateId;
      const assocQueryOverride =
        assocQueryOverrideRaw != null && String(assocQueryOverrideRaw).trim() !== ''
          ? String(assocQueryOverrideRaw).trim()
          : null;

      // ── Per-agent stats cache (8s TTL) ─────────────────────────────────────
      // Return cached full response if fresh — avoids 7 Supabase queries per poll
      const agentStatsCacheKey = `${normEmail}:${marketParam}`;
      if (!assocQueryOverride) {
        const statsCacheHit = panelAgentStatsCache.get(agentStatsCacheKey);
        if (statsCacheHit && Date.now() < statsCacheHit.expires) {
          return res.json(statsCacheHit.payload);
        }
      }

      // ── Per-agent profile cache (60s TTL) ──────────────────────────────────
      // producerlist/agent_profiles/customers rarely change — cache for 60s
      let assocId: string | null = assocQueryOverride;
      let agentName: string | null = null;
      let market: string = '';
      let agentIdsUnique: (string | number)[] = [];
      let profilePicture: string | null = null;

      const profileCacheHit = panelAgentProfileCache.get(normEmail);
      if (profileCacheHit && Date.now() < profileCacheHit.expires && !assocQueryOverride) {
        assocId = assocId ?? profileCacheHit.assocId;
        agentName = profileCacheHit.agentName;
        market = profileCacheHit.market;
        agentIdsUnique = profileCacheHit.agentIdsUnique;
        profilePicture = profileCacheHit.profilePicture ?? null;
      } else {
        // Run producer + profile + customer (associate_id often only on customers)
        const [{ data: producer }, { data: agentProfile }, { data: customerRow }] = await Promise.all([
          withPostgrestTimeout(
            'producerlist',
            supabaseAdmin!.from('producerlist').select('associate_id, name, mga, market').ilike('company_email', normEmail).maybeSingle(),
          ),
          withPostgrestTimeout(
            'agent_profiles',
            supabaseAdmin!.from('agent_profiles').select('profile_picture, first_name, last_name').ilike('email', normEmail).maybeSingle(),
          ),
          withPostgrestTimeout(
            'customers',
            supabaseAdmin!.from('customers').select('associate_id').or(`company_email.ilike.${normEmail},personal_email.ilike.${normEmail}`).maybeSingle(),
          ),
        ]);

        agentName = (producer as any)?.name ||
          [(agentProfile as any)?.first_name, (agentProfile as any)?.last_name].filter(Boolean).join(' ') ||
          null;

        const assocIdFromDb =
          (producer as any)?.associate_id != null
            ? String((producer as any).associate_id)
            : (customerRow as any)?.associate_id != null
              ? String((customerRow as any).associate_id)
              : null;

        if (assocId == null) assocId = assocIdFromDb;

        const rawMarket = (producer as any)?.market;
        market = Array.isArray(rawMarket)
          ? (rawMarket.filter(Boolean)[0] || '')
          : typeof rawMarket === 'string'
            ? (() => { try { const p = JSON.parse(rawMarket); return Array.isArray(p) ? p[0] : rawMarket; } catch { return rawMarket; } })()
            : '';

        const agentIdsForVdp: (string | number)[] = [];
        if (assocId != null && String(assocId).trim() !== "") {
          const s = String(assocId).trim();
          agentIdsForVdp.push(s);
          const n = Number(s);
          if (Number.isFinite(n)) agentIdsForVdp.push(n);
        }
        agentIdsUnique = [...new Set(agentIdsForVdp)];

        profilePicture = (agentProfile as any)?.profile_picture ?? null;

        // Store in profile cache
        panelAgentProfileCache.set(normEmail, {
          expires: Date.now() + PANEL_AGENT_PROFILE_TTL,
          assocId,
          agentName,
          market,
          agentIdsUnique,
          profilePicture,
        });
      }

      // Supabase `vdp_calls` has no `city` column — selecting it breaks panel-data ticker queries.
      const vdpSelect = 'id, time, market, state, duration, company_email, agent';
      const vdpEndOr = 'event.eq.END,event.eq.end';

      // Market scope for the Recent Connects ticker (company-wide, not "this agent only")
      const scopeMarket = String(marketParam || market || '').trim();

      const tickerKey = panelTickerCacheKey(recruitFeed, scopeMarket, connectsLookback);
      const tickerHit = panelDataTickerCache.get(tickerKey);
      const tickerFresh = tickerHit && Date.now() < tickerHit.expires;

      const vdpCompanyTickerPromise = tickerFresh
        ? Promise.resolve({ data: tickerHit!.vdp, error: null } as any)
        : recruitFeed
          ? supabaseAdmin!.from('vdp_calls').select(vdpSelect)
              .or(vdpEndOr)
              .or('market.ilike.%aorecruit%,market.ilike.%ao recruit%')
              .gte('time', connectsLookback)
              .order('time', { ascending: false })
              .limit(75)
          : (() => {
              let q = supabaseAdmin!.from('vdp_calls').select(vdpSelect).or(vdpEndOr).gte('time', connectsLookback);
              if (scopeMarket) q = q.ilike('market', `%${scopeMarket}%`);
              return q.order('time', { ascending: false }).limit(75);
            })();

      const iseCompanyTickerPromise = tickerFresh
        ? Promise.resolve({ data: tickerHit!.ise, error: null } as any)
        : (() => {
            let q = supabaseAdmin!.from('inbound_success_events').select('id, agent_name, agent_id, market, state, connected_at')
              .gte('connected_at', connectsLookback);
            if (recruitFeed) {
              q = q.or('market.ilike.%aorecruit%,market.ilike.%ao recruit%,market.ilike.%recruit%');
            } else if (scopeMarket) {
              q = q.ilike('market', `%${scopeMarket}%`);
            }
            return q.order('connected_at', { ascending: false }).limit(75);
          })();

      // Run all data queries in parallel — each capped so slowness cannot stall the whole response for minutes.
      const [vdpEmailRes, vdpAgentRes, vdpCompanyRes, iseCompanyRes, vdpWeekRes, vdpWeekAgentRes, btRes] = await Promise.all([
        withPostgrestTimeout(
          'vdp_calls by email',
          supabaseAdmin!.from('vdp_calls').select(vdpSelect)
            .ilike('company_email', normEmail).or(vdpEndOr)
            .gte('time', connectsLookback).order('time', { ascending: false }).limit(50),
        ),
        agentIdsUnique.length > 0
          ? withPostgrestTimeout(
              'vdp_calls by agent',
              supabaseAdmin!.from('vdp_calls').select(vdpSelect)
                .in('agent', agentIdsUnique as any).or(vdpEndOr)
                .gte('time', connectsLookback).order('time', { ascending: false }).limit(50),
            )
          : Promise.resolve({ data: [] } as any),
        withPostgrestTimeout('vdp_calls company ticker', vdpCompanyTickerPromise as any),
        withPostgrestTimeout('inbound_success_events company ticker', iseCompanyTickerPromise as any),
        withPostgrestTimeout(
          'vdp_calls week email',
          supabaseAdmin!.from('vdp_calls').select('duration')
            .ilike('company_email', normEmail).or(vdpEndOr).gte('time', weekStart),
        ),
        agentIdsUnique.length > 0
          ? withPostgrestTimeout(
              'vdp_calls week agent',
              supabaseAdmin!.from('vdp_calls').select('duration').in('agent', agentIdsUnique as any).or(vdpEndOr).gte('time', weekStart),
            )
          : Promise.resolve({ data: [] } as any),
        withPostgrestTimeout(
          'billing_transactions week',
          supabaseAdmin!.from('billing_transactions').select('id, created_at, adjudication_decision, status')
            .ilike('agent_email', normEmail).eq('status', 'completed').gte('created_at', weekStart),
        ),
      ]);

      const vdpTickerErr = (vdpCompanyRes as any)?.error;
      const iseTickerErr = (iseCompanyRes as any)?.error;
      const tickerTimedOut =
        vdpTickerErr?.message === 'PANEL_DATA_QUERY_TIMEOUT' ||
        iseTickerErr?.message === 'PANEL_DATA_QUERY_TIMEOUT';
      if (!tickerFresh && !tickerTimedOut && !vdpTickerErr && !iseTickerErr) {
        panelDataTickerCache.set(tickerKey, {
          expires: Date.now() + PANEL_TICKER_CACHE_TTL_MS,
          vdp: ((vdpCompanyRes as any).data || []) as any[],
          ise: ((iseCompanyRes as any).data || []) as any[],
        });
      }

      const vdpByEmail = (vdpEmailRes.data || []) as any[];
      const vdpByAgent = (vdpAgentRes.data || []) as any[];
      const vdpForEvents = (vdpCompanyRes.data || []) as any[];
      const iseGlobal = (iseCompanyRes.data || []) as any[];
      if (iseCompanyRes.error) {
        console.warn('panel-data: inbound_success_events (company ticker):', iseCompanyRes.error.message);
      }
      if ((vdpCompanyRes as any).error) {
        console.warn('panel-data: vdp_calls (company ticker):', (vdpCompanyRes as any).error?.message);
      }
      const vdpWeekEmail = (vdpWeekRes.data || []) as any[];
      const bts = (btRes.data || []) as any[];

      let platformSalesAlpRows: any[] = [];
      try {
        if (assocId != null && String(assocId).trim() !== "" && supabaseAdmin) {
          platformSalesAlpRows = await withTimeoutPick(
            'platform_sales ALP',
            loadPlatformSalesForAgentAlp(supabaseAdmin, assocId, alp30dStartIso),
            12_000,
            [],
          );
        }
      } catch (alpLoadErr) {
        console.warn("panel-data: platform_sales ALP load failed (non-fatal):", (alpLoadErr as Error)?.message);
      }
      const { alpRolling: alpRolling30, alpToday: alpFromSalesToday } = sumPlatformSalesAlp(
        platformSalesAlpRows,
        alp30dStartMs,
        todayStartMs
      );

      const vdpMineMap = new Map<string, any>();
      for (const r of vdpByEmail) vdpMineMap.set(`vdp-${r.id}`, r);
      for (const r of vdpByAgent) vdpMineMap.set(`vdp-${r.id}`, r);
      const vdpTodayMine = Array.from(vdpMineMap.values());

      const vdpWeekAgent = (vdpWeekAgentRes.data || []) as any[];
      const vdpWeek = [...vdpWeekEmail, ...vdpWeekAgent];

      // Ticker shows company-wide connects — label with the producing agent (email or id), not always "you"
      const rowToEvent = (r: any) => {
        const rowEmail = r.company_email != null ? String(r.company_email).trim().toLowerCase() : '';
        const displayName =
          rowEmail === normEmail
            ? agentName || rowEmail.split('@')[0] || 'You'
            : rowEmail
              ? rowEmail.split('@')[0] || 'Agent'
              : r.agent != null
                ? `Agent ${String(r.agent)}`
                : 'Agent';
        return {
          id: `vdp-${r.id}`,
          connectedAt: r.time,
          agentName: displayName,
          market: r.market || market,
          state: r.state || '',
          source: 'vdp',
          durationSeconds: Number(r.duration) || undefined,
        };
      };

      // ── Recent connects (company / market-scoped ticker — NOT this agent only) + inbound_success_events (609) ──
      const events = [
        ...vdpForEvents.map(rowToEvent),
        ...iseGlobal.map((r: any) => {
          return {
            id: `ise-${r.id}`,
            connectedAt: r.connected_at,
            agentName: (r.agent_name && String(r.agent_name).trim()) || (r.agent_id != null ? String(r.agent_id) : "Agent"),
            market: (r.market && String(r.market).trim()) || "Inbound",
            state: (r.state && String(r.state).trim()) || "",
            source: "inbound_success_events",
          };
        }),
      ].sort((a, b) => {
        const tb = new Date(b.connectedAt).getTime();
        const ta = new Date(a.connectedAt).getTime();
        return (Number.isFinite(tb) ? tb : 0) - (Number.isFinite(ta) ? ta : 0);
      })
       .slice(0, limit);

      // ── My Stats ─────────────────────────────────────────────────────────────
      const btsToday     = bts.filter((b: any) => b.created_at >= todayStart);
      const eligibleToday = btsToday.filter((b: any) => b.adjudication_decision !== 'refund').length;
      const eligibleWeek  = bts.filter((b: any) => b.adjudication_decision !== 'refund').length;

      // My Stats: this agent's VDP only (ticker above is company-wide)
      const vdpActualToday = vdpTodayMine.filter((c: any) => c.time >= todayStart);
      const durArrToday = vdpActualToday.map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
      const avgDuration = durArrToday.length ? Math.round(durArrToday.reduce((a: number, b: number) => a + b, 0) / durArrToday.length) : null;

      const durArrWeek  = vdpWeek.map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
      const avgDurationWeek = durArrWeek.length ? Math.round(durArrWeek.reduce((a: number, b: number) => a + b, 0) / durArrWeek.length) : null;

      const alpWeek = alpRolling30;
      const alpToday = alpFromSalesToday;

      const badge = alpWeek >= 5000 ? 'gold' : alpWeek >= 2000 ? 'silver' : undefined;

      const stats = agentName ? {
        agentName,
        market,
        badge,
        avatarUrl: profilePicture || null,
        today: { connects: btsToday.length, alp: Math.round(alpToday), eligible: eligibleToday, avgDuration },
        week:  { connects: bts.length, alp: Math.round(alpWeek), eligible: eligibleWeek, avgDuration: avgDurationWeek },
        recent: vdpActualToday.slice(0, 8).map((c: any) => ({
          connectedAt: c.time,
          market: c.market || market,
          state: c.state || '',
          city: c.city || undefined,
          durationSeconds: Number(c.duration) || undefined,
        })),
      } : null;

      const panelPayload = { events, lastHourCount: events.length, stats };
      // Cache the full response per agent for 8s (skip if assocId was overridden via query)
      if (!assocQueryOverride) {
        panelAgentStatsCache.set(agentStatsCacheKey, {
          expires: Date.now() + PANEL_AGENT_STATS_TTL,
          payload: panelPayload,
        });
      }
      res.json(panelPayload);
    } catch (err) {
      console.error('❌ /api/agent/panel-data error:', err);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Inbound My Stats — powers the baseball card in InboundSuccessViewer
  app.get("/api/inbound/my-stats", async (req, res) => {
    try {
      const email: string | undefined =
        (req.headers['x-user-email'] as string) ||
        (req.query.email as string) ||
        (req.session as any)?.user?.email;
      if (!email) return res.status(401).json({ error: 'Unauthorized' });

      const now = new Date();
      const estOffset = 5 * 60 * 60 * 1000;
      const nowEst = new Date(now.getTime() - estOffset);
      const todayStart = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate()) + estOffset).toISOString();
      const weekStart = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate() - nowEst.getUTCDay()) + estOffset).toISOString();
      const alp30dStartIso = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
      const alp30dStartMs = new Date(alp30dStartIso).getTime();
      const todayStartMs = new Date(todayStart).getTime();
      const normEmail = String(email).trim().toLowerCase();

      // Agent info — same associate resolution as panel-data (producerlist or customers)
      const [{ data: producer }, { data: agentProfile }, { data: customerRow }] = await Promise.all([
        supabaseAdmin!.from('producerlist').select('associate_id, name, mga, market').ilike('company_email', normEmail).maybeSingle(),
        supabaseAdmin!.from('agent_profiles').select('profile_picture, first_name, last_name').ilike('email', normEmail).maybeSingle(),
        supabaseAdmin!.from('customers').select('associate_id').or(`company_email.ilike.${normEmail},personal_email.ilike.${normEmail}`).maybeSingle(),
      ]);

      const agentName = producer?.name ||
        [agentProfile?.first_name, agentProfile?.last_name].filter(Boolean).join(' ') ||
        null;

      if (!agentName) return res.json({ error: 'Agent not found' });

      const assocId =
        producer?.associate_id != null
          ? producer.associate_id
          : (customerRow as any)?.associate_id != null
            ? (customerRow as any).associate_id
            : null;

      // billing_transactions — connects + eligible
      const { data: allBt } = await supabaseAdmin!
        .from('billing_transactions')
        .select('id, created_at, adjudication_decision, status')
        .ilike('agent_email', normEmail)
        .eq('status', 'completed')
        .gte('created_at', weekStart);

      const bts = allBt || [];
      const btsToday = bts.filter((b: any) => b.created_at >= todayStart);
      const eligibleToday = btsToday.filter((b: any) => b.adjudication_decision !== 'refund').length;
      const eligibleWeek = bts.filter((b: any) => b.adjudication_decision !== 'refund').length;

      // vdp_calls — avg duration today
      const { data: callsToday } = await supabaseAdmin!
        .from('vdp_calls')
        .select('id, duration, time, market, state, city')
        .eq('agent', String(assocId))
        .or('event.eq.END,event.eq.end')
        .gte('time', todayStart)
        .order('time', { ascending: false });

      const durArr = (callsToday || []).map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
      const avgDuration = durArr.length ? Math.round(durArr.reduce((a: number, b: number) => a + b, 0) / durArr.length) : null;

      // vdp_calls — avg duration this week
      const { data: callsWeekV2 } = await supabaseAdmin!
        .from('vdp_calls')
        .select('duration')
        .eq('agent', String(assocId))
        .or('event.eq.END,event.eq.end')
        .gte('time', weekStart);
      const durArrW2 = (callsWeekV2 || []).map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
      const avgDurationWeek = durArrW2.length ? Math.round(durArrW2.reduce((a: number, b: number) => a + b, 0) / durArrW2.length) : null;

      // platform_sales — ALP from AOI/CCPRO rows, rolling 30 days (stats.week.alp); today = calendar-day portion of those rows
      let alpToday = 0;
      let alpWeek = 0;
      if (assocId != null && String(assocId).trim() !== '' && supabaseAdmin) {
        const salesRows = await loadPlatformSalesForAgentAlp(supabaseAdmin, assocId, alp30dStartIso);
        const sums = sumPlatformSalesAlp(salesRows, alp30dStartMs, todayStartMs);
        alpWeek = sums.alpRolling;
        alpToday = sums.alpToday;
      }

      // Recent calls — no per-call sale lookup (no reliable phone key on vdp_calls)
      const recentCalls = (callsToday || []).slice(0, 8);
      const recent = recentCalls.map((c: any) => ({
        connectedAt: c.time,
        market: c.market || market,
        state: c.state || '',
        city: c.city || undefined,
        durationSeconds: Number(c.duration) || undefined,
      }));

      // Badge logic: gold if week ALP >= 5000, silver >= 2000
      const badge = alpWeek >= 5000 ? 'gold' : alpWeek >= 2000 ? 'silver' : undefined;

      const market = Array.isArray(producer?.market)
        ? producer!.market.filter(Boolean)[0] || ''
        : typeof producer?.market === 'string'
          ? (() => { try { const p = JSON.parse(producer!.market); return Array.isArray(p) ? p[0] : producer!.market; } catch { return producer!.market; } })()
          : '';

      res.json({
        agentName,
        market,
        badge,
        avatarUrl: agentProfile?.profile_picture || null,
        today: { connects: btsToday.length, alp: Math.round(alpToday), eligible: eligibleToday, avgDuration },
        week:  { connects: bts.length, alp: Math.round(alpWeek), eligible: eligibleWeek, avgDuration: avgDurationWeek },
        recent,
      });
    } catch (err) {
      console.error('❌ /api/inbound/my-stats error:', err);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Agent My Stats — connects, ALP, eligible for today + this week
  app.get("/api/agent/my-stats", async (req, res) => {
    try {
      if (!supabaseAdmin) {
        return res.status(503).json({ error: "Stats temporarily unavailable" });
      }

      const email = (req.query.email as string) || (req.session as any)?.user?.email;
      if (!email) return res.status(400).json({ error: 'Email required' });

      const normEmail = String(email).trim().toLowerCase();
      const alp30dStartIso = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
      const alp30dStartMs = new Date(alp30dStartIso).getTime();

      // Resolve agent info (producerlist or customers — matches panel-data)
      const [{ data: producer }, { data: customerRow }] = await Promise.all([
        supabaseAdmin.from('producerlist').select('associate_id, name, mga, market').ilike('company_email', normEmail).maybeSingle(),
        supabaseAdmin.from('customers').select('associate_id').or(`company_email.ilike.${normEmail},personal_email.ilike.${normEmail}`).maybeSingle(),
      ]);

      const assocId =
        producer?.associate_id != null
          ? producer.associate_id
          : (customerRow as any)?.associate_id != null
            ? (customerRow as any).associate_id
            : null;

      // Date window helpers (EST = UTC-5)
      const now = new Date();
      const estOffset = 5 * 60 * 60 * 1000;
      const nowEst = new Date(now.getTime() - estOffset);
      const todayStart = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate()) + estOffset).toISOString();
      const todayStartMs = new Date(todayStart).getTime();
      const weekStart  = new Date(Date.UTC(nowEst.getUTCFullYear(), nowEst.getUTCMonth(), nowEst.getUTCDate() - nowEst.getUTCDay()) + estOffset).toISOString();

      // billing_transactions — connects + eligible
      const { data: allBt, error: btErr } = await supabaseAdmin
        .from('billing_transactions')
        .select('id, created_at, adjudication_decision, status')
        .ilike('agent_email', normEmail)
        .eq('status', 'completed');
      if (btErr) {
        console.warn("⚠️ /api/agent/my-stats billing_transactions:", btErr.message);
      }
      const bts = allBt || [];
      const btsToday = bts.filter((b: any) => b.created_at >= todayStart);
      const btsWeek = bts.filter((b: any) => b.created_at >= weekStart);
      const eligible = (bt: any[]) => bt.filter((b: any) => b.adjudication_decision !== 'refund').length;

      // vdp_calls — avg duration today + week (skip if no associate id)
      let avgDurToday = 0;
      let avgDurWeek = 0;
      if (assocId != null && String(assocId).trim() !== "") {
        const agentKey = String(assocId);
        const { data: callsTodayV, error: vdpTodayErr } = await supabaseAdmin
          .from('vdp_calls')
          .select('duration')
          .eq('agent', agentKey)
          .or('event.eq.END,event.eq.end')
          .gte('time', todayStart);
        if (vdpTodayErr) console.warn("⚠️ /api/agent/my-stats vdp_calls today:", vdpTodayErr.message);
        const durArr = (callsTodayV || []).map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
        avgDurToday = durArr.length ? Math.round(durArr.reduce((a: number, b: number) => a + b, 0) / durArr.length) : 0;

        const { data: callsWeekV, error: vdpWeekErr } = await supabaseAdmin
          .from('vdp_calls')
          .select('duration')
          .eq('agent', agentKey)
          .or('event.eq.END,event.eq.end')
          .gte('time', weekStart);
        if (vdpWeekErr) console.warn("⚠️ /api/agent/my-stats vdp_calls week:", vdpWeekErr.message);
        const durArrW = (callsWeekV || []).map((c: any) => Number(c.duration) || 0).filter((d: number) => d > 0);
        avgDurWeek = durArrW.length ? Math.round(durArrW.reduce((a: number, b: number) => a + b, 0) / durArrW.length) : 0;
      }

      // platform_sales — AOI/CCPRO ALP, rolling 30d (week key); today = calendar day on those rows
      let alpToday = 0;
      let alpWeek = 0;
      if (assocId != null && String(assocId).trim() !== '') {
        const salesRows = await loadPlatformSalesForAgentAlp(supabaseAdmin, assocId, alp30dStartIso);
        const sums = sumPlatformSalesAlp(salesRows, alp30dStartMs, todayStartMs);
        alpWeek = sums.alpRolling;
        alpToday = sums.alpToday;
      }

      // Recent connects (last 10 billing_transactions with sale lookup)
      const recentBts = bts.slice(-10).reverse();
      const recent = await Promise.all(recentBts.map(async (bt: any) => {
        return {
          id: bt.id,
          time: bt.created_at,
          leadName: null,
          market: null,
          alp: null,
          hasSale: false,
        };
      }));

      res.json({
        agent: {
          name: producer?.name || null,
          email,
          associateId: assocId,
          mga: producer?.mga || null,
          market: producer?.market || null,
        },
        today: {
          connects: btsToday.length,
          eligible: eligible(btsToday),
          alp: Math.round(alpToday),
          avgDurSeconds: avgDurToday,
        },
        week: {
          connects: btsWeek.length,
          eligible: eligible(btsWeek),
          alp: Math.round(alpWeek),
          avgDurSeconds: avgDurWeek,
        },
        recent,
      });
    } catch (err) {
      console.error('❌ /api/agent/my-stats error:', err);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Serve attached video files
  app.get("/attached_assets/:filename", (req, res) => {
    try {
      const { filename } = req.params;
      const path = require('path');
      const fs = require('fs');
      
      // Decode the URL-encoded filename
      const decodedFilename = decodeURIComponent(filename);
      const filePath = path.join(__dirname, '..', 'attached_assets', decodedFilename);
      
      console.log('🎬 Video request for:', decodedFilename);
      console.log('🎬 Full path:', filePath);
      console.log('🎬 __dirname:', __dirname);
      
      // Check if file exists
      if (!fs.existsSync(filePath)) {
        console.log('❌ Video file not found:', filePath);
        return res.status(404).json({ error: 'File not found' });
      }
      
      const stat = fs.statSync(filePath);
      const fileSize = stat.size;
      const range = req.headers.range;
      
      console.log('✅ Video file found, size:', (fileSize / 1024 / 1024).toFixed(2), 'MB');
      
      // Set appropriate headers for video files
      res.setHeader('Content-Type', 'video/mp4');
      res.setHeader('Accept-Ranges', 'bytes');
      res.setHeader('Cache-Control', 'public, max-age=3600');
      
      if (range) {
        // Handle range requests for video streaming
        console.log('📡 Range request:', range);
        const parts = range.replace(/bytes=/, "").split("-");
        const start = parseInt(parts[0], 10);
        const end = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;
        const chunksize = (end - start) + 1;
        
        const head = {
          'Content-Range': `bytes ${start}-${end}/${fileSize}`,
          'Content-Length': chunksize,
          'Content-Type': 'video/mp4',
        };
        res.writeHead(206, head);
        
        const file = fs.createReadStream(filePath, { start, end });
        file.on('error', (err) => {
          console.error('❌ Stream error:', err);
          if (!res.headersSent) {
            res.status(500).send('Stream error');
          }
        });
        file.pipe(res);
      } else {
        // Send entire file
        console.log('📡 Sending entire file');
        res.setHeader('Content-Length', fileSize);
        const stream = fs.createReadStream(filePath);
        stream.on('error', (err) => {
          console.error('❌ Stream error:', err);
          if (!res.headersSent) {
            res.status(500).send('Stream error');
          }
        });
        stream.pipe(res);
      }
    } catch (error) {
      console.error('❌ Video serving error:', error);
      if (!res.headersSent) {
        res.status(500).json({ error: 'Internal server error', message: error.message });
      }
    }
  });

