  // ===== HELP LIVE SUPPORT: BOOKINGS & QUEUE (Supabase) =====
  const ensureSupportTables = () => supportSupabase.ensureSupportTables();

  // Support schedule: Mon 12–2 PM, Tue 9–10:30 AM, Thu 9–10:30 AM PST, 10-min increments
  const SUPPORT_SCHEDULE_PST: { dayOfWeek: number; startMin: number; endMin: number }[] = [
    { dayOfWeek: 1, startMin: 12 * 60, endMin: 14 * 60 },
    { dayOfWeek: 2, startMin: 9 * 60, endMin: 10 * 60 + 30 },
    { dayOfWeek: 4, startMin: 9 * 60, endMin: 10 * 60 + 30 },
  ];
  function isValidSupportSlot(slotStart: string, slotEnd: string): boolean {
    const PST = 'America/Los_Angeles';
    const start = new Date(slotStart);
    const end = new Date(slotEnd);
    const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: PST, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
    const parts = (d: Date) => fmt.formatToParts(d);
    const get = (p: Intl.DateTimeFormatPart[], t: string) => parseInt(p.find((x) => x.type === t)?.value || '0', 10);
    const ps = parts(start);
    const pe = parts(end);
    const y = get(ps, 'year');
    const m = get(ps, 'month');
    const d = get(ps, 'day');
    const iso = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}T12:00:00`;
    const inDST = m >= 3 && m <= 10;
    const noonPST = new Date(iso + (inDST ? '-07:00' : '-08:00'));
    const dow = noonPST.getUTCDay();
    const sched = SUPPORT_SCHEDULE_PST.find((s) => s.dayOfWeek === dow);
    if (!sched) return false;
    const startMin = get(ps, 'hour') * 60 + get(ps, 'minute');
    const endMin = get(pe, 'hour') * 60 + get(pe, 'minute');
    if (startMin % 10 !== 0 || endMin - startMin !== 10) return false;
    return startMin >= sched.startMin && endMin <= sched.endMin;
  }

