  // Payment intent endpoint for credit purchases
  app.post("/api/payments/create-payment-intent", async (req, res) => {
    try {
      const { amount, creditPackage, userEmail, userName } = req.body;
      
      if (!amount || !creditPackage || !userEmail) {
        return res.status(400).json({ error: 'Amount, credit package, and user email are required' });
      }

      if (!stripe || !HARDCODED_CONFIG.STRIPE_SECRET_KEY) {
        return res.status(500).json({ error: 'Stripe is not configured' });
      }

      // Create Stripe customer if needed and get customer ID
      let stripeCustomerId;
      try {
        const existingCustomers = await stripe.customers.list({
          email: userEmail,
          limit: 1
        });

        if (existingCustomers.data.length > 0) {
          stripeCustomerId = existingCustomers.data[0].id;
        } else {
          // Create new customer with billing details
          const customer = await stripe.customers.create({
            email: userEmail,
            name: userName || userEmail.split('@')[0],
            metadata: {
              source: 'ConnectNow CRM'
            }
          });
          stripeCustomerId = customer.id;
        }
      } catch (customerError) {
        console.warn('Could not create/find Stripe customer:', customerError);
        // Continue without customer for now
      }

      // Create payment intent with Stripe
      const paymentIntent = await stripe.paymentIntents.create({
        amount: Math.round(amount * 100), // Convert to cents
        currency: "usd",
        customer: stripeCustomerId,
        metadata: {
          creditPackage: creditPackage.toString(),
          credits: creditPackage.toString(),
          userEmail: userEmail,
          userName: userName || userEmail.split('@')[0]
        },
        automatic_payment_methods: {
          enabled: true,
        },
      });

      res.json({ 
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id
      });
      
    } catch (error: any) {
      console.error('Payment intent creation error:', error);
      res.status(500).json({ 
        error: "Error creating payment intent: " + (error?.message || 'Unknown error')
      });
    }
  });
  
