  // HPPRO → local EappSync: browser polls while Present mode, POSTs to localhost:7432/inject-next
  // NOTE: primary route is in index.ts (registered before HPPRO proxy); this is a fallback
  app.get("/api/hppro/eapp-pending-legacy", async (req, res) => {
    return res.json({ pending: null }); // handled by index.ts route
  });

  app.post("/api/hppro/eapp-pending/:id/ack", async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isFinite(id) || id <= 0) {
        return res.status(400).json({ ok: false, error: "bad_id" });
      }
      const email = await resolveAgentEmailFromRequest(req);
      if (!email) {
        return res.status(401).json({ ok: false, error: "unauthorized" });
      }
      if (!supabaseAdmin) {
        return res.status(503).json({ ok: false, error: "service_unavailable" });
      }
      const { data: row, error: selErr } = await supabaseAdmin
        .from("hppro_eapp_pending")
        .select("id, agent_email")
        .eq("id", id)
        .maybeSingle();
      if (selErr || !row) {
        return res.status(404).json({ ok: false, error: "not_found" });
      }
      if (String(row.agent_email).toLowerCase() !== email) {
        return res.status(403).json({ ok: false, error: "forbidden" });
      }
      const { error } = await supabaseAdmin
        .from("hppro_eapp_pending")
        .update({ consumed_at: new Date().toISOString() })
        .eq("id", id)
        .eq("agent_email", email);
      if (error) {
        return res.status(500).json({ ok: false, error: error.message });
      }
      return res.json({ ok: true });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "error";
      return res.status(500).json({ ok: false, error: msg });
    }
  });

  // ── AOI Application persistence (auto-save + load) ─────────────────────────

  // GET /api/application/state — load saved wizard state for this agent
  app.get('/api/application/state', async (req, res) => {
    try {
      const email = await resolveAgentEmailFromRequest(req);
      if (!email) return res.status(401).json({ state: null });

      const guid = (req.query.guid as string) || null;
      const { rows } = await pool.query(
        `SELECT wizard_state, step, updated_at, presentation_guid FROM aoi_applications
         WHERE agent_email = $1 ${guid ? 'AND presentation_guid = $2' : ''}
         ORDER BY updated_at DESC LIMIT 1`,
        guid ? [email, guid] : [email]
      );
      if (!rows.length) return res.json({ state: null });
      const data = rows[0];
      return res.json({ state: data.wizard_state, step: data.step, updated_at: data.updated_at, presentation_guid: data.presentation_guid });
    } catch (e: any) {
      return res.json({ state: null });
    }
  });

  // POST /api/application/state — auto-save wizard state
  app.post('/api/application/state', async (req, res) => {
    try {
      const email = await resolveAgentEmailFromRequest(req);
      if (!email) return res.status(401).json({ ok: false });

      const { wizard_state, step, presentation_guid } = req.body as { wizard_state: unknown; step?: string; presentation_guid?: string };
      if (!wizard_state || typeof wizard_state !== 'object') return res.status(400).json({ ok: false });

      const guid = presentation_guid || null;
      // Use upsert via delete+insert to avoid constraint issues with partial index
      await pool.query(
        `INSERT INTO aoi_applications (agent_email, presentation_guid, wizard_state, step, updated_at)
         VALUES ($1, $2, $3, $4, NOW())
         ON CONFLICT ON CONSTRAINT aoi_apps_uq DO UPDATE
         SET wizard_state = EXCLUDED.wizard_state, step = EXCLUDED.step, updated_at = NOW()`,
        [email, guid || '', JSON.stringify(wizard_state), step || null]
      ).catch(async () => {
        // Fallback: manual upsert
        await pool.query(`DELETE FROM aoi_applications WHERE agent_email=$1 AND coalesce(presentation_guid,'')=$2`, [email, guid || '']);
        await pool.query(`INSERT INTO aoi_applications (agent_email, presentation_guid, wizard_state, step, updated_at) VALUES ($1,$2,$3,$4,NOW())`, [email, guid || '', JSON.stringify(wizard_state), step || null]);
      });
      return res.json({ ok: true });
    } catch (e: any) {
      return res.json({ ok: false, error: e.message });
    }
  });

  // Senior Combo intake wizard → merge inject_payload + push to EappSync
  app.post('/api/application/senior-combo', async (req, res) => {
    try {
      const email = await resolveAgentEmailFromRequest(req);
      if (!email) return res.status(401).json({ ok: false });

      const body = req.body as Record<string, unknown>;

      // Build flat inject payload from body
      const flat: Record<string,string> = {};

      // Medical questions
      const MQ_KEYS = ['MQRejectedByAIL','MQSmokeCigarettesTobacco','MQTerminalIllness','MQOrganTransplant',
        'MQlTreated4ALS','MQKidneyDisease','MQAmputationCausedByDisease','MQAIDS',
        'MQConfined2NursingFacility','MQReceivingTreatment','MQ12MonthsLostWeight',
        'MQArthritisBackKnee','MQTreatment4HodgkinsLeukemiaMalignantCancer','MQDrugAlcoholAbuse'];
      const MQ_SECTIONS: Record<string,string> = {
        MQArthritisBackKnee:'SectionB', MQTreatment4HodgkinsLeukemiaMalignantCancer:'SectionC',
        MQDrugAlcoholAbuse:'SectionB'
      };
      const getSection = (k:string) => MQ_SECTIONS[k] || 'SectionA';

      const primaryMQ = (body.primaryMQ || {}) as Record<string,boolean>;
      const spouseMQ = (body.spouseMQ || {}) as Record<string,boolean>;

      for (const k of MQ_KEYS) {
        const sec = getSection(k);
        const pVal = primaryMQ[k] ? 'True' : 'False';
        flat[`${sec}.${k}Yes`] = pVal;
        flat[`${sec}.${k}No`] = pVal === 'True' ? 'False' : 'True';
        const sVal = spouseMQ[k] ? 'True' : 'False';
        flat[`${sec}.${k}SpouseYes`] = sVal;
        flat[`${sec}.${k}SpouseNo`] = sVal === 'True' ? 'False' : 'True';
      }

      // Height/weight/tobacco
      const s = (v:unknown) => v == null ? '' : String(v);
      flat.insured1Height = s(body.primaryHeightInches);
      flat.insured1Weight = s(body.primaryWeight);
      flat.insured1Tobacco = (body.primaryTobacco as boolean) ? 'True' : 'False';
      flat.spouse1Height = s(body.spouseHeightInches);
      flat.spouse1Weight = s(body.spouseWeight);
      flat.spouse1Tobacco = (body.spouseTobacco as boolean) ? 'True' : 'False';

      // Rx primary
      for (let i = 1; i <= 10; i++) {
        const rx = (body.primaryRx as any[])?.[i-1];
        if (rx) { flat[`rx${i}Name`]=rx.name||''; flat[`rx${i}Dosage`]=rx.dosage||''; flat[`rx${i}Doctor`]=rx.doctor||''; flat[`rx${i}DoctorAddress`]=rx.doctorAddress||''; flat[`rx${i}DoctorPhone`]=rx.doctorPhone||''; flat[`rx${i}Reason`]=rx.reason||''; flat[`rx${i}Duration`]=rx.duration||''; }
      }
      // Rx spouse
      for (let i = 1; i <= 10; i++) {
        const rx = (body.spouseRx as any[])?.[i-1];
        if (rx) { flat[`rxSp${i}Name`]=rx.name||''; flat[`rxSp${i}Dosage`]=rx.dosage||''; flat[`rxSp${i}Doctor`]=rx.doctor||''; flat[`rxSp${i}DoctorAddress`]=rx.doctorAddress||''; flat[`rxSp${i}DoctorPhone`]=rx.doctorPhone||''; flat[`rxSp${i}Reason`]=rx.reason||''; flat[`rxSp${i}Duration`]=rx.duration||''; }
      }

      // Beneficiaries (no DOB or percentage — not required)
      // Primary insured beneficiaries
      const pb1 = body.primaryBene1 as any;
      if (pb1) { flat.beneficiary1Name=pb1.name||''; flat.beneficiary1Relationship=pb1.relationship||''; }
      const pb2 = body.primaryBene2 as any;
      if (pb2?.enabled) { flat.beneficiary2Name=pb2.name||''; flat.beneficiary2Relationship=pb2.relationship||''; }
      // Spouse beneficiaries (keyed differently so they inject to the spouse form)
      const sb1 = body.spouseBene1 as any;
      if (sb1) { flat.spouseBeneficiary1Name=sb1.name||''; flat.spouseBeneficiary1Relationship=sb1.relationship||''; }
      const sb2 = body.spouseBene2 as any;
      if (sb2?.enabled) { flat.spouseBeneficiary2Name=sb2.name||''; flat.spouseBeneficiary2Relationship=sb2.relationship||''; }

      // Banking
      const bk = body.banking as any;
      if (bk) { flat.bankName=bk.bankName||''; flat.routingNumber=bk.routing||''; flat.accountNumber=bk.account||''; flat.accountType=bk.accountType||'Checking'; flat.drawDay=String(bk.drawDay||1); flat.bankHolderName=bk.holderName||''; }

      // Personal details
      // (s helper already declared above)
      // Single birthplace field matching eApp MibBirthplaceData.Description (e.g. "Missouri", "Mexico")
      flat.primaryBirthPlace   = s(body.primaryBirthPlace);
      flat.primaryUSResident   = body.primaryUSResident === true ? 'True' : body.primaryUSResident === false ? 'False' : '';
      flat.primaryDL           = s(body.primaryDL);
      flat.primaryDLState      = s(body.primaryDLState);
      flat.primarySSN          = s(body.primarySSN);
      flat.spouseBirthPlace    = s(body.spouseBirthPlace);
      flat.spouseUSResident    = body.spouseUSResident === true ? 'True' : body.spouseUSResident === false ? 'False' : '';
      flat.spouseDL            = s(body.spouseDL);
      flat.spouseDLState       = s(body.spouseDLState);
      flat.spouseSSN           = s(body.spouseSSN);

      // Doctor info — primary (PersonPhysican1 FDS keys)
      const pd = (body.primaryDetails as any)?.doctor || {};
      flat.primaryDoctorName        = s(pd.name);
      flat.primaryDoctorAddress     = s(pd.address);
      flat.primaryDoctorPhone       = s(pd.phone);
      flat.primaryDoctorDateLastSeen= s(pd.dateLastSeen);
      flat.primaryDoctorIsVA        = pd.isVA ? 'True' : 'False';
      // Doctor info — spouse
      const sd = (body.spouseDetails as any)?.doctor || {};
      flat.spouseDoctorName         = s(sd.name);
      flat.spouseDoctorAddress      = s(sd.address);
      flat.spouseDoctorPhone        = s(sd.phone);
      flat.spouseDoctorDateLastSeen = s(sd.dateLastSeen);
      flat.spouseDoctorIsVA         = sd.isVA ? 'True' : 'False';
      // VA HIPAA flag — if either doctor is VA, force form injection
      flat.requiresVAHipaa = (pd.isVA || sd.isVA) ? 'True' : 'False';
      flat.primaryDoctorMedRecordsId = s(pd.medicalRecordsId);
      flat.spouseDoctorMedRecordsId  = s(sd.medicalRecordsId);

      // ISaw, secondary phone, best time to call
      const pDetails = (body.primaryDetails as any) || {};
      const sDetails = (body.spouseDetails as any) || {};
      flat.primaryISaw           = (body.primaryISaw !== false) ? 'True' : 'False';
      flat.spouseISaw            = (body.spouseISaw  !== false) ? 'True' : 'False';
      flat.primaryCellPhone      = s(body.primaryCellPhone)  || s(pDetails.cellPhone);
      flat.spouseCellPhone       = s(body.spouseCellPhone)   || s(sDetails.cellPhone);
      flat.primaryBestTimeToCall = s(body.primaryBestTimeToCall) || s(pDetails.bestTimeToCall);
      flat.spouseBestTimeToCall  = s(body.spouseBestTimeToCall)  || s(sDetails.bestTimeToCall);

      // App-level fields
      const appMeta = (body.appMeta as any) || {};
      flat.remarks = s(body.remarks) || s(appMeta.remarks);
      flat.mailTo  = s(body.mailTo)  || s(appMeta.mailTo) || 'Policyholder';

      // Occupation & Employer
      flat.insured1Occupation    = s(pDetails.occupation) || s(body.occupation) || '';
      flat.insured1Employer      = s(pDetails.employer) || '';
      flat.spouse1Occupation     = s(sDetails.occupation) || '';
      flat.spouse1Employer       = s(sDetails.employer) || '';

      // Replacement
      const pr = pDetails.replacement || {};
      const sr = sDetails.replacement || {};
      flat.primaryReplacementYes        = pr.applies ? 'True' : 'False';
      flat.primaryReplacementNo         = pr.applies ? 'False' : 'True';
      flat.primaryInsuranceAmount       = s(pr.amountOfInsurance);
      flat.primaryInsuranceType         = s(pr.insuredType);
      flat.primaryInsuranceCompany      = s(pr.company);
      flat.primaryInsuranceBenefit      = s(pr.benefit);
      flat.spouseReplacementYes         = sr.applies ? 'True' : 'False';
      flat.spouseReplacementNo          = sr.applies ? 'False' : 'True';
      flat.spouseInsuranceAmount        = s(sr.amountOfInsurance);
      flat.spouseInsuranceType          = s(sr.insuredType);
      flat.spouseInsuranceCompany       = s(sr.company);
      flat.spouseInsuranceBenefit       = s(sr.benefit);

      // Merge with existing pending record if any
      if (supabaseAdmin) {
        const { data: existing } = await supabaseAdmin.from('hppro_eapp_pending').select('id,inject_payload,presentation_guid').eq('agent_email', email).is('consumed_at', null).order('created_at', { ascending: false }).limit(1).maybeSingle();

        const merged = { ...(existing?.inject_payload as Record<string,string> || {}), ...flat };

        if (existing?.id) {
          await supabaseAdmin.from('hppro_eapp_pending').update({ inject_payload: merged }).eq('id', existing.id);
        }

        // Push to EappSync
        let injected = false;
        try {
          const r = await fetch('http://localhost:7432/inject-next', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(merged)
          });
          injected = r.ok;
        } catch {}

        return res.json({ ok: true, injected });
      }

      return res.json({ ok: true, injected: false });
    } catch (e: any) {
      return res.status(500).json({ ok: false, error: e.message });
    }
  });

