  // AO Precheck Admin API routes
  app.get("/api/aoi-precheck/sessions", async (req, res) => {
    try {
      console.log('📊 Fetching AO Precheck sessions for admin');
      
      // Get user permissions for RBAC - prioritize header over session
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string || req.headers['User-Email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const userEmail = headerEmail || sessionEmail;
      
      if (!userEmail) {
        console.error('❌ NO USER EMAIL FOUND - header:', headerEmail, 'session:', sessionEmail);
        return res.status(401).json({ error: 'User email required', debug: { headerEmail, sessionEmail } });
      }
      
      console.log(`🔍 EMAIL DEBUG: header='${headerEmail}', session='${sessionEmail}', final='${userEmail}'`);
      console.log('🔍 ALL HEADERS:', Object.keys(req.headers).filter(h => h.toLowerCase().includes('email')));
      
      const { getUserPermissions } = await import('./rbac-helper');
      const permissions = await getUserPermissions(userEmail);
      
      console.log(`🔐 User ${userEmail} permissions:`, {
        role: permissions.role,
        canViewAll: permissions.canViewAll,
        allowedMgaTeams: permissions.allowedMgaTeams,
        allowedRgaTeams: permissions.allowedRgaTeams
      });
      
      const { search, status, method, agent, rga, mga, dateRange, page, limit, teamManager } = req.query;
      const teamManagerEmail = teamManager ? String(teamManager).trim().toLowerCase() : '';
      const isTeamManagerScope = !!teamManagerEmail;
      if (isTeamManagerScope && String(userEmail).trim().toLowerCase() !== teamManagerEmail) {
        return res.status(403).json({ error: 'not authorized for this team view' });
      }
      console.log(`🔍 QUERY PARAMS DEBUG:`, { search, status, method, agent, rga, mga, dateRange, page, limit, teamManager: teamManagerEmail || undefined });
      
      let queryText = `
        SELECT s.*, 
               s.agent_mga_team,
               s.agent_rga_team,
               s.agent_first_name,
               s.agent_last_name
        FROM verification_sessions s
        WHERE 1=1
      `;
      const queryParams: any[] = [];
      let paramCount = 0;

      // Apply filters
      if (search) {
        paramCount++;
        queryText += ` AND first_name ILIKE $${paramCount}`;
        queryParams.push(`%${search}%`);
      }
      if (status && status !== 'all') {
        paramCount++;
        queryText += ` AND status = $${paramCount}`;
        queryParams.push(status);
      }
      if (method && method !== 'all') {
        paramCount++;
        queryText += ` AND verification_method = $${paramCount}`;
        queryParams.push(method);
      }
      if (agent && agent !== 'all') {
        paramCount++;
        queryText += ` AND company_email = $${paramCount}`;
        queryParams.push(agent);
      }
      
      // Apply user-selected RGA/MGA team filters (within RBAC constraints)
      // 🔥 CRITICAL: Use case-insensitive matching (ILIKE for exact match)
      if (rga && rga !== 'all') {
        paramCount++;
        queryText += ` AND LOWER(ap.rga_team) = LOWER($${paramCount})`;
        queryParams.push(rga);
      }
      if (mga && mga !== 'all') {
        paramCount++;
        queryText += ` AND LOWER(ap.mga_team) = LOWER($${paramCount})`;
        queryParams.push(mga);
      }
      
      // Apply RBAC filtering based on user permissions
      if (permissions.precheck.readScope === 'assigned_mga') {
        // Quality Manager and similar roles - filter by assigned teams
        if (permissions.allowedMgaTeams && permissions.allowedMgaTeams.length > 0) {
          const mgaTeamsPlaceholder = permissions.allowedMgaTeams.map(() => {
            paramCount++;
            return `$${paramCount}`;
          }).join(',');
          queryText += ` AND ap.mga_team IN (${mgaTeamsPlaceholder})`;
          queryParams.push(...permissions.allowedMgaTeams);
          console.log(`🔐 RBAC filtering applied for user: ${userEmail} with ${permissions.allowedMgaTeams.length} teams`);
        } else {
          console.log(`⚠️ Quality Manager has no assigned teams - showing no sessions`);
          queryText += ` AND ap.mga_team = 'NO_TEAMS_ASSIGNED'`; // This will return no results
        }
      } else if (permissions.precheck.readScope === 'all') {
        // AO Quality Manager - see all sessions (no filtering)
        console.log(`🌍 AO Quality Manager - showing all sessions`);
      }
      
      // Apply date range filter
      if (dateRange && dateRange !== 'all') {
        const now = new Date();
        let startDate: Date;
        
        switch (dateRange) {
          case 'today':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            break;
          case 'yesterday':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
            paramCount++;
            queryText += ` AND created_at < $${paramCount}`;
            queryParams.push(new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString());
            break;
          case 'week':
            startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            break;
          case 'month':
            startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            break;
          default:
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        }
        
        if (dateRange !== 'yesterday') {
          paramCount++;
          queryText += ` AND created_at >= $${paramCount}`;
          queryParams.push(startDate.toISOString());
        }
      }

      // Use Supabase instead of pool query
      console.log('🔄 Using Supabase to fetch verification sessions...');
      
      // Pagination parameters
      const pageNum = parseInt(page as string) || 1;
      const pageSize = Math.min(parseInt(limit as string) || 1000, 5000);
      const offset = (pageNum - 1) * pageSize;

      // CRITICAL: Show transmitted sessions + sessions without transmit created PRIOR to 2/9/2026
      // Transmitted: always show. Pre-2/9: include pending_transmit/null (legacy sessions before transmit workflow)
      const PRE_TRANSMIT_CUTOFF = '2026-02-09T00:00:00.000Z';
      const transmitFilter = `transmit_status.eq.transmitted,and(created_at.lt.${PRE_TRANSMIT_CUTOFF},or(transmit_status.is.null,transmit_status.eq.pending_transmit))`;
      let query = supabaseAdmin.from('verification_sessions').select('*');
      let countQuery = supabaseAdmin.from('verification_sessions').select('*', { count: 'exact', head: true });

      if (isTeamManagerScope) {
        const { resolveManagerTeamEmails, teamEmailOrFilter } = await import('./aoprecheck-team-shared');
        const teamEmails = await resolveManagerTeamEmails(teamManagerEmail);
        const emailFilter = teamEmailOrFilter(teamEmails);
        query = query.or(emailFilter);
        countQuery = countQuery.or(emailFilter);
        console.log(`👥 Team manager scope: ${teamManagerEmail} → ${teamEmails.length} agent emails (all transmit statuses)`);
      } else {
        query = query.or(transmitFilter);
        countQuery = countQuery.or(transmitFilter);
      }

      // Apply case-insensitive search filter
      if (search) {
        // Search across multiple fields with case-insensitive matching
        query = query.or(`first_name.ilike.%${search}%,last_name.ilike.%${search}%,phone.ilike.%${search}%,company_email.ilike.%${search}%,agent_first_name.ilike.%${search}%,agent_last_name.ilike.%${search}%`);
        countQuery = countQuery.or(`first_name.ilike.%${search}%,last_name.ilike.%${search}%,phone.ilike.%${search}%,company_email.ilike.%${search}%,agent_first_name.ilike.%${search}%,agent_last_name.ilike.%${search}%`);
        console.log(`🔍 Case-insensitive search filter applied: "${search}"`);
      }

      // Apply status filter
      if (status && status !== 'all') {
        query = query.eq('status', status);
        countQuery = countQuery.eq('status', status);
      }

      // Apply method filter
      if (method && method !== 'all') {
        query = query.eq('verification_method', method);
        countQuery = countQuery.eq('verification_method', method);
      }

      // Apply agent/producer filter (case-insensitive exact match)
      if (agent && agent !== 'all') {
        query = query.ilike('company_email', agent);
        countQuery = countQuery.ilike('company_email', agent);
        console.log(`🔍 Case-insensitive agent/producer filter applied: "${agent}"`);
      }

      // Apply case-insensitive RGA filter (exact match, case-insensitive)
      if (rga && rga !== 'all') {
        // Use ilike for case-insensitive exact match (no wildcards needed)
        query = query.ilike('agent_rga_team', rga);
        countQuery = countQuery.ilike('agent_rga_team', rga);
        console.log(`🔍 Case-insensitive RGA filter applied: "${rga}"`);
      }

      // Apply case-insensitive MGA filter (exact match, case-insensitive)
      if (mga && mga !== 'all') {
        // Use ilike for case-insensitive exact match (no wildcards needed)
        query = query.ilike('agent_mga_team', mga);
        countQuery = countQuery.ilike('agent_mga_team', mga);
        console.log(`🔍 Case-insensitive MGA filter applied: "${mga}"`);
      }

      // Apply RBAC filtering based on new capability system (ONLY FILTER - hierarchy access)
      if (!isTeamManagerScope && permissions.precheck.readScope === 'assigned_mga') {
        // Quality Manager and similar roles - filter by assigned teams
        if (permissions.allowedMgaTeams && permissions.allowedMgaTeams.length > 0) {
          // ✅ FIXED: Case-insensitive RBAC filtering - use ilike for each team
          const teamFilters = permissions.allowedMgaTeams.map(team => `agent_mga_team.ilike.${team}`).join(',');
          query = query.or(`${teamFilters},agent_mga_team.is.null`);
          countQuery = countQuery.or(`${teamFilters},agent_mga_team.is.null`);
          console.log(`🔐 RBAC ENABLED - Case-insensitive filtering by assigned MGA teams (including null):`, permissions.allowedMgaTeams.slice(0, 5), `... (${permissions.allowedMgaTeams.length} total teams)`);
        } else {
          // If no teams assigned, show sessions with null MGA team (unassigned sessions)
          query = query.is('agent_mga_team', null);
          countQuery = countQuery.is('agent_mga_team', null);
          console.log(`⚠️ Quality Manager has no assigned teams - showing only unassigned sessions`);
        }
      } else if (!isTeamManagerScope && permissions.precheck.readScope === 'all') {
        // AO Quality Manager - see all sessions (no filtering)
        console.log(`🌍 AO Quality Manager - showing all sessions`);
      }

      // Apply date range filter to Supabase queries
      if (dateRange && dateRange !== 'all') {
        const now = new Date();
        let startDate: Date;
        let endDate: Date | null = null;
        
        switch (dateRange) {
          case 'today':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
            break;
          case 'yesterday':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
            endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59, 999);
            break;
          case 'week':
            startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            break;
          case 'month':
            startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            break;
          default:
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        }
        
        if (dateRange === 'yesterday') {
          query = query.gte('created_at', startDate.toISOString()).lt('created_at', endDate!.toISOString());
          countQuery = countQuery.gte('created_at', startDate.toISOString()).lt('created_at', endDate!.toISOString());
        } else {
          query = query.gte('created_at', startDate.toISOString());
          countQuery = countQuery.gte('created_at', startDate.toISOString());
        }
        console.log(`📅 Date range filter applied: ${dateRange} (from ${startDate.toISOString()})`);
      }

      // CRITICAL: Apply ordering AFTER all filters to ensure most recent sessions appear first
      // MUST be the last operation before range() to ensure proper sorting
      // Use nullsLast: false to ensure NULL dates come last
      // FORCE ordering by removing any existing order and applying fresh
      query = query.order('created_at', { ascending: false, nullsFirst: false, foreignTable: undefined });

      // Apply pagination (range is applied AFTER ordering and all filters)
      query = query.range(offset, offset + pageSize - 1);

      console.log(`🔍 FINAL QUERY DEBUG: offset=${offset}, pageSize=${pageSize}, dateRange=${dateRange || 'all'}, ordering=created_at DESC (nullsLast)`);

      // Execute both queries in parallel
      const [{ data: result, error }, { count: totalCount, error: countError }] = await Promise.all([
        query,
        countQuery
      ]);

      if (error) {
        console.error('❌ Supabase query error:', error);
        return res.status(500).json({ error: 'Database query failed' });
      }

      // Log query results for debugging - check if most recent sessions are included
      if (result && result.length > 0) {
        const newestSession = result[0];
        const oldestSession = result[result.length - 1];
        const now = new Date();
        const newestDate = new Date(newestSession.created_at);
        const daysAgo = Math.floor((now.getTime() - newestDate.getTime()) / (1000 * 60 * 60 * 24));
        
        console.log(`📊 Query returned ${result.length} sessions (total in DB: ${totalCount || 'unknown'})`);
        console.log(`   ⚠️ MOST RECENT SESSION: ${newestSession.created_at} (${daysAgo} days ago, ID: ${newestSession.id}, Status: ${newestSession.status})`);
        console.log(`   Oldest in result: ${oldestSession.created_at} (ID: ${oldestSession.id})`);
        console.log(`   Pagination: page ${pageNum}, size ${pageSize}, offset ${offset}`);
        console.log(`   Date range filter: ${dateRange || 'none'}`);
        
        if (daysAgo > 2) {
          console.error(`   🚨 WARNING: Most recent session is ${daysAgo} days old! Expected sessions from today.`);
        }
      } else {
        console.log(`⚠️ Query returned 0 sessions (total in DB: ${totalCount || 'unknown'})`);
        console.log(`   Pagination: page ${pageNum}, size ${pageSize}, offset ${offset}`);
        console.log(`   Date range filter: ${dateRange || 'none'}`);
      }

      // CRITICAL SAFETY: Re-sort results by created_at DESC to ensure newest first
      // This is a fallback in case Supabase ordering fails
      // Handle both string and Date objects for created_at
      const sortedResults = (result || []).sort((a: any, b: any) => {
        const dateA = a.created_at ? (typeof a.created_at === 'string' ? new Date(a.created_at) : a.created_at).getTime() : 0;
        const dateB = b.created_at ? (typeof b.created_at === 'string' ? new Date(b.created_at) : b.created_at).getTime() : 0;
        // Ensure newest (larger timestamp) comes first
        if (dateB > dateA) return 1;
        if (dateB < dateA) return -1;
        return 0;
      });
      
      // VERIFY sorting is correct - log if not
      if (sortedResults.length > 1) {
        const firstDate = sortedResults[0]?.created_at ? new Date(sortedResults[0].created_at).getTime() : 0;
        const lastDate = sortedResults[sortedResults.length - 1]?.created_at ? new Date(sortedResults[sortedResults.length - 1].created_at).getTime() : 0;
        if (firstDate < lastDate) {
          console.error('🚨 CRITICAL: Server-side sort FAILED! First session is older than last session!');
          console.error(`   First: ${sortedResults[0]?.created_at} (${firstDate}), Last: ${sortedResults[sortedResults.length - 1]?.created_at} (${lastDate})`);
        }
      }

      // Count verification sessions per phone (total attempts for each client)
      const uniquePhones = [...new Set((sortedResults || []).map((s: any) => s.phone).filter(Boolean))] as string[];
      let countsByPhone: Record<string, number> = {};
      if (uniquePhones.length > 0) {
        try {
          const countResult = await pool.query<{ phone: string; attempt_count: string }>(
            `SELECT phone, COUNT(*)::int as attempt_count FROM verification_sessions WHERE phone = ANY($1::text[]) GROUP BY phone`,
            [uniquePhones]
          );
          countsByPhone = Object.fromEntries(countResult.rows.map((r) => [r.phone, parseInt(r.attempt_count, 10) || 1]));
        } catch (countErr) {
          console.error('❌ Error fetching attempt counts by phone:', countErr);
        }
      }

      // Map verification_sessions fields to frontend expected field names
      const mappedSessions = sortedResults.map((session: any) => {
        return {
          ...session,
          // Map client and agent names
          client_name: `${session.first_name || ''} ${session.last_name || ''}`.trim(),
          client_email: '', // Not available in verification_sessions
          client_phone: session.phone,
          agent_name: `${session.agent_first_name || ''} ${session.agent_last_name || ''}`.trim(),
          agent_email: session.company_email || '',
          
          // Use MGA/RGA team from verification_sessions (will be fixed by proper creation logic)
          agent_mga_team: session.agent_mga_team,
          agent_rga_team: session.agent_rga_team,
          
          // JUST USE THE FUCKING URLs FROM THE DATABASE - THEY'RE ALREADY CORRECT!
          // Use taalk_call_url as fallback if recording_url is missing (for older sessions)
          recording_url: session.recording_url || session.taalk_call_url || null,
          screenshot_url: session.screenshot_url || session.screenshot_path,
          certificate_url: session.status === 'completed' ? `/api/aoi-precheck/download/certificate/${session.session_id}` : null,
          transcript_url: null,
          
          // Taalk Transcript and AI Summary - Include all fields from database
          call_transcript: session.call_transcript || null,
          taalk_ai_summary: session.taalk_ai_summary || null,
          ai_quick_recap: session.ai_quick_recap || null,
          ai_next_steps: session.ai_next_steps || null,
          ai_key_topics: session.ai_key_topics || null,
          ai_sentiment_score: session.ai_sentiment_score || null,
          ai_user_refused_call: session.ai_user_refused_call || false,
          ai_result: session.ai_result || null,
          ai_result_passed: session.ai_result_passed ?? null,
          ai_red_flags: session.ai_red_flags || null,
          ai_favorite_feature: session.ai_favorite_feature || null,
          ai_preview: session.ai_preview || null,
          
          // AI Validation Results
          screenshot_validation: session.screenshot_validation || null,
        screenshot_analysis_complete: session.screenshot_analysis_complete ?? null,
        screenshot_analysis_confidence: session.screenshot_analysis_confidence ?? null,
          // Attempts: total verification sessions for this client (by phone number)
          attempts: countsByPhone[session.phone] ?? 1,
          audio_analysis: session.audio_analysis || null,
        call_analysis_complete: session.call_analysis_complete ?? null,
        
        // Additional frontend fields
        verification_notes: session.verification_result || null,
          policy_number: null,
        beneficiary_info: session.spouse_name || null,
        premium_amount: (() => {
          const numericPremium = String(session.premium || '0').replace(/[^0-9.]/g, '');
          const parsed = parseFloat(numericPremium);
          return isNaN(parsed) ? null : parsed;
        })(),
        verification_score: null,
        screenshots_count: (session.screenshot_url || session.screenshot_path) ? 1 : 0,
        call_duration: session.taalk_call_duration || null,
        cancellation_reason: ''
        };
      });

      // Sessions are already filtered by RBAC at the database level
      console.log(`✅ Found ${mappedSessions.length} verification sessions from Supabase (total: ${totalCount || 0})`);
      
      // Return data with pagination metadata
      res.json({
        sessions: mappedSessions,
        pagination: {
          page: pageNum,
          limit: pageSize,
          total: totalCount || 0,
          totalPages: Math.ceil((totalCount || 0) / pageSize)
        }
      });

    } catch (error) {
      console.error('❌ Precheck sessions API error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  // Diagnostic endpoint to check database state
  app.get("/api/aoi-precheck/check-transcript-status", async (req, res) => {
    try {
      const { supabaseAdmin } = await import('./supabase');
      
      // Check if columns exist by trying to select them
      const { data: testSession, error: columnError } = await supabaseAdmin
        .from('verification_sessions')
        .select('session_id, call_transcript, taalk_ai_summary, taalk_call_id, status')
        .limit(1)
        .single();
      
      // Count total completed sessions
      const { count: totalCompleted } = await supabaseAdmin
        .from('verification_sessions')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'completed');
      
      // Count completed with taalk_call_id
      const { count: completedWithTaalkId } = await supabaseAdmin
        .from('verification_sessions')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'completed')
        .not('taalk_call_id', 'is', null);
      
      // Count missing transcript or summary
      const { count: missingData } = await supabaseAdmin
        .from('verification_sessions')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'completed')
        .not('taalk_call_id', 'is', null)
        .or('call_transcript.is.null,taalk_ai_summary.is.null');
      
      // Get a sample of completed sessions
      const { data: sampleSessions } = await supabaseAdmin
        .from('verification_sessions')
        .select('session_id, taalk_call_id, call_transcript, taalk_ai_summary, completed_at')
        .eq('status', 'completed')
        .not('taalk_call_id', 'is', null)
        .order('completed_at', { ascending: false })
        .limit(5);
      
      const diagnostics = {
        columnsExist: !columnError,
        columnError: columnError?.message || null,
        totalCompleted: totalCompleted || 0,
        completedWithTaalkId: completedWithTaalkId || 0,
        missingTranscriptOrSummary: missingData || 0,
        sampleSessions: sampleSessions?.map(s => ({
          session_id: s.session_id,
          taalk_call_id: s.taalk_call_id,
          has_transcript: !!s.call_transcript,
          has_summary: !!s.taalk_ai_summary,
          completed_at: s.completed_at
        })) || []
      };
      
      res.json(diagnostics);
    } catch (error: any) {
      console.error('❌ Error checking transcript status:', error);
      res.status(500).json({ error: 'Failed to check status', details: error.message });
    }
  });

