  app.get("/api/aoi-precheck/stats", async (req, res) => {
    try {
      // Get user permissions for RBAC - prioritize header over session
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string || req.headers['User-Email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const userEmail = headerEmail || sessionEmail;
      
      if (!userEmail) {
        console.error('❌ NO USER EMAIL FOUND - header:', headerEmail, 'session:', sessionEmail);
        return res.status(401).json({ error: 'User email required', debug: { headerEmail, sessionEmail } });
      }
      
      console.log(`🔍 STATS EMAIL DEBUG: header='${headerEmail}', session='${sessionEmail}', final='${userEmail}'`);
      
      const { getUserPermissions } = await import('./rbac-helper');
      const permissions = await getUserPermissions(userEmail);
      const teamManagerParam = req.query.teamManager ? String(req.query.teamManager).trim().toLowerCase() : '';
      const isTeamManagerScope = !!teamManagerParam;
      if (isTeamManagerScope && String(userEmail).trim().toLowerCase() !== teamManagerParam) {
        return res.status(403).json({ error: 'not authorized for this team view' });
      }
      
      const today = new Date();
      const todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate());

      // Use Supabase with same RBAC filtering as sessions endpoint
      let query = supabaseAdmin
        .from('verification_sessions')
        .select('status, created_at, agent_mga_team, agent_rga_team, company_email')
        .neq('session_type', 'demo'); // Filter out demo sessions

      if (isTeamManagerScope) {
        const { resolveManagerTeamEmails, teamEmailOrFilter } = await import('./aoprecheck-team-shared');
        const teamEmails = await resolveManagerTeamEmails(teamManagerParam);
        query = query.or(teamEmailOrFilter(teamEmails));
      }

      // Apply RBAC filtering based on user permissions
      if (!isTeamManagerScope && permissions.precheck.readScope === 'assigned_mga') {
        // Quality Manager and similar roles - filter by assigned teams
        if (permissions.allowedMgaTeams && permissions.allowedMgaTeams.length > 0) {
          // ✅ FIXED: Case-insensitive RBAC filtering - use ilike for each team
          const teamFilters = permissions.allowedMgaTeams.map(team => `agent_mga_team.ilike.${team}`).join(',');
          query = query.or(`${teamFilters},agent_mga_team.is.null`);
          console.log(`🔐 STATS RBAC ENABLED - Case-insensitive filtering by assigned MGA teams (including null):`, permissions.allowedMgaTeams.slice(0, 5), `... (${permissions.allowedMgaTeams.length} total teams)`);
        } else {
          // If no teams assigned, show sessions with null MGA team (unassigned sessions)
          query = query.is('agent_mga_team', null);
          console.log(`⚠️ Quality Manager has no assigned teams - showing only unassigned sessions`);
        }
      } else if (!isTeamManagerScope && permissions.precheck.readScope === 'all') {
        // AO Quality Manager - see all sessions (no filtering)
        console.log(`🌍 AO Quality Manager - showing all stats`);
      } else if (!isTeamManagerScope) {
        // Other roles - no access
        console.log(`🚫 No access to precheck stats for role: ${permissions.role}`);
        query = query.eq('agent_mga_team', 'NO_ACCESS'); // This will return no results
      }

      const { data, error } = await query;

      if (error) {
        console.error('❌ Supabase stats query error:', error);
        return res.json({ total: 0, completed: 0, in_progress: 0, failed: 0, today: 0 });
      }
      
      const stats = {
        total: data?.length || 0,
        completed: data?.filter(s => s.status === 'completed').length || 0,
        in_progress: data?.filter(s => s.status === 'in_progress').length || 0,
        failed: data?.filter(s => s.status === 'failed').length || 0,
        today: data?.filter(s => new Date(s.created_at) >= todayStart).length || 0
      };

      console.log(`📊 RBAC Stats for ${userEmail} (${permissions.role}):`, stats);
      res.json(stats);
    } catch (error) {
      console.error('❌ Precheck stats API error:', error);
      res.json({ total: 0, completed: 0, in_progress: 0, failed: 0, today: 0 });
    }
  });

