  // Agent Usage Stats API - Shows VDP online time and connects per agent
  app.get("/api/admin/usage-stats", async (req, res) => {
    try {
      const { dateRange = 'week' } = req.query;
      
      // Calculate date range
      const now = new Date();
      let startDate: Date;
      
      if (dateRange === 'today') {
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      } else if (dateRange === 'week') {
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      } else if (dateRange === 'month') {
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      } else {
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000); // Default to week
      }
      
      const startDateStr = startDate.toISOString();
      
      // Get VDP connects (picked calls)
      const { data: vdpCalls } = await supabaseAdmin
        ?.from('vdp_calls')
        .select('agent_email, created_at, duration, outcome, call_status')
        .gte('created_at', startDateStr) || { data: [] };
      
      // Get agent profiles with last_heartbeat to calculate online time
      const { data: agentProfiles } = await supabaseAdmin
        ?.from('agent_profiles')
        .select('email, last_heartbeat, status, VDPACTIVE, first_name, last_name') || { data: [] };
      
      // Aggregate by agent
      const agentStats = new Map<string, any>();
      
      // Process VDP calls to count connects
      (vdpCalls || []).forEach((call: any) => {
        if (!call.agent_email) return;
        
        if (!agentStats.has(call.agent_email)) {
          agentStats.set(call.agent_email, {
            email: call.agent_email,
            name: call.agent_email.split('@')[0],
            connects: 0,
            total_call_minutes: 0,
            vdp_active: false,
            last_activity: call.created_at
          });
        }
        
        const stats = agentStats.get(call.agent_email);
        
        // Count as connect if call was picked up (outcome = 'picked', 'connected', or duration > 30s)
        if (call.outcome === 'picked' || call.outcome === 'connected' || call.call_status === 'completed' || (call.duration && call.duration > 30)) {
          stats.connects++;
        }
        
        if (call.duration) stats.total_call_minutes += Math.round(call.duration / 60);
        
        if (new Date(call.created_at) > new Date(stats.last_activity)) {
          stats.last_activity = call.created_at;
        }
      });
      
      // Add agent profile info
      (agentProfiles || []).forEach((profile: any) => {
        if (!profile.email) return;
        
        if (agentStats.has(profile.email)) {
          const stats = agentStats.get(profile.email);
          stats.name = `${profile.first_name || ''} ${profile.last_name || ''}`.trim() || profile.email.split('@')[0];
          stats.vdp_active = profile.VDPACTIVE === 'ACTIVE';
        } else if (profile.VDPACTIVE === 'ACTIVE') {
          // Agent has VDP active but no calls yet
          agentStats.set(profile.email, {
            email: profile.email,
            name: `${profile.first_name || ''} ${profile.last_name || ''}`.trim() || profile.email.split('@')[0],
            connects: 0,
            total_call_minutes: 0,
            vdp_active: true,
            last_activity: profile.last_heartbeat
          });
        }
      });
      
      // Convert to array and sort by connects (most active first)
      const usageStats = Array.from(agentStats.values())
        .filter(s => s.vdp_active) // Only show VDP active agents
        .sort((a, b) => b.connects - a.connects);
      
      res.json({
        success: true,
        dateRange,
        startDate: startDateStr,
        totalAgents: usageStats.length,
        stats: usageStats
      });
      
    } catch (error: any) {
      console.error('❌ Usage stats API error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.put("/api/aoi-precheck/sessions/:sessionId", async (req, res) => {
    try {
      const { sessionId } = req.params;
      const updates = req.body;
      
      // 🔒 PERMISSION CHECK: Require admin permissions to modify sessions
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const userEmail = headerEmail || sessionEmail;
      
      if (!userEmail) {
        console.error('🚫 BLOCKED: No user email for session update');
        return res.status(401).json({ error: 'Authentication required to modify sessions' });
      }
      
      const { getUserPermissions } = await import('./rbac-helper');
      const permissions = await getUserPermissions(userEmail);
      
      // Only system admins and AO quality managers can modify sessions
      if (permissions.role !== 'system_admin' && permissions.role !== 'ao_quality_manager') {
        console.log(`🚫 BLOCKED: User ${userEmail} (role: ${permissions.role}) attempted to modify session ${sessionId} - INSUFFICIENT PERMISSIONS`);
        return res.status(403).json({ 
          error: 'Insufficient permissions', 
          message: 'Only system administrators and AO quality managers can modify sessions. Contact an administrator for access.' 
        });
      }
      
      console.log(`✅ PERMISSION GRANTED: User ${userEmail} (role: ${permissions.role}) updating session ${sessionId}`);
      
      if (!supabaseAdmin) {
        return res.status(500).json({ error: 'Database not available' });
      }

      const { data, error } = await supabaseAdmin
        .from('verification_sessions')
        .update({
          ...updates,
          updated_at: new Date().toISOString()
        })
        .eq('id', sessionId)
        .select()
        .single();

      if (error) {
        console.error('❌ Error updating precheck session:', error);
        return res.status(500).json({ error: 'Failed to update session' });
      }

      res.json(data);
    } catch (error) {
      console.error('❌ Update precheck session error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

