  // Status update endpoint with validation and audit tracking
  // Simple transmit endpoint - just update transmit_status
  app.post("/api/aoi-precheck/agent/transmit", async (req, res) => {
    try {
      const { sessionId, precheckType } = req.body;
      if (!sessionId) return res.status(400).json({ success: false, error: "sessionId required" });
      
      // Find session by session_id or id
      let { data: session } = await supabaseAdmin
        .from("verification_sessions")
        .select("id")
        .eq("session_id", sessionId)
        .maybeSingle();
      
      if (!session) {
        const result = await supabaseAdmin
          .from("verification_sessions")
          .select("id")
          .eq("id", sessionId)
          .maybeSingle();
        session = result.data || null;
      }
      
      if (!session) return res.status(404).json({ success: false, error: "Session not found" });
      
      // Update transmit_status
      const type = (precheckType || "live").toLowerCase();
      const now = new Date();
      const payload = type === "live" 
        ? { transmit_status: "transmitted", precheck_type: "live", transmitted_at: now.toISOString(), scheduled_delete_at: null }
        : { transmit_status: "scheduled_delete", precheck_type: type, transmitted_at: now.toISOString(), scheduled_delete_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString() };
      
      const { error } = await supabaseAdmin
        .from("verification_sessions")
        .update(payload)
        .eq("id", session.id);
      
      if (error) return res.status(500).json({ success: false, error: error.message });
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ success: false, error: error instanceof Error ? error.message : "Failed" });
    }
  });

  app.put("/api/aoi-precheck/sessions/:sessionId/status", async (req, res) => {
    try {
      const { sessionId } = req.params;
      const { status, note, updated_by } = req.body;
      
      // Check RBAC permissions
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const userEmail = headerEmail || sessionEmail;
      
      if (!userEmail) {
        console.error('❌ NO USER EMAIL FOR SESSION UPDATE - header:', headerEmail, 'session:', sessionEmail);
        return res.status(401).json({ error: 'User email required for session updates' });
      }
      
      const { getUserPermissions } = await import('./rbac-helper');
      const permissions = await getUserPermissions(userEmail);
      
      // Check if user can update status
      if (!permissions.precheck.canUpdateStatus) {
        console.log(`🚫 User ${userEmail} attempted to update status but lacks permission`);
        return res.status(403).json({ error: 'Insufficient permissions to update session status' });
      }
      
      // Validate required fields
      if (!status) {
        return res.status(400).json({ error: 'Status is required' });
      }

      // Validate status values
      const validStatuses = ['pending', 'in_progress', 'completed', 'failed', 'cancelled'];
      if (!validStatuses.includes(status)) {
        return res.status(400).json({ error: `Invalid status. Must be one of: ${validStatuses.join(', ')}` });
      }
      
      if (!supabaseAdmin) {
        return res.status(500).json({ error: 'Database not available' });
      }

      // Get current session to track status change
      console.log(`🔍 Fetching session with ID: ${sessionId}`);
      const { data: currentSession, error: fetchError } = await supabaseAdmin
        .from('verification_sessions')
        .select('status, first_name, last_name')
        .eq('id', parseInt(sessionId))
        .single();
      
      console.log(`📊 Fetch result - Session:`, currentSession, `Error:`, fetchError);

      if (fetchError || !currentSession) {
        return res.status(404).json({ error: 'Session not found' });
      }
      const oldStatus = currentSession.status;

      // Update the session status
      console.log(`🔄 Updating session ${sessionId} to status: ${status}`);
      const { data: updatedSession, error: updateError } = await supabaseAdmin
        .from('verification_sessions')
        .update({ status: status })
        .eq('id', parseInt(sessionId));

      if (updateError) {
        console.error('❌ Supabase update error:', updateError);
        return res.status(500).json({ error: 'Failed to update session status', details: updateError });
      }
      
      console.log('✅ Status update successful - no error returned');

      // Log the status change for audit trail
      const clientName = `${currentSession.first_name || ''} ${currentSession.last_name || ''}`.trim();
      console.log(`📋 AOI Precheck Status Change: Session ${sessionId} (${clientName}) changed from ${oldStatus} to ${status} by ${updated_by || 'manager'}${note ? ` - Note: ${note}` : ''}`);

      res.json({ 
        success: true, 
        session: updatedSession,
        statusChange: {
          from: oldStatus,
          to: status,
          note: note,
          updated_by: updated_by || 'manager',
          changed_at: new Date().toISOString()
        }
      });

    } catch (error) {
      console.error('❌ Status update error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

