          const agentName = (workerAttrs ? String(workerAttrs.full_name ?? workerAttrs.agent_email ?? workerAttrs.agent_id ?? 'Agent').trim() : 'Agent') || 'Agent';
          const market = (taskAttrs ? String(taskAttrs.market ?? 'Inbound').trim() : 'Inbound') || 'Inbound';
