  // Recent Connects feed for inbound panel – from inbound_success_events (609 TaskRouter) + vdp_calls (legacy). No throw – always 200.
  app.get("/api/inbound/recent-successes", async (req, res) => {
    // Prevent caching so the panel always shows fresh data
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    const safeJson = (events: any[], lastHourCount = 0) => {
      try { res.status(200).json({ events: events ?? [], lastHourCount }); } catch (_) {}
    };
    try {
      const limit = Math.min(10, Math.max(1, parseInt(String(req.query.limit || 5), 10) || 5));
      if (!supabaseAdmin) return safeJson([]);

      let viewerEmail: string | null = null;
      try {
        const authHeader = req.headers.authorization;
        if (authHeader && typeof authHeader === 'string' && authHeader.startsWith('Bearer ')) {
          const token = authHeader.substring(7);
          const { data: userResponse, error: authError } = await supabaseAdmin.auth.getUser(token);
          if (!authError && userResponse?.user?.email) viewerEmail = userResponse.user.email;
        }
        if (!viewerEmail) viewerEmail = (req.session as any)?.user?.email ?? (req.session as any)?.passport?.user?.email ?? (req.headers['x-user-email'] as string) ?? (req.headers['user-email'] as string) ?? null;
        viewerEmail = viewerEmail ? String(viewerEmail).toLowerCase().trim() : null;
      } catch (_) {}

      let normalizeMarket = (s: string | null | undefined) => (s != null && String(s).trim()) ? String(s).trim() : 'Unknown';
      let normalizeState = (s: string | null | undefined) => (s != null && String(s).trim()) ? String(s).trim().toUpperCase().slice(0, 2) : 'XX';
      let parseMarketFromCustomer: (c: any) => string[] = () => [];
      let parseStatesFromCustomer: (c: any) => string[] = () => [];
      try {
        const tr = await import('./taskrouter-service.js');
        normalizeMarket = tr.normalizeMarket;
        normalizeState = tr.normalizeState;
        parseMarketFromCustomer = tr.parseMarketFromCustomer;
        parseStatesFromCustomer = tr.parseStatesFromCustomer;
      } catch (_) {}

      let viewerElig: { markets: string[]; states: string[] } | null = null;
      if (viewerEmail && supabaseAdmin) {
        try {
          const { data: viewerCust } = await supabaseAdmin.from('customers').select('market, states').eq('company_email', viewerEmail).maybeSingle();
          if (viewerCust) viewerElig = { markets: parseMarketFromCustomer(viewerCust), states: parseStatesFromCustomer(viewerCust) };
        } catch (_) {}
      }

      const elig = (market: string, state: string) => {
        if (!viewerElig) return false;
        const callMarketNorm = normalizeMarket(market);
        const callStateNorm = normalizeState(state);
        if (callMarketNorm === 'Unknown') return false;
        const marketMatch = (viewerElig!.markets || []).some((m: string) => String(m).toLowerCase().includes(callMarketNorm.toLowerCase()) || callMarketNorm.toLowerCase().includes(String(m).toLowerCase()));
        if (!marketMatch) return false;
        // If state is unknown (VDP calls often lack state), show to any agent of matching market
        if (callStateNorm === 'XX') return marketMatch;
        const stateMatch = viewerElig!.states.includes(callStateNorm) || (viewerElig!.states || []).some((s: string) => s.includes(callStateNorm) || callStateNorm.includes(s));
        return stateMatch && marketMatch;
      };

      // 1) inbound_success_events = 609 TaskRouter accepts (primary source so Recent Connects actually shows connects)
      let iseRows: any[];
      const { data: iseData, error: iseError } = await supabaseAdmin
        .from('inbound_success_events')
        .select('id, agent_name, agent_id, agent_email, market, state, source, connected_at')
        .order('connected_at', { ascending: false })
        .limit(limit);
      if (iseError && (String(iseError.message || '').includes('agent_email') || String(iseError.message || '').includes('does not exist'))) {
        const { data: fallback } = await supabaseAdmin
          .from('inbound_success_events')
          .select('id, agent_name, agent_id, market, state, source, connected_at')
          .order('connected_at', { ascending: false })
          .limit(limit);
        iseRows = Array.isArray(fallback) ? fallback : [];
      } else {
        iseRows = Array.isArray(iseData) ? iseData : [];
      }
      const iseList: any[] = (iseRows ?? []).map((r: any) => {
        const market = (r?.market != null && String(r.market).trim()) ? String(r.market).trim() : 'Inbound';
        const state = (r?.state != null && String(r.state).trim()) ? String(r.state).trim() : '';
        const rowAgentEmail = (r?.agent_email != null && String(r.agent_email).trim()) ? String(r.agent_email).toLowerCase().trim() : null;
        const isMyCall = !!viewerEmail && !!rowAgentEmail && viewerEmail === rowAgentEmail;
        return {
          id: String(r?.id ?? ''),
          agentName: (r?.agent_name && String(r.agent_name).trim()) ? String(r.agent_name).trim() : 'Agent',
          market,
          state,
          city: undefined,
          source: 'inbound_success_events',
          connectedAt: r?.connected_at || new Date().toISOString(),
          eligible: isMyCall || elig(market, state),
        };
      });

      // 2) vdp_calls (legacy END events) – merge so both sources show
      const { data: vdpRows, error: vdpErr } = await supabaseAdmin
        .from('vdp_calls')
        .select('id, company_email, agent, updated_at, time, market, state, city')
        .or('event.eq.END,event.eq.end')
        .order('updated_at', { ascending: false })
        .limit(limit);
      const byEmail: Record<string, string> = {};
      const byAgentId: Record<string, string> = {};
      const vdpListRaw = !vdpErr && Array.isArray(vdpRows) ? vdpRows : [];
      if (vdpListRaw.length > 0) {
        try {
          const emails = [...new Set(vdpListRaw.map((r: any) => String(r?.company_email || '').toLowerCase().trim()).filter(Boolean))];
          const agentIds = [...new Set(vdpListRaw.map((r: any) => r?.agent).filter((a: any) => a != null && String(a).trim() !== ''))];
          if (emails.length > 0) {
            const { data: cust } = await supabaseAdmin.from('customers').select('company_email, first_name, last_name').in('company_email', emails);
            for (const c of cust || []) {
              const e = String(c?.company_email || '').toLowerCase().trim();
              const name = [c?.first_name, c?.last_name].filter(Boolean).join(' ').trim();
              if (e && name) byEmail[e] = name;
            }
            const { data: pl } = await supabaseAdmin.from('producerlist').select('company_email, first_name, last_name').in('company_email', emails);
            for (const p of pl || []) {
              const e = String(p?.company_email || '').toLowerCase().trim();
              if (e && !byEmail[e]) {
                const name = [p?.first_name, p?.last_name].filter(Boolean).join(' ').trim();
                if (name) byEmail[e] = name;
              }
            }
          }
          if (agentIds.length > 0) {
            const numericIds = agentIds.map((a: any) => parseInt(String(a), 10)).filter((n: number) => !Number.isNaN(n));
            if (numericIds.length > 0) {
              const { data: custByAssoc } = await supabaseAdmin.from('customers').select('associate_id, first_name, last_name').in('associate_id', numericIds);
              for (const c of custByAssoc || []) {
                const id = String(c?.associate_id);
                const name = [c?.first_name, c?.last_name].filter(Boolean).join(' ').trim();
                if (id && name) byAgentId[id] = name;
              }
            }
          }
        } catch (_) {}
      }
      const vdpList: any[] = vdpListRaw.map((r: any) => {
        const connectedAt = r?.updated_at || r?.time || new Date().toISOString();
        const email = r?.company_email ? String(r.company_email).toLowerCase().trim() : '';
        const agentId = r?.agent != null ? String(r.agent).trim() : '';
        let agentName = byAgentId[agentId] || byEmail[email] || 'Agent';
        if (agentName === 'Agent' && email) agentName = (email.split('@')[0] || '').replace(/[._]/g, ' ').replace(/\b\w/g, (ch: string) => ch.toUpperCase()) || 'Agent';
        const market = (r?.market && String(r.market).trim()) ? String(r.market).trim() : 'Inbound';
        const state = (r?.state != null && String(r.state).trim()) ? String(r.state).trim() : (r?.State != null && String(r.State).trim()) ? String(r.State).trim() : '';
        const city = (r?.city != null && String(r.city).trim()) ? String(r.city).trim() : (r?.City != null && String(r.City).trim()) ? String(r.City).trim() : undefined;
        const isMyCall = !!viewerEmail && !!email && viewerEmail === email;
        return { id: String(r?.id ?? ''), agentName, market, state, city: city || undefined, source: 'vdp_calls', connectedAt, eligible: isMyCall || elig(market, state) };
      });

      // Merge by connectedAt desc, then take limit
      const merged = [...iseList, ...vdpList].sort((a, b) => new Date(b.connectedAt).getTime() - new Date(a.connectedAt).getTime()).slice(0, limit);
      return safeJson(merged);
    } catch (e) {
      console.warn('Recent connects error:', e);
      return safeJson([]);
    }
  });

