  // Check VDP status based on TaskRouter status
  app.post("/api/vdp/check-status/:agentEmail", express.json(), async (req, res) => {
    try {
      const { agentEmail } = req.params;
      if (!agentEmail) {
        return res.status(400).json({ error: 'Agent email required' });
      }

      // Check TaskRouter status to determine if VDP should be online
      let shouldBeOffline = true;
      let reason = 'TaskRouter status unknown';
      
      try {
        const { getWorkerByEmail } = await import('./taskrouter-service.js');
        const worker = await getWorkerByEmail(agentEmail);
        
        if (worker) {
          const activityName = worker.activityName || '';
          const normalizedActivity = activityName.toLowerCase();
          
          // VDP should be online if worker is in AvailableInbound or BusyOnCall
          if (normalizedActivity.includes('availableinbound') || normalizedActivity.includes('available')) {
            shouldBeOffline = false;
            reason = `TaskRouter: ${activityName}`;
          } else if (normalizedActivity.includes('busy') || normalizedActivity.includes('call')) {
            shouldBeOffline = false;
            reason = `TaskRouter: ${activityName} (on call)`;
          } else if (normalizedActivity.includes('wrap')) {
            shouldBeOffline = false;
            reason = `TaskRouter: ${activityName} (wrap up)`;
          } else {
            shouldBeOffline = true;
            reason = `TaskRouter: ${activityName} (offline/unavailable)`;
          }
        } else {
          shouldBeOffline = true;
          reason = 'TaskRouter: Worker not found';
        }
      } catch (taskRouterError) {
        console.warn('⚠️ Could not check TaskRouter status for VDP check:', taskRouterError);
        // Default to offline if we can't check
        shouldBeOffline = true;
        reason = 'TaskRouter: Status check failed';
      }

      console.log(`🎯 VDP Status Check: ${agentEmail} → shouldBeOffline=${shouldBeOffline} (${reason})`);

      res.json({
        agent: agentEmail,
        shouldBeOffline,
        reason,
        action: shouldBeOffline ? 'take_offline' : 'bring_online',
        vdpCommand: shouldBeOffline ? 'TaalkVDP.close()' : 'TaalkVDP.open(agentId, params)'
      });
    } catch (error) {
      console.error('❌ Error checking VDP status:', error);
      res.status(500).json({ error: 'Failed to check VDP status' });
    }
  });
