  // ---------- TaskRouter: sync Worker from Voice device events (no frontend TaskRouter SDK) ----------
  // When device.registered → POST voice-online (create/update Worker, set AvailableInbound).
  // When device unregistered / power off → POST voice-offline (set Offline).
  // When call connects → POST voice-busy (set BusyOnCall); when call ends → POST voice-online again.
  async function getAgentEmailFromRequest(req: any, bodyFallback?: { email?: string }): Promise<string | null> {
    const sessionEmail = (req.session as any)?.user?.email;
    const jwtUserEmail = (req as any)?.user?.email;
    const headerEmail = (req.headers['x-user-email'] || req.headers['X-User-Email']) as string | undefined;
    if (sessionEmail || jwtUserEmail || headerEmail) {
      const e = (sessionEmail || jwtUserEmail || headerEmail)?.toString?.()?.trim?.()?.toLowerCase?.();
      if (e && e.includes('@')) return e;
    }
    if (supabaseAdmin) {
      try {
        const cookieHeader = req.headers.cookie || '';
        // Try sb-access-token (app-set) then Supabase default sb-<projectRef>-auth-token
        let token: string | null = null;
        const m1 = cookieHeader.match(/sb-access-token=([^;]+)/);
        if (m1) token = decodeURIComponent(m1[1].trim());
        if (!token) {
          const m2 = cookieHeader.match(/sb-[a-z0-9]+-auth-token=([^;]+)/);
          if (m2) token = decodeURIComponent(m2[1].trim());
        }
        if (token) {
          const { data: { user }, error } = await supabaseAdmin.auth.getUser(token);
          if (!error && user?.email) return user.email.trim().toLowerCase();
        }
      } catch (_) {}
    }
    // Fallback: body.email when request has cookies (same browser, frontend sends authState.user.email)
    if (bodyFallback?.email && req.headers.cookie) {
      const e = bodyFallback.email.toString().trim().toLowerCase();
      if (e && e.includes('@')) return e;
    }
    return null;
  }

  /** Charge saved Stripe card to clear negative prepaid credits ($1 per credit). */
  app.post("/api/payments/bring-credits-current", express.json(), async (req, res) => {
    try {
      const userEmail = await getAgentEmailFromRequest(req, req.body);
      if (!userEmail) {
        return res.status(401).json({ error: "Login required" });
      }
      if (!HARDCODED_CONFIG.STRIPE_SECRET_KEY || !stripe || typeof (stripe as Stripe).paymentIntents?.create !== "function") {
        return res.status(503).json({ error: "Stripe is not configured" });
      }

      const creditsRow = await connectnowService.getUserCredits(userEmail);
      const remaining =
        (creditsRow as { credits_remaining?: number; creditsRemaining?: number })?.credits_remaining ??
        (creditsRow as { creditsRemaining?: number })?.creditsRemaining ??
        0;
      if (remaining >= 0) {
        return res.status(400).json({
          error: "No credit deficit",
          credits_remaining: remaining,
        });
      }

      const deficitCredits = Math.ceil(Math.abs(Number(remaining)));
      if (!deficitCredits || deficitCredits > 100_000) {
        return res.status(400).json({ error: "Invalid deficit amount" });
      }

      const amountCents = deficitCredits * 100;
      const customers = await stripe.customers.list({ email: userEmail, limit: 1 });
      if (customers.data.length === 0) {
        return res.status(400).json({
          error: "No Stripe customer on file — use Buy credits once to add a card.",
        });
      }
      const customerId = customers.data[0].id;
      const customer = (await stripe.customers.retrieve(customerId, {
        expand: ["invoice_settings.default_payment_method"],
      })) as Stripe.Customer;
      let paymentMethodId: string | undefined;
      const dpm = customer.invoice_settings?.default_payment_method;
      if (typeof dpm === "string") paymentMethodId = dpm;
      else if (dpm && typeof dpm === "object" && "id" in dpm) {
        paymentMethodId = (dpm as Stripe.PaymentMethod).id;
      }
      if (!paymentMethodId) {
        const pms = await stripe.paymentMethods.list({
          customer: customerId,
          type: "card",
          limit: 5,
        });
        paymentMethodId = pms.data[0]?.id;
      }
      if (!paymentMethodId) {
        return res.status(400).json({
          error: "No saved card on file — complete Buy credits once, then retry Bring current.",
        });
      }

      const idem = req.body?.idempotencyKey;
      const idempotencyKey =
        typeof idem === "string" && idem.length > 0 && idem.length <= 255 ? idem : undefined;

      const piParams: Stripe.PaymentIntentCreateParams = {
        amount: amountCents,
        currency: "usd",
        customer: customerId,
        payment_method: paymentMethodId,
        confirm: true,
        off_session: true,
        metadata: {
          userEmail,
          kind: "bring_credits_current",
          credits: String(deficitCredits),
        },
        description: `Bring credits current (${deficitCredits} credits)`,
      };

      let pi: Stripe.PaymentIntent;
      try {
        pi = idempotencyKey
          ? await stripe.paymentIntents.create(piParams, { idempotencyKey })
          : await stripe.paymentIntents.create(piParams);
      } catch (err: unknown) {
        const e = err as { code?: string; message?: string; raw?: { payment_intent?: { client_secret?: string } } };
        if (e?.code === "authentication_required") {
          return res.status(402).json({
            error: "Your bank requires extra verification for this charge.",
            payment_intent_client_secret: e?.raw?.payment_intent?.client_secret ?? null,
          });
        }
        console.error("bring-credits-current Stripe error:", err);
        return res.status(400).json({
          error: e?.message || "Payment failed",
        });
      }

      if (pi.status !== "succeeded") {
        return res.status(400).json({
          error: `Payment not completed (${pi.status})`,
          status: pi.status,
        });
      }

      await connectnowService.addUserCredits(userEmail, deficitCredits);
      const updated = await connectnowService.getUserCredits(userEmail);
      const newRemaining =
        (updated as { credits_remaining?: number; creditsRemaining?: number })?.credits_remaining ??
        (updated as { creditsRemaining?: number })?.creditsRemaining ??
        0;

      console.log(
        `✅ bring-credits-current: ${userEmail} +${deficitCredits} credits ($${deficitCredits}) pi=${pi.id} balance=${newRemaining}`,
      );

      return res.json({
        ok: true,
        credits_added: deficitCredits,
        amount_usd: deficitCredits,
        payment_intent_id: pi.id,
        credits_remaining: newRemaining,
      });
    } catch (e: unknown) {
      const err = e as { message?: string };
      console.error("bring-credits-current error:", e);
      return res.status(500).json({ error: err?.message || "Server error" });
    }
  });

  // Legacy presence endpoint (client calls /agent/presence) - updates agent_live_call_status
  app.post("/agent/presence", express.json(), async (req, res) => {
    try {
      const agent_email = req.body?.agent_email || req.body?.email;
      if (!agent_email || !String(agent_email).includes('@')) {
        return res.status(400).json({ error: 'agent_email required' });
      }
      const status = req.body?.status === 'in_call' ? 'in_call' : 'available';
      if (supabaseAdmin) {
        const { error } = await supabaseAdmin.from('agent_live_call_status').upsert({
          agent_email: String(agent_email).trim().toLowerCase(),
          status,
          last_heartbeat_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        }, { onConflict: 'agent_email' });
        if (error) console.warn('agent/presence upsert:', error.message);
      }
      return res.status(200).json({ ok: true });
    } catch (e: any) {
      console.warn('agent/presence error:', e?.message);
      return res.status(200).json({ ok: true }); // Don't fail client - non-blocking
    }
  });

  // Manual recovery endpoint: mark an agent online and force a lease-queue warmup.
  // This is a direct "I am online and need leads now" path when heartbeat detection lags.
  app.post("/api/leads/signal-online-and-request", express.json(), async (req, res) => {
    try {
      const body = req.body || {};
      const resolvedEmail =
        String(body.agentEmail || body.agent_email || body.email || resolveUserEmail(req) || "")
          .trim()
          .toLowerCase();
      if (!resolvedEmail || !resolvedEmail.includes("@")) {
        return res.status(400).json({ success: false, error: "agentEmail required" });
      }

      const presenceStatus = String(body.status || "available") === "in_call" ? "in_call" : "available";
      const nowIso = new Date().toISOString();

      if (supabaseAdmin) {
        const { error: presenceErr } = await supabaseAdmin
          .from("agent_live_call_status")
          .upsert(
            {
              agent_email: resolvedEmail,
              status: presenceStatus,
              last_heartbeat_at: nowIso,
              updated_at: nowIso,
            },
            { onConflict: "agent_email" },
          );
        if (presenceErr) {
          console.warn("signal-online-and-request presence upsert failed:", presenceErr.message);
        }
      }

      if (!supabaseAdmin) {
        return res.status(503).json({
          success: false,
          error: "Supabase admin not initialized",
        });
      }

      const { data: customer } = await supabaseAdmin
        .from("customers")
        .select("company_email, personal_email, market, states")
        .or(`company_email.eq.${resolvedEmail},personal_email.eq.${resolvedEmail}`)
        .limit(1)
        .maybeSingle();

      const markets = parseArrayField((customer as any)?.market || []);
      const states = parseArrayField((customer as any)?.states || []);
      if (!customer || markets.length === 0 || states.length === 0) {
        return res.status(409).json({
          success: false,
          error: "MISSING_CUSTOMERS_ROUTING_PROFILE",
          statusTitle: "Routing profile missing",
          statusMessage:
            "Routing source is customers table only; this agent is missing market/states in Supabase customers.",
        });
      }

      await upsertAgentRoutingProfile({
        agentEmail: resolvedEmail,
        markets,
        states,
        source: "manual_signal_online",
      });

      const requestedQueue = String(body.queue || "hotlead");
      const leaseSync = await syncLeaseDialerLead({
        agentEmail: resolvedEmail,
        queue: requestedQueue,
      }).catch((syncError: any) => {
        console.warn("signal-online-and-request fast lease sync failed:", syncError?.message || syncError);
        return null;
      });

      outboundDialerLeadCache.clearCache(resolvedEmail);
      const leads = leaseSync?.lead ? [leaseSync.lead, ...(leaseSync.backupLeads || [])].filter(Boolean) : [];

      return res.json({
        success: true,
        agentEmail: resolvedEmail,
        status: presenceStatus,
        markets,
        states,
        warmed: leaseSync?.assigned ? 1 : 0,
        warmReason: leaseSync?.reason || null,
        mode: "leasedialer_v2",
        reused: leaseSync?.reused ?? false,
        assigned: leaseSync?.assigned ?? false,
        assignmentId: leaseSync?.assignmentId ?? null,
        leads,
        currentLead: leaseSync?.lead ?? null,
        backupLead: leaseSync?.backupLead ?? null,
        backupLeads: leaseSync?.backupLeads || [],
        total: leads.length,
      });
    } catch (error: any) {
      console.error("❌ /api/leads/signal-online-and-request failed:", error);
      return res.status(500).json({ success: false, error: error?.message || "Failed to signal online/request leads" });
    }
  });

  app.post("/api/agents/voice-online", express.json(), async (req, res) => {
    try {
      const email = await getAgentEmailFromRequest(req, req.body);
      if (!email) {
        const hasCookie = !!req.headers.cookie;
        const bodyEmail = (req.body && typeof req.body === 'object' && req.body.email) ? String(req.body.email) : '';
        console.log('voice-online: 401 no email (session/jwt/cookie not resolved)', { hasCookie, bodyEmail: bodyEmail ? '(present)' : '(missing)' });
        return res.status(401).json({ error: 'Login required' });
      }
      const {
        isTaskRouterConfigured,
        setWorkerAvailableForVoice,
      } = await import('./taskrouter-service.js');
      if (!isTaskRouterConfigured()) {
        console.log('voice-online: 503 TaskRouter not configured');
        return res.status(503).json({ error: 'TaskRouter not configured' });
      }
      let customer: { market?: unknown; states?: unknown; associate_id?: unknown; first_name?: string | null; last_name?: string | null } | null = null;
      if (supabaseAdmin) {
        const customerCols = 'market, states, associate_id, first_name, last_name';
        const { data: byCompany } = await supabaseAdmin
          .from('customers')
          .select(customerCols)
          .eq('company_email', email)
          .limit(1)
          .maybeSingle();
        if (byCompany) {
          customer = byCompany;
        } else {
          const { data: byPersonal } = await supabaseAdmin
            .from('customers')
            .select(customerCols)
            .eq('personal_email', email)
            .limit(1)
            .maybeSingle();
          if (byPersonal) customer = byPersonal;
        }
      }
      const { workerSid } = await setWorkerAvailableForVoice(email, customer);
      console.log('voice-online: OK', email, workerSid);
      
      // Notify Taalk about agent going online
      try {
        const { notifyTaalkAgentStatus } = await import('./taalk-agent-status.js');
        await notifyTaalkAgentStatus(email, 'online', {
          associateId: customer?.associate_id as number | undefined,
          market: customer?.market as string | undefined,
          states: customer?.states as string[] | undefined,
        });
      } catch (taalkError) {
        console.warn('⚠️ Failed to notify Taalk about agent online (non-fatal):', taalkError);
      }
      
      return res.status(200).json({ ok: true, workerSid });
    } catch (e) {
      console.error('voice-online error:', e);
      return res.status(500).json({ error: (e as Error).message });
    }
  });

