  // AMD (Answering Machine Detection) status callback
  app.post("/api/twilio/amd-status", async (req, res) => {
    try {
      const { CallSid, AnsweredBy, MachineDetectionDuration } = req.body;
      const agentEmail = req.query.agentEmail as string || req.body.agent_email || '';
      
      console.log(`📞 AMD callback received: CallSid=${CallSid}, AnsweredBy=${AnsweredBy}, Duration=${MachineDetectionDuration}ms, agentEmail=${agentEmail}`);
      console.log(`   Full request body:`, JSON.stringify(req.body, null, 2));
      
      if (!CallSid) {
        console.warn('⚠️ AMD callback missing CallSid - request body:', JSON.stringify(req.body));
        return res.status(200).send('OK'); // Always return 200 to Twilio
      }

      // Update twilio_call_logs with AMD result
      if (supabaseAdmin) {
        // Try to update by CallSid (could be parent or child)
        await TwilioCallLogger.updateAmdResult(CallSid, {
          answeredBy: AnsweredBy || null,
          machineDetectionDurationMs: MachineDetectionDuration ? parseInt(String(MachineDetectionDuration), 10) : null
        });
        
        // Also try to find child calls with this parent_call_sid and update them
        // (Twilio might send parent CallSid but we need to update child calls)
        const { data: childCalls } = await supabaseAdmin
          .from('twilio_call_logs')
          .select('twilio_call_sid')
          .eq('parent_call_sid', CallSid)
          .is('answered_by', null);
        
        if (childCalls && childCalls.length > 0) {
          console.log(`📞 Found ${childCalls.length} child calls with parent ${CallSid} - updating AMD for all`);
          for (const child of childCalls) {
            await TwilioCallLogger.updateAmdResult(child.twilio_call_sid, {
              answeredBy: AnsweredBy || null,
              machineDetectionDurationMs: MachineDetectionDuration ? parseInt(String(MachineDetectionDuration), 10) : null
            });
          }
        }
      } else {
        console.error('❌ AMD callback: supabaseAdmin is not available');
      }

      res.status(200).send('OK');
    } catch (error) {
      console.error('❌ AMD callback error:', error);
      console.error('   Error stack:', error instanceof Error ? error.stack : 'No stack trace');
      console.error('   Request body:', JSON.stringify(req.body));
      res.status(200).send('OK'); // Always return 200 to Twilio even on error
    }
  });

  // Recording status webhook - CRITICAL: This updates recording_url in twilio_call_logs
  app.post("/api/twilio/recording-status", express.urlencoded({ extended: false }), async (req, res) => {
    try {
      const CallSid = req.body.CallSid;
      const ConferenceSid = req.body.ConferenceSid;
      const RecordingSid = req.body.RecordingSid;
      const RecordingUrl = req.body.RecordingUrl ?? req.body.recording_url ?? null;
      const RecordingStatus = req.body.RecordingStatus ?? req.body.recording_status ?? null;
      const RecordingDuration = req.body.RecordingDuration ?? req.body.recording_duration;

      console.log(`📹 Recording status webhook: CallSid=${CallSid}, ConferenceSid=${ConferenceSid}, Status=${RecordingStatus}, URL=${RecordingUrl ? 'present' : 'missing'}`);

      if (RecordingStatus !== "completed" || !RecordingUrl) {
        console.log(`📹 Recording not completed or missing URL - skipping update. Status=${RecordingStatus}, URL=${RecordingUrl ? 'present' : 'missing'}`);
        res.status(200).send("OK");
        return;
      }

      // Update by CallSid (direct calls)
      // CRITICAL: For WebRTC direct calls, Twilio sends the parent CallSid (the WebRTC call from agent)
      // We need to update BOTH the parent call AND any child calls (the actual outbound calls to leads)
      if (CallSid) {
        console.log(`📹 Updating recording URL for CallSid=${CallSid}`);
        
        // First, update the parent call (the WebRTC call)
        const { data: row } = await supabaseAdmin.from("twilio_call_logs").select("metadata").eq("twilio_call_sid", CallSid).maybeSingle();
        const existingMeta = (row?.metadata && typeof row.metadata === "object") ? row.metadata : (typeof row?.metadata === "string" ? JSON.parse(String(row?.metadata || "{}")) : {});
        const updatedMeta = { ...existingMeta, recording_url: RecordingUrl, recording_sid: RecordingSid, recording_duration: RecordingDuration ? parseInt(String(RecordingDuration), 10) : null };
        const { data: updated, error } = await supabaseAdmin.from("twilio_call_logs").update({ metadata: updatedMeta, recording_url: RecordingUrl }).eq("twilio_call_sid", CallSid).select("twilio_call_sid");
        if (error) {
          console.error(`❌ Failed to update recording URL for parent call ${CallSid}:`, error);
        } else if (updated && updated.length > 0) {
          console.log(`✅ Successfully updated recording URL for parent call ${CallSid}: ${RecordingUrl}`);
        } else {
          console.warn(`⚠️ No rows updated for parent call ${CallSid} - call may not exist in twilio_call_logs yet`);
        }
        
        // CRITICAL: Also update any child calls (the actual outbound calls to leads)
        // For direct calls, the child call is the one that was actually dialed to the lead
        const { data: childCalls, error: childError } = await supabaseAdmin
          .from("twilio_call_logs")
          .select("twilio_call_sid, metadata")
          .eq("parent_call_sid", CallSid);
        
        if (childError) {
          console.error(`❌ Failed to find child calls for parent ${CallSid}:`, childError);
        } else if (childCalls && childCalls.length > 0) {
          console.log(`📹 Found ${childCalls.length} child call(s) for parent ${CallSid} - updating recording URL for all`);
          for (const child of childCalls) {
            const childExistingMeta = (child.metadata && typeof child.metadata === "object") ? child.metadata : (typeof child.metadata === "string" ? JSON.parse(String(child.metadata || "{}")) : {});
            const childUpdatedMeta = { ...childExistingMeta, recording_url: RecordingUrl, recording_sid: RecordingSid, recording_duration: RecordingDuration ? parseInt(String(RecordingDuration), 10) : null };
            const { error: childUpdateError } = await supabaseAdmin
              .from("twilio_call_logs")
              .update({ metadata: childUpdatedMeta, recording_url: RecordingUrl })
              .eq("twilio_call_sid", child.twilio_call_sid);
            
            if (childUpdateError) {
              console.error(`❌ Failed to update recording URL for child call ${child.twilio_call_sid}:`, childUpdateError);
            } else {
              console.log(`✅ Successfully updated recording URL for child call ${child.twilio_call_sid}: ${RecordingUrl}`);
            }
          }
        } else {
          console.log(`📹 No child calls found for parent ${CallSid} - this may be a direct call without a child`);
        }
      }
      
      // Update by ConferenceSid (conference calls - WebRTC inbound/outbound)
      if (ConferenceSid && !CallSid) {
        console.log(`📹 Updating recording URL for ConferenceSid=${ConferenceSid}`);
        // Find all calls with this conference_sid in metadata
        const { data: rows } = await supabaseAdmin
          .from("twilio_call_logs")
          .select("twilio_call_sid, metadata")
          .or(`metadata->>conference_sid.eq.${ConferenceSid},metadata->conference_sid.eq.${ConferenceSid}`);
        
        if (rows && rows.length > 0) {
          for (const r of rows) {
            const existingMeta = (r.metadata && typeof r.metadata === "object") ? r.metadata : (typeof r.metadata === "string" ? JSON.parse(String(r.metadata || "{}")) : {});
            const updatedMeta = { ...existingMeta, recording_url: RecordingUrl, recording_sid: RecordingSid, recording_duration: RecordingDuration ? parseInt(String(RecordingDuration), 10) : null, conference_sid: ConferenceSid };
            const { error } = await supabaseAdmin.from("twilio_call_logs").update({ metadata: updatedMeta, recording_url: RecordingUrl }).eq("twilio_call_sid", r.twilio_call_sid);
            if (error) {
              console.error(`❌ Failed to update recording URL for conference call ${r.twilio_call_sid}:`, error);
            } else {
              console.log(`✅ Successfully updated recording URL for conference call ${r.twilio_call_sid}: ${RecordingUrl}`);
            }
          }
        } else {
          // If no calls found by conference_sid, try to find by matching call_started_at time window (within 5 seconds)
          console.log(`⚠️ No calls found with ConferenceSid=${ConferenceSid}, trying time-based lookup`);
          const now = new Date();
          const fiveSecondsAgo = new Date(now.getTime() - 5000);
          const { data: recentCalls } = await supabaseAdmin
            .from("twilio_call_logs")
            .select("twilio_call_sid, metadata, call_started_at")
            .gte("call_started_at", fiveSecondsAgo.toISOString())
            .lte("call_started_at", now.toISOString())
            .is("recording_url", null)
            .limit(10);
          
          if (recentCalls && recentCalls.length > 0) {
            console.log(`📹 Found ${recentCalls.length} recent calls without recording_url, updating first match`);
            const callToUpdate = recentCalls[0];
            const existingMeta = (callToUpdate.metadata && typeof callToUpdate.metadata === "object") ? callToUpdate.metadata : (typeof callToUpdate.metadata === "string" ? JSON.parse(String(callToUpdate.metadata || "{}")) : {});
            const updatedMeta = { ...existingMeta, recording_url: RecordingUrl, recording_sid: RecordingSid, recording_duration: RecordingDuration ? parseInt(String(RecordingDuration), 10) : null, conference_sid: ConferenceSid };
            const { error } = await supabaseAdmin.from("twilio_call_logs").update({ metadata: updatedMeta, recording_url: RecordingUrl }).eq("twilio_call_sid", callToUpdate.twilio_call_sid);
            if (error) {
              console.error(`❌ Failed to update recording URL for recent call ${callToUpdate.twilio_call_sid}:`, error);
            } else {
              console.log(`✅ Successfully updated recording URL for recent call ${callToUpdate.twilio_call_sid}: ${RecordingUrl}`);
            }
          }
        }
      }
      
      res.status(200).send("OK");
    } catch (error) {
      console.error('❌ Recording status webhook error:', error);
      console.error('   Error stack:', error instanceof Error ? error.stack : 'No stack trace');
      console.error('   Request body:', JSON.stringify(req.body, null, 2));
      res.status(200).send("OK"); // Always return 200 to Twilio
    }
  });

  // Post-call AMD result webhook (from <Dial action> callback)
  // This is called AFTER the dial completes, with the AMD result
  app.post("/api/twilio/amd-result", express.urlencoded({ extended: false }), async (req, res) => {
    try {
      const answeredBy = req.body.AnsweredBy; // human | machine_start | machine_end_beep | fax | unknown
      const callSid = req.body.CallSid;       // parent call sid
      const dialCallSid = req.body.DialCallSid; // child call sid (the actual dialed call)
      const to = req.body.To;
      const from = req.body.From;
      const dialCallStatus = req.body.DialCallStatus; // completed/busy/no-answer/failed

      // COMPREHENSIVE LOGGING - Log everything we receive from Twilio
      console.log("📞 AMD RESULT WEBHOOK RECEIVED", {
        answeredBy,
        callSid,
        dialCallSid,
        dialCallStatus,
        to,
        from,
        fullBody: JSON.stringify(req.body, null, 2),
        headers: JSON.stringify(req.headers, null, 2),
      });

      // Answered-by persistence is intentionally disabled.
      // Keep webhook ingest/logging only to avoid DB write pressure from AMD callbacks.
      console.warn(`⚠️ AMD result write skipped (answered_by disabled):`, {
        callSid: callSid || null,
        dialCallSid: dialCallSid || null,
        answeredBy: answeredBy || null,
        to: to || null,
      });

      // Always return TwiML response (even if empty)
      res.type("text/xml").send("<Response/>");
    } catch (error) {
      console.error('❌ AMD result webhook error:', error);
      console.error('   Error stack:', error instanceof Error ? error.stack : 'No stack trace');
      console.error('   Request body:', JSON.stringify(req.body));
      // Always return valid TwiML even on error
      res.type("text/xml").send("<Response/>");
    }
  });

  // CRITICAL: Twilio status callback - updates call durations, statuses, and answered_by
  app.post("/api/twilio/call-status", express.urlencoded({ extended: false }), express.json(), async (req, res) => {
    try {
      const body = (req.body && typeof req.body === "object") ? req.body as Record<string, any> : {};
      const query = (req.query && typeof req.query === "object") ? req.query as Record<string, any> : {};
      const CallSid = String(body.CallSid ?? query.CallSid ?? "").trim();
      const CallStatus = String(body.CallStatus ?? query.CallStatus ?? "").trim();
      const CallDuration = String(body.CallDuration ?? query.CallDuration ?? "").trim();
      const From = String(body.From ?? query.From ?? "").trim();
      const To = String(body.To ?? query.To ?? "").trim();
      const Direction = String(body.Direction ?? query.Direction ?? "").trim();
      const ParentCallSid = String(body.ParentCallSid ?? query.ParentCallSid ?? "").trim();
      const ConferenceSid = String(body.ConferenceSid ?? query.ConferenceSid ?? "").trim();
      const AnsweredBy = String(body.AnsweredBy ?? query.AnsweredBy ?? "").trim();
      if (!CallSid) {
        console.warn("⚠️ /api/twilio/call-status missing CallSid; skipping", {
          bodyKeys: Object.keys(body || {}),
          queryKeys: Object.keys(query || {}),
          contentType: req.headers["content-type"] || null,
        });
        return res.status(204).end();
      }
      const callbackContext = {
        agentEmail: String(query.agentEmail || body["metadata[agent_email]"] || body.agent_email || body.AgentEmail || "").trim(),
        leadId: String(query.leadId || body.leadId || body.lead_id || "").trim(),
        taalkLeadId: String(query.taalkLeadId || query.taalk_lead_id || body.taalkLeadId || body.taalk_lead_id || "").trim(),
        leadPhone: String(query.leadPhone || query.lead_phone || body.leadPhone || body.lead_phone || "").trim(),
        leadName: String(query.leadName || query.lead_name || body.leadName || body.lead_name || "").trim(),
        leadState: String(query.leadState || query.lead_state || body.leadState || body.lead_state || "").trim(),
        localPresenceFrom: String(query.localPresenceFrom || query.local_presence_from || body.localPresenceFrom || body.local_presence_from || "").trim(),
        assignmentId: String(query.assignmentId || query.assignment_id || body.assignmentId || body.assignment_id || "").trim(),
      };
      let agentEmail = callbackContext.agentEmail;
      if (!agentEmail && From && String(From).startsWith("client:") && String(From).includes("@")) {
        agentEmail = String(From).replace(/^client:/i, "").trim().toLowerCase();
      }
      const BAD_OWNER = ["cnsysop@aoglobelife.com", "unknown@aoglobelife.com", "system@aoglobelife.com", "unknown", ""];
      const isBadOwner = (e: string | null | undefined) => !e || !e.includes("@") || BAD_OWNER.includes((e || "").trim().toLowerCase());
      let ownerForLog: string | null = agentEmail && !isBadOwner(agentEmail) ? agentEmail.trim().toLowerCase() : null;
      if (CallSid && !ownerForLog && !ParentCallSid) {
        let childOwners: string[] = [];
        try {
          childOwners = await getChildOwnersForParentLocal(CallSid, 5);
        } catch (localErr) {
          console.warn(`⚠️ Local child-owner lookup failed for ${CallSid}; falling back to Supabase:`, localErr);
          const { data: children } = await supabaseAdmin.from("twilio_call_logs").select("owner_email").eq("parent_call_sid", CallSid).limit(5);
          childOwners = (children || []).map((r: any) => String(r?.owner_email || "").trim()).filter(Boolean);
        }
        const childOwner = childOwners.find((e: string) => e.includes("@") && !BAD_OWNER.includes(e.toLowerCase()));
        if (childOwner) ownerForLog = childOwner.toLowerCase();
      }

      if (CallSid) {
        try {
          console.log(`📞 Call status webhook: CallSid=${CallSid}, Status=${CallStatus}, Duration=${CallDuration}, AnsweredBy=${AnsweredBy || 'NULL'}, Owner=${ownerForLog || 'none'}, To=${To || 'MISSING'}, From=${From || 'MISSING'}, Direction=${Direction || 'MISSING'}`);
          
          // CRITICAL: Determine call direction correctly
          // WebRTC calls from agents (From starts with "client:") are ALWAYS outbound
          // Check existing call record first to preserve correct direction
          let direction = "outbound"; // Default to outbound for WebRTC
          let existingCall: any = null;
          if (From && String(From).startsWith("client:")) {
            direction = "outbound"; // WebRTC agent calls are outbound
          } else if (Direction && /outbound/i.test(String(Direction))) {
            direction = "outbound";
          } else if (Direction && /inbound/i.test(String(Direction))) {
            direction = "inbound";
          } else {
            // Check existing call record to preserve direction
            try {
              let existingCallRow: any = null;
              try {
                existingCallRow = await getTwilioCallBySidLocal(CallSid);
              } catch (localErr) {
                console.warn(`⚠️ Local twilio_call_logs lookup failed for ${CallSid}; falling back to Supabase:`, localErr);
                const { data } = await supabaseAdmin
                  .from("twilio_call_logs")
                  .select("call_direction,to_number,metadata,call_source")
                  .eq("twilio_call_sid", CallSid)
                  .maybeSingle();
                existingCallRow = data || null;
              }
              existingCall = existingCallRow || null;
              if (existingCallRow?.call_direction) {
                direction = existingCallRow.call_direction;
                console.log(`📞 Using existing call_direction from database: ${direction}`);
              }
            } catch (checkError) {
              console.warn(`⚠️ Could not check existing call direction:`, checkError);
            }
          }

          // CRITICAL: Twilio parent leg callbacks often have no usable To number.
          // Never overwrite a valid stored to_number with null/invalid values.
          const toRaw = String(To || "").trim();
          const numericTo = toRaw.replace(/[^\d+]/g, "");
          const isUsablePhoneTo = numericTo.length >= 10 && !toRaw.toLowerCase().startsWith("client:");
          let resolvedToNumber: string | null = isUsablePhoneTo ? toRaw : null;
          if (!resolvedToNumber && existingCall?.to_number) {
            resolvedToNumber = String(existingCall.to_number).trim() || null;
          }
          if (!resolvedToNumber) {
            const metadataLeadPhone = String(existingCall?.metadata?.lead_phone || req.body["metadata[lead_phone]"] || "").trim();
            const metadataLeadPhoneDigits = metadataLeadPhone.replace(/[^\d+]/g, "");
            if (metadataLeadPhoneDigits.length >= 10) {
              resolvedToNumber = metadataLeadPhone;
            }
          }
          if (!resolvedToNumber && !ParentCallSid) {
            let latestChildTo: string | null = null;
            try {
              latestChildTo = await getLatestChildToNumberLocal(CallSid);
            } catch (localErr) {
              console.warn(`⚠️ Local child to_number lookup failed for ${CallSid}; falling back to Supabase:`, localErr);
              const { data: childCall } = await supabaseAdmin
                .from("twilio_call_logs")
                .select("to_number")
                .eq("parent_call_sid", CallSid)
                .not("to_number", "is", null)
                .neq("to_number", "")
                .order("call_started_at", { ascending: false })
                .limit(1)
                .maybeSingle();
              latestChildTo = childCall?.to_number ? String(childCall.to_number).trim() : null;
            }
            if (latestChildTo) {
              resolvedToNumber = latestChildTo;
            }
          }
          // WebRTC/client status callbacks often omit PSTN to_number.
          // Recover a real phone from this owner's most recent PSTN leg so lead matching remains possible.
          if (!resolvedToNumber && ownerForLog) {
            try {
              const twoHoursAgoIso = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();
              let recentPstn = await getLatestPstnCallByOwnerLocal(ownerForLog, twoHoursAgoIso);
              if (!recentPstn) {
                recentPstn = await getLatestPstnCallByOwnerLocal(ownerForLog);
              }
              const candidateTo = String((recentPstn as any)?.to_number || "").trim();
              const candidateFrom = String((recentPstn as any)?.from_number || "").trim();
              const candidate = [candidateTo, candidateFrom].find((n) => {
                if (!n) return false;
                const digits = n.replace(/[^\d]/g, "");
                return digits.length >= 10 && !n.toLowerCase().startsWith("client:");
              });
              if (candidate) {
                resolvedToNumber = candidate;
                console.log(
                  `📞 call-status recovered PSTN number for ${CallSid} from owner recent leg ${String((recentPstn as any)?.twilio_call_sid || "unknown")}: ${candidate}`,
                );
              }
            } catch (recoverErr) {
              console.warn(`⚠️ call-status PSTN recovery failed for ${CallSid}:`, (recoverErr as Error)?.message);
            }
          }
          
          const status = (CallStatus || "").toLowerCase();
          const duration = CallDuration ? parseInt(CallDuration, 10) : null;

          // Clean up TaskRouter pending and complete task when call ends (caller or agent hangup)
          if (CallSid && ['completed', 'canceled', 'busy', 'failed'].includes(status)) {
            await cleanupTaskRouterStateForCall(CallSid);
          }

          const existingMeta =
            existingCall?.metadata && typeof existingCall.metadata === "object"
              ? existingCall.metadata
              : {};
          const callMetadata: Record<string, unknown> = {
            ...existingMeta,
            agent_email: ownerForLog || callbackContext.agentEmail || null,
            lead_id: callbackContext.leadId || (existingMeta as any).lead_id || null,
            leadId: callbackContext.leadId || (existingMeta as any).leadId || null,
            taalk_lead_id: callbackContext.taalkLeadId || (existingMeta as any).taalk_lead_id || null,
            taalkLeadId: callbackContext.taalkLeadId || (existingMeta as any).taalkLeadId || null,
            lead_phone: callbackContext.leadPhone || resolvedToNumber || (existingMeta as any).lead_phone || null,
            leadPhone: callbackContext.leadPhone || resolvedToNumber || (existingMeta as any).leadPhone || null,
            lead_name: callbackContext.leadName || (existingMeta as any).lead_name || null,
            leadName: callbackContext.leadName || (existingMeta as any).leadName || null,
            lead_state: callbackContext.leadState || (existingMeta as any).lead_state || null,
            leadState: callbackContext.leadState || (existingMeta as any).leadState || null,
            local_presence_from: callbackContext.localPresenceFrom || (existingMeta as any).local_presence_from || (existingMeta as any).caller_id || null,
            caller_id: callbackContext.localPresenceFrom || (existingMeta as any).caller_id || null,
            assignment_id: callbackContext.assignmentId || (existingMeta as any).assignment_id || null,
          };

          const numericCallbackLeadId = Number(callbackContext.leadId);
          const dbLeadId = Number.isFinite(numericCallbackLeadId) && numericCallbackLeadId > 0 ? numericCallbackLeadId : null;
          const callData: Record<string, unknown> = {
            twilio_call_sid: CallSid,
            owner_email: ownerForLog,
            agent_identity: ownerForLog ? `client:${ownerForLog}` : null,
            from_number: From || null,
            to_number: resolvedToNumber, // preserve/fallback when Twilio callback omits phone on parent leg
            call_direction: direction,
            call_status: status || "initiated",
            call_duration: duration, // CRITICAL: This updates the duration from 0 to actual value
            call_started_at: new Date().toISOString(),
            parent_call_sid: ParentCallSid || null,
            call_source: "twilio_call_status_webhook",
            metadata: callMetadata,
            lead_id: dbLeadId || null,
            taalk_lead_id: callbackContext.taalkLeadId || (existingCall as any)?.taalk_lead_id || null,
          };
          // Inbound 609: preserve call_source and mark as transfer when an agent took the call
          if (existingCall?.call_source === 'incomingcall_609') {
            callData.call_source = 'incomingcall_609';
            if (ownerForLog || (existingCall as any)?.owner_email) callData.is_transferred = true;
          }
          
          // Answered-by persistence is intentionally disabled.
          
          if (status === "completed" || status === "failed") callData.call_ended_at = new Date().toISOString();
          let writeError: unknown = null;
          try {
            await upsertTwilioCallLogLocal(callData);
          } catch (localErr) {
            writeError = localErr;
          }

          await incrementLeadCallAttemptCounter({
            callSid: CallSid,
            toNumber: resolvedToNumber || To || null,
            direction,
            status,
          }).catch((counterErr) => {
            console.warn("⚠️ Lead call counter increment failed:", counterErr);
          });
          
          if (writeError) {
            console.error(`❌ CRITICAL: Failed to upsert call ${CallSid} to twilio_call_logs:`, writeError);
            console.error(`   Error details:`, JSON.stringify(writeError, null, 2));
            console.error(`   Call data:`, JSON.stringify(callData, null, 2));
          } else {
            console.log(`✅ Successfully upserted call ${CallSid} to twilio_call_logs - Duration: ${duration || 'NULL'}, Status: ${status}, AnsweredBy: ${AnsweredBy || 'NULL'}, To: ${To || 'NULL'}`);
            if (
              direction === "outbound" &&
              ownerForLog &&
              ["failed", "no-answer", "no_answer", "busy", "canceled", "cancelled"].includes(status)
            ) {
              await autoResolveFailedOutboundCall({
                ownerEmail: ownerForLog,
                leadId: callbackContext.leadId || String(callData.lead_id || ""),
                taalkLeadId:
                  callbackContext.taalkLeadId ||
                  String(callData.taalk_lead_id || (callMetadata as any).taalk_lead_id || (callMetadata as any).taalkLeadId || ""),
                toNumber: resolvedToNumber || To || null,
                status,
                callSid: CallSid,
              }).catch((autoResolveErr) => {
                console.warn(`⚠️ autoResolveFailedOutboundCall failed for ${CallSid}:`, (autoResolveErr as Error)?.message || autoResolveErr);
              });
            }
            try {
              const { pushStatusEvent } = await import('./twilio-task-route-service');
              pushStatusEvent({ callSid: CallSid, status, duration: duration ?? undefined, owner: ownerForLog ?? undefined });
              // Client polls by caller (task) call_sid; when agent leg ends we get agent's CallSid – push caller SID too so UI updates
              if (ParentCallSid && (status === 'completed' || status === 'failed')) {
                pushStatusEvent({ callSid: ParentCallSid, status, duration: duration ?? undefined, owner: ownerForLog ?? undefined });
              }
              if (From && String(From).startsWith('client:') && (status === 'completed' || status === 'failed') && ownerForLog) {
                let inboundCallSid: string | null = null;
                try {
                  inboundCallSid = await getLatestInbound609CallSidByOwnerLocal(ownerForLog);
                } catch (localErr) {
                  console.warn(`⚠️ Local inbound-609 lookup failed for ${ownerForLog}; falling back to Supabase:`, localErr);
                  const { data: inboundRow } = await supabaseAdmin.from('twilio_call_logs').select('twilio_call_sid').eq('call_source', 'incomingcall_609').eq('owner_email', ownerForLog).order('call_started_at', { ascending: false }).limit(1).maybeSingle();
                  inboundCallSid = inboundRow?.twilio_call_sid || null;
                }
                if (inboundCallSid && inboundCallSid !== CallSid) {
                  pushStatusEvent({ callSid: inboundCallSid, status, duration: duration ?? undefined, owner: ownerForLog });
                }
              }
            } catch (_) {}
            // 🔥 CRITICAL: Automatically send webhook if call ended with duration >= 45 seconds
            if ((status === "completed" || status === "failed") && duration && duration >= 45 && direction === "outbound" && ownerForLog) {
              try {
                // Get the upserted call to access metadata
                let upsertedCall: any = null;
                try {
                  upsertedCall = { metadata: await getTwilioCallMetadataLocal(CallSid) };
                } catch (localErr) {
                  console.warn(`⚠️ Local metadata lookup failed for ${CallSid}; falling back to Supabase:`, localErr);
                  const { data } = await supabaseAdmin
                    .from('twilio_call_logs')
                    .select('metadata')
                    .eq('twilio_call_sid', CallSid)
                    .maybeSingle();
                  upsertedCall = data || null;
                }
                
                // Resolve lead from call metadata or phone number
                const meta = upsertedCall?.metadata || existingCall?.metadata || {};
                const leadIdFromMeta = meta.lead_id || meta.leadId || meta.taalk_lead_id || meta.taalkLeadId;
                const leadPhoneFromMeta = meta.lead_phone || meta.leadPhone || resolvedToNumber;
                
                let lead: any = null;
                if (leadIdFromMeta) {
                  const { data: leadData } = await masterleadClient.from('masterlead')
                    .select('id, taalk_lead_id, associate_id')
                    .or(`id.eq.${leadIdFromMeta},taalk_lead_id.eq.${leadIdFromMeta}`)
                    .maybeSingle();
                  if (leadData) lead = leadData;
                }

                if (!lead && ownerForLog && leadPhoneFromMeta) {
                  const cleanPhone = String(leadPhoneFromMeta).replace(/\D/g, '').slice(-10);
                  if (cleanPhone.length >= 10) {
                    const metricResult = await pool.query(
                      `
                        SELECT lead_id, notes
                        FROM agent_dial_metrics
                        WHERE lower(agent_email) = lower($1)
                          AND lead_phone = $2
                          AND event_timestamp >= NOW() - INTERVAL '4 hours'
                        ORDER BY event_timestamp DESC NULLS LAST, id DESC
                        LIMIT 1
                      `,
                      [ownerForLog, cleanPhone],
                    ).catch(() => ({ rows: [] as any[] }));
                    const metric = metricResult.rows[0] || null;
                    let metricTaalkLeadId = '';
                    try {
                      const parsedNotes = metric?.notes ? JSON.parse(String(metric.notes)) : {};
                      metricTaalkLeadId = String(parsedNotes?.taalk_lead_id || parsedNotes?.taalkLeadId || '').trim();
                    } catch {
                      metricTaalkLeadId = '';
                    }
                    const metricLeadId = String(metric?.lead_id || '').trim();
                    const lookupId = metricTaalkLeadId || metricLeadId;
                    if (lookupId) {
                      const { data: leadData } = await masterleadClient
                        .from('masterlead')
                        .select('id, taalk_lead_id, associate_id')
                        .or(`id.eq.${lookupId},taalk_lead_id.eq.${lookupId}`)
                        .maybeSingle();
                      if (leadData) {
                        lead = leadData;
                        console.log(`📞 Auto 45s webhook resolved lead from agent_dial_metrics owner=${ownerForLog} phone=...${cleanPhone} lead=${lookupId}`);
                      }
                    }
                  }
                }
                
                if (!lead && leadPhoneFromMeta) {
                  const cleanPhone = String(leadPhoneFromMeta).replace(/\D/g, '').slice(-10);
                  if (cleanPhone.length >= 10) {
                    const { data: leadData } = await masterleadClient.from('masterlead')
                      .select('id, taalk_lead_id, associate_id, updated_at')
                      .or(`phone.eq.${cleanPhone},phone.eq.+1${cleanPhone},phone_number.eq.${cleanPhone},phone_number.eq.+1${cleanPhone}`)
                      .order('updated_at', { ascending: false })
                      .limit(1)
                      .maybeSingle();
                    if (leadData) lead = leadData;
                  }
                }
                
                if (lead) {
                  const taalkLeadId = await resolveTaalkLeadIdForWebhook({
                    lead,
                  });
                  const associateId = await resolveAssociateIdForZapier(ownerForLog);
                  
                  if (!taalkLeadId) {
                    console.warn(`⚠️ Cannot auto-send webhook: No taalk_lead_id resolved for call ${CallSid}`);
                  } else if (associateId) {
                    const webhookPayload = {
                      lead_id: taalkLeadId,
                      taalk_lead_id: taalkLeadId,
                      associate_id: associateId,
                      agent_email: ownerForLog
                    };
                    
                    console.log(`📤 Auto-sending 45-second reach webhook (call ended): ${taalkLeadId} (duration: ${duration}s)`);
                    
                    const webhookResponse = await fetch(ZAPIER_60SEC_CALL_URL, {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify(webhookPayload)
                    });
                    
                    if (webhookResponse.ok) {
                      console.log(`✅ Auto-sent 45-second reach webhook successfully (call ended)`);
                    } else {
                      console.error(`❌ Auto-send 45-second reach webhook failed: ${webhookResponse.status}`);
                    }
                  } else {
                    console.warn(`⚠️ Cannot auto-send webhook: No associate_id for ${ownerForLog}`);
                  }
                } else {
                  console.warn(`⚠️ Cannot auto-send webhook: Could not resolve lead for call ${CallSid}`);
                }
              } catch (webhookError) {
                console.warn('⚠️ Failed to auto-send 45-second reach webhook (non-blocking):', webhookError);
              }
            }
          }
        } catch (error) {
          console.error(`❌ CRITICAL ERROR in call-status webhook for ${CallSid}:`, error);
          console.error(`   Error stack:`, error instanceof Error ? error.stack : 'No stack trace');
          console.error(`   Request body:`, JSON.stringify(req.body, null, 2));
        }
      }
      res.status(204).end();
    } catch (error) {
      console.error(`❌ CRITICAL ERROR in call-status webhook handler:`, error);
      res.status(204).end(); // Always return 204 to Twilio
    }
  });

  // DIAL ACTION endpoint — called by Twilio when the outbound <Dial> ends (no-answer, busy, failed, completed).
  // Must return TwiML immediately so Twilio can hang up the call without waiting.
  // Logging is fire-and-forget so we never block the TwiML response.
  app.post("/api/twilio/dial-action", express.urlencoded({ extended: false }), async (req, res) => {
    // Return <Hangup/> immediately — this is what tells Twilio the call is done NOW.
    res.type('text/xml').send('<?xml version="1.0" encoding="UTF-8"?><Response><Hangup/></Response>');

    // Fire-and-forget: log the dial outcome asynchronously
    const { DialCallStatus, DialCallDuration, DialCallSid, CallSid, To } = req.body;
    const agentEmail = (req.query.agentEmail as string || '').trim();
    const leadId = String(req.query.leadId || '').trim();
    const taalkLeadId = String(req.query.taalkLeadId || req.query.taalk_lead_id || '').trim();
    const leadPhone = String(req.query.leadPhone || To || '').trim();
    const localPresenceFrom = String(req.query.localPresenceFrom || req.query.local_presence_from || '').trim();
    void (async () => {
      try {
        console.log(`📞 dial-action: CallSid=${CallSid} DialCallStatus=${DialCallStatus} DialDuration=${DialCallDuration}s To=${To} Agent=${agentEmail}`);
        if (DialCallSid) {
          const duration = DialCallDuration ? parseInt(DialCallDuration, 10) : 0;
          const numericLeadId = Number(leadId);
          await updateTwilioCallLogBySidLocal(DialCallSid, {
            owner_email: agentEmail || undefined,
            call_status: DialCallStatus || undefined,
            call_duration: duration,
            metadata: {
              agent_email: agentEmail || null,
              lead_id: leadId || null,
              leadId: leadId || null,
              taalk_lead_id: taalkLeadId || null,
              taalkLeadId: taalkLeadId || null,
              lead_phone: leadPhone || null,
              leadPhone: leadPhone || null,
              local_presence_from: localPresenceFrom || null,
              caller_id: localPresenceFrom || null,
            },
            lead_id: Number.isFinite(numericLeadId) && numericLeadId > 0 ? numericLeadId : undefined,
            taalk_lead_id: taalkLeadId || undefined,
          });
        }
        if (supabaseAdmin && DialCallSid) {
          await supabaseAdmin.from('twilio_call_logs')
            .update({ call_status: DialCallStatus, call_duration: DialCallDuration ? parseInt(DialCallDuration) : 0 })
            .eq('twilio_call_sid', DialCallSid);
        }
        const dialStatus = String(DialCallStatus || "").trim().toLowerCase();
        if (
          agentEmail &&
          ["failed", "no-answer", "no_answer", "busy", "canceled", "cancelled"].includes(dialStatus)
        ) {
          await autoResolveFailedOutboundCall({
            ownerEmail: agentEmail,
            leadId: leadId || null,
            taalkLeadId: taalkLeadId || null,
            toNumber: leadPhone || To || null,
            status: dialStatus,
            callSid: DialCallSid || CallSid || null,
          }).catch((autoResolveErr) => {
            console.warn(
              `⚠️ dial-action autoResolveFailedOutboundCall failed for ${DialCallSid || CallSid || "unknown"}:`,
              (autoResolveErr as Error)?.message || autoResolveErr,
            );
          });
        }
      } catch (e) {
        console.warn('⚠️ dial-action logging failed (non-critical):', e instanceof Error ? e.message : e);
      }
    })();
  });

  // TEST ENDPOINT: TwiML for AMD testing
  app.post("/api/twilio/test-amd-voice", express.urlencoded({ extended: false }), async (req, res) => {
    try {
      const callSid = req.body.CallSid || req.query.CallSid;
      const to = req.body.To || '+15032018470';
      const from = req.body.From || req.query.From;
      const amdResultUrl = `${PRODUCTION_BASE_URL}/api/twilio/amd-result`;
      const statusCallback = `${PRODUCTION_BASE_URL}/api/twilio/call-status`;
      
      console.log(`🧪 TEST AMD: Generating TwiML for ${to}, CallSid=${callSid}`);
      
      // Pre-log the call so status callback can find it
      if (callSid) {
        try {
          await upsertTwilioCallLogLocal({
            twilio_call_sid: callSid,
            from_number: from || 'TEST',
            to_number: to,
            call_direction: 'outbound',
            call_status: 'initiated',
            call_source: 'amd_test',
            owner_email: 'test@amd.test',
            call_started_at: new Date().toISOString(),
            created_at: new Date().toISOString(),
          });
          console.log(`✅ Pre-logged test call ${callSid}`);
        } catch (logError) {
          console.warn(`⚠️ Failed to pre-log test call:`, logError);
        }
      }
      
      const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="alice">This is a test call to verify AMD is working.</Say>
  <Dial 
    action="${amdResultUrl}"
    method="POST"
    statusCallback="${statusCallback}"
    statusCallbackMethod="POST"
    statusCallbackEvent="initiated,ringing,answered,completed">
    <Number>${to}</Number>
  </Dial>
</Response>`;
      
      res.type('text/xml').send(twiml);
    } catch (error) {
      console.error('❌ Test AMD voice endpoint error:', error);
      res.type('text/xml').send('<Response><Say>Error generating test TwiML</Say></Response>');
    }
  });

  // Dashboard routes (ConnectNow takes precedence)
  const dashboardService = new DashboardService(storage);

  // Helper function to get call history filtered by agent lead ownership
  async function getAgentOwnedCallHistory(agentEmail: string, range: string = 'today') {
    try {
      console.log(`🔍 Checking Supabase connection for call history...`);
      
      if (!supabaseAdmin) {
        console.warn('⚠️ Supabase not available, falling back to PostgreSQL');
        return [];
      }

      // Get date range
      const now = new Date();
      let startDate: Date;
      
      switch (range) {
        case 'yesterday':
          startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
          break;
        case 'week':
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          break;
        case 'month':
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          break;
        case 'all':
          startDate = new Date('2020-01-01'); // Far back date
          break;
        default: // today
          startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      }

      // CORRECTED APPROACH: Only get VDP calls that were directly assigned to this agent's leads
      // First, get all phone numbers for leads owned by this agent
      const { data: agentLeads, error: leadsError } = await masterleadClient.from('masterlead')
        .select('phone, first_name, last_name, cn_email')
        .eq('cn_email', agentEmail);

      if (leadsError) {
        console.error('❌ Error fetching agent leads:', leadsError);
        return [];
      }

      if (!agentLeads || agentLeads.length === 0) {
        console.log(`📋 No leads assigned to this agent: ${agentEmail}`);
        console.log('🚨🚨🚨 CRITICAL: AGENT HAS NO LEADS - this is why filtering fails!');
        // Return empty array instead of all calls
        return [];
      }

      // Get normalized phone numbers for this agent's leads
      const agentPhones = agentLeads.map(lead => lead.phone.replace(/\D/g, '').slice(-10));
      console.log(`📋 Agent ${agentEmail} owns ${agentPhones.length} leads`);

      // Now query VDP calls for these specific phone numbers only
      const phoneQueries = agentPhones.map(phone => `+1${phone}`);
      
      let allVdpCalls = [];
      
      // Query in batches to avoid URL length limits
      for (let i = 0; i < phoneQueries.length; i += 50) {
        const batch = phoneQueries.slice(i, i + 50);
        
        const { data: batchCalls, error: batchError } = await supabaseAdmin
          .from('vdp_calls')
          .select(`
            id,
            agent_email,
            agent_name,
            caller_phone,
            call_duration,
            call_status,
            created_at,
            market,
            lead_data,
            raw_webhook_data
          `)
          .in('caller_phone', batch)
          .gte('created_at', startDate.toISOString())
          .order('created_at', { ascending: false });

        if (!batchError && batchCalls) {
          allVdpCalls.push(...batchCalls);
        }
      }

      console.log(`📞 Found ${allVdpCalls.length} VDP calls for agent's owned leads`);

      const filteredCalls = allVdpCalls;

      // Transform to standard format
      const transformedCalls = filteredCalls.map(call => {
        const rawData = call.raw_webhook_data || {};
        return {
          id: call.id,
          leadName: rawData.name || `${rawData.clientfirstname || ''} ${rawData.clientlastname || ''}`.trim() || 'Unknown',
          phone: rawData.clientphone || call.caller_phone,
          agentEmail: call.agent_email,
          agentName: call.agent_name,
          duration: call.call_duration || 0,
          status: call.call_status || 'completed',
          timestamp: call.created_at,
          market: call.market || rawData.clientmarket || 'Unknown',
          leadSource: 'VDP Call',
          state: rawData.clientstate || 'Unknown'
        };
      });

      return transformedCalls;
    } catch (error) {
      console.error('❌ Error getting agent owned call history:', error);
      return [];
    }
  }
