  // Call Connector Pro heartbeat - frontend sends every 10s; updates in-memory tracker so /api/twilio-task-route/agents and inbound routing see agents as online
  app.post("/api/call-connector-pro/heartbeat", async (req, res) => {
    try {
      const { agentEmail, sessionId } = req.body;
      if (!agentEmail || !String(agentEmail).includes('@')) {
        return res.status(400).json({ error: 'Agent email is required' });
      }
      const { callConnectorTracker } = await import('./call-connector-tracker');
      const normalized = String(agentEmail).trim().toLowerCase();
      const localLeasedLeadCount = Math.max(0, Math.min(500, Number(req.body?.localLeasedLeadCount || 0) || 0));
      const currentLeadId = String(req.body?.currentLeadId || "").trim() || null;
      callConnectorTracker.updateHeartbeat(normalized, sessionId || 'default');
      const lastHeartbeat = new Date().toISOString();
      // Respond immediately; in-memory tracker is source of truth for same-process routing.
      res.json({ success: true, lastHeartbeat });
      // Queue client status update — batched every 5s to avoid per-agent lock contention
      // Only overwrite with 0 if we don't already have a higher count queued (prevents race where
      // client reports 0 before it has downloaded its assigned leads)
      const existing = pendingClientStatusUpserts.get(normalized);
      if (!existing || localLeasedLeadCount > 0 || existing.count === 0) {
        pendingClientStatusUpserts.set(normalized, { count: localLeasedLeadCount, leadId: currentLeadId });
      }
      void Promise.resolve().catch((error) => {
          console.warn("leasedialer client status upsert failed:", error?.message || error);
        });
      if (supabaseAdmin) {
        void supabaseAdmin
          .from('agent_live_call_status')
          .upsert(
            {
              agent_email: normalized,
              status: 'available',
              last_heartbeat_at: lastHeartbeat,
              updated_at: lastHeartbeat,
            },
            { onConflict: 'agent_email' },
          )
          .then(({ error }) => {
            if (!error) return;
            const now = Date.now();
            if (now - lastCallConnectorHeartbeatSupabaseWarnMs >= 120_000) {
              lastCallConnectorHeartbeatSupabaseWarnMs = now;
              console.warn('call-connector-pro heartbeat supabase:', error.message);
            }
          });
      }
    } catch (error) {
      console.error('❌ Error updating Call Connector heartbeat:', error);
      res.status(500).json({ error: 'Failed to update heartbeat' });
    }
  });

