  app.get("/api/leasedialer/callable-by-agent", async (req, res) => {
    try {
      const emails = String(req.query?.emails || "")
        .split(",")
        .map((email) => email.trim().toLowerCase())
        .filter((email) => email.includes("@"));
      if (emails.length === 0) return res.json({ counts: {}, rows: [], asOf: new Date().toISOString() });

      const result = await leaseDialerPool.query<{
        agent_email: string;
        callable_leased: number;
        callable_plus: number;
      }>(
        `
          WITH normalized AS (
            SELECT
              lower(trim(coalesce(cn_email, ''))) AS agent_email,
              lower(trim(coalesce(cnresolution, 'pending'))) AS cnresolution_norm,
              lower(trim(coalesce(taalk_market, ''))) AS market_norm,
              created_at,
              coalesce(btrim(coalesce(taalk_lead_id::text, '')), '') AS taalk_lead_id_norm,
              coalesce(dnc::text, 'false') AS dnc_text,
              coalesce("TaalkResolve"::text, '') AS taalk_resolve_text
            FROM masterlead
            WHERE lower(trim(coalesce(cn_email, ''))) = ANY($1::text[])
          )
          SELECT
            agent_email,
            COUNT(*) FILTER (
              WHERE cnresolution_norm IN ('pending','new','','null')
                AND taalk_lead_id_norm <> ''
                AND dnc_text NOT IN ('true','1')
                AND taalk_resolve_text NOT IN ('true','1')
                AND (
                  market_norm NOT LIKE '%globe%'
                  OR (created_at IS NOT NULL AND created_at >= NOW() - INTERVAL '6 months')
                )
                AND market_norm NOT IN ('plus','plus lead','plus leads')
            )::int AS callable_leased,
            COUNT(*) FILTER (
              WHERE cnresolution_norm IN ('pending','new','','null')
                AND taalk_lead_id_norm <> ''
                AND dnc_text NOT IN ('true','1')
                AND taalk_resolve_text NOT IN ('true','1')
                AND market_norm IN ('plus','plus lead','plus leads')
            )::int AS callable_plus
          FROM normalized
          GROUP BY agent_email
        `,
        [emails],
      );

      const counts: Record<string, { callable_leased: number; callable_plus: number }> = {};
      for (const email of emails) {
        counts[email] = { callable_leased: 0, callable_plus: 0 };
      }
      for (const row of result.rows) {
        const key = String(row.agent_email || "").toLowerCase();
        counts[key] = {
          callable_leased: Number(row.callable_leased || 0),
          callable_plus: Number(row.callable_plus || 0),
        };
      }
      return res.json({ counts, rows: result.rows, asOf: new Date().toISOString() });
    } catch (error: any) {
      console.error("leasedialer callable-by-agent failed:", error);
      return res.status(500).json({ error: error?.message || "Failed to fetch callable counts by agent" });
    }
  });

  app.get("/api/leasedialer/flow-utilization", async (_req, res) => {
    try {
      const dormantMinutes = Math.max(15, Math.min(24 * 60, Number(process.env.LEASEDIALER_DORMANT_MINUTES || 60)));
      const recentMinutes = Math.max(5, Math.min(6 * 60, Number(process.env.LEASEDIALER_UTIL_RECENT_MINUTES || 60)));
      const activeStatusMinutes = Math.max(10, Math.min(240, Number(process.env.LEASEDIALER_ACTIVE_STATUS_RECENT_MINUTES || 30)));
      // Keep this endpoint on the lightweight path in production.
      // The full query can exceed read timeouts under load.
      const fastMode = true;

      if (fastMode) {
        const nowMs = Date.now();
        const snapshotAgeMs = nowMs - flowUtilCallableSnapshotCache.generatedAtMs;
        const snapshotFresh = flowUtilCallableSnapshotCache.generatedAtMs > 0 && snapshotAgeMs <= FLOW_UTIL_CALLABLE_SNAPSHOT_TTL_MS;
        if (!flowUtilCallableSnapshotCache.refreshing && !snapshotFresh) {
          void refreshFlowCallableSnapshot();
        }

        // Use denormalized market/state columns on leasedialer_assignments — no masterlead JOIN needed
        const assignmentResult = await leaseDialerPool.query<{
          market: string;
          state: string;
          queued: number;
          active: number;
          dormant_queued: number;
          dials_60m: number;
          active_agents_60m: number;
        }>(`
          SELECT
            COALESCE(la.market, 'Unknown') AS market,
            COALESCE(la.state, 'XX') AS state,
            COUNT(*) FILTER (WHERE la.status = 'queued')::int AS queued,
            COUNT(*) FILTER (WHERE la.status IN ('queued','active'))::int AS active,
            COUNT(*) FILTER (
              WHERE la.status = 'queued'
                AND la.assigned_at < NOW() - ($1::int * INTERVAL '1 minute')
            )::int AS dormant_queued,
            COUNT(*) FILTER (
              WHERE la.updated_at >= NOW() - ($2::int * INTERVAL '1 minute')
            )::int AS dials_60m,
            COUNT(DISTINCT lower(la.agent_email)) FILTER (
              WHERE la.updated_at >= NOW() - ($3::int * INTERVAL '1 minute')
                AND la.status IN ('queued','active')
                AND COALESCE(NULLIF(btrim(la.agent_email), ''), '') <> ''
            )::int AS active_agents_60m
          FROM leasedialer_assignments la
          WHERE la.queue = 'hotlead'
            AND la.status IN ('queued','active')
            AND la.market IS NOT NULL
          GROUP BY la.market, la.state
        `, [dormantMinutes, recentMinutes, activeStatusMinutes]);

        const callableByBucket = new Map<string, number>();
        for (const row of flowUtilCallableSnapshotCache.rows) {
          callableByBucket.set(flowBucketKey(row.market, row.state), Number(row.callable_total || 0));
        }

        const assignmentByBucket = new Map<string, {
          market: string;
          state: string;
          queued: number;
          active: number;
          dormant_queued: number;
          dials_60m: number;
          active_agents_60m: number;
        }>();
        for (const row of assignmentResult.rows) {
          const market = normalizeFlowMarket(row.market);
          const state = normalizeFlowState(row.state);
          const key = flowBucketKey(market, state);
          const current = assignmentByBucket.get(key) || {
            market,
            state,
            queued: 0,
            active: 0,
            dormant_queued: 0,
            dials_60m: 0,
            active_agents_60m: 0,
          };
          current.queued += Number(row.queued || 0);
          current.active += Number(row.active || 0);
          current.dormant_queued += Number(row.dormant_queued || 0);
          current.dials_60m += Number(row.dials_60m || 0);
          current.active_agents_60m += Number(row.active_agents_60m || 0);
          assignmentByBucket.set(key, current);
        }

        const bucketKeys = new Set<string>([
          ...Array.from(callableByBucket.keys()),
          ...Array.from(assignmentByBucket.keys()),
        ]);

        const rows = Array.from(bucketKeys).map((key) => {
          const assignment = assignmentByBucket.get(key);
          const [market, state] = key.split("__");
          const callable = Number(callableByBucket.get(key) || 0);
          const queued = Number(assignment?.queued || 0);
          const active = Number(assignment?.active || 0);
          const dormantQueued = Number(assignment?.dormant_queued || 0);
          const dials60m = Number(assignment?.dials_60m || 0);
          const activeAgents60m = Number(assignment?.active_agents_60m || 0);
          const scored = computeFlowWeighting({
            callable,
            queued,
            active,
            activeAgents: activeAgents60m,
          });
          return {
            market,
            state,
            callable_leased: callable,
            callable_plus: 0,
            queued,
            active,
            dormant_queued: dormantQueued,
            dials_60m: dials60m,
            active_agents_60m: activeAgents60m,
            utilization_ratio: scored.utilizationRatio,
            pressure_score: scored.pressureScore,
            available: callable,
            leased: active,
            remaining: scored.remaining,
            recommended_weight: scored.recommendedWeight,
          };
        }).sort((a, b) => {
          if (b.pressure_score !== a.pressure_score) return b.pressure_score - a.pressure_score;
          if (a.market !== b.market) return a.market.localeCompare(b.market);
          return a.state.localeCompare(b.state);
        });

        const overall = rows.reduce(
          (acc, row) => {
            acc.callable_leased += Number(row.callable_leased || 0);
            acc.callable_plus += Number(row.callable_plus || 0);
            acc.queued += Number(row.queued || 0);
            acc.active += Number(row.active || 0);
            acc.dormant_queued += Number(row.dormant_queued || 0);
            acc.dials_60m += Number(row.dials_60m || 0);
            acc.active_agents_60m += Number(row.active_agents_60m || 0);
            acc.available += Number(row.available || 0);
            acc.leased += Number(row.leased || 0);
            acc.remaining += Number(row.remaining || 0);
            return acc;
          },
          {
            callable_leased: 0,
            callable_plus: 0,
            queued: 0,
            active: 0,
            dormant_queued: 0,
            dials_60m: 0,
            active_agents_60m: 0,
            available: 0,
            leased: 0,
            remaining: 0,
          },
        );

        const byMarket = rows.reduce<Record<string, any>>((acc, row) => {
          const market = String(row.market || "Unknown");
          if (!acc[market]) {
            acc[market] = {
              market,
              callable_leased: 0,
              callable_plus: 0,
              queued: 0,
              active: 0,
              dormant_queued: 0,
              dials_60m: 0,
              available: 0,
              leased: 0,
              remaining: 0,
            };
          }
          acc[market].callable_leased += Number(row.callable_leased || 0);
          acc[market].callable_plus += Number(row.callable_plus || 0);
          acc[market].queued += Number(row.queued || 0);
          acc[market].active += Number(row.active || 0);
          acc[market].dormant_queued += Number(row.dormant_queued || 0);
          acc[market].dials_60m += Number(row.dials_60m || 0);
          acc[market].available += Number(row.available || 0);
          acc[market].leased += Number(row.leased || 0);
          acc[market].remaining += Number(row.remaining || 0);
          return acc;
        }, {});

        return res.json({
          generatedAt: new Date().toISOString(),
          degraded: !snapshotFresh || flowUtilCallableSnapshotCache.rows.length === 0,
          degradedReason:
            flowUtilCallableSnapshotCache.rows.length === 0
              ? "callable snapshot warming from masterlead; assigned metrics are live"
              : (!snapshotFresh
                ? "callable snapshot stale; refresh in progress"
                : "fast mode with callable snapshot + live assignments"),
          config: { dormantMinutes, recentMinutes, activeStatusMinutes, fastMode: true },
          callableSnapshot: {
            generatedAt: flowUtilCallableSnapshotCache.generatedAtMs
              ? new Date(flowUtilCallableSnapshotCache.generatedAtMs).toISOString()
              : null,
            ttlMs: FLOW_UTIL_CALLABLE_SNAPSHOT_TTL_MS,
            refreshing: flowUtilCallableSnapshotCache.refreshing,
            lastError: flowUtilCallableSnapshotCache.lastError,
          },
          overall,
          byMarket: Object.values(byMarket),
          byBucket: rows,
        });
      }

      const result = await leaseDialerPool.query<{
        market: string;
        state: string;
        callable_leased: number;
        callable_plus: number;
        queued: number;
        active: number;
        dormant_queued: number;
        dials_60m: number;
        active_agents_60m: number;
        utilization_ratio: number;
        pressure_score: number;
      }>(
        `
          WITH callable AS (
            SELECT
              CASE
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%globe%' THEN 'Globe Market'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%veteran%' THEN 'Veteran'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%plus%' THEN 'Plus'
                ELSE COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), '')
              END AS market,
              COALESCE(NULLIF(upper(btrim(ml.taalk_state::text)), ''), NULLIF(upper(btrim(ml.state::text)), '')) AS state,
              COUNT(*) FILTER (
                WHERE lower(trim(coalesce(ml.cnresolution, 'pending'))) IN ('pending', 'new', '', 'null')
                  AND COALESCE(btrim(ml.taalk_lead_id::text), '') <> ''
                  AND COALESCE(ml.dnc::text, 'false') NOT IN ('true','1')
                  AND COALESCE(ml."TaalkResolve"::text, '') NOT IN ('true','1')
                  AND ${GLOBE_MAX_AGE_SQL}
                  AND lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) NOT LIKE '%plus%'
              )::int AS callable_leased,
              COUNT(*) FILTER (
                WHERE lower(trim(coalesce(ml.cnresolution, 'pending'))) IN ('pending', 'new', '', 'null')
                  AND COALESCE(btrim(ml.taalk_lead_id::text), '') <> ''
                  AND COALESCE(ml.dnc::text, 'false') NOT IN ('true','1')
                  AND COALESCE(ml."TaalkResolve"::text, '') NOT IN ('true','1')
                  AND ${GLOBE_MAX_AGE_SQL}
                  AND lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%plus%'
              )::int AS callable_plus
            FROM masterlead ml
            GROUP BY 1,2
          ),
          assigned AS (
            SELECT
              CASE
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%globe%' THEN 'Globe Market'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%veteran%' THEN 'Veteran'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), ''), '\\s+', '', 'g')) LIKE '%plus%' THEN 'Plus'
                ELSE COALESCE(NULLIF(btrim(ml.taalk_market::text), ''), btrim(ml.market::text), '')
              END AS market,
              COALESCE(NULLIF(upper(btrim(ml.taalk_state::text)), ''), NULLIF(upper(btrim(ml.state::text)), '')) AS state,
              COUNT(*) FILTER (WHERE la.status = 'queued')::int AS queued,
              COUNT(*) FILTER (WHERE la.status = 'active')::int AS active,
              COUNT(*) FILTER (
                WHERE la.status = 'queued'
                  AND la.assigned_at < NOW() - ($1::int * INTERVAL '1 minute')
              )::int AS dormant_queued
            FROM leasedialer_assignments la
            JOIN masterlead ml ON ml.id = la.lead_id
            WHERE la.queue = 'hotlead'
              AND la.status IN ('queued','active')
              AND lower(trim(coalesce(ml.cnresolution, 'pending'))) IN ('pending', 'new', '', 'null')
              AND COALESCE(btrim(ml.taalk_lead_id::text), '') <> ''
              AND ${GLOBE_MAX_AGE_SQL}
            GROUP BY 1,2
          ),
          recent_active_agents AS (
            SELECT DISTINCT lower(lcs.agent_email) AS agent_email
            FROM leasedialer_client_status lcs
            WHERE lcs.updated_at >= NOW() - ($3::int * INTERVAL '1 minute')
          ),
          latest_profiles AS (
            SELECT DISTINCT ON (lower(arp.agent_email))
              lower(arp.agent_email) AS agent_email,
              ARRAY(
                SELECT CASE
                  WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(m), ''), ''), '\\s+', '', 'g')) LIKE '%globe%' THEN 'Globe Market'
                  WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(m), ''), ''), '\\s+', '', 'g')) LIKE '%veteran%' THEN 'Veteran'
                  WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(m), ''), ''), '\\s+', '', 'g')) LIKE '%plus%' THEN 'Plus'
                  ELSE COALESCE(NULLIF(btrim(m), ''), '')
                END
                FROM unnest(COALESCE(arp.markets, ARRAY[]::text[])) m
                WHERE COALESCE(NULLIF(btrim(m), ''), '') <> ''
              ) AS markets,
              ARRAY(
                SELECT upper(regexp_replace(s, '[^A-Za-z]', '', 'g'))
                FROM unnest(COALESCE(arp.states, ARRAY[]::text[])) s
                WHERE upper(regexp_replace(s, '[^A-Za-z]', '', 'g')) ~ '^[A-Z]{2}$'
              ) AS states
            FROM agent_routing_profiles arp
            JOIN recent_active_agents ra ON ra.agent_email = lower(arp.agent_email)
            ORDER BY lower(arp.agent_email), arp.updated_at DESC
          ),
          active_capacity AS (
            SELECT
              mk AS market,
              st AS state,
              COUNT(DISTINCT lp.agent_email)::int AS active_agents_60m
            FROM latest_profiles lp
            CROSS JOIN LATERAL unnest(COALESCE(lp.markets, ARRAY[]::text[])) mk
            CROSS JOIN LATERAL unnest(COALESCE(lp.states, ARRAY[]::text[])) st
            GROUP BY 1,2
          ),
          recent_dials AS (
            SELECT
              CASE
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(arpm.market), ''), ''), '\\s+', '', 'g')) LIKE '%globe%' THEN 'Globe Market'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(arpm.market), ''), ''), '\\s+', '', 'g')) LIKE '%veteran%' THEN 'Veteran'
                WHEN lower(regexp_replace(COALESCE(NULLIF(btrim(arpm.market), ''), ''), '\\s+', '', 'g')) LIKE '%plus%' THEN 'Plus'
                ELSE COALESCE(NULLIF(btrim(arpm.market), ''), '')
              END AS market,
              upper(regexp_replace(arpm.state, '[^A-Za-z]', '', 'g')) AS state,
              COUNT(*)::int AS dials_60m
            FROM agent_dial_metrics adm
            JOIN LATERAL (
              SELECT mk.market, st.state
              FROM (
                SELECT arp.markets, arp.states
                FROM agent_routing_profiles arp
                WHERE lower(arp.agent_email) = lower(adm.agent_email)
                ORDER BY arp.updated_at DESC
                LIMIT 1
              ) lp
              CROSS JOIN LATERAL unnest(COALESCE(lp.markets, ARRAY[]::text[])) AS mk(market)
              CROSS JOIN LATERAL unnest(COALESCE(lp.states, ARRAY[]::text[])) AS st(state)
            ) arpm ON true
            WHERE adm.event_type = 'dial'
              AND adm.event_timestamp >= NOW() - ($2::int * INTERVAL '1 minute')
            GROUP BY 1,2
          ),
          buckets AS (
            SELECT market, state FROM callable
            UNION
            SELECT market, state FROM assigned
            UNION
            SELECT market, state FROM active_capacity
          )
          SELECT
            b.market,
            b.state,
            COALESCE(c.callable_leased, 0)::int AS callable_leased,
            COALESCE(c.callable_plus, 0)::int AS callable_plus,
            COALESCE(a.queued, 0)::int AS queued,
            COALESCE(a.active, 0)::int AS active,
            COALESCE(a.dormant_queued, 0)::int AS dormant_queued,
            COALESCE(rd.dials_60m, 0)::int AS dials_60m,
            COALESCE(ac.active_agents_60m, 0)::int AS active_agents_60m,
            CASE
              WHEN COALESCE(c.callable_leased, 0) <= 0 THEN 0
              ELSE LEAST(1, COALESCE(rd.dials_60m, 0)::numeric / GREATEST(1, COALESCE(c.callable_leased, 0)))
            END AS utilization_ratio,
            (
              COALESCE(c.callable_leased, 0) * 0.9 +
              COALESCE(a.dormant_queued, 0) * 4 +
              GREATEST(0, COALESCE(c.callable_leased, 0) - COALESCE(a.queued, 0) - COALESCE(a.active, 0)) * 1.2 -
              COALESCE(rd.dials_60m, 0) * 1.1 -
              COALESCE(ac.active_agents_60m, 0) * 4
            )::numeric(12,2) AS pressure_score
          FROM buckets b
          LEFT JOIN callable c ON c.market = b.market AND c.state = b.state
          LEFT JOIN assigned a ON a.market = b.market AND a.state = b.state
          LEFT JOIN recent_dials rd ON rd.market = b.market AND rd.state = b.state
          LEFT JOIN active_capacity ac ON ac.market = b.market AND ac.state = b.state
          WHERE COALESCE(b.market, '') <> ''
            AND COALESCE(b.state, '') ~ '^[A-Z]{2}$'
          ORDER BY pressure_score DESC, callable_leased DESC, b.market ASC, b.state ASC
        `,
        [dormantMinutes, recentMinutes, activeStatusMinutes],
      );

      const rows = result.rows.map((row) => ({
        ...row,
        recommended_weight: Math.max(
          0,
          Math.round(
            (Number(row.pressure_score || 0) + Number(row.callable_leased || 0) * 0.5 + Number(row.dormant_queued || 0) * 2) *
              10,
          ) / 10,
        ),
      }));

      const overall = rows.reduce(
        (acc, row) => {
          acc.callable_leased += Number(row.callable_leased || 0);
          acc.callable_plus += Number(row.callable_plus || 0);
          acc.queued += Number(row.queued || 0);
          acc.active += Number(row.active || 0);
          acc.dormant_queued += Number(row.dormant_queued || 0);
          acc.dials_60m += Number(row.dials_60m || 0);
          acc.active_agents_60m += Number(row.active_agents_60m || 0);
          return acc;
        },
        {
          callable_leased: 0,
          callable_plus: 0,
          queued: 0,
          active: 0,
          dormant_queued: 0,
          dials_60m: 0,
          active_agents_60m: 0,
        },
      );

      const byMarket = rows.reduce<Record<string, any>>((acc, row) => {
        const market = String(row.market || "Unknown");
        if (!acc[market]) {
          acc[market] = {
            market,
            callable_leased: 0,
            callable_plus: 0,
            queued: 0,
            active: 0,
            dormant_queued: 0,
            dials_60m: 0,
          };
        }
        acc[market].callable_leased += Number(row.callable_leased || 0);
        acc[market].callable_plus += Number(row.callable_plus || 0);
        acc[market].queued += Number(row.queued || 0);
        acc[market].active += Number(row.active || 0);
        acc[market].dormant_queued += Number(row.dormant_queued || 0);
        acc[market].dials_60m += Number(row.dials_60m || 0);
        return acc;
      }, {});

      return res.json({
        generatedAt: new Date().toISOString(),
        config: { dormantMinutes, recentMinutes, activeStatusMinutes },
        overall,
        byMarket: Object.values(byMarket),
        byBucket: rows,
      });
    } catch (error: any) {
      const message = String(error?.message || "");
      const isTimeout =
        /timeout/i.test(message) ||
        /canceling statement/i.test(message) ||
        /Query read timeout/i.test(message);
      if (isTimeout) {
        try {
          const fallback = await leaseDialerPool.query<{
            market: string;
            state: string;
            ready: number;
            claimed: number;
          }>(`
            SELECT
              COALESCE(NULLIF(btrim(market), ''), 'Unknown') AS market,
              COALESCE(NULLIF(upper(btrim(state)), ''), 'XX') AS state,
              COUNT(*) FILTER (WHERE status = 'ready')::int AS ready,
              COUNT(*) FILTER (WHERE status = 'claimed')::int AS claimed
            FROM leasedialer_eligible_pool
            WHERE status IN ('ready', 'claimed')
            GROUP BY 1,2
            HAVING
              COUNT(*) FILTER (WHERE status = 'ready') > 0 OR
              COUNT(*) FILTER (WHERE status = 'claimed') > 0
            ORDER BY 1,2
          `);
          const rows = fallback.rows.map((row) => {
            const callableLeased = Number(row.ready || 0);
            const queued = Number(row.claimed || 0);
            const pressure = callableLeased * 0.9 + queued * 0.5;
            return {
              market: row.market,
              state: row.state,
              callable_leased: callableLeased,
              callable_plus: 0,
              queued,
              active: 0,
              dormant_queued: 0,
              dials_60m: 0,
              active_agents_60m: 0,
              utilization_ratio: 0,
              pressure_score: Number(pressure.toFixed(2)),
              recommended_weight: Math.max(0, Number((pressure * 0.7).toFixed(1))),
            };
          });
          const overall = rows.reduce(
            (acc, row) => {
              acc.callable_leased += Number(row.callable_leased || 0);
              acc.callable_plus += Number(row.callable_plus || 0);
              acc.queued += Number(row.queued || 0);
              acc.active += Number(row.active || 0);
              acc.dormant_queued += Number(row.dormant_queued || 0);
              acc.dials_60m += Number(row.dials_60m || 0);
              acc.active_agents_60m += Number(row.active_agents_60m || 0);
              return acc;
            },
            {
              callable_leased: 0,
              callable_plus: 0,
              queued: 0,
              active: 0,
              dormant_queued: 0,
              dials_60m: 0,
              active_agents_60m: 0,
            },
          );
          const byMarket = rows.reduce<Record<string, any>>((acc, row) => {
            const market = String(row.market || "Unknown");
            if (!acc[market]) {
              acc[market] = {
                market,
                callable_leased: 0,
                callable_plus: 0,
                queued: 0,
                active: 0,
                dormant_queued: 0,
                dials_60m: 0,
              };
            }
            acc[market].callable_leased += Number(row.callable_leased || 0);
            acc[market].callable_plus += Number(row.callable_plus || 0);
            acc[market].queued += Number(row.queued || 0);
            acc[market].active += Number(row.active || 0);
            acc[market].dormant_queued += Number(row.dormant_queued || 0);
            acc[market].dials_60m += Number(row.dials_60m || 0);
            return acc;
          }, {});
          return res.json({
            generatedAt: new Date().toISOString(),
            degraded: true,
            degradedReason: "primary query timeout; using eligible pool fallback",
            config: { dormantMinutes, recentMinutes, activeStatusMinutes },
            overall,
            byMarket: Object.values(byMarket),
            byBucket: rows,
          });
        } catch (fallbackError: any) {
          console.error("leasedialer flow-utilization fallback failed:", fallbackError);
          return res.json({
            generatedAt: new Date().toISOString(),
            degraded: true,
            degradedReason: "all flow-utilization queries timed out; returning empty snapshot",
            config: { dormantMinutes, recentMinutes, activeStatusMinutes, fastMode: true },
            overall: {
              callable_leased: 0,
              callable_plus: 0,
              queued: 0,
              active: 0,
              dormant_queued: 0,
              dials_60m: 0,
              active_agents_60m: 0,
            },
            byMarket: [],
            byBucket: [],
          });
        }
      }
      console.error("leasedialer flow-utilization failed:", error);
      return res.status(500).json({ error: error?.message || "Failed to fetch flow/utilization metrics" });
    }
  });

  app.get("/api/leasedialer/health", async (_req, res) => {
    try {
      const [stuckAssignments, poolSummary, orphanClaimedPoolRows, bufferSummary] = await Promise.all([
        pool.query(`
          SELECT la.status, COUNT(*)::int AS count
          FROM leasedialer_assignments la
          JOIN masterlead ml ON ml.id = la.lead_id
          WHERE la.status IN ('queued', 'active')
            AND (
              lower(trim(coalesce(ml.cnresolution, 'pending'))) NOT IN ('pending', 'new', '', 'null')
            )
          GROUP BY la.status
          ORDER BY la.status
        `),
        pool.query(`
          SELECT status, COUNT(*)::int AS count, COUNT(DISTINCT market || '|' || state)::int AS buckets
          FROM leasedialer_eligible_pool
          GROUP BY status
          ORDER BY status
        `),
        pool.query(`
          SELECT COUNT(*)::int AS count
          FROM leasedialer_eligible_pool ep
          WHERE ep.status = 'claimed'
            AND NOT EXISTS (
              SELECT 1
              FROM leasedialer_assignments la
              WHERE la.lead_id = ep.lead_id
                AND lower(la.agent_email) = lower(coalesce(ep.claimed_by_agent_email, ''))
                AND la.status IN ('queued', 'active')
            )
        `),
        pool.query(`
          WITH active_agents AS (
            SELECT DISTINCT lower(agent_email) AS agent_email
            FROM leasedialer_assignments
            WHERE status = 'active'
          ),
          q AS (
            SELECT
              a.agent_email,
              COUNT(la.id) FILTER (WHERE la.status = 'queued' AND la.queue = 'hotlead')::int AS queued
            FROM active_agents a
            LEFT JOIN leasedialer_assignments la ON lower(la.agent_email) = a.agent_email
            GROUP BY a.agent_email
          )
          SELECT
            COUNT(*)::int AS active_agents,
            COUNT(*) FILTER (WHERE queued < 25)::int AS below_refill,
            COUNT(*) FILTER (WHERE queued >= 50)::int AS at_or_above_target,
            MIN(queued)::int AS min_queued,
            MAX(queued)::int AS max_queued
          FROM q
        `),
      ]);

      return res.json({
        ok: true,
        checkedAt: new Date().toISOString(),
        stuckAssignments: stuckAssignments.rows,
        poolSummary: poolSummary.rows,
        orphanClaimedPoolRows: orphanClaimedPoolRows.rows[0] || { count: 0 },
        bufferSummary: bufferSummary.rows[0] || null,
      });
    } catch (error: any) {
      return res.status(500).json({ ok: false, error: error?.message || "Failed leasedialer health" });
    }
  });

  // /api/reactor/pool-health — per-agent queued lead counts for AOI Command Pending column
  // Cached 30s to avoid per-request DB hits from 87+ agents polling simultaneously
  let poolHealthCache: { data: unknown; ts: number } | null = null;
  app.get("/api/reactor/pool-health", async (_req, res) => {
    try {
      if (poolHealthCache && Date.now() - poolHealthCache.ts < 30_000) {
        return res.json(poolHealthCache.data);
      }
      const result = await pool.query<{ agent_email: string; queued: number; active: number }>(
        `SELECT lower(agent_email) AS agent_email,
           COUNT(*) FILTER (WHERE status = 'queued')::int AS queued,
           COUNT(*) FILTER (WHERE status = 'active')::int AS active
         FROM leasedialer_assignments
         WHERE status IN ('queued', 'active')
         GROUP BY lower(agent_email)`,
      );
      const data = {
        ok: true,
        asOf: new Date().toISOString(),
        agentBuffers: result.rows.map((r) => ({
          agent_email: r.agent_email,
          queued: r.queued,
          active: r.active,
        })),
      };
      poolHealthCache = { data, ts: Date.now() };
      return res.json(data);
    } catch (error: any) {
      return res.status(500).json({ ok: false, error: error?.message || "Failed pool health" });
    }
  });

  app.post("/api/leasedialer/cleanup", async (_req, res) => {
    try {
      const requestedBatch = Number((_req.query?.batchSize as string) || (_req.body as any)?.batchSize || 500);
      const reclaimed = await reclaimOrphanedLeasePoolRows({ batchSize: requestedBatch });
      return res.json({ ok: true, ...reclaimed });
    } catch (error: any) {
      return res.status(500).json({ ok: false, error: error?.message || "Failed leasedialer cleanup" });
    }
  });

  app.post("/api/leasedialer/release-to-pool", express.json(), async (req, res) => {
    try {
      const leadId = Number(req.body?.leadId || req.body?.id || 0);
      const agentEmail = String(
        req.body?.agentEmail ||
        req.headers["x-user-email"] ||
        req.headers["user-email"] ||
        "",
      ).trim().toLowerCase();
      const reason = String(req.body?.reason || "browser_outside_calling_window").trim();

      if (!Number.isFinite(leadId) || leadId <= 0) {
        return res.status(400).json({ ok: false, error: "leadId is required" });
      }
      if (!agentEmail.includes("@")) {
        return res.status(400).json({ ok: false, error: "agentEmail is required" });
      }

      const result = await releaseLeaseDialerAssignmentBackToPool({ leadId, agentEmail, reason });
      return res.json({ ok: true, ...result });
    } catch (error: any) {
      return res.status(500).json({ ok: false, error: error?.message || "Failed to release leased lead" });
    }
  });

  // Pool status endpoint - fast breakdown for AOI Command Reactor Panel
  app.get("/api/leasedialer/pool-status", async (_req, res) => {
    try {
      if (String(process.env.LEAD_ONLY_MODE || "").toLowerCase() === "true") {
        return res.status(503).json({
          ok: false,
          error: "LEAD_ONLY_MODE_ENABLED",
          message: "Pool status disabled while lead-only mode is active.",
        });
      }
      const [overall, byMarket, lowBuckets, agentBuffers, masteleadCounts] = await Promise.all([
        pool.query(`
          SELECT status, COUNT(*)::int AS count
          FROM leasedialer_eligible_pool
          GROUP BY status ORDER BY status
        `),
        pool.query(`
          SELECT market, state, COUNT(*) FILTER (WHERE status='ready')::int AS ready,
            COUNT(*) FILTER (WHERE status='claimed')::int AS claimed
          FROM leasedialer_eligible_pool
          GROUP BY market, state
          ORDER BY market, state
        `),
        pool.query(`
          SELECT queue, market, state, COUNT(*)::int AS ready
          FROM leasedialer_eligible_pool
          WHERE status = 'ready'
          GROUP BY queue, market, state
          HAVING COUNT(*) < 50
          ORDER BY ready ASC
          LIMIT 20
        `),
        // No masterlead JOIN — direct count from assignments only (fast)
        pool.query(`
          SELECT lower(agent_email) AS agent_email,
            COUNT(*) FILTER (WHERE status='queued')::int AS queued,
            COUNT(*) FILTER (WHERE status='active')::int AS active
          FROM leasedialer_assignments
          WHERE status IN ('queued','active')
          GROUP BY lower(agent_email)
          ORDER BY queued DESC
        `),
        // Callable/assigned/available counts for ReactorPanel
        pool.query(`
          SELECT
            COUNT(*) FILTER (WHERE la.status IN ('queued','active'))::int AS callable_leased,
            COUNT(*) FILTER (WHERE la.status = 'queued')::int AS queued_total,
            COUNT(*) FILTER (WHERE la.status = 'active')::int AS active_total
          FROM leasedialer_assignments la
          WHERE la.status IN ('queued','active')
        `),
      ]);

      const overallRow = masteleadCounts.rows[0] || { callable_leased: 0, queued_total: 0, active_total: 0 };
      return res.json({
        ok: true,
        checkedAt: new Date().toISOString(),
        overall: {
          callable_leased: overallRow.callable_leased,
          callable_plus: 0,
          available: overallRow.callable_leased,
        },
        byMarket: byMarket.rows,
        lowBuckets: lowBuckets.rows,
        agentBuffers: agentBuffers.rows,
        poolSummary: overall.rows,
      });
    } catch (error: any) {
      return res.status(500).json({ ok: false, error: error?.message || "Failed pool status" });
    }
  });

  // Call Connector Pro activity (dialing, ringing, live, idle) - so presence API shows correct state
