  app.post("/api/call-connector-pro/activity", async (req, res) => {
    try {
      const { agentEmail, activity, callDetails } = req.body;
      if (!agentEmail || !activity) {
        return res.status(400).json({ error: 'Agent email and activity are required' });
      }
      const { callConnectorTracker } = await import('./call-connector-tracker');
      const normalizedEmail = String(agentEmail).trim().toLowerCase();
      callConnectorTracker.updateActivity({
        agentEmail: normalizedEmail,
        activity: activity,
        callDetails: callDetails || undefined,
      });

      // Fire-and-forget: forward to AOI Command for real-time status
      fetch(`${getCampaignManagerBaseUrl()}/api/webrtc/presence`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          identity: normalizedEmail,
          status: activity === 'live' ? 'on_call' : activity === 'dialing' ? 'dialing' : activity === 'ringing' ? 'ringing' : 'available',
          callDirection: 'outbound',
          name: normalizedEmail.split('@')[0],
        }),
        signal: AbortSignal.timeout(3000),
      }).catch(() => {});

      // Fire-and-forget: update Twilio TaskRouter worker activity
      const CCP_ACTIVITY_MAP: Record<string, string> = {
        'dialing': 'WAbec4616ec491b3d3d96c87717d64b71c',
        'ringing': 'WA965abc2ba4f81befd087c77614f3b714',
        'live': 'WA5306bcbb57fd389e964b4190ceaf71cc',
        'wrapping_up': 'WA7cbb8457461d3e22fd83473d7186a3d5',
        'idle': 'WAc2513cd4c7ec03511690c328ff2a49cd',
      };
      const activitySid = CCP_ACTIVITY_MAP[activity];
      if (activitySid) {
        twilioClient.taskrouter.v1
          .workspaces('WS6a978202496f59f6cd478c1310f5c2eb')
          .workers.list({ friendlyName: normalizedEmail, limit: 1 })
          .then((workers) => {
            if (workers.length > 0) {
              return twilioClient.taskrouter.v1
                .workspaces('WS6a978202496f59f6cd478c1310f5c2eb')
                .workers(workers[0].sid)
                .update({ activitySid });
            }
          })
          .catch((err: unknown) => {
            console.error('Failed to update Twilio worker activity for CCP:', err);
          });
      }

      res.json({ success: true });
    } catch (error) {
      console.error('❌ Error updating Call Connector activity:', error);
      res.status(500).json({ error: 'Failed to update activity' });
    }
  });

  // Agent says "I can take a call" (Complete & Dial Next). If inbound queue has a call, connect it to this agent and return lead for same CCP lead card; else return hasInbound: false so client dials next outbound.
  app.post("/api/call-connector-pro/ready-for-next-call", async (req, res) => {
    try {
      const { agentEmail, agentName } = req.body;
      if (!agentEmail || !String(agentEmail).includes('@')) {
        return res.status(400).json({ error: 'agentEmail required' });
      }
      const email = String(agentEmail).trim().toLowerCase();
      const item = inboundQueueDequeue();
      if (!item) {
        return res.json({ hasInbound: false });
      }
      const baseUrl = PRODUCTION_BASE_URL;
      const joinUrl = `${baseUrl}/api/twilio/agent-join-inbound-conference?conference=${encodeURIComponent(item.conferenceName)}`;
      await twilioClient.calls.create({
        to: `client:${email}`,
        from: process.env.TWILIO_CALLER_ID || process.env.TWILIO_TWIML_APP_PHONE || '+12035896464',
        url: joinUrl,
        method: 'GET',
        statusCallback: `${baseUrl}/api/twilio/call-status`,
        statusCallbackEvent: ['initiated', 'ringing', 'answered', 'completed'],
        statusCallbackMethod: 'POST',
        timeout: 25,
      });
      const callerLast10 = String(item.from).replace(/\D/g, '').slice(-10);
      let lead: Record<string, unknown> = {
        id: null,
        first_name: 'Unknown',
        last_name: 'Caller',
        name: 'Unknown Caller',
        phone: item.from,
        state: item.leadState || 'Unknown',
        taalk_market: item.leadMarket || 'Unknown',
        city: null,
      };
      if (supabaseAdmin && callerLast10.length >= 10) {
        const { data: row } = await masterleadClient.from('masterlead')
          .select('id, taalk_lead_id, first_name, last_name, phone, state, taalk_market, city, taalk_email, cn_email, email, taalk_secretkey, taalk_address, address, taalk_beneficiary, taalk_relationship, taalk_reffered, taalk_sponsor_org, taalk_group_code, taalk_groupname, taalk_city, taalk_state, date_of_birth')
          .eq('phone_last10', callerLast10)
          .order('updated_at', { ascending: false })
          .limit(1)
          .maybeSingle();
        if (row) {
          const r = row as any;
          lead = {
            id: r.id,
            first_name: r.first_name || 'Unknown',
            last_name: r.last_name || 'Caller',
            name: [r.first_name, r.last_name].filter(Boolean).join(' ').trim() || 'Unknown Caller',
            phone: r.phone || item.from,
            state: r.state || item.leadState || 'Unknown',
            taalk_market: r.taalk_market || item.leadMarket || 'Unknown',
            city: r.city ?? null,
            taalk_lead_id: r.taalk_lead_id,
            taalk_email: r.taalk_email || r.cn_email || r.email,
            email: r.taalk_email || r.cn_email || r.email,
            taalk_secretkey: r.taalk_secretkey,
            secretKey: r.taalk_secretkey,
            taalk_address: r.taalk_address || r.address,
            address: r.taalk_address || r.address,
            taalk_beneficiary: r.taalk_beneficiary,
            taalk_relationship: r.taalk_relationship,
            taalk_reffered: r.taalk_reffered,
            taalk_sponsor_org: r.taalk_sponsor_org,
            taalk_group_code: r.taalk_group_code,
            taalk_groupname: r.taalk_groupname,
            taalk_city: r.taalk_city,
            taalk_state: r.taalk_state,
            date_of_birth: r.date_of_birth,
          };
        }
      }
      console.log(`📞 INBOUND QUEUE: routed ${item.callSid} to ${email}, lead=${(lead as any).name}`);
      res.json({ hasInbound: true, lead });
    } catch (err: any) {
      console.error('❌ ready-for-next-call:', err?.message);
      res.status(500).json({ error: err?.message || 'Failed' });
    }
  });

  // Who is eligible to receive an inbound (queue size, queued callers, agents with heartbeat not on call)
  // POS in CCPro header polls this. Order of truth:
  // 1) Supabase agent_queue_position (email + position) if you maintain that table
  // 2) Else agent_live_call_status — rows updated by POST /api/call-connector-pro/heartbeat (and /agent/presence)
  // 3) Else in-memory callConnectorTracker heartbeats (same process only; often empty on Railway multi-instance)
  app.get("/api/call-connector-pro/eligible-for-inbound", async (req, res) => {
    try {
      const queued = inboundQueueGetAll().map((q) => ({ from: q.from, to: q.to, createdAt: q.createdAt, callSid: q.callSid }));
      const queueLength = inboundQueueSize();
      let eligibleRingGroup: { email: string; lastHeartbeat?: string }[] = [];
      let onCall: string[] = [];
      let myPosition = 0;
      let totalEligible = 0;
      const agentEmail = typeof req.query?.agentEmail === 'string' ? req.query.agentEmail.trim().toLowerCase() : '';
      let usedAgentQuePosition = false;

      try {
        const { twilioCallsPoller } = await getTwilioCallsPollerModule();
        onCall = (twilioCallsPoller.getAllActiveCalls() || []).map((c: { agentEmail?: string }) => (c.agentEmail || '').toLowerCase().trim()).filter(Boolean);
      } catch (_) {}

      if (supabaseAdmin && agentEmail) {
        try {
          const { data: row, error: posErr } = await supabaseAdmin
            .from('agent_queue_position')
            .select('position')
            .eq('email', agentEmail)
            .maybeSingle();

          if (!posErr && row != null) {
            myPosition = Math.max(0, Math.floor((row as { position: number }).position ?? 0));
            usedAgentQuePosition = true;
          }

          // Count total online eligible agents
          const { count: totalCount } = await supabaseAdmin
            .from('agent_queue_position')
            .select('*', { count: 'exact', head: true })
            .eq('is_online', true)
            .gt('position', 0);
          totalEligible = Math.max(0, totalCount ?? 0);

          if (posErr) {
            console.warn('eligible-for-inbound: agent_queue_position query failed:', posErr.message);
          }
        } catch (dbErr) {
          console.warn('eligible-for-inbound: failed to read agent_queue_position', dbErr);
        }
      }

      if (!usedAgentQuePosition) {
        let filledFromLiveStatus = false;
        if (supabaseAdmin) {
          try {
            const heartbeatCutoff = new Date(Date.now() - 3 * 60 * 1000).toISOString();
            const { data: liveRows, error: liveErr } = await supabaseAdmin
              .from('agent_live_call_status')
              .select('agent_email, status, last_heartbeat_at')
              .gte('last_heartbeat_at', heartbeatCutoff);
            if (!liveErr && liveRows && liveRows.length > 0) {
              const inCall = (s: string) => String(s || '').toLowerCase() === 'in_call';
              const pool = (liveRows as any[])
                .filter((r) => r.agent_email && !inCall(r.status))
                .filter((r) => !onCall.includes(String(r.agent_email).toLowerCase()))
                .sort((a, b) => {
                  const ta = new Date(a.last_heartbeat_at).getTime();
                  const tb = new Date(b.last_heartbeat_at).getTime();
                  if (ta !== tb) return ta - tb;
                  return String(a.agent_email).localeCompare(String(b.agent_email));
                });
              const seen = new Set<string>();
              eligibleRingGroup = [];
              for (const r of pool) {
                const em = String(r.agent_email).toLowerCase();
                if (seen.has(em)) continue;
                seen.add(em);
                eligibleRingGroup.push({ email: em, lastHeartbeat: r.last_heartbeat_at });
              }
              totalEligible = eligibleRingGroup.length;
              if (agentEmail) {
                const idx = eligibleRingGroup.findIndex((e) => e.email === agentEmail);
                myPosition = idx >= 0 ? idx + 1 : 0;
              }
              filledFromLiveStatus = true;
            }
          } catch (liveDbErr) {
            console.warn('eligible-for-inbound: agent_live_call_status fallback failed', liveDbErr);
          }
        }

        if (!filledFromLiveStatus) {
          try {
            const { callConnectorTracker } = await import('./call-connector-tracker');
            const active = callConnectorTracker.getActiveAgents();
            eligibleRingGroup = active.map((a: { agentEmail: string; lastHeartbeat?: Date }) => ({
              email: a.agentEmail,
              lastHeartbeat: a.lastHeartbeat?.toISOString?.(),
            }));
            eligibleRingGroup = eligibleRingGroup.filter((e) => !onCall.includes(e.email.toLowerCase()));
            if (agentEmail) {
              const idx = eligibleRingGroup.findIndex((e) => e.email.toLowerCase() === agentEmail);
              myPosition = idx >= 0 ? idx + 1 : 0;
            }
            totalEligible = eligibleRingGroup.length;
          } catch (_) {}
        }
      }

      res.json({ queueLength, queuedCalls: queued, eligibleRingGroup, onCall, myPosition, totalEligible });
    } catch (e: any) {
      res.status(500).json({ error: e?.message || 'Failed' });
    }
  });

