  // Admin: Reset Call Connector Pro disclaimer for everyone (Supabase source of truth)
  // POST /api/admin/sessions/clear — clears all active sessions, forcing all users to log in again
  // No auth required - this is a critical admin function that may be called during emergencies
  app.post("/api/admin/sessions/clear", async (req, res) => {
    try {
      // Import sessionStore from index.ts
      const { sessionStore } = await import('./index');
      
      if (!sessionStore) {
        return res.status(500).json({ 
          error: 'Session store not available (MemoryStore not initialized)' 
        });
      }

      if (typeof sessionStore.clear !== 'function') {
        return res.status(500).json({ 
          error: 'Session store does not support clear() method' 
        });
      }

      // Clear all sessions
      sessionStore.clear((err: Error | null) => {
        if (err) {
          console.error('❌ Error clearing session store:', err);
          return res.status(500).json({ 
            error: 'Failed to clear session store',
            details: err.message 
          });
        }

        console.log('🔒 Admin session clear: all sessions cleared – users must sign back in.');
        res.json({ 
          success: true, 
          message: 'All active sessions cleared. All users will be forced to log in again.',
          timestamp: new Date().toISOString()
        });
      });
    } catch (error) {
      console.error('❌ Error in admin session clear endpoint:', error);
      res.status(500).json({ 
        error: 'Failed to clear sessions',
        details: error instanceof Error ? error.message : String(error)
      });
    }
  });

  // POST /api/admin/disclaimers/reset — clears call_connector_pro_disclaimer_accepted_at for all agent_profiles.
  // Body: { scope?: 'ccpro' | 'recruit' | 'all' }. Default: 'ccpro'.
  // After reset, clients will see the disclaimer again (API is source of truth; localStorage cleared when not accepted).
  app.post("/api/admin/disclaimers/reset", async (req, res) => {
    try {
      if (!supabaseAdmin) {
        return res.status(500).json({ error: 'Supabase admin client not available' });
      }

      const scope = (req.body?.scope as string) || 'ccpro';
      const resetCCPro = scope === 'ccpro' || scope === 'all';
      const resetRecruit = scope === 'recruit' || scope === 'all';

      const ccproResult: { updated: number; error?: string } = { updated: 0 };
      const recruitResult: { updated: number; error?: string } = { updated: 0 };

      if (resetCCPro) {
        const { data, error } = await supabaseAdmin
          .from('agent_profiles')
          .update({
            call_connector_pro_disclaimer_accepted_at: null,
            updated_at: new Date().toISOString()
          })
          .not('call_connector_pro_disclaimer_accepted_at', 'is', null)
          .select('id');
        if (error) {
          ccproResult.error = error.message;
        } else {
          ccproResult.updated = data?.length ?? 0;
        }
      }

      if (resetRecruit) {
        try {
          const resRecruit = await supabaseAdmin
            .from('agent_profiles')
            .update({
              call_connector_pro_recruit_disclaimer_accepted_at: null,
              updated_at: new Date().toISOString()
            })
            .not('call_connector_pro_recruit_disclaimer_accepted_at', 'is', null)
            .select('id');
          if (resRecruit.error) {
            recruitResult.error = resRecruit.error.message;
          } else {
            recruitResult.updated = resRecruit.data?.length ?? 0;
          }
        } catch (e: any) {
          recruitResult.error = e?.message ?? 'Recruit column may not exist';
        }
      }

      console.log(`✅ Admin disclaimer reset: CCPro=${ccproResult.updated}${ccproResult.error ? ` (${ccproResult.error})` : ''}, Recruit=${recruitResult.updated}${recruitResult.error ? ` (${recruitResult.error})` : ''}`);

      res.json({
        success: true,
        message: 'Disclaimer flags reset',
        callConnectorPro: ccproResult,
        recruit: recruitResult
      });
    } catch (error: any) {
      console.error('❌ Error resetting disclaimers:', error);
      res.status(500).json({
        error: 'Failed to reset disclaimers',
        details: error?.message
      });
    }
  });

