  // Elite performance endpoint with real associate production data
  app.get("/api/gamification/elite-performance/:email", async (req, res) => {
    try {
      const { email } = req.params;
      console.log(`🔍 Fetching elite performance data for: ${email}`);
      
      // Get user credits to access associate_id and production data
      const userCredits = await connectnowService.getUserCredits(email);
      console.log(`📊 User credits for elite performance:`, userCredits);
      
      let elitePerformance = [];
      let hasEliteAccess = false;
      let associateId = null;
      let dataSource = 'activity_based';
      
      // Load real production data from Excel file
      let realProductionData = null;
      try {
        const fs = await import('fs');
        const productionDataFile = fs.readFileSync('./production-data.json', 'utf8');
        const allProductionData = JSON.parse(productionDataFile);
        console.log(`📈 Loaded ${allProductionData.length} associate production records`);
        
        // Extract associate ID if available
        if (userCredits && userCredits.associate_id) {
          associateId = userCredits.associate_id;
          console.log(`👤 Found associate ID: ${associateId}`);
          
          // Find production data for this associate ID
          realProductionData = allProductionData.find(record => 
            record['Associate ID'] && record['Associate ID'].toString() === associateId.toString()
          );
          
          if (realProductionData) {
            console.log(`🎯 Found real production data for associate ${associateId}:`, realProductionData);
            dataSource = 'real_production_data';
            // Extract ALL monthly production data including January (the actual best month)
            const januaryALP = parseInt(realProductionData.January) || 0;
            const februaryALP = parseInt(realProductionData.February) || 0;
            const marchALP = parseInt(realProductionData.March) || 0;
            const aprilALP = parseInt(realProductionData.April) || 0;
            const mayALP = parseInt(realProductionData.May) || 0;
            const decemberALP = parseInt(realProductionData.December) || 0;
            
            elitePerformance = [
              { month: "January", year: 2024, alp: januaryALP, rank: 1 },
              { month: "February", year: 2024, alp: februaryALP, rank: 2 },
              { month: "March", year: 2024, alp: marchALP, rank: 3 },
              { month: "April", year: 2024, alp: aprilALP, rank: 4 },
              { month: "May", year: 2024, alp: mayALP, rank: 5 },
              { month: "December", year: 2023, alp: decemberALP, rank: 6 },
            ].filter(month => month.alp > 0); // Only include positive performance months
            
            // Sort by highest production
            elitePerformance.sort((a, b) => b.alp - a.alp);
            elitePerformance.forEach((month, index) => {
              month.rank = index + 1;
            });
            
            hasEliteAccess = elitePerformance[0]?.alp >= 6000;
          }
        }
        
        // If no associate ID or no production data found, try to match by name/email
        if (!realProductionData) {
          const userName = userCredits?.name?.toUpperCase() || '';
          const emailName = email.split('@')[0].toUpperCase();
          
          // Search by name patterns
          realProductionData = allProductionData.find(record => {
            const recordName = (record.Name || '').toUpperCase();
            return recordName.includes(userName) || 
                   recordName.includes(emailName) ||
                   (userName && recordName.split(' ').some(part => userName.includes(part)));
          });
          
          if (realProductionData) {
            console.log(`🔍 Found production data by name match for ${email}:`, realProductionData);
            dataSource = 'real_production_data';
            associateId = realProductionData['Associate ID'];
            
            // Extract ALL monthly production data including January (the actual best month)
            const januaryALP = parseInt(realProductionData.January) || 0;
            const februaryALP = parseInt(realProductionData.February) || 0;
            const marchALP = parseInt(realProductionData.March) || 0;
            const aprilALP = parseInt(realProductionData.April) || 0;
            const mayALP = parseInt(realProductionData.May) || 0;
            const decemberALP = parseInt(realProductionData.December) || 0;
            
            elitePerformance = [
              { month: "January", year: 2024, alp: januaryALP, rank: 1 },
              { month: "February", year: 2024, alp: februaryALP, rank: 2 },
              { month: "March", year: 2024, alp: marchALP, rank: 3 },
              { month: "April", year: 2024, alp: aprilALP, rank: 4 },
              { month: "May", year: 2024, alp: mayALP, rank: 5 },
              { month: "December", year: 2023, alp: decemberALP, rank: 6 },
            ].filter(month => month.alp > 0); // Only include positive performance months
            
            elitePerformance.sort((a, b) => b.alp - a.alp);
            elitePerformance.forEach((month, index) => {
              month.rank = index + 1;
            });
            
            hasEliteAccess = elitePerformance[0]?.alp >= 6000;
          }
        }
      } catch (fileError) {
        console.log(`⚠️ Could not load production data file:`, fileError.message);
      }
      
      // Fallback to activity-based calculation if no real data found
      if (!realProductionData) {
        console.log(`⚠️ No real production data found for ${email}, using activity-based calculation`);
        
        // Calculate based on actual AO Intelligence activity and credits
        const creditsUsed = userCredits?.credits_used || 0;
        const creditsRemaining = userCredits?.credits_remaining || 0;
        const totalCredits = creditsUsed + creditsRemaining;
        const connectCreditsUsed = userCredits?.aoi_connect_credits_used || 0;
        
        // Enhanced calculation for high-usage accounts
        const baseALP = 3000;
        const connectBonus = connectCreditsUsed * 75; // Each Connect credit = $75 ALP
        const activityMultiplier = Math.min((totalCredits / 50) * 0.8, 2.5);
        const usageBonus = creditsUsed * 35;
        
        const currentALP = Math.floor(baseALP * activityMultiplier + usageBonus + connectBonus);
        
        elitePerformance = [
          { month: "December", year: 2024, alp: currentALP, rank: 1 },
          { month: "November", year: 2024, alp: Math.floor(currentALP * 0.87), rank: 2 },
          { month: "October", year: 2024, alp: Math.floor(currentALP * 0.81), rank: 3 },
        ];
        
        hasEliteAccess = currentALP >= 6000;
        
        console.log(`📈 Calculated ALP for ${email}: ${currentALP} (${connectCreditsUsed} Connect credits, ${creditsUsed} total used)`);
      }
      
      console.log(`🎯 Elite performance result for ${email}:`, {
        dataSource,
        hasEliteAccess,
        bestMonth: elitePerformance[0]?.alp,
        bestMonthName: elitePerformance[0]?.month,
        associateId
      });
      
      res.json({
        success: true,
        topMonths: elitePerformance,
        hasEliteAccess: hasEliteAccess,
        targetALP: 6000,
        associateId: associateId,
        dataSource: dataSource,
        realAssociateName: realProductionData?.Name || null
      });
    } catch (error) {
      console.error('❌ Error fetching elite performance:', error);
      res.status(500).json({ error: 'Failed to fetch elite performance data' });
    }
  });

