  // User Credits API (uses same auth resolution as voice-online: session, JWT, cookie, header, query)
  // User credits cache — 10s TTL (credits update on call end, not continuously)
  const _userCreditsCache = new Map<string, { expires: number; payload: any }>();
  const USER_CREDITS_TTL = 10_000;

  app.get("/api/user/credits", async (req, res) => {
    try {
      const userEmail = await getAgentEmailFromRequest(req, { email: req.query?.email as string });
      if (!userEmail) return res.status(401).json({ error: 'User email required for credits' });

      // Serve from cache if fresh
      const cached = _userCreditsCache.get(userEmail);
      if (cached && Date.now() < cached.expires) {
        return res.json(cached.payload);
      }

      const [credits, bonusConnects] = await Promise.all([
        connectnowService.getUserCredits(userEmail),
        getBonusConnectSnapshot(userEmail),
      ]);

      const response = {
        credits_remaining: (credits as any)?.credits_remaining || (credits as any)?.creditsRemaining || 0,
        credits_used: (credits as any)?.credits_used || (credits as any)?.creditsUsed || 0,
        credits_purchased: (credits as any)?.credits_purchased || (credits as any)?.creditsPurchased || 0,
        bonus_connects_remaining: bonusConnects.bonus_connects_remaining,
        bonus_connects_max: bonusConnects.bonus_connects_max,
        bonus_connects_reset_key: bonusConnects.reset_key,
      };

      _userCreditsCache.set(userEmail, { expires: Date.now() + USER_CREDITS_TTL, payload: response });
      res.json(response);
    } catch (error) {
      console.error('User credits error:', error);
      res.status(500).json({ error: 'Failed to get user credits' });
    }
  });

