  // User profile for UserpilotInit (associate_id, name, teams, etc.)
  app.get("/api/user/profile", async (req, res) => {
    try {
      const userEmail = (req.headers['user-email'] as string) || (req.headers['x-user-email'] as string) || (req.query.email as string);
      if (!userEmail?.trim()) {
        return res.status(400).json({ error: 'User email is required (user-email or x-user-email header, or email query)' });
      }
      const email = userEmail.trim().toLowerCase();
      if (!supabaseAdmin) {
        return res.status(503).json({ error: 'Database unavailable' });
      }
      let associateId: number | null = null;
      let firstName: string | null = null;
      let lastName: string | null = null;
      let createdAt: string | null = null;
      let mga: string | null = null;
      let rga: string | null = null;
      let markets: string[] | null = null;
      let plan = 'Standard';

      const { data: ap } = await supabaseAdmin
        .from('agent_profiles')
        .select('first_name, last_name, created_at, mga_team, rga_team, authorized_markets')
        .eq('email', email)
        .maybeSingle();
      if (ap) {
        firstName = ap.first_name ?? null;
        lastName = ap.last_name ?? null;
        createdAt = ap.created_at ? new Date(ap.created_at).toISOString() : null;
        mga = ap.mga_team ?? null;
        rga = ap.rga_team ?? null;
        if (ap.authorized_markets && Array.isArray(ap.authorized_markets)) {
          markets = ap.authorized_markets as string[];
        }
      }

      const { data: custRows } = await supabaseAdmin
        .from('customers')
        .select('associate_id, mga, rga, market, primary_market')
        .or(`company_email.eq.${email},personal_email.eq.${email}`)
        .limit(1);
      const cust = custRows?.[0] ?? null;
      let customerMarket: string | string[] | null = null;
      if (cust) {
        associateId = cust.associate_id ?? null;
        if (cust.mga) mga = cust.mga;
        if (cust.rga) rga = cust.rga;
        // Get market from customers table (can be string or JSONB array)
        customerMarket = cust.market || cust.primary_market || null;
      }

      res.json({
        associate_id: associateId,
        first_name: firstName,
        last_name: lastName,
        created_at: createdAt,
        mga,
        rga,
        markets: markets ?? undefined,
        market: customerMarket, // Market from customers table
        plan,
      });
    } catch (e: any) {
      console.error('❌ /api/user/profile error:', e?.message ?? e);
      res.status(500).json({ error: 'Failed to fetch user profile' });
    }
  });

