  // Shared token generation function
  const generateTwilioToken = async (req: any, res: any, platform: 'browser' | 'electron') => {
    try {
      const ua = req.headers['user-agent'] || '';
      const desktopHeader = `${req.headers['x-desktop-app'] || ''}`.toLowerCase();
      const isElectron = ua.includes('AOI-Desktop') || ua.includes('Electron') || desktopHeader === 'true' || desktopHeader === '1';
      
      console.log(`🔍 [TOKEN DEBUG - ${platform.toUpperCase()}]`, {
        ua: ua.substring(0, 100),
        desktop: req.headers['x-desktop-app'],
        desktopHeader,
        isElectron,
        detectedPlatform: platform,
        cookie: req.headers.cookie ? req.headers.cookie.substring(0, 200) : 'NO COOKIES',
        sessionID: (req as any).sessionID,
        sessionUser: (req.session as any)?.user?.email || 'NO SESSION USER',
        reqUser: (req as any)?.user?.email || 'NO REQ USER',
        hasSession: !!req.session,
        sessionKeys: req.session ? Object.keys(req.session) : [],
        origin: req.headers.origin,
      });
      
      // VALIDATE platform matches request
      if (platform === 'electron' && !isElectron) {
        console.warn(`⚠️ [TOKEN DEBUG] Electron endpoint called from browser - REJECTING`);
        return res.status(400).json({ error: 'This endpoint is for Electron only. Use /api/twilio/token for browser.' });
      }
      if (platform === 'browser' && isElectron) {
        console.warn(`⚠️ [TOKEN DEBUG] Browser endpoint called from Electron - REJECTING`);
        return res.status(400).json({ error: 'This endpoint is for browser only. Use /api/electron/twilio/token for Electron.' });
      }
      
      // Try multiple sources for user email (session, req.user from JWT middleware, or x-user-email header)
      const sessionEmail = (req.session as any)?.user?.email;
      const jwtUserEmail = (req as any)?.user?.email;
      const headerEmail = req.headers['x-user-email'] || req.headers['X-User-Email'];
      
      // Also try to extract from Supabase token directly if session doesn't have it
      let supabaseEmail: string | null = null;
      if (!sessionEmail && !jwtUserEmail) {
        try {
          const cookieHeader = req.headers.cookie || '';
          const match = cookieHeader.match(/sb-access-token=([^;]+)/);
          if (match) {
            const token = decodeURIComponent(match[1].trim());
            if (token && supabaseAdmin) {
              const { data: { user }, error } = await supabaseAdmin.auth.getUser(token);
              if (!error && user?.email) {
                supabaseEmail = user.email;
                // Also populate session for next time
                if (req.session) {
                  (req.session as any).user = { id: user.id, email: user.email };
                }
              }
            }
          }
        } catch (e) {
          // Ignore errors
        }
      }
      
      const userEmail = sessionEmail || jwtUserEmail || headerEmail || supabaseEmail;
      
      if (!userEmail || typeof userEmail !== 'string' || !userEmail.includes('@')) {
        console.error(`❌ [TOKEN DEBUG - ${platform.toUpperCase()}] No user email found`, {
          hasSession: !!req.session,
          sessionEmail: sessionEmail || 'none',
          jwtUserEmail: jwtUserEmail || 'none',
          headerEmail: headerEmail || 'none',
          supabaseEmail: supabaseEmail || 'none',
          sessionID: (req as any).sessionID,
          cookies: req.headers.cookie ? 'present' : 'missing',
          sessionKeys: req.session ? Object.keys(req.session) : 'no session'
        });
        return res.status(401).json({ error: 'Login required', message: 'You must be logged in to use WebRTC.' });
      }
      const identity = userEmail.trim().toLowerCase();

      const accountSid = TWILIO_ACCOUNT_SID;
      const apiKey = TWILIO_API_KEY;
      const apiSecret = TWILIO_API_SECRET;
      const twimlAppSid = TWILIO_TWIML_APP_SID;
      
      if (!accountSid || !apiKey || !apiSecret || !twimlAppSid) {
        return res.status(500).json({ error: 'Missing Twilio credentials' });
      }

      const AccessToken = twilio.jwt.AccessToken;
      const VoiceGrant = AccessToken.VoiceGrant;

      const voiceGrant = new VoiceGrant({
        outgoingApplicationSid: twimlAppSid,
        incomingAllow: true,
      });

      const token = new AccessToken(accountSid, apiKey, apiSecret, {
        identity: identity,
        ttl: 28800 // 8 hours — covers a full shift so token never expires mid-day
      });

      token.addGrant(voiceGrant);

      const jwt = token.toJwt();
      console.log(`✅ [${platform.toUpperCase()}] Generated token for identity: ${identity}`);
      if (identity === 'cnsysop@aoglobelife.com') {
        console.log('Voice token identity for 609 dequeue match: browser must use exactly client:cnsysop@aoglobelife.com — identity=', identity);
      }

      res.json({ token: jwt, identity: identity });

    } catch (error: any) {
      console.error(`❌ Token generation failed (${platform}):`, error.message);
      res.status(500).json({ error: 'Failed to generate token' });
    }
  };

