  // SINGLE WebRTC endpoint - handles ALL agent WebRTC connections AND INBOUND CALLS
  const handleWebRTC = async (req, res) => {
    try {
      // Conference POC: agent_conference_test mode
      const mode = req.body?.mode || req.query?.mode;
      if (mode === 'agent_conference_test') {
        const agentId = String(req.body?.agentId || req.query?.agentId || 'test-agent');
        const sessionId = String(req.body?.sessionId || req.query?.sessionId || '');
        const callSid = req.body?.CallSid || '';
        const conferenceName = `connect-${sessionId}`;
        const baseUrl = process.env.BASE_URL || process.env.PUBLIC_BASE_URL || PRODUCTION_BASE_URL;
        handleAgentConferenceJoin(agentId, sessionId, callSid);
        res.set('Content-Type', 'text/xml');
        return res.send(`<?xml version='1.0' encoding='UTF-8'?><Response><Dial><Conference startConferenceOnEnter='true' endConferenceOnExit='false' beep='false' statusCallback='${baseUrl}/api/connect/conference-status' statusCallbackEvent='start end join leave mute hold' statusCallbackMethod='POST'>${conferenceName}</Conference></Dial></Response>`);
      }
      // INBOUND: caller is PSTN (From = phone number), we're not in a conference — route to /connect
      // Twilio sends form-encoded body; also allow query fallback so we never miss 609 Enqueue
      const body = req.body || {};
      const q = req.query || {};
      const callerNumber = body.From || body.from || q.From || q.from;
      const calledNumber = body.To || body.to || body.Called || body.called || q.To || q.Called;
      const callSid = body.CallSid || body.call_sid || q.CallSid;
      const hasConference = !!(body.conference || req.query.conference || body.agentEmail || req.query.agentEmail);
      const fromStr = String(callerNumber || '');
      const isPstnCaller = fromStr.length > 0 && (fromStr.startsWith('+') || /^\d+$/.test(fromStr.replace(/\D/g, ''))) && !fromStr.toLowerCase().startsWith('client:');
      const calledDigits = String(calledNumber || '').replace(/\D/g, '');
      const calledLast10 = calledDigits.slice(-10);
      // All inbound calls come in to the 609 number. This URL is the Voice URL for 609; if PSTN caller and no conference, treat as inbound and route.
      const isInboundNumber = calledLast10 === '6096048379' || (isPstnCaller && !hasConference && !calledLast10);
      const shouldRouteInbound = isPstnCaller && !hasConference && (calledLast10 === '6096048379' || isInboundNumber);
      const inboundBaseUrl = PRODUCTION_BASE_URL;
      // Diagnostic: log every webhook request so we can see why inbound might show busy (missing body? wrong path?)
      console.error(`📞 WebRTC ${req.method} From=${callerNumber} To=${calledNumber} CallSid=${callSid} bodyKeys=${Object.keys(body).join(',')} isPstn=${isPstnCaller} shouldRouteInbound=${shouldRouteInbound} calledLast10=${calledLast10}`);
      // Inbound call to 914 number → AI customer service bot
      const is914Inbound = isPstnCaller && !hasConference && calledLast10 === '9142289324';
      if (is914Inbound) {
        const csBotUrl = `${PRODUCTION_BASE_URL}/cs-bot/voice`;
        console.log(`📞 914 inbound → CS bot: ${csBotUrl}`);
        res.type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?><Response><Redirect method="POST">${csBotUrl}</Redirect></Response>`);
        return;
      }
      if (isPstnCaller && !hasConference && !shouldRouteInbound) {
        console.log(`📞 Inbound-style request to non-inbound number ${calledNumber} (last10=${calledLast10}) — skipping /connect`);
      }
      if (shouldRouteInbound) {
        const redirectUrl = `${inboundBaseUrl}/incomingcall`;
        console.error(`📞 Redirecting legacy inbound webhook to dedicated inbound route: ${redirectUrl}`);
        res.type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?><Response><Redirect method="POST">${redirectUrl}</Redirect></Response>`);
        return;
      }
      
      // OUTBOUND: No call without logged-in user. ONLY trust Twilio Caller/From (client:email) — never query/body.
      const callerIdentity = (req.body.Caller || req.body.From || req.query.Caller || req.query.From || '').toString();
      const hasClientIdentity = callerIdentity.toLowerCase().startsWith('client:') && callerIdentity.includes('@');
      let agentEmail = hasClientIdentity ? callerIdentity.replace(/^client:/i, '').trim().toLowerCase() : '';
      if (!agentEmail || !agentEmail.includes('@')) {
        console.warn('⚠️ WebRTC rejected: no user — Caller/From must be client:email (user must be logged in)');
        res.status(403).type('text/xml').send('<?xml version="1.0" encoding="UTF-8"?><Response><Reject reason="rejected"/></Response>');
        return;
      }
      if (agentEmail === 'cnsysop@aoglobelife.com' || agentEmail === 'unknown@aoglobelife.com') {
        console.warn(`⚠️ WebRTC rejected: invalid identity (${agentEmail}) — never cnsysop, never unknown`);
        res.status(403).type('text/xml').send('<?xml version="1.0" encoding="UTF-8"?><Response><Reject reason="rejected"/></Response>');
        return;
      }
      
      // Get conference name from WebRTC device params (supports both 'conference' and 'conferenceName')
      const conferenceName = req.body.conference || req.body.conferenceName || req.query.conference || req.query.conferenceName;
      const agentName = req.body.agentName || req.query.agentName || 'Unknown Agent';
      
      // Check for DIRECT CALL mode (Call Connector Pro direct dial)
      const directCallNumber = req.body.To || req.query.To;
      
      if (directCallNumber) {
        const directLeadIdRaw = req.body.leadId || req.query.leadId || req.body.lead_id || req.query.lead_id;
        const directLeadId = Number(directLeadIdRaw);
        if (!Number.isFinite(directLeadId) || directLeadId <= 0) {
          console.warn(`⚠️ Direct call rejected: missing/invalid leadId (agent=${agentEmail}, to=${directCallNumber})`);
          res.status(400).type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Lead ID is required before calling.</Say>
  <Hangup/>
</Response>`);
          return;
        }
        // DIRECT CALL MODE: Agent dials lead directly (NO CONFERENCE)
        console.log(`📞 DIRECT CALL: Agent ${agentEmail} calling ${directCallNumber} (leadId=${directLeadId})`);
        
        // NOTE: We don't log here with a fake callSid - the Dial action callback will log with the real callSid
        
        // Get local presence number based on lead state
        const leadState = req.body.leadState || req.query.leadState;
        let callerIdNumber = TWILIO_PHONE_NUMBER || '+19142289324';
        if (leadState && (global as any).localPresenceService) {
          try {
            const localNumber = (global as any).localPresenceService.getLocalNumber(leadState);
            if (localNumber && localNumber !== TWILIO_PHONE_NUMBER) {
              callerIdNumber = localNumber;
              console.log(`📞 LOCAL PRESENCE: Using ${localNumber} for ${leadState} lead`);
            }
          } catch (error) {
            console.error('❌ Local presence lookup failed, using default:', error);
          }
        }
        
        // CRITICAL: Add Dial action callback to capture the REAL call SID when Dial creates the outbound call
        // CRITICAL: Pass agentEmail in statusCallback URL so status webhook can log the call with correct attribution
        const currentDomain = req.get('host')?.includes('localhost') ? WEBHOOK_BASE_URL.replace(/^https?:\/\//, '') : req.get('host');
        const statusCallback = `https://${currentDomain}/api/twilio/call-status?agentEmail=${encodeURIComponent(agentEmail)}&leadState=${encodeURIComponent(leadState || 'Unknown')}`;
        const dialAction = `https://${currentDomain}/api/twilio/dial-action?agentEmail=${encodeURIComponent(agentEmail)}&leadState=${encodeURIComponent(leadState || 'Unknown')}`;
        const amdResultUrl = `${PRODUCTION_BASE_URL}/api/twilio/amd-result`;
        const recordingCbDirect = `${PRODUCTION_BASE_URL}/api/twilio/recording-status`;
        const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial 
    callerId="${escapeXml(callerIdNumber)}"
    action="${escapeXml(amdResultUrl)}"
    method="POST"
    statusCallback="${escapeXml(statusCallback)}"
    statusCallbackMethod="POST"
    statusCallbackEvent="initiated,ringing,answered,completed"
    record="record-from-answer"
    recordingStatusCallback="${escapeXml(recordingCbDirect)}"
    recordingStatusCallbackMethod="POST">
    <Number>${escapeXml(directCallNumber)}</Number>
  </Dial>
</Response>`;
        
        // DIRECT DIAL COUNT — same atomic write as /api/dial-lead path
        void incrementAgentDailyStat(agentEmail, 'dial').catch(e =>
          console.warn(`⚠️ Direct call dial count failed (non-blocking): ${e?.message}`)
        );
        console.log(`✅ DIRECT CALL TwiML sent for ${directCallNumber} with Dial action: ${dialAction}`);
        res.type('text/xml');
        res.send(twiml);
        return;
      }
      
      console.log(`🔥 AGENT ATTRIBUTION: ${agentEmail} (${agentName}) joining conference: ${conferenceName}`);
      
      if (!conferenceName) {
        console.log('❌ No conference name provided - using fallback');
        res.status(400).type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>No conference specified</Say>
</Response>`);
        return;
      }
      
      console.log(`🎯 Agent ${agentEmail} joining conference: ${conferenceName}`);
      
      // CRITICAL: Add StatusCallback with metadata for proper call attribution
      const statusCallback = `${WEBHOOK_BASE_URL}/api/twilio/status`;
      
      // FORCE ALL WEBRTC CONFERENCES TO USE SOFT-ROCK (override agent preferences)
      const waitMusicUrl = "http://twimlets.com/holdmusic?Bucket=com.twilio.music.soft-rock";
      console.log(`🎵 FORCED: All WebRTC conferences using soft-rock hold music for ${agentEmail}`);
      
      const recordingCb = `${PRODUCTION_BASE_URL}/api/twilio/recording-status`;
      const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial>
    <Conference 
      beep="false"
      startConferenceOnEnter="true"
      endConferenceOnExit="false"
      maxParticipants="2"
      waitUrl="${waitMusicUrl}"
      statusCallback="${statusCallback}"
      statusCallbackEvent="start,end,join,leave"
      statusCallbackMethod="POST"
      record="record-from-start"
      recordingStatusCallback="${recordingCb}"
      recordingStatusCallbackMethod="POST">${conferenceName}</Conference>
  </Dial>
</Response>`;

      console.log(`✅ TwiML sent - Agent ${agentEmail} going to: ${conferenceName}`);
      res.type('text/xml');
      res.send(twiml);
      
      // CRITICAL: Store this WebRTC connection in the live tracking
      try {
        // Log this agent connection for call attribution
        storage.trackAgentWebRTCConnection({
          agentEmail,
          agentName,
          conferenceName,
          timestamp: new Date().toISOString(),
          connectionType: 'webrtc_agent'
        });
        console.log(`✅ Agent WebRTC connection tracked for ${agentEmail}`);
      } catch (trackingError) {
        console.warn('⚠️ Failed to track agent WebRTC connection:', trackingError);
      }
      
    } catch (error) {
      console.error('❌ WebRTC error:', error);
      res.status(500).type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Connection error</Say>
</Response>`);
    }
  };

  // Dedicated webhook for test inbound: route into the exact same inbound webhook path as real 609 calls.
  const handleTestInboundWebhook = (req: any, res: any) => {
    const inboundBaseUrl = PRODUCTION_BASE_URL;
    const redirectUrl = `${inboundBaseUrl}/incomingcall`;
    console.log(`[webhook/test-inbound] Redirecting test inbound to ${redirectUrl}`);
    res.type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?><Response><Redirect method="POST">${redirectUrl}</Redirect></Response>`);
  };
  app.get("/webhook/test-inbound", handleTestInboundWebhook);
  app.post("/webhook/test-inbound", handleTestInboundWebhook);

  // 609 inbound: cascade ring — caller hears RINGING the entire time (no hold music, no Enqueue).
  const RING_WAVE_SECONDS = 4;
  const AGENTS_PER_WAVE = 3;
  const FALLBACK_TWIML = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="alice">We are temporarily unable to route your call. Please try again later.</Say><Hangup/></Response>';
  const NO_AGENT_TWIML = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="alice">No agent is available. Please try again later.</Say><Hangup/></Response>';
  const escapeXml = (s: string) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
  // Ringback = caller hears phone ringing while in queue. We serve the audio ourselves so Twilio never hits an external URL.
  const RINGBACK_TWIML_BASE = WEBHOOK_BASE_URL;
  const RINGBACK_TWIML = `<?xml version="1.0" encoding="UTF-8"?><Response><Play loop="0">${RINGBACK_TWIML_BASE}/api/twilio/ringback-audio</Play></Response>`;
  app.get('/api/twilio/ringback', (_req, res) => { res.type('text/xml').send(RINGBACK_TWIML); });
  app.post('/api/twilio/ringback', (_req, res) => { res.type('text/xml').send(RINGBACK_TWIML); });
  // Fallback audio URL if our fetch fails — 502 here causes Twilio to play "application error" to caller.
  const RINGBACK_FALLBACK_AUDIO_URL = 'https://demo.twilio.com/docs/classic.mp3';
  let ringbackAudioCache: Buffer | null = null;
  app.get('/api/twilio/ringback-audio', async (_req, res) => {
    try {
      if (ringbackAudioCache) {
        res.setHeader('Content-Type', 'audio/ogg');
        return res.send(ringbackAudioCache);
      }
      const r = await fetch('https://upload.wikimedia.org/wikipedia/commons/c/cd/US_ringback_tone.ogg', { signal: AbortSignal.timeout(5000) });
      if (!r.ok) throw new Error(`upstream ${r.status}`);
      const buf = Buffer.from(await r.arrayBuffer());
      ringbackAudioCache = buf;
      res.setHeader('Content-Type', 'audio/ogg');
      res.send(buf);
    } catch (e) {
      if (ringbackAudioCache) {
        res.setHeader('Content-Type', 'audio/ogg');
        return res.send(ringbackAudioCache);
      }
      // Never return 502 — Twilio plays "application error". Redirect to known-good audio.
      res.redirect(302, RINGBACK_FALLBACK_AUDIO_URL);
    }
  });
  const handleIncomingCallDialAction = async (req: any, res: any) => {
    const wave = parseInt(String(req.query?.wave || req.body?.wave || '1'), 10) || 1;
    const market = String(req.query?.market || req.body?.market || '').trim() || 'Unknown';
    const state = String(req.query?.state || req.body?.state || '').trim() || 'XX';
    const baseUrl = PRODUCTION_BASE_URL;
    const { orderedEmails } = await getEligibleAgentsForInbound(market, state);
    const start = (wave - 1) * AGENTS_PER_WAVE;
    const waveEmails = orderedEmails.slice(start, start + AGENTS_PER_WAVE);
    if (waveEmails.length === 0) {
      console.error(`609 dial-action wave=${wave} no more agents market=${market} state=${state}`);
      res.type('text/xml').send(NO_AGENT_TWIML);
      return;
    }
    const nextWave = wave + 1;
    const actionUrl = `${baseUrl}/incomingcall-dial-action?wave=${nextWave}&market=${encodeURIComponent(market)}&state=${encodeURIComponent(state)}`;
    const waitUrl = `${baseUrl}/api/twilio/ringback`;
    const clientTags = waveEmails.map((email: string) => `<Client>${escapeXml(email)}</Client>`).join('\n    ');
    const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial timeout="${RING_WAVE_SECONDS}" action="${escapeXml(actionUrl)}" ringTone="us" waitUrl="${escapeXml(waitUrl)}">
    ${clientTags}
  </Dial>
</Response>`;
    console.error(`609 dial-action wave=${wave} ringing ${waveEmails.length} agent(s): ${waveEmails.join(', ')}`);
    res.type('text/xml').send(twiml);
  };
  app.get("/incomingcall-dial-action", (req: any, res: any) => { handleIncomingCallDialAction(req, res).catch(() => res.type('text/xml').send(NO_AGENT_TWIML)); });
  app.post("/incomingcall-dial-action", express.urlencoded({ extended: false }), (req: any, res: any) => { handleIncomingCallDialAction(req, res).catch(() => res.type('text/xml').send(NO_AGENT_TWIML)); });
  const handleIncomingCall = async (req: any, res: any) => {
    const body = req.body || {};
    const q = req.query || {};
    const callSid = body.CallSid || body.call_sid || q.CallSid;
    const from = body.From || body.from || q.From || q.from;
    const to = body.To || body.to || body.Called || q.To || q.Called;
    const effectiveCallSid = callSid || 'inbound-' + Date.now();
    const responseCode = 200;
    let responseBody: string;
    try {
      const phoneNumber = String(from || '').trim();
      const callerLast10 = phoneNumber.replace(/\D/g, '').slice(-10);
      let leadMarket = 'Unknown';
      let leadState = 'XX';
      let leadName = 'Unknown';
      let leadId: string | undefined;
      let firstName: string | undefined;
      let lastName: string | undefined;
      let taalkLeadId: string | undefined;
      let leadEmail: string | undefined;
      let leadCity: string | undefined;

      // Look up lead by caller phone in masterlead (normalized last-10 match first, then ilike fallback).
      // Cap at 3s so we never exceed Twilio's webhook timeout (~15s) — slow DB = use Unknown/XX and still Enqueue.
      const fetchLead = async (): Promise<Record<string, unknown> | null> => {
        if (callerLast10.length < 10) return null;
        const byNorm = await getMasterleadByPhoneLast10(callerLast10);
        if (byNorm) return byNorm;
        const { data: leadRow } = await masterleadClient.from('masterlead')
          .select('id, state, taalk_state, taalk_market, first_name, last_name, taalk_lead_id, email, cn_email, city, taalk_city')
          .eq('phone_last10', callerLast10)
          .order('updated_at', { ascending: false })
          .limit(1)
          .maybeSingle();
        return leadRow ?? null;
      };
      const LEAD_LOOKUP_MS = 3000;
      let leadRow: Record<string, unknown> | null = null;
      try {
        leadRow = await Promise.race([
          fetchLead(),
          new Promise<null>((_, reject) => setTimeout(() => reject(new Error('lead lookup timeout')), LEAD_LOOKUP_MS)),
        ]);
      } catch (_) {
        // timeout or error: use Unknown/XX
      }
      try {
        if (leadRow) {
          // State: masterlead.state or masterlead.taalk_state (normalize to 2-letter)
          const rawState = (leadRow.state ?? (leadRow as any)?.taalk_state) != null ? String(leadRow.state ?? (leadRow as any).taalk_state).trim() : '';
          if (rawState) leadState = rawState.length === 2 ? rawState.toUpperCase() : rawState;
          // Market: masterlead.taalk_market or masterlead.market
          const rawMarket = ((leadRow as any)?.taalk_market ?? (leadRow as any)?.market) != null ? String((leadRow as any).taalk_market ?? (leadRow as any).market).trim() : '';
          if (rawMarket) leadMarket = rawMarket;
          console.error(`609 /incomingcall: masterlead lookup phone ...${callerLast10} → market=${leadMarket} state=${leadState} (from masterlead id=${leadRow.id})`);
          if (leadMarket === 'Unknown' || leadState === 'XX') {
            console.error(`609 /incomingcall: lead id=${leadRow.id} has Unknown/XX — raw row state=${leadRow.state} taalk_state=${(leadRow as any).taalk_state} taalk_market=${(leadRow as any).taalk_market}`);
          }
          if (leadRow.first_name || leadRow.last_name) {
            firstName = leadRow.first_name ? String(leadRow.first_name).trim() : undefined;
            lastName = leadRow.last_name ? String(leadRow.last_name).trim() : undefined;
            leadName = [firstName, lastName].filter(Boolean).join(' ').trim() || 'Unknown';
          }
          if (leadRow.id) leadId = String(leadRow.id);
          if (leadRow.taalk_lead_id) taalkLeadId = String(leadRow.taalk_lead_id).trim();
          const em = leadRow.email || leadRow.cn_email;
          if (em) leadEmail = String(em).trim();
          try {
            const rawCity = (leadRow as any).city ?? (leadRow as any).taalk_city;
            if (rawCity != null && String(rawCity).trim()) leadCity = String(rawCity).trim();
          } catch (_) {}
        } else if (callerLast10.length >= 10) {
          console.error(`609 /incomingcall: no masterlead row for phone ...${callerLast10} (tried normalized SQL + ilike)`);
        }
      } catch (leadErr) {
        console.error('609 /incomingcall: masterlead lookup failed', leadErr);
      }
      // Use lead market/state from masterlead (no debug override).

      // Log every 609 inbound to twilio_call_logs so we have them (call-status will update same row when status changes).
      if (effectiveCallSid && !String(effectiveCallSid).startsWith('inbound-')) {
        const inboundLogPayload = {
          twilio_call_sid: effectiveCallSid,
          from_number: from || null,
          to_number: to || null,
          call_direction: 'inbound',
          call_status: 'queued',
          call_duration: 0,
          call_started_at: new Date().toISOString(),
          call_source: 'incomingcall_609',
        };
        upsertTwilioCallLogLocal(inboundLogPayload)
          .catch((localErr) => {
            console.warn('609 inbound local twilio_call_logs upsert failed:', (localErr as Error)?.message);
          })
          .then(() => {})
          .catch((err) => console.warn('609 inbound log to twilio_call_logs failed:', (err as Error)?.message));
      }

      // 609: Always Enqueue. Use THIS request's host for waitUrl/actionUrl so Twilio hits the same server (no 404 / application error).
      if (!isTaskRouterConfigured()) {
        responseBody = FALLBACK_TWIML;
        console.error(`609 /incomingcall TaskRouter not configured CallSid=${effectiveCallSid}`);
      } else {
        const protocol = req.secure || req.headers['x-forwarded-proto'] === 'https' ? 'https' : 'http';
        const host = (req.headers['x-forwarded-host'] as string) || req.get('host') || '';
        const baseUrl = host ? `${protocol}://${host}` : PRODUCTION_BASE_URL;
        const waitUrl = `${baseUrl}/api/twilio/ringback`; // ringback tone (ringing), not hold music
        const actionUrl = `${baseUrl}/api/twilio/enqueue-action`; // when call leaves queue (hangup or bridge end) → cleanup task
        const taskAttributesJson = buildTaskAttributesFor609Inbound({
          call_sid: effectiveCallSid,
          phone_number: phoneNumber,
          market: leadMarket,
          state: leadState,
          lead_id: leadId,
          lead_name: leadName,
          first_name: firstName,
          last_name: lastName,
          lead_email: leadEmail,
          taalk_lead_id: taalkLeadId,
          city: leadCity,
        });
        const workflowSid = getWorkflowSidForEnqueue();
        responseBody = buildEnqueueTwiML(workflowSid, taskAttributesJson, waitUrl, actionUrl);
        console.log(`609 TASK CREATED CallSid=${effectiveCallSid} From=${from} To=${to} market=${leadMarket} state=${leadState} workflowSid=${workflowSid}`);
        console.error(`609 /incomingcall Enqueue CallSid=${effectiveCallSid} From=${from} To=${to} market=${leadMarket} state=${leadState} workflowSid=${workflowSid} twiml=${responseBody.slice(0, 200)}...`);
        console.error(`LIVE_CALL_INCOMINGCALL 609 ENQUEUE method=${req.method} CallSid=${effectiveCallSid} From=${from} To=${to}`);
      }
      res.status(responseCode).type('text/xml').send(responseBody);
      return;
    } catch (e) {
      console.error('📞 609 /incomingcall exception:', e);
      try {
        res.status(200).type('text/xml').send(FALLBACK_TWIML);
      } catch (_) {}
      return;
    }
  };
