  // Inbound call fallback endpoint - when agent doesn't answer or when Dial ends (re-enable VDP)
  app.post("/api/twilio/inbound-fallback", async (req, res) => {
    try {
      const market = req.query.market as string || '';
      const caller = req.query.caller as string || '';
      const dialCallStatus = req.body.DialCallStatus; // 'no-answer', 'busy', 'failed', 'completed'
      const agentEmailParam = (req.query.agentEmail as string)?.trim();
      const ringGroupEmailsParam = (req.query.ringGroupEmails as string)?.trim();
      // Re-enable VDP for agent(s) when inbound Dial ends (answered, no-answer, or busy)
      const emailsToReenable: string[] = [];
      if (agentEmailParam && agentEmailParam.includes('@')) emailsToReenable.push(agentEmailParam.toLowerCase());
      if (ringGroupEmailsParam) emailsToReenable.push(...ringGroupEmailsParam.split(',').map((e: string) => e.trim().toLowerCase()).filter((e: string) => e.includes('@')));
      if (emailsToReenable.length > 0) {
        try {
          const { error: vdpOn } = await supabaseAdmin.from('customers').update({ VDPACTIVE: 'ACTIVE' }).in('company_email', [...new Set(emailsToReenable)]);
          if (vdpOn) console.warn('⚠️ Failed to set VDPACTIVE ACTIVE after inbound:', vdpOn?.message);
          else console.log(`✅ VDP re-enabled after inbound for: ${emailsToReenable.length} agent(s)`);
        } catch (_) {}
      }
      console.log(`📞 INBOUND FALLBACK triggered: market=${market}, caller=${caller}, status=${dialCallStatus}`);
      
      // Determine fallback number based on market
      const VETERANS_FALLBACK = '+17046868739'; // Veterans support line
      const GLOBE_FALLBACK = '+14583132402';    // Globe Life support line
      
      const fallbackNumber = market.toLowerCase().includes('veteran') 
        ? VETERANS_FALLBACK 
        : GLOBE_FALLBACK;
      
      const fallbackName = market.toLowerCase().includes('veteran') 
        ? 'Veterans support team' 
        : 'Globe Life support team';
      
      // If agent answered, just end
      if (dialCallStatus === 'completed') {
        res.type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Hangup/>
</Response>`);
        return;
      }
      
      // Agent didn't answer, route to fallback
      console.log(`📞 Agent unavailable, routing to ${fallbackName} at ${fallbackNumber}`);
      
      const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="alice">Your agent is currently unavailable. Connecting you to our ${fallbackName}.</Say>
  <Dial timeout="30">
    <Number>${fallbackNumber}</Number>
  </Dial>
  <Say voice="alice">We're sorry, all representatives are busy. Please call back later or leave a message after the tone.</Say>
  <Record maxLength="120" transcribe="true" transcribeCallback="/api/twilio/voicemail"/>
</Response>`;
      
      res.type('text/xml').send(twiml);
      
    } catch (error) {
      console.error('❌ Fallback error:', error);
      res.type('text/xml').send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="alice">We're experiencing technical difficulties. Please call back later.</Say>
  <Hangup/>
</Response>`);
    }
  });
  

  // ✅ 3. API endpoint for dialing leads with shared conference + HOTLEAD EARNED DEDUCTION
  app.post("/api/dial-lead", async (req, res) => {
    try {
      const { leadPhone, conference, leadId, isHotLead, agentEmail: bodyAgentEmail, agentName: bodyAgentName } = req.body;
      console.log('📞 /api/dial-lead - dialing to conf:', conference);
      
      if (!leadPhone || !conference) {
        return res.status(400).json({ error: 'leadPhone and conference are required' });
      }

      // CRITICAL: Agent attribution - prefer explicit body (so client can pass it), then session
      const agentEmail = (bodyAgentEmail && String(bodyAgentEmail).includes('@')) ? String(bodyAgentEmail).trim().toLowerCase() : (req.user?.email || 'unknown@aoglobelife.com');
      const agentName = (bodyAgentName && String(bodyAgentName).trim()) || req.user?.name || 'Unknown Agent';
      
      // 🔥 FIX: REMOVED lead assignment at dial start - leads are ONLY assigned after 110 seconds
      // Assignment happens via /api/hotleads/assign-to-agent endpoint which has 110-second validation
      // This prevents leads from being assigned on every call before duration check
      
      // 🔥 REMOVED: Zapier webhook at dial start - NO webhooks until 110 seconds
      // Webhook ONLY sent when /api/hotleads/assign-to-agent is called at 110 seconds
      // This prevents leads from being sent to Zapier before the 110-second duration requirement
      if (isHotLead && leadId) {
        // Only track last_contacted - NO webhook until 110 seconds
        try {
          const { error: supabaseError } = await masterleadClient.from('masterlead')
            .update({ 
              last_contacted: new Date().toISOString()
            })
            .eq('taalk_lead_id', leadId)
            .eq('cn_email', agentEmail);
            
          if (supabaseError) {
            console.error('❌ Failed to update hotlead metadata:', supabaseError);
          } else {
            console.log('✅ Hotlead last_contacted timestamp updated (NO webhook - waiting for 110s assignment)');
          }
        } catch (updateError) {
          console.error('❌ Error updating hotlead metadata:', updateError);
        }
      }
      
      // Track outbound dial for weekly usage stats
      try {
        await usageTracker.trackDialMade(agentEmail, 0);
        console.log(`✅ Dial tracked for ${agentEmail}`);
      } catch (err) {
        console.error('❌ CRITICAL: Failed to track dial:', err);
        // Don't block the call, but log the error
      }
      
      // FORCE RECORDING: REST record: true + lead-join TwiML has Dial record="record-from-answer"
      const call = await twilioClient.calls.create({
        url: `${PRODUCTION_BASE_URL}/lead-join?conf=${encodeURIComponent(conference)}`,
        to: leadPhone,
        from: process.env.TWILIO_CALLER_ID || '+12035896464',
        method: 'GET',
        record: true,
        recordingStatusCallback: `${PRODUCTION_BASE_URL}/api/twilio/recording-status`,
        recordingStatusCallbackMethod: 'POST',
        statusCallback: `${PRODUCTION_BASE_URL}/api/twilio/call-status?agentEmail=${encodeURIComponent(agentEmail || '')}`,
        statusCallbackEvent: ['initiated', 'ringing', 'answered', 'completed'],
        statusCallbackMethod: 'POST',
        metadata: {
          agent_email: agentEmail,
          agent_name: agentName,
          call_source: 'agent_initiated',
          conference_name: conference,
          lead_phone: leadPhone,
          lead_id: leadId,
          is_hotlead: isHotLead ? 'true' : 'false',
          timestamp: new Date().toISOString()
        }
      });

      console.log('📞 Lead call initiated:', call.sid);

      // DIRECT DIAL COUNT — fire-and-forget, independent of webhook chain
      // Tested: atomic upsert, race-safe, 82ms avg latency (test-dial-counter.cjs)
      void incrementAgentDailyStat(agentEmail, 'dial').catch(e =>
        console.warn(`⚠️ Direct dial count failed (non-blocking): ${e?.message}`)
      );

      // CRITICAL: Pre-insert twilio_call_logs with agent info so call-status webhook never loses attribution
      // Never persist cnsysop/unknown/system as owner
      const BAD_OWNER_API = ['cnsysop@aoglobelife.com', 'unknown@aoglobelife.com', 'system@aoglobelife.com', 'unknown', ''];
      const isBadOwnerApi = (e: string | null | undefined) => !e || !e.includes('@') || BAD_OWNER_API.includes((e || '').trim().toLowerCase());
      const ownerForLog = agentEmail && !isBadOwnerApi(agentEmail) ? agentEmail : null;
      try {
        const preInsertPayload = {
          twilio_call_sid: call.sid,
          owner_email: ownerForLog,
          agent_identity: ownerForLog ? `client:${ownerForLog}` : null,
          from_number: process.env.TWILIO_CALLER_ID || null,
          to_number: leadPhone,
          call_direction: 'outbound',
          call_status: 'initiated',
          call_started_at: new Date().toISOString(),
          call_source: 'api_dial_lead',
          metadata: {
            agent_email: agentEmail,
            agent_name: agentName,
            conference_name: conference,
            lead_phone: leadPhone,
            lead_id: leadId || null,
            call_created_at: new Date().toISOString(),
          },
        };
        try {
          await upsertTwilioCallLogLocal(preInsertPayload);
        } catch (localErr) {
          console.warn('⚠️ Local pre-insert twilio_call_logs failed:', (localErr as Error)?.message);
        }
        console.log('✅ Pre-inserted twilio_call_logs with owner_email:', ownerForLog ?? '(null, avoided bad owner)');
      } catch (preInsertErr: any) {
        console.warn('⚠️ Pre-insert twilio_call_logs failed (webhook will still log):', preInsertErr?.message);
      }
      
      // 🔥 INSERT INTO call_connector_tracker for webhook tracking
      if (leadId) {
        try {
          const { data: leadData } = await masterleadClient.from('masterlead')
            .select('id, first_name, last_name, phone, state')
            .eq('id', leadId)
            .single();
          
          if (leadData) {
            await supabaseAdmin
              .from('call_connector_tracker')
              .insert({
                lead_id: leadData.id,
                agent_email: agentEmail,
                agent_name: agentName,
                call_sid: call.sid,
                lead_phone: leadPhone,
                lead_name: `${leadData.first_name} ${leadData.last_name}`,
                lead_state: leadData.state,
                conference_name: conference,
                status: 'dialing',
                reached: false,
                created_at: new Date().toISOString()
              });
            
            console.log(`✅ Call tracked in database: ${call.sid}`);
          }
        } catch (trackError) {
          console.error('⚠️ Failed to track call in database:', trackError);
          // Don't fail the call if tracking fails
        }
      }
      
      res.json({ 
        success: true, 
        callSid: call.sid,
        hotleadDeductionTriggered: isHotLead || false
      });
      
    } catch (error) {
      console.error('❌ Dial lead error:', error);
      res.status(500).json({ error: 'Failed to dial lead' });
    }
  });

