  // Check if user needs to be blocked due to too many pending AOI reports (NO CACHE)
  app.get("/api/aoi-reports/check-blocking/:email", async (req, res) => {
    // AOI Reports disabled — return unblocked instantly (was taking 3-5s per call)
    return res.json({
      hasPendingReports: false,
      pendingCount: 0,
      hasOverdueAppointments: false,
      overdueAppointmentsCount: 0,
      bookedCallsWithoutAppointments: 0,
      mustResolveReports: false,
    });
    try {
      const userEmail = req.params.email;
      const BLOCKING_THRESHOLD = -8; // Allow negative balance before blocking (grace period)
      
      console.log(`🚨 AOI Reports: Checking blocking status for ${userEmail}...`);
      
      // Get user's associate ID for AOI reports filtering 
      let userAssociateId = null;
      try {
        const { data: customerData } = await supabaseAdmin
          .from('customers')
          .select('associate_id')
          .eq('company_email', userEmail)
          .single();
        userAssociateId = customerData?.associate_id?.toString();
        console.log(`🔍 Found associate ID for ${userEmail}: ${userAssociateId}`);
      } catch (error) {
        console.log('⚠️ Could not find associate ID for AOI reports blocking check');
      }
      
      // Resolve finalAgentId (customers query already done above; cache handles the 7-fallback chain)
      const finalAgentId = userAssociateId || (await resolveAssociateIdForZapier(userEmail));
      const normalizedEmail = (userEmail || '').toLowerCase().trim();
      const twentyFourHoursAgo = new Date();
      twentyFourHoursAgo.setHours(twentyFourHoursAgo.getHours() - 24);

      // Run all independent queries in parallel
      const [vdpResult, masterleadPendingResult, bookedCallsResult, overdueResult] = await Promise.all([
        // 1) VDP calls needing closure (needs finalAgentId)
        finalAgentId != null
          ? supabaseAdmin.from('vdp_calls').select('id').eq('agent', String(finalAgentId)).is('cnresolution', null)
          : Promise.resolve({ data: [], error: null }),

        // 2) Masterlead calls needing follow-up
        masterleadClient.from('masterlead').select('id').eq('cn_email', userEmail)
          .in('cnresolution', ['booked', 'appointment_set', 'callback_requested']),

        // 3) Booked calls (for appointment cross-check)
        masterleadClient.from('masterlead')
          .select('id, first_name, last_name, phone, cnresolution, created_at')
          .eq('cn_email', normalizedEmail).eq('cnresolution', 'booked'),

        // 4) Overdue appointments (scheduled 24+ hrs ago, still open)
        supabaseAdmin.from('appointments')
          .select('id, start_time, status, lead_phone, lead_name')
          .eq('agent_email', userEmail)
          .in('status', ['scheduled', 'confirmed'])
          .lte('start_time', twentyFourHoursAgo.toISOString()),
      ]);

      // Process VDP + masterlead pending counts
      let totalPendingAOIReports = 0;
      if (finalAgentId != null) {
        const vdpCount = vdpResult.data?.length || 0;
        const masterleadCount = masterleadPendingResult.data?.length || 0;
        totalPendingAOIReports = vdpCount + masterleadCount;
        console.log(`🔍 AOI Reports blocking check for ${userEmail}: VDP=${vdpCount}, Masterlead=${masterleadCount}, Total=${totalPendingAOIReports}`);
      }

      // Process overdue appointments
      let hasOverdueAppointments = false;
      let overdueAppointmentsList: any[] = [];
      if (!overdueResult.error) {
        overdueAppointmentsList = overdueResult.data || [];
        hasOverdueAppointments = overdueAppointmentsList.length > 0;
        if (hasOverdueAppointments) {
          console.log(`⏰ Found ${overdueAppointmentsList.length} appointment(s) scheduled 24+ hours ago for ${userEmail} that need resolution`);
        }
      } else {
        console.error('❌ Error checking overdue appointments:', overdueResult.error);
      }

      // Process booked calls — cross-check against future appointments (sequential: needs bookedCalls first)
      let bookedCallsWithoutAppointments = 0;
      let bookedCallsList: any[] = [];
      const bookedCalls = bookedCallsResult.data || [];
      console.log(`📅 Query returned ${bookedCalls.length} booked call(s)`);

      if (bookedCalls.length > 0) {
        let appointmentPhones = new Set<string>();
        try {
          const { data: appointments, error: aptError } = await supabaseAdmin
            .from('appointments')
            .select('lead_phone')
            .eq('agent_email', normalizedEmail)
            .gte('start_time', new Date().toISOString());
          if (!aptError) {
            appointmentPhones = new Set((appointments || []).map((apt: any) => apt.lead_phone?.replace(/\D/g, '') || ''));
            console.log(`📅 Found ${appointmentPhones.size} future appointment(s) with phone numbers`);
          }
        } catch (error: any) {
          console.log(`⚠️  Error checking appointments (assuming no appointments): ${error.message}`);
        }

        bookedCallsList = bookedCalls.filter((call: any) => {
          const callPhone = call.phone?.replace(/\D/g, '') || '';
          const hasAppointment = appointmentPhones.has(callPhone);
          if (!hasAppointment) {
            console.log(`  - Booked call ${call.id} (${call.first_name} ${call.last_name}, ${call.phone}) has NO appointment`);
          }
          return !hasAppointment;
        });
        bookedCallsWithoutAppointments = bookedCallsList.length;
      }
      
      // Force blocking if:
      // 1. There are "booked" calls without appointments scheduled, OR
      // 2. There are appointments scheduled 24+ hours ago that need results
      const mustResolveReports = bookedCallsWithoutAppointments > 0 || hasOverdueAppointments;
      
      console.log(`🚨 Blocking decision for ${userEmail}:`);
      console.log(`   - Booked calls without appointments: ${bookedCallsWithoutAppointments}`);
      console.log(`   - Overdue appointments: ${overdueAppointmentsList.length}`);
      console.log(`   - Must resolve reports: ${mustResolveReports}`);
      
      const blockingStatus = {
        hasPendingReports: totalPendingAOIReports > 0,
        pendingCount: totalPendingAOIReports,
        mustResolveReports: mustResolveReports,
        hasOverdueAppointments: hasOverdueAppointments,
        overdueAppointmentsCount: overdueAppointmentsList.length,
        bookedCallsWithoutAppointments: bookedCallsWithoutAppointments,
        threshold: BLOCKING_THRESHOLD
      };
      
      console.log(`🚨 AOI Reports blocking status for ${userEmail}:`, JSON.stringify(blockingStatus, null, 2));
      console.log(`🚨 Sending response with bookedCallsWithoutAppointments: ${bookedCallsWithoutAppointments}`);
      res.json(blockingStatus);
      
    } catch (error) {
      console.error('❌ AOI Reports blocking check error:', error);
      console.error('   Error stack:', error instanceof Error ? error.stack : 'No stack');
      res.status(500).json({
        hasPendingReports: false,
        pendingCount: 0,
        mustResolveReports: false,
        hasOverdueAppointments: false,
        overdueAppointmentsCount: 0,
        bookedCallsWithoutAppointments: 0,
        threshold: 0
      });
    }
  });

