  app.put("/api/aoi-followups/complete/:followupId", async (req, res) => {
    try {
      const { followupId } = req.params;
      const { finalOutcome, finalNotes, completedBy } = req.body;
      
      console.log(`✅ Completing follow-up ${followupId} with outcome: ${finalOutcome}`);
      
      // Update the follow-up record
      const updatedFollowup = await storage.db
        .update(aoiFollowups)
        .set({
          finalOutcome,
          finalNotes,
          completedAt: new Date(),
          completedBy,
          status: 'completed'
        })
        .where(eq(aoiFollowups.id, parseInt(followupId)))
        .returning();
      
      if (updatedFollowup.length === 0) {
        return res.status(404).json({ error: 'Follow-up not found' });
      }
      
      const followup = updatedFollowup[0];
      
      // Update the related VDP call with final outcome
      if (followup.vdpCallId) {
        const { error: vdpError } = await supabaseAdmin
          .from('vdp_calls')
          .update({
            final_outcome: finalOutcome,
            final_outcome_notes: finalNotes,
            final_outcome_at: new Date().toISOString()
          })
          .eq('id', followup.vdpCallId);
        
        if (vdpError) {
          console.warn(`⚠️ Warning: Could not update VDP call final outcome:`, vdpError);
        }
      }
      
      // Update masterleads with final outcome
      if (followup.taalk_leadid) {
        const { error: masterError } = await supabaseAdmin
          .from('masterleads')
          .update({
            final_outcome: finalOutcome,
            final_outcome_notes: finalNotes,
            updated_at: new Date().toISOString()
          })
          .eq('taalk_lead_id', followup.taalk_leadid);
        
        if (masterError) {
          console.warn(`⚠️ Warning: Could not update masterleads final outcome:`, masterError);
        }
      }
      
      console.log(`✅ Follow-up ${followupId} completed successfully with outcome: ${finalOutcome}`);
      res.json({ 
        success: true, 
        followup: updatedFollowup[0],
        message: 'Follow-up completed and final outcome recorded'
      });
      
    } catch (error) {
      console.error('❌ Error completing follow-up:', error);
      res.status(500).json({ error: 'Failed to complete follow-up' });
    }
  });

