  // Backfill script to fix owner_email for existing calls
  app.post("/api/twilio-calls/backfill-owner-email", async (req, res) => {
    try {
      console.log(`🔧 Backfill endpoint called`);
      console.log(`📥 Request body:`, JSON.stringify(req.body));
      
      if (!supabaseAdmin) {
        console.error('❌ supabaseAdmin is null!');
        return res.status(500).json({ error: 'Database not configured - supabaseAdmin is null' });
      }

      const { limit = 10000, dryRun = false, batchSize = 100 } = req.body || {};
      
      console.log(`🔧 Starting backfill of owner_email for calls with system@aoglobelife.com`);
      console.log(`📊 Limit: ${limit}, Dry Run: ${dryRun}, Batch Size: ${batchSize}`);

      // Get all calls with system@aoglobelife.com as owner_email
      console.log(`🔍 Querying twilio_call_logs for system@aoglobelife.com...`);
      const { data: systemCalls, error: fetchError, count } = await supabaseAdmin
        .from('twilio_call_logs')
        .select('twilio_call_sid, from_number, to_number, call_started_at, call_ended_at, metadata, call_source, agent_identity', { count: 'exact' })
        .eq('owner_email', 'system@aoglobelife.com')
        .order('call_started_at', { ascending: false })
        .limit(limit);

      console.log(`📊 Query result: ${systemCalls?.length || 0} calls found, count: ${count}, error: ${fetchError?.message || 'none'}`);

      if (fetchError) {
        console.error('❌ Fetch error details:', fetchError);
        throw new Error(`Failed to fetch calls: ${fetchError.message} (code: ${fetchError.code})`);
      }

      if (!systemCalls || systemCalls.length === 0) {
        return res.json({
          success: true,
          message: 'No calls found with system@aoglobelife.com',
          updated: 0,
          skipped: 0,
          errors: 0,
          total: 0
        });
      }

      console.log(`📞 Found ${systemCalls.length} calls to process`);

      let updated = 0;
      let skipped = 0;
      let errors = 0;
      const updates: Array<{ callSid: string; oldEmail: string; newEmail: string; source: string }> = [];

      // Process in batches to avoid overwhelming the database
      for (let i = 0; i < systemCalls.length; i += batchSize) {
        const batch = systemCalls.slice(i, i + batchSize);
        console.log(`\n📦 Processing batch ${Math.floor(i / batchSize) + 1}/${Math.ceil(systemCalls.length / batchSize)} (${batch.length} calls)`);

        for (const call of batch) {
          try {
            let newOwnerEmail: string | null = null;
            let source = 'unknown';

            // PRIORITY 1: Extract from agent_identity if it's a client: call
            if (!newOwnerEmail && call.agent_identity && call.agent_identity.startsWith('client:')) {
              const extractedEmail = call.agent_identity.replace('client:', '');
              if (extractedEmail && extractedEmail.includes('@')) {
                newOwnerEmail = extractedEmail;
                source = 'agent_identity_client_prefix';
              }
            }

            // PRIORITY 2: Extract from From field if it's a client: call
            if (!newOwnerEmail && call.from_number && call.from_number.startsWith('client:')) {
              const extractedEmail = call.from_number.replace('client:', '');
              if (extractedEmail && extractedEmail.includes('@')) {
                newOwnerEmail = extractedEmail;
                source = 'from_number_client_prefix';
              }
            }

            // PRIORITY 3: Check metadata if it exists
            if (!newOwnerEmail && call.metadata) {
              try {
                const metadata = typeof call.metadata === 'string' ? JSON.parse(call.metadata) : call.metadata;
                if (metadata.agent_email && metadata.agent_email !== 'unknown' && metadata.agent_email !== 'system@aoglobelife.com' && metadata.agent_email.includes('@')) {
                  newOwnerEmail = metadata.agent_email;
                  source = 'metadata';
                }
              } catch (e) {
                // Metadata parse error, skip
              }
            }

            // PRIORITY 4: Check outbound_call_history table
            if (!newOwnerEmail) {
              try {
                const { data: outboundCall, error: outboundError } = await supabaseAdmin
                  .from('outbound_call_history')
                  .select('agent_email')
                  .eq('call_sid', call.twilio_call_sid)
                  .order('created_at', { ascending: false })
                  .limit(1)
                  .maybeSingle();

                if (outboundError && outboundError.code !== 'PGRST116') {
                  // PGRST116 = no rows returned, which is fine
                  console.warn(`⚠️ Error checking outbound_call_history for ${call.twilio_call_sid}:`, outboundError.message);
                }

                if (outboundCall?.agent_email && outboundCall.agent_email.includes('@')) {
                  newOwnerEmail = outboundCall.agent_email;
                  source = 'outbound_call_history';
                }
              } catch (e: any) {
                // Table might not exist, skip
              }
            }

            // PRIORITY 5: Check call_connector_tracker table
            if (!newOwnerEmail) {
              try {
                const { data: trackerCall, error: trackerError } = await supabaseAdmin
                  .from('call_connector_tracker')
                  .select('agent_email')
                  .eq('call_sid', call.twilio_call_sid)
                  .order('created_at', { ascending: false })
                  .limit(1)
                  .maybeSingle();

                if (trackerError && trackerError.code !== 'PGRST116') {
                  console.warn(`⚠️ Error checking call_connector_tracker for ${call.twilio_call_sid}:`, trackerError.message);
                }

                if (trackerCall?.agent_email && trackerCall.agent_email.includes('@')) {
                  newOwnerEmail = trackerCall.agent_email;
                  source = 'call_connector_tracker';
                }
              } catch (e: any) {
                // Table might not exist, skip
              }
            }

            // PRIORITY 6: Check call_log table
            if (!newOwnerEmail) {
              try {
                const { data: callLog, error: callLogError } = await supabaseAdmin
                  .from('call_log')
                  .select('agent_email')
                  .eq('call_sid', call.twilio_call_sid)
                  .order('started_at', { ascending: false })
                  .limit(1)
                  .maybeSingle();

                if (callLogError && callLogError.code !== 'PGRST116') {
                  console.warn(`⚠️ Error checking call_log for ${call.twilio_call_sid}:`, callLogError.message);
                }

                if (callLog?.agent_email && callLog.agent_email.includes('@')) {
                  newOwnerEmail = callLog.agent_email;
                  source = 'call_log';
                }
              } catch (e: any) {
                // Table might not exist, skip
              }
            }

            // PRIORITY 7: Try to match by phone number and date range (find other calls from same number around same time)
            if (!newOwnerEmail && call.from_number && call.call_started_at) {
              const callDate = new Date(call.call_started_at);
              const startRange = new Date(callDate.getTime() - 5 * 60 * 1000); // 5 minutes before
              const endRange = new Date(callDate.getTime() + 5 * 60 * 1000); // 5 minutes after

              const { data: similarCalls } = await supabaseAdmin
                .from('twilio_call_logs')
                .select('owner_email')
                .eq('from_number', call.from_number)
                .neq('owner_email', 'system@aoglobelife.com')
                .gte('call_started_at', startRange.toISOString())
                .lte('call_started_at', endRange.toISOString())
                .limit(1)
                .maybeSingle();

              if (similarCalls?.owner_email && similarCalls.owner_email.includes('@')) {
                newOwnerEmail = similarCalls.owner_email;
                source = 'similar_call_by_phone_time';
              }
            }

            if (newOwnerEmail && newOwnerEmail !== 'system@aoglobelife.com' && newOwnerEmail.includes('@')) {
              if (!dryRun) {
                const { error: updateError, data: updateData } = await supabaseAdmin
                  .from('twilio_call_logs')
                  .update({
                    owner_email: newOwnerEmail,
                    agent_identity: newOwnerEmail,
                    updated_at: new Date().toISOString()
                  })
                  .eq('twilio_call_sid', call.twilio_call_sid)
                  .select();

                if (updateError) {
                  console.error(`❌ Error updating ${call.twilio_call_sid}:`, updateError);
                  console.error(`   Error details:`, JSON.stringify(updateError));
                  errors++;
                  continue;
                }

                if (!updateData || updateData.length === 0) {
                  console.warn(`⚠️ Update returned no rows for ${call.twilio_call_sid} - call may not exist`);
                  errors++;
                  continue;
                }
              }

              updates.push({
                callSid: call.twilio_call_sid,
                oldEmail: 'system@aoglobelife.com',
                newEmail: newOwnerEmail,
                source
              });
              updated++;
              
              if (updated % 10 === 0 || updated === 1) {
                console.log(`   ✅ Progress: ${updated} updated, ${skipped} skipped, ${errors} errors`);
              }
            } else {
              skipped++;
              if (skipped <= 5) {
                console.log(`   ⏭️  Skipped ${call.twilio_call_sid} - no agent email found. From: ${call.from_number}, Agent Identity: ${call.agent_identity}`);
              }
            }
          } catch (error: any) {
            console.error(`❌ Error processing ${call.twilio_call_sid}:`, error.message);
            errors++;
          }
        }
      }

      const result = {
        success: true,
        message: dryRun ? 'Dry run completed' : 'Backfill completed',
        stats: {
          total: systemCalls.length,
          updated,
          skipped,
          errors
        },
        updates: updates.slice(0, 100) // Return first 100 updates for review
      };

      console.log(`\n🎉 Backfill ${dryRun ? '(DRY RUN) ' : ''}complete!`);
      console.log(`📊 Total: ${systemCalls.length}, Updated: ${updated}, Skipped: ${skipped}, Errors: ${errors}`);
      
      if (updated > 0) {
        console.log(`\n✅ Sample updates (first 5):`);
        updates.slice(0, 5).forEach(u => {
          console.log(`   ${u.callSid.substring(0, 20)}... → ${u.newEmail} (${u.source})`);
        });
      }

      return res.json(result);
    } catch (error: any) {
      console.error('❌ Backfill error:', error);
      console.error('❌ Error stack:', error.stack);
      return res.status(500).json({
        success: false,
        error: error.message || 'Failed to backfill owner emails',
        stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
      });
    }
  });

