  // Generate Twilio Video access token
  app.post("/api/video/token", async (req, res) => {
    try {
      const { identity, roomName } = req.body;
      
      if (!identity || !roomName) {
        return res.status(400).json({ error: 'Identity and roomName required' });
      }
      
      // Create unique identities as specified
      const timestamp = Date.now().toString();
      const uniqueIdentity = identity.includes('Agent') 
        ? `Agent-${identity.replace('Agent ', '').replace(/\s+/g, '-')}-${timestamp}`
        : `${identity.replace(/\s+/g, '-')}-${timestamp}`;
      
      console.log(`🎥 Generating Twilio Video token for ${uniqueIdentity} in room ${roomName}`);
      
      // Import Twilio AccessToken
      const AccessToken = twilio.jwt.AccessToken;
      const VideoGrant = AccessToken.VideoGrant;
      
      // Create access token
      const token = new AccessToken(
        TWILIO_ACCOUNT_SID,        // Account SID (sub)
        TWILIO_API_KEY,            // API Key SID (iss)
        TWILIO_API_SECRET,         // API Secret
        { identity: uniqueIdentity }
      );
      
      // Add video grant with exact room name
      const videoGrant = new VideoGrant({
        room: roomName
      });
      token.addGrant(videoGrant);
      
      token.ttl = 10800; // 3 hours
      
      const jwtToken = token.toJwt();
      
      // Log token details as specified
      console.log(`✅ Generated Twilio Video token:`, {
        room: roomName,
        iss: TWILIO_API_KEY,      // API Key SID
        sub: TWILIO_ACCOUNT_SID,  // Account SID
        identity: uniqueIdentity
      });
      
      res.json({ token: jwtToken });
    } catch (error) {
      console.error('❌ Video token generation error:', error);
      res.status(500).json({ error: 'Failed to generate video token' });
    }
  });

