  // ===== QUALITY MANAGER SYSTEM =====
  
  // Middleware to load user context and roles
  async function loadUserContext(req: any) {
    const userEmail = req.query.userEmail || req.body.userEmail || req.headers['user-email'];
    
    if (!userEmail) {
      return { email: null, roles: [], isAdmin: false, assignedTeams: [] };
    }

    try {
      // Check if user is admin
      const isAdmin = userEmail === 'admin@aoprecheck.net'; // Adjust as needed
      
      // Check if user is Quality Manager
      const qmQuery = `
        SELECT * FROM quality_manager_roles 
        WHERE email = '${userEmail}' AND is_active = true
      `;
      const qmResult = await db.execute(sql.raw(qmQuery));
      const isQualityManager = qmResult.rows.length > 0;
      
      let assignedTeams: string[] = [];
      if (isQualityManager) {
        // Get assigned MGA teams for Quality Manager
        const teamsQuery = `
          SELECT mt.name FROM quality_manager_assignments qma
          JOIN mga_teams mt ON qma.mga_team_id = mt.id
          WHERE qma.qm_email = '${userEmail}' AND mt.is_active = true
        `;
        const teamsResult = await db.execute(sql.raw(teamsQuery));
        assignedTeams = teamsResult.rows.map((row: any) => row.name);
      }

      const roles = [];
      if (isAdmin) roles.push('ADMIN');
      if (isQualityManager) roles.push('QUALITY_MANAGER');
      
      return {
        email: userEmail,
        roles,
        isAdmin,
        isQualityManager,
        assignedTeams
      };
    } catch (error) {
      console.error('Error loading user context:', error);
      return { email: userEmail, roles: [], isAdmin: false, assignedTeams: [] };
    }
  }

  // Helper function to apply team-based data scoping
  function applyTeamScope(baseQuery: string, userContext: any, teamColumn: string) {
    if (userContext.isAdmin) {
      return baseQuery; // Admins see everything
    }
    
    if (userContext.isQualityManager && userContext.assignedTeams.length > 0) {
      const teamFilter = userContext.assignedTeams.map((team: string) => `'${team}'`).join(',');
      return `${baseQuery} AND ${teamColumn} IN (${teamFilter})`;
    }
    
    return `${baseQuery} AND 1=0`; // No access if no teams assigned
  }

