  // Get all quality managers with their assigned teams
  app.get('/api/admin/quality-managers', async (req, res) => {
    try {
      const userContext = await loadUserContext(req);
      
      if (!userContext.isAdmin) {
        return res.status(403).json({ error: 'Admin access required' });
      }

      const query = `
        SELECT 
          qmr.email,
          qmr.is_active,
          qmr.assigned_by,
          qmr.created_at,
          COALESCE(
            JSON_AGG(
              CASE WHEN mt.id IS NOT NULL 
              THEN JSON_BUILD_OBJECT('id', mt.id, 'name', mt.name) 
              END
            ) FILTER (WHERE mt.id IS NOT NULL), 
            '[]'::json
          ) as assigned_teams
        FROM quality_manager_roles qmr
        LEFT JOIN quality_manager_assignments qma ON qmr.email = qma.qm_email
        LEFT JOIN mga_teams mt ON qma.mga_team_id = mt.id AND mt.is_active = true
        WHERE qmr.is_active = true
        GROUP BY qmr.email, qmr.is_active, qmr.assigned_by, qmr.created_at
        ORDER BY qmr.created_at DESC
      `;
      
      const result = await db.execute(sql.raw(query));
      res.json({ success: true, qualityManagers: result.rows });
      
    } catch (error) {
      console.error('Error fetching quality managers:', error);
      res.status(500).json({ error: 'Failed to fetch quality managers' });
    }
  });

