  // ===== DETAILED APPOINTMENT OUTCOMES ANALYTICS =====
  app.get('/api/accountability/outcomes-analytics', async (req, res) => {
    try {
      const { agentEmail, dateRange } = req.query;
      
      if (!agentEmail) {
        return res.status(400).json({ error: 'Agent email is required' });
      }
      
      let dateFilter = '';
      if (dateRange === 'week') {
        dateFilter = "AND da.accountability_date >= CURRENT_DATE - INTERVAL '7 days'";
      } else if (dateRange === 'month') {
        dateFilter = "AND da.accountability_date >= CURRENT_DATE - INTERVAL '30 days'";
      } else if (dateRange === 'quarter') {
        dateFilter = "AND da.accountability_date >= CURRENT_DATE - INTERVAL '90 days'";
      }
      
      // Get detailed appointment outcomes (individual records)
      const outcomesQuery = `
        SELECT 
          ao.outcome,
          ao.sale_amount,
          da.accountability_date,
          ao.appointment_title,
          ao.lead_name,
          ao.notes,
          ao.reported_at
        FROM appointment_outcomes ao
        JOIN daily_accountability da ON ao.accountability_id = da.id
        WHERE ao.agent_email = '${agentEmail}'
        ${dateFilter}
        ORDER BY ao.reported_at DESC
      `;
      
      const outcomesResult = await db.execute(sql.raw(outcomesQuery));
      const outcomes = outcomesResult.rows;
      
      // Get summary by outcome type
      const summaryQuery = `
        SELECT 
          ao.outcome,
          COUNT(*) as count,
          SUM(ao.sale_amount) as total_revenue,
          AVG(ao.sale_amount) as avg_sale_amount
        FROM appointment_outcomes ao
        JOIN daily_accountability da ON ao.accountability_id = da.id
        WHERE ao.agent_email = '${agentEmail}'
        ${dateFilter}
        GROUP BY ao.outcome
        ORDER BY count DESC
      `;
      
      const summaryResult = await db.execute(sql.raw(summaryQuery));
      const summary = summaryResult.rows;
      
      res.json({
        success: true,
        agentEmail,
        dateRange: dateRange || 'all',
        totalOutcomes: outcomes.length,
        outcomes,
        summary
      });
      
    } catch (error) {
      console.error('❌ Outcomes analytics error:', error);
      res.status(500).json({ error: 'Failed to fetch outcomes analytics' });
    }
  });

  // ===== WEEKLY SALES TOTAL FOR AOI ALP =====
  app.get('/api/accountability/weekly-sales-total', async (req, res) => {
    try {
      const { agentEmail } = req.query;
      
      if (!agentEmail) {
        return res.status(400).json({ error: 'Agent email is required' });
      }
      
      // Calculate this week's sales total (Monday to Sunday)
      const weeklyTotalQuery = `
        SELECT 
          COALESCE(SUM(total_revenue), 0) as weekly_total,
          COUNT(*) as reports_count,
          SUM(total_sales) as total_sales_count,
          SUM(plus_leads_collected) as plus_leads_total
        FROM daily_accountability
        WHERE agent_email = '${agentEmail}'
        AND accountability_date >= DATE_TRUNC('week', CURRENT_DATE)
        AND accountability_date <= CURRENT_DATE
      `;
      
      const weeklyResult = await db.execute(sql.raw(weeklyTotalQuery));
      const weeklyData = weeklyResult.rows[0];
      
      // Also get individual appointment outcomes for this week
      const detailedOutcomesQuery = `
        SELECT 
          SUM(ao.sale_amount) as detailed_sales_total,
          COUNT(CASE WHEN ao.outcome = 'sale' THEN 1 END) as detailed_sales_count
        FROM appointment_outcomes ao
        JOIN daily_accountability da ON ao.accountability_id = da.id
        WHERE ao.agent_email = '${agentEmail}'
        AND da.accountability_date >= DATE_TRUNC('week', CURRENT_DATE)
        AND da.accountability_date <= CURRENT_DATE
      `;
      
      const detailedResult = await db.execute(sql.raw(detailedOutcomesQuery));
      const detailedData = detailedResult.rows[0];
      
      res.json({
        success: true,
        agentEmail,
        weeklyTotal: Number(weeklyData?.weekly_total || 0),
        reportsCount: Number(weeklyData?.reports_count || 0),
        salesCount: Number(weeklyData?.total_sales_count || 0),
        plusLeadsTotal: Number(weeklyData?.plus_leads_total || 0),
        detailedSalesTotal: Number(detailedData?.detailed_sales_total || 0),
        detailedSalesCount: Number(detailedData?.detailed_sales_count || 0),
        weekStart: new Date().toISOString().split('T')[0],
        lastUpdated: new Date().toISOString()
      });
      
    } catch (error) {
      console.error('❌ Weekly sales total error:', error);
      res.status(500).json({ error: 'Failed to fetch weekly sales total' });
    }
  });

  // Get comprehensive weekly stats for AOMeet page
  app.get('/api/aoi-meet/weekly-stats', async (req, res) => {
    try {
      const { agentEmail } = req.query;
      
      if (!agentEmail) {
        return res.status(400).json({ error: 'Agent email is required' });
      }

      // Calculate week start (Sunday) and week end (Saturday)
      const now = new Date();
      const weekStart = new Date(now);
      weekStart.setDate(now.getDate() - now.getDay()); // Start of week (Sunday)
      weekStart.setHours(0, 0, 0, 0);
      
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 6); // End of week (Saturday)
      weekEnd.setHours(23, 59, 59, 999);

      // 1. Get appointments count from Supabase appointments table
      let appointments = 0;
      if (supabaseAdmin) {
        try {
          const { count: appointmentsCount, error: appointmentsError } = await supabaseAdmin
            .from('appointments')
            .select('*', { count: 'exact', head: true })
            .eq('agent_email', agentEmail)
            .gte('created_at', weekStart.toISOString())
            .lte('created_at', weekEnd.toISOString());
          
          if (!appointmentsError && appointmentsCount !== null) {
            appointments = appointmentsCount;
          }
        } catch (err) {
          console.error('Error fetching appointments count:', err);
        }
      }
      
      // 2. Get presentations count (any resolved call from masterlead this week)
      const presentationsQuery = `
        SELECT COUNT(*) as count
        FROM masterlead
        WHERE cn_email = '${agentEmail}'
        AND cnresolution IS NOT NULL
        AND cnresolution != ''
        AND updated_at >= '${weekStart.toISOString()}'
        AND updated_at <= '${weekEnd.toISOString()}'
      `;
      
      // 3. Get sales count and ALP total (sales from masterlead)
      const salesQuery = `
        SELECT 
          COUNT(*) as count,
          COALESCE(SUM(
            CASE 
              WHEN ALP IS NOT NULL AND ALP::text != '' THEN
                CAST(ALP AS DECIMAL)
              WHEN disposition_notes LIKE '%ALP: $%' THEN
                CAST(REGEXP_REPLACE(SUBSTRING(disposition_notes FROM 'ALP: \\$([0-9,]+)'), ',', '', 'g') AS DECIMAL)
              ELSE 0
            END
          ), 0) as alp_total
        FROM masterlead
        WHERE cn_email = '${agentEmail}'
        AND (cnresolution = 'SALE' OR cnresolution = 'sale' OR LOWER(cnresolution) = 'sale')
        AND updated_at >= '${weekStart.toISOString()}'
        AND updated_at <= '${weekEnd.toISOString()}'
      `;

      const [presentationsResult, salesResult] = await Promise.all([
        db.execute(sql.raw(presentationsQuery)),
        db.execute(sql.raw(salesQuery))
      ]);

      const presentations = Number(presentationsResult.rows[0]?.count || 0);
      const sales = Number(salesResult.rows[0]?.count || 0);
      const alp = Math.round(Number(salesResult.rows[0]?.alp_total || 0));

      res.json({
        success: true,
        appointments,
        presentations,
        sales,
        alp,
        weekStart: weekStart.toISOString(),
        weekEnd: weekEnd.toISOString()
      });
      
    } catch (error) {
      console.error('❌ Weekly stats error:', error);
      res.status(500).json({ error: 'Failed to fetch weekly stats' });
    }
  });

  // CCPro Rank API endpoint
  app.get('/api/ccpro/rank', async (req, res) => {
    try {
      if (String(process.env.LEAD_ONLY_MODE || "").toLowerCase() === "true") {
        return res.status(503).json({
          success: false,
          error: "LEAD_ONLY_MODE_ENABLED",
          message: "CCPro rank is disabled while lead-only mode is active.",
        });
      }
      // Try multiple methods to get user email
      const sessionUser = (req.session as any)?.user;
      const queryEmail = req.query.agentEmail as string;
      const agentEmail = queryEmail || sessionUser?.email || (req as any)?.user?.email;
      
      if (!agentEmail) {
        console.error('❌ CCPro rank: No agent email found', {
          hasSession: !!req.session,
          sessionUser: sessionUser || 'none',
          queryEmail: queryEmail || 'none',
          reqUser: (req as any)?.user || 'none'
        });
        return res.status(400).json({ error: 'Agent email is required' });
      }
      
      const normalizedEmail = agentEmail.toLowerCase().trim();
      console.log(`🔍 CCPro rank request for: ${normalizedEmail}`);

      const requestHost = String(req.headers?.host || '').toLowerCase();
      const isDataHost =
        requestHost.includes('aoirail-data-production.up.railway.app') ||
        requestHost.includes('aoirail-data-');
      if (!isDataHost) {
        const dataBaseUrl = getAoirailDataServiceBaseUrl() || "https://aoirail-data-production.up.railway.app";
        const proxyUrl = `${dataBaseUrl}/api/ccpro/rank?agentEmail=${encodeURIComponent(normalizedEmail)}`;
        try {
          const proxyResp = await fetch(proxyUrl, {
            method: 'GET',
            signal: AbortSignal.timeout(10_000),
          });
          const proxyText = await proxyResp.text();
          res.status(proxyResp.status);
          res.setHeader('Content-Type', proxyResp.headers.get('content-type') || 'application/json');
          return res.send(proxyText);
        } catch (proxyErr: any) {
          console.warn('⚠️ CCPro rank proxy to data service failed:', proxyErr?.message || proxyErr);
          return res.json({
            rank: 'gold',
            weeklyALP: 0,
            rolling21DayALP: 0,
            averageWeeklyALP: 0,
            leadMix: { tier1: 10, tier2: 50, tier3: 40 },
            calculatedAt: new Date().toISOString(),
            progressToNext: 0,
            currentTier: {
              id: 'gold',
              name: 'Gold',
              threshold: 0,
              description: 'Default rank while production rank service is unavailable.',
              advantages: [],
            },
            allTiers: [],
            source: 'fallback_rank_proxy_failed',
          });
        }
      }
      
      const { getCCProRankForEmail } = await import('./ccpro-rank-service');
      const rankData = await getCCProRankForEmail(normalizedEmail);
      
      if (!rankData) {
        console.warn(`⚠️ CCPro rank: No rank data returned for ${normalizedEmail}`);
        return res.status(404).json({ error: 'Rank data not found' });
      }
      
      console.log(`✅ CCPro rank for ${normalizedEmail}: ${rankData.rank} (ALP: $${rankData.weeklyALP})`);
      res.json(rankData);
    } catch (error: any) {
      console.error('❌ CCPro rank error:', error);
      res.status(500).json({ error: 'Failed to fetch rank', details: error.message });
    }
  });

  // Agent Dashboard API routes - REAL DATA FOR TODAY ONLY
  app.get("/api/dashboard/agent-stats", async (req, res) => {
    try {
      const userEmail = req.query.userEmail as string || (req.session as any)?.user?.email;
      if (!userEmail || !String(userEmail).includes('@')) {
        return res.status(401).json({ error: 'Login required' });
      }
      console.log(`📊 Getting TODAY's dashboard stats for: ${userEmail}`);
      
      // Get user credits
      let creditsRemaining = 0;
      try {
        const userCredits = await connectnowService.getUserCredits(userEmail);
        creditsRemaining = (userCredits as any)?.credits_remaining || (userCredits as any)?.creditsRemaining || 0;
      } catch (error) {
        console.log('Could not fetch user credits for dashboard');
      }

      // Query TODAY's real calling stats from war_connects
      const todayConnectsQuery = `
        SELECT 
          COUNT(*) as total_connects_today,
          COUNT(CASE WHEN duration >= 45 THEN 1 END) as reached_today,
          COUNT(CASE WHEN immediate_outcome = 'appointment' OR connect_type = 'appointment' OR immediate_outcome = 'booked' THEN 1 END) as booked_today,
          AVG(CASE WHEN duration > 0 THEN duration END) as avg_call_duration
        FROM war_connects 
        WHERE agent_email = '${userEmail}' 
        AND DATE(connect_date) = CURRENT_DATE
      `;

      // Query TODAY's appointments from the appointments table
      const todayAppointmentsQuery = `
        SELECT 
          COUNT(*) as appointments_today,
          COUNT(*) as total_appointments_all_time
        FROM appointments 
        WHERE agent_email = '${userEmail}' 
        AND DATE(created_at) = CURRENT_DATE
      `;

      // Query TODAY's outbound call history
      const todayCallsQuery = `
        SELECT 
          COUNT(*) as outbound_calls_today,
          COUNT(CASE WHEN call_status = 'completed' THEN 1 END) as completed_calls_today
        FROM outbound_call_history 
        WHERE agent_email = '${userEmail}' 
        AND DATE(created_at) = CURRENT_DATE
      `;

      // Query ALL-TIME stats for historical context
      const allTimeQuery = `
        SELECT 
          COUNT(*) as total_connects_all,
          COUNT(CASE WHEN connect_date >= CURRENT_DATE - INTERVAL '7 days' THEN 1 END) as week_connects,
          COUNT(CASE WHEN duration >= 45 AND disposition != 'wrong_number' AND disposition != 'wrong number' THEN 1 END) as total_reached
        FROM war_connects 
        WHERE agent_email = '${userEmail}'
      `;

      const [todayConnectsResult, todayCallsResult, allTimeResult, todayAppointmentsResult] = await Promise.all([
        db.execute(sql.raw(todayConnectsQuery)),
        db.execute(sql.raw(todayCallsQuery)),
        db.execute(sql.raw(allTimeQuery)),
        db.execute(sql.raw(todayAppointmentsQuery))
      ]);

      const todayConnects = todayConnectsResult.rows[0] || {};
      const todayCalls = todayCallsResult.rows[0] || {};
      const allTime = allTimeResult.rows[0] || {};
      const todayAppointments = todayAppointmentsResult.rows[0] || {};

      // Calculate TODAY's real statistics
      const connectCallsToday = Number(todayConnects.total_connects_today || 0) + Number(todayCalls.outbound_calls_today || 0);
      const reachedToday = Number(todayConnects.reached_today || 0);
      const bookedToday = Number(todayConnects.booked_today || 0) + Number(todayAppointments.appointments_today || 0);
      const avgDuration = Number(todayConnects.avg_call_duration || 0);
      
      // Format average call time
      const avgMinutes = Math.floor(avgDuration / 60);
      const avgSeconds = Math.round(avgDuration % 60);
      const avgCallTime = `${avgMinutes}:${String(avgSeconds).padStart(2, '0')}`;

      // Calculate success rates with TODAY's data
      const successRate = connectCallsToday > 0 ? Math.round((reachedToday / connectCallsToday) * 100) : 0;

      const stats = {
        // TODAY's Connect (Calling) Stats - REAL DATA ONLY
        connectCalls: Number(allTime.total_connects_all || 0), // Historical total
        connectCallsToday: connectCallsToday, // TODAY ONLY
        connectCallsWeek: Number(allTime.week_connects || 0), // This week
        connectSuccessRate: successRate, // TODAY's success rate
        connectAppointments: bookedToday, // Real appointments booked today
        connectRevenue: bookedToday * 500, // Estimate $500 per appointment
        
        // TODAY's activity stats
        recruitLeads: 0, // No recruit data available 
        recruitLeadsToday: 0,
        recruitLeadsWeek: 0,
        recruitConversions: bookedToday,
        recruitRevenue: bookedToday * 150,
        
        // TODAY's precheck stats
        precheckVerifications: 0,
        precheckVerificationsToday: 0, 
        precheckVerificationsWeek: 0,
        precheckSuccessRate: successRate,
        precheckRevenue: 0,
        
        // Overall Stats
        totalRevenue: bookedToday * 650, // Total estimated revenue from TODAY's bookings
        totalActivities: connectCallsToday, // TODAY's total activity
        avgCallTime: avgCallTime,
        creditsRemaining: creditsRemaining
      };

      console.log(`📊 TODAY's dashboard stats for ${userEmail}:`, {
        connectCallsToday,
        reachedToday,
        bookedToday,
        successRate
      });

      res.json(stats);
    } catch (error) {
      console.error('Agent dashboard stats error:', error);
      res.status(500).json({ error: 'Failed to fetch agent statistics' });
    }
  });

