  // VDP Agent Tracking - Heartbeat endpoint
  app.post("/api/vdp/heartbeat", async (req, res) => {
    try {
      const { email, timestamp } = req.body;
      
      if (!email) {
        return res.status(400).json({ error: 'Email required' });
      }

      // CHECK CREDITS - Enforce -10 credit limit
      const { data: creditsData } = await supabaseAdmin
        .from('user_credits')
        .select('credits_remaining')
        .eq('email', email)
        .maybeSingle();
      
      const creditsRemaining = creditsData?.credits_remaining || 0;
      
      if (creditsRemaining <= -8) {
        console.log(`🚫 VDP HEARTBEAT REJECTED: ${email} has ${creditsRemaining} credits (limit: -8)`);
        
        // Auto-disable VDP in customers table
        await supabaseAdmin
          .from('customers')
          .update({ VDPACTIVE: 'INACTIVE' })
          .ilike('company_email', email);
        
        return res.status(403).json({ 
          error: 'Account suspended - insufficient credits',
          creditsRemaining,
          message: 'Your VDP account has been automatically disabled due to insufficient credits. Please contact support.'
        });
      }

      // Get agent name from database
      let agentName = email.split('@')[0];
      try {
        const { data: profile } = await supabaseAdmin
          .from('agent_profiles')
          .select('first_name, last_name')
          .eq('email', email)
          .single();
        
        if (profile) {
          agentName = `${profile.first_name} ${profile.last_name}`;
        }
      } catch (error) {
        // Use email if profile not found
      }

      // Update tracker
      const { vdpAgentTracker } = await import('./vdp-agent-tracker');
      vdpAgentTracker.updateHeartbeat(email, agentName);

      res.json({ success: true, timestamp: new Date().toISOString() });
    } catch (error) {
      console.error('❌ VDP heartbeat error:', error);
      res.status(500).json({ error: 'Failed to process heartbeat' });
    }
  });

