  // Webhook for incoming Taalk VDP calls - data capture and recruit AI summary
  app.post("/api/taalk/incoming-call", express.json(), express.urlencoded({ extended: true }), async (req, res) => {
    try {
      console.log('🔍 RAW WEBHOOK DATA RECEIVED:');
      console.log('Headers:', JSON.stringify(req.headers, null, 2));
      console.log('Body:', JSON.stringify(req.body, null, 2));
      console.log('Query:', JSON.stringify(req.query, null, 2));
      console.log('Method:', req.method);
      console.log('Timestamp:', new Date().toISOString());
      console.log('Content-Type:', req.headers['content-type']);
      console.log('Raw body length:', JSON.stringify(req.body || {}).length);

      const body = req.body || {};
      const {
        associate_id,
        agent,
        event,
        duration,
        LeadId,
        company_email,
        clientmarket,
        clientaddress,
        clientcity,
        clientstate,
        clientsecretkey,
        clientemail,
        clientphone,
        clientgroupcode,
        name,
        ai_summary,
        summary,
        analysis,
        call_summary
      } = body;

      // Taalk sometimes sends full candidate record: phone, first_name, last_name, ai_summary, agent_id, agent_email (no event/clientphone)
      const candidateStylePhone = body.phone ?? clientphone;
      const candidateStyleSummary = body.ai_summary ?? ai_summary ?? summary ?? analysis ?? call_summary;
      const candidateStyleAgentEmail = body.agent_email ?? company_email;
      const candidateStyleAgentId = body.agent_id ?? agent ?? associate_id;
      const hasCandidateStylePayload = candidateStylePhone && candidateStyleSummary;

      if (hasCandidateStylePayload && supabaseAdmin) {
        const summaryStr = typeof candidateStyleSummary === 'string' ? candidateStyleSummary : JSON.stringify(candidateStyleSummary);
        const { data: existing, error: lookupErr } = await supabaseAdmin
          .from('recruit_candidates')
          .select('id, first_name, last_name, agent_email')
          .eq('phone', candidateStylePhone)
          .order('updated_at', { ascending: false })
          .limit(1)
          .maybeSingle();
        if (!lookupErr && existing) {
          const updates: Record<string, unknown> = {
            ai_summary: summaryStr,
            updated_at: new Date().toISOString(),
          };
          if (candidateStyleAgentEmail) updates.agent_email = candidateStyleAgentEmail;
          if (candidateStyleAgentId != null) updates.agent_id = String(candidateStyleAgentId);
          const { error: updateErr } = await supabaseAdmin
            .from('recruit_candidates')
            .update(updates)
            .eq('id', existing.id);
          if (updateErr) {
            console.warn('⚠️ Taalk candidate-style ai_summary update failed:', updateErr?.message);
          } else {
            console.log(`✅ Taalk summary applied to recruit_candidates id=${existing.id} (phone=${candidateStylePhone})`);
          }
        } else {
          console.log(`ℹ️ No recruit_candidates row for phone ${candidateStylePhone} (summary not applied)`);
        }
      }

      const aiSummaryData = ai_summary || summary || analysis || call_summary;

      let agentEmail = company_email || candidateStyleAgentEmail;
      const agentAssociateId = agent || associate_id || candidateStyleAgentId;

      if (!agentEmail && agentAssociateId && supabaseAdmin) {
        console.log(`🔍 Looking up agent email for associate_id: ${agentAssociateId}`);
        const idStr = String(agentAssociateId);
        const { data: producer } = await supabaseAdmin
          .from('producerlist')
          .select('company_email')
          .eq('associate_id', idStr)
          .maybeSingle();
        if (producer?.company_email) {
          agentEmail = producer.company_email;
          console.log(`✅ Found agent email: ${agentEmail}`);
        } else {
          console.warn(`⚠️ No email found for associate_id: ${agentAssociateId}`);
        }
      }

      const callerNumber = clientphone;
      const CallerName = name || (body.first_name && body.last_name ? `${body.first_name} ${body.last_name}` : undefined);
      const CallerCity = clientcity;
      const CallerState = clientstate;
      const AgentEmail = agentEmail;
      const leadName = CallerName || `Lead ${callerNumber}`;

      console.log(`📋 VDP Call Data Received: ${callerNumber}, Caller: ${CallerName || 'Unknown'} from ${CallerCity || 'Unknown'}, ${CallerState || 'Unknown'}`);
      console.log(`🎯 Assigned Agent: ${AgentEmail || 'Not specified'} (Associate ID: ${agentAssociateId})`);

      const isVdpCallPayload = event != null && (callerNumber != null || clientphone != null);

      try {
        if (supabaseAdmin && isVdpCallPayload && callerNumber) {
          await supabaseAdmin.from("vdp_calls").insert({
            agent: agentAssociateId,
            event,
            leadid: LeadId,
            company_email: agentEmail,
            phone: callerNumber,
            firstName: CallerName?.split(' ')[0] || '',
            lastName: CallerName?.split(' ').slice(1).join(' ') || '',
            market: clientmarket,
            duration: duration ? parseFloat(String(duration)) : null,
            mga: body.mga,
            rga: body.rga,
            time: new Date().toISOString()
          });
          console.log(`✅ VDP call logged to Supabase for ${agentEmail || 'unknown'}`);
        }
      } catch (err: any) {
        console.warn("⚠️ Supabase vdp_calls log failed (non-critical):", err?.message);
      }

      const isRecruitCall = (clientmarket?.toLowerCase?.() || '').includes('recruit') ||
                           (clientmarket?.toLowerCase?.() || '').includes('hiring') ||
                           (clientgroupcode?.toLowerCase?.() || '').includes('recruit');

      // CRITICAL: Recruit poller reads vdp_calls_BLASTPICK for transfer/no-transfer logic.
      // Store key recruit events (BLASTER/PICK_UP/END/etc.) so "no PICK_UP" can be detected.
      const normalizedRecruitEvent = String(event || '').toUpperCase();
      const isRecruitBlastEvent = ['BLASTER', 'PICK_UP', 'PICKED', 'END', 'NEW'].includes(normalizedRecruitEvent);
      if (isRecruitCall && isRecruitBlastEvent && callerNumber && supabaseAdmin) {
        const blastPickRecord = {
          time: new Date().toISOString(),
          event: normalizedRecruitEvent,
          phone: callerNumber,
          agent: String(agentAssociateId || ''),
          leadid: LeadId ?? null,
          market: (clientmarket || 'aorecruit').toLowerCase().includes('recruit') ? 'aorecruit' : (clientmarket || 'aorecruit'),
          firstName: CallerName?.split(' ')[0] || 'Unknown',
          lastName: CallerName?.split(' ').slice(1).join(' ') || '',
          duration: duration ? parseFloat(String(duration)) : null,
          querystring: null,
          task: null,
          mga: body.mga ?? null,
          rga: body.rga ?? null,
          sessionid: body.sessionid || body.sessionId || LeadId || `webhook_${Date.now()}_${callerNumber}`,
        };
        try {
          const { data: blastInsert, error: blastErr } = await supabaseAdmin
            .from('vdp_calls_BLASTPICK')
            .insert(blastPickRecord)
            .select('id')
            .single();
          if (blastErr) {
            console.warn("⚠️ vdp_calls_BLASTPICK insert failed (recruit poller won't see this call):", blastErr?.message);
          } else {
            console.log(`✅ Recruit ${normalizedRecruitEvent} event written to vdp_calls_BLASTPICK (id=${blastInsert?.id})`);
          }
        } catch (blastEx: any) {
          console.warn("⚠️ vdp_calls_BLASTPICK insert error:", blastEx?.message);
        }
      }

      if (isRecruitCall && normalizedRecruitEvent === 'PICK_UP' && callerNumber) {
        const recruitAgentEmail = AgentEmail || (agentAssociateId ? `unknown-agent-${String(agentAssociateId).trim()}@aoglobelife.com` : 'unknown-agent@aoglobelife.com');
        console.log(`🎯 Detected recruit VDP call for ${recruitAgentEmail}: ${leadName} (${callerNumber})`);

        try {
          if (supabaseAdmin && callerNumber) {
            const { data: existingCandidate, error: lookupError } = await supabaseAdmin
              .from('recruit_candidates')
              .select('id, first_name, last_name, current_stage_id, status')
              .eq('phone', callerNumber)
              .maybeSingle();

            if (lookupError) {
              console.error('❌ Error looking up candidate for 1st interview auto-mark:', lookupError);
            } else if (existingCandidate) {
              const currentStage = Number(existingCandidate.current_stage_id || 0);
              const currentStatus = String(existingCandidate.status || '').toLowerCase();
              const promotePatch: Record<string, unknown> = {
                updated_at: new Date().toISOString(),
                agent_email: recruitAgentEmail,
                agent_id: String(agentAssociateId || ''),
              };
              if (!Number.isFinite(currentStage) || currentStage < 2) {
                promotePatch.current_stage_id = 2; // 1st Interview
                promotePatch.stage_entered_at = new Date().toISOString();
              }
              if (currentStatus === 'new' || currentStatus === 'contacted' || !currentStatus) {
                promotePatch.status = 'interview';
              }
              const { error: promoteError } = await supabaseAdmin
                .from('recruit_candidates')
                .update(promotePatch)
                .eq('id', existingCandidate.id);
              if (promoteError) {
                console.error(`❌ Failed to auto-mark 1st interview for candidate ${existingCandidate.id}:`, promoteError);
              } else {
                console.log(`✅ Candidate ${existingCandidate.id} confirmed at 1st Interview after PICK_UP`);
              }
            } else {
              const callerNameNorm = String(CallerName || '').trim();
              const nameParts = callerNameNorm.split(/\s+/).filter(Boolean);
              const autoFirstName = nameParts[0] || 'Unknown';
              const autoLastName = nameParts.slice(1).join(' ') || 'Candidate';
              const { data: insertedCandidate, error: insertError } = await supabaseAdmin
                .from('recruit_candidates')
                .insert({
                  first_name: autoFirstName,
                  last_name: autoLastName,
                  phone: callerNumber,
                  email: '',
                  status: 'interview',
                  current_stage_id: 2, // 1st Interview
                  stage_entered_at: new Date().toISOString(),
                  agent_id: String(agentAssociateId || ''),
                  agent_email: recruitAgentEmail,
                  notes: `Auto-created from recruit PICK_UP call. Auto-marked to 1st Interview.`,
                  created_at: new Date().toISOString(),
                  updated_at: new Date().toISOString(),
                })
                .select('id')
                .single();
              if (insertError) {
                console.error('❌ Failed to auto-create recruit candidate on PICK_UP:', insertError);
              } else {
                console.log(`✅ Auto-created recruit candidate ${insertedCandidate?.id} at 1st Interview from PICK_UP`);
              }
            }
          }
        } catch (stageError: any) {
          console.error('❌ Error auto-marking 1st Interview from PICK_UP:', stageError?.message || stageError);
        }

        if (aiSummaryData && callerNumber) {
          const summaryStr = typeof aiSummaryData === 'string' ? aiSummaryData : JSON.stringify(aiSummaryData);
          console.log(`🤖 AI Summary received for ${callerNumber}`);
          console.log(`📝 Summary: ${summaryStr.substring(0, 200)}...`);

          try {
            if (supabaseAdmin) {
              const { data: existingCandidate, error: lookupError } = await supabaseAdmin
                .from('recruit_candidates')
                .select('id, first_name, last_name')
                .eq('phone', callerNumber)
                .maybeSingle();

              if (lookupError) {
                console.error('❌ Error looking up candidate:', lookupError);
              } else if (existingCandidate) {
                console.log(`✅ Found candidate ${existingCandidate.id}: ${existingCandidate.first_name} ${existingCandidate.last_name}`);

                const { error: updateError } = await supabaseAdmin
                  .from('recruit_candidates')
                  .update({
                    ai_summary: summaryStr,
                    updated_at: new Date().toISOString()
                  })
                  .eq('id', existingCandidate.id);

                if (updateError) {
                  console.error('❌ Failed to update candidate with AI summary:', updateError);
                } else {
                  console.log(`✅ ✅ ✅ AI SUMMARY SAVED to candidate ${existingCandidate.id}!`);
                }
              } else {
                console.log(`⚠️ No candidate found for phone ${callerNumber} - will be created by poller`);
              }
            }
          } catch (summaryError: any) {
            console.error('❌ Error processing AI summary:', summaryError?.message || summaryError);
          }
        } else if (!aiSummaryData) {
          console.log(`ℹ️ No AI summary in webhook data`);
        }
      }

      res.json({
        success: true,
        message: 'Call data captured for agent display',
        displayData: {
          callerName: leadName,
          callerNumber: callerNumber,
          location: `${CallerCity || ''} ${CallerState || ''}`.trim(),
          agent: AgentEmail || 'Unknown'
        }
      });
    } catch (error: any) {
      console.error('❌ Failed to capture VDP call data:', error);
      res.status(500).json({
        error: 'Failed to capture call data',
        details: error?.message || String(error)
      });
    }
  });

