  app.get("/api/recruit/stages", async (_req, res) => {
    res.json({ success: true, stages: RECRUIT_STAGES });
  });

  app.get("/api/recruit/candidates/:id(\\d+)/stage-accountability", async (req, res) => {
    try {
      const { id } = req.params;
      const candidate = await storage.getRecruitCandidateById(parseInt(id));
      if (!candidate) {
        return res.status(404).json({ success: false, message: 'Candidate not found' });
      }

      const headerEmail = req.headers['x-user-email'] as string | undefined;
      const sessionEmail = (req.session as any)?.user?.email as string | undefined;
      const agentEmail = String(headerEmail || sessionEmail || candidate.agentEmail || '').toLowerCase().trim();
      if (!agentEmail) {
        return res.status(401).json({ success: false, message: 'Authentication required' });
      }
      if (String(candidate.agentEmail || '').toLowerCase().trim() !== agentEmail) {
        return res.status(403).json({ success: false, message: 'Not authorized for this candidate' });
      }

      const accountability = await buildRecruitStageAccountability(candidate, agentEmail);
      return res.json({
        success: true,
        candidateId: candidate.id,
        currentStageId: candidate.currentStageId ?? null,
        stages: accountability,
      });
    } catch (error: any) {
      console.error('Failed to get recruit stage accountability:', error);
      return res.status(500).json({ success: false, message: 'Failed to get stage accountability' });
    }
  });

  app.get("/api/recruit/accountability/check-blocking/:email", async (req, res) => {
    try {
      const enforceRecruitBlocking = false;
      // Temporary override requested: keep accountability visible in UI flows,
      // but do not enforce recruit platform lock right now.
      if (!enforceRecruitBlocking) {
        return res.json({
          success: true,
          isBlocked: false,
          pendingCount: 0,
          blockers: [],
          enforcementDisabled: true,
        });
      }

      const emailParam = String(req.params.email || '').toLowerCase().trim();
      if (!emailParam || !emailParam.includes('@')) {
        return res.status(400).json({ success: false, message: 'Valid email is required' });
      }

      const candidates = await storage.getRecruitCandidates(emailParam);
      const blockingItems: Array<{
        candidateId: number;
        candidateName: string;
        currentStageId: number | null;
        currentStageName: string | null;
        blockingStageId: number;
        blockingStageName: string;
        reason: string;
        latestAppointmentId: number | null;
        latestOutcome: string | null;
        latestAppointmentAt: string | null;
      }> = [];

      for (const candidate of candidates || []) {
        const currentStageId = Number(candidate.currentStageId || 0);
        if (!Number.isFinite(currentStageId) || currentStageId <= 1) continue;

        const stageAccountability = await buildRecruitStageAccountability(candidate, emailParam);
        const currentStageName = RECRUIT_STAGES.find((s) => s.id === currentStageId)?.name || null;
        const previousRequiredStages = stageAccountability
          .filter((stage) => stage.stageId < currentStageId && stage.resolutionRequired === true);

        for (const stage of previousRequiredStages) {
          if (!stage.hasResolution) {
            blockingItems.push({
              candidateId: Number(candidate.id),
              candidateName: `${String(candidate.firstName || '').trim()} ${String(candidate.lastName || '').trim()}`.trim() || `Candidate #${candidate.id}`,
              currentStageId: currentStageId || null,
              currentStageName,
              blockingStageId: stage.stageId,
              blockingStageName: stage.stageName,
              reason: `Missing outcome for previous stage "${stage.stageName}"`,
              latestAppointmentId: Number(stage.latestAppointmentId || 0) || null,
              latestOutcome: stage.latestOutcome ? String(stage.latestOutcome) : null,
              latestAppointmentAt: stage.latestAppointmentAt ? String(stage.latestAppointmentAt) : null,
            });
            break;
          }
        }
      }

      return res.json({
        success: true,
        isBlocked: blockingItems.length > 0,
        pendingCount: blockingItems.length,
        blockers: blockingItems,
      });
    } catch (error: any) {
      console.error('Failed to check recruit accountability blocking:', error);
      return res.status(500).json({ success: false, message: 'Failed to check recruit blocking' });
    }
  });

  // Stage counts used by Recruit CCPRO stage dropdown
  app.get("/api/recruit/candidates/stage-counts", async (req, res) => {
    try {
      const headerEmail = req.headers['x-user-email'] as string | undefined;
      const queryEmail = req.query.email as string | undefined;
      const sessionEmail = (req as any).user?.email as string | undefined;
      const agentEmail = (headerEmail || queryEmail || sessionEmail || '').trim();
      if (!agentEmail) {
        return res.status(400).json({ success: false, message: 'Agent email required' });
      }

      const candidates = await storage.getRecruitCandidates(agentEmail);
      const stageCounts = candidates.reduce((acc: Record<number, number>, candidate: any) => {
        const parsedStageId = Number(candidate?.currentStageId ?? candidate?.current_stage_id ?? 0);
        const stageId = Number.isFinite(parsedStageId) && parsedStageId > 0 ? parsedStageId : 0;
        acc[stageId] = (acc[stageId] || 0) + 1;
        return acc;
      }, {});

      return res.json({
        success: true,
        total: candidates.length,
        stageCounts,
      });
    } catch (error: any) {
      console.error('Failed to get recruit stage counts:', error);
      return res.status(500).json({ success: false, message: 'Failed to get recruit stage counts' });
    }
  });

  app.get("/api/recruit/stats", async (req, res) => {
    try {
      const agentEmail = (req.query.email as string) || (req as any).user?.email;
      if (!agentEmail) {
        return res.status(400).json({ success: false, message: 'Agent email required' });
      }
      const candidates = await storage.getRecruitCandidates(agentEmail);
      const stats = {
        totalCandidates: candidates.length,
        newCandidates: candidates.filter(c => c.status === 'new').length,
        contactedCandidates: candidates.filter(c => c.status === 'contacted').length,
        interviewCandidates: candidates.filter(c => c.status === 'interview').length,
        pendingCandidates: candidates.filter(c => c.status === 'pending').length,
        hiredCandidates: candidates.filter(c => c.status === 'hired').length,
        rejectedCandidates: candidates.filter(c => c.status === 'rejected').length,
        upcomingAppointments: candidates.filter(c => c.appointmentDate && new Date(c.appointmentDate) > new Date()).length,
      };
      res.json({ success: true, stats });
    } catch (error: any) {
      console.error('Failed to get recruit stats:', error);
      res.status(500).json({ success: false, message: 'Failed to retrieve stats' });
    }
  });

  // Journey session read API used by /recruit journey tracker
  app.get("/api/recruit/journey-session/:candidateId", async (req, res) => {
    try {
      const candidateId = Number(req.params.candidateId);
      if (!Number.isFinite(candidateId) || candidateId <= 0) {
        return res.status(400).json({ success: false, message: "Valid candidateId is required" });
      }
      if (!supabaseAdmin) {
        return res.status(503).json({ success: false, message: "Supabase unavailable" });
      }

      const { data, error } = await supabaseAdmin
        .from("candidate_journey_sessions")
        .select("*")
        .eq("candidate_id", candidateId)
        .maybeSingle();
      if (error) throw error;

      return res.json({ success: true, session: data || null });
    } catch (error: any) {
      console.error("Failed to get journey session:", error);
      return res.status(500).json({ success: false, message: "Failed to get journey session" });
    }
  });

  // Journey session write API used by /recruit journey tracker
  app.patch("/api/recruit/journey-session/:candidateId", async (req, res) => {
    try {
      const candidateId = Number(req.params.candidateId);
      if (!Number.isFinite(candidateId) || candidateId <= 0) {
        return res.status(400).json({ success: false, message: "Valid candidateId is required" });
      }
      if (!supabaseAdmin) {
        return res.status(503).json({ success: false, message: "Supabase unavailable" });
      }

      const updates = { ...(req.body || {}), candidate_id: candidateId };
      const { data, error } = await supabaseAdmin
        .from("candidate_journey_sessions")
        .upsert(updates, { onConflict: "candidate_id" })
        .select("*")
        .single();
      if (error) throw error;

      return res.json({ success: true, session: data });
    } catch (error: any) {
      console.error("Failed to update journey session:", error);
      return res.status(500).json({ success: false, message: "Failed to update journey session" });
    }
  });

  app.post("/api/recruit/candidates", async (req, res) => {
    try {
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const agentEmail = headerEmail || sessionEmail;
      if (!agentEmail) {
        return res.status(401).json({ success: false, message: 'Authentication required - no user email found' });
      }
      const agentProfile = await storage.getAgentProfileByEmail(agentEmail);
      const agentId = agentProfile?.supabaseUserId || agentEmail;
      const candidateData = { ...req.body, agentId, agentEmail };
      const parsedData = insertRecruitCandidateSchema.parse(candidateData);
      const candidate = await storage.createRecruitCandidate(parsedData);
      res.json({ success: true, candidate });
    } catch (error: any) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ success: false, message: 'Invalid candidate data', errors: error.errors });
      }
      console.error('Failed to create candidate:', error);
      res.status(500).json({ success: false, message: 'Failed to create candidate' });
    }
  });

  app.patch("/api/recruit/candidates/:id(\\d+)", async (req, res) => {
    try {
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const agentEmail = headerEmail || sessionEmail;
      if (!agentEmail) {
        return res.status(401).json({ success: false, message: 'Authentication required' });
      }
      const { id } = req.params;
      const body = { ...req.body };
      if (body.appointmentDate != null && typeof body.appointmentDate === 'string') {
        body.appointmentDate = new Date(body.appointmentDate);
      }
      if (body.stageEnteredAt != null && typeof body.stageEnteredAt === 'string') {
        body.stageEnteredAt = new Date(body.stageEnteredAt);
      }
      if (body.lastContacted != null && typeof body.lastContacted === 'string') {
        body.lastContacted = new Date(body.lastContacted);
      }
      const parsedUpdates = updateRecruitCandidateSchema.parse(body);
      const updatedCandidate = await storage.updateRecruitCandidate(parseInt(id), parsedUpdates);
      if (!updatedCandidate) {
        return res.status(404).json({ success: false, message: 'Candidate not found' });
      }
      res.json({ success: true, candidate: updatedCandidate });
    } catch (error: any) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ success: false, message: 'Invalid update data', errors: error.errors });
      }
      console.error('Failed to update candidate:', error);
      res.status(500).json({ success: false, message: 'Failed to update candidate' });
    }
  });

  app.get("/api/recruit/candidates/:id(\\d+)/examfx", async (req, res) => {
    try {
      const candidateId = parseInt(req.params.id);
      const { data, error } = await supabase
        .from("recruit_candidates")
        .select("id, first_name, last_name, examfx_voucher_code, examfx_enrolled_at, examfx_state, examfx_course_type, examfx_status, examfx_progress_percent, examfx_practice_scores, examfx_exam_date, examfx_exam_result, examfx_exam_result_at, examfx_notes, examfx_last_sync_at")
        .eq("id", candidateId)
        .single();
      if (error) throw error;
      res.json({ success: true, examfx: data });
    } catch (error: any) {
      res.status(500).json({ success: false, error: error.message });
    }
  });

  app.post("/api/recruit/candidates/:id(\\d+)/examfx", async (req, res) => {
    try {
      const candidateId = parseInt(req.params.id);
      const {
        examfxVoucherCode,
        examfxEnrolledAt,
        examfxState,
        examfxCourseType,
        examfxStatus,
        examfxProgressPercent,
        examfxPracticeScores,
        examfxExamDate,
        examfxExamResult,
        examfxExamResultAt,
        examfxNotes,
      } = req.body;

      const updates: Record<string, any> = {};
      if (examfxVoucherCode !== undefined) updates.examfx_voucher_code = examfxVoucherCode;
      if (examfxEnrolledAt !== undefined) updates.examfx_enrolled_at = examfxEnrolledAt;
      if (examfxState !== undefined) updates.examfx_state = examfxState;
      if (examfxCourseType !== undefined) updates.examfx_course_type = examfxCourseType;
      if (examfxStatus !== undefined) updates.examfx_status = examfxStatus;
      if (examfxProgressPercent !== undefined) updates.examfx_progress_percent = examfxProgressPercent;
      if (examfxPracticeScores !== undefined) updates.examfx_practice_scores = typeof examfxPracticeScores === 'string' ? examfxPracticeScores : JSON.stringify(examfxPracticeScores);
      if (examfxExamDate !== undefined) updates.examfx_exam_date = examfxExamDate;
      if (examfxExamResult !== undefined) updates.examfx_exam_result = examfxExamResult;
      if (examfxExamResultAt !== undefined) updates.examfx_exam_result_at = examfxExamResultAt;
      if (examfxNotes !== undefined) updates.examfx_notes = examfxNotes;
      updates.examfx_last_sync_at = new Date().toISOString();

      // If enrolling for the first time (status becomes enrolled), set enrolled_at if not provided
      if (examfxStatus === 'enrolled' && !examfxEnrolledAt && !updates.examfx_enrolled_at) {
        updates.examfx_enrolled_at = new Date().toISOString();
      }

      const { data, error } = await supabase
        .from("recruit_candidates")
        .update(updates)
        .eq("id", candidateId)
        .select()
        .single();

      if (error) throw error;
      res.json({ success: true, candidate: data });
    } catch (error: any) {
      res.status(500).json({ success: false, error: error.message });
    }
  });

  app.post("/api/recruit/candidates/:id(\\d+)/examfx/send-enrollment-sms", async (req, res) => {
    try {
      const candidateId = parseInt(req.params.id);
      const { voucherCode, state, courseType, candidatePhone, candidateName, agentEmail } = req.body;

      if (!candidatePhone) {
        return res.status(400).json({ success: false, error: "Candidate phone number required" });
      }

      const courseLabel = courseType || "Life & Health";
      const stateLabel = state || "";
      const voucherPart = voucherCode ? `\nYour voucher code: ${voucherCode}` : "";
      const smsBody = `Hi ${candidateName || "there"}! Congratulations on your hire with AO GlobeLife. Your next step is completing your ${courseLabel}${stateLabel ? ` (${stateLabel})` : ""} prelicensing course on ExamFX.${voucherPart}\n\nVisit: https://www.examfx.com and click "Redeem Voucher" to get started. Questions? Reply to this message or contact your manager.`;

      // Use existing Twilio SMS infrastructure
      const twilioClient = (global as any).twilioClient;
      if (!twilioClient) {
        return res.status(500).json({ success: false, error: "SMS service unavailable" });
      }

      const formattedPhone = candidatePhone.replace(/\D/g, '');
      const e164Phone = formattedPhone.startsWith('1') ? `+${formattedPhone}` : `+1${formattedPhone}`;

      await twilioClient.messages.create({
        body: smsBody,
        from: process.env.TWILIO_PHONE_NUMBER || process.env.TWILIO_FROM_NUMBER,
        to: e164Phone,
      });

      res.json({ success: true, message: "Enrollment SMS sent" });
    } catch (error: any) {
      console.error("Failed to send ExamFX enrollment SMS:", error);
      res.status(500).json({ success: false, error: error.message });
    }
  });

  app.delete("/api/recruit/candidates/:id(\\d+)", async (req, res) => {
    try {
      const headerEmail = req.headers['x-user-email'] as string || req.headers['user-email'] as string;
      const sessionEmail = (req.session as any)?.user?.email;
      const agentEmail = headerEmail || sessionEmail;
      if (!agentEmail) {
        return res.status(401).json({ success: false, message: 'Authentication required' });
      }
      const { id } = req.params;
      const success = await storage.deleteRecruitCandidate(parseInt(id));
      if (!success) {
        return res.status(404).json({ success: false, message: 'Candidate not found' });
      }
      res.json({ success: true, message: 'Candidate deleted' });
    } catch (error: any) {
      console.error('Failed to delete candidate:', error);
      res.status(500).json({ success: false, message: 'Failed to delete candidate' });
    }
  });

  app.post("/api/recruit/candidates/appointment", async (req, res) => {
    try {
      const agentEmailRaw =
        (req.headers['x-user-email'] as string) ||
        (req.headers['user-email'] as string) ||
        (req.session as any)?.user?.email ||
        '';
      const agentEmail = String(agentEmailRaw || '').toLowerCase().trim();
      if (!agentEmail) {
        return res.status(401).json({ success: false, error: 'Authentication required' });
      }
      if (!supabaseAdmin) {
        return res.status(503).json({ success: false, error: 'Supabase unavailable' });
      }

      const {
        candidateId,
        appointmentDate,
        appointmentNotes,
        sendSMS,
        smsMessage,
        currentStageId,
        stageName,
        stageUrl,
      } = req.body || {};

      const parsedCandidateId = Number(candidateId);
      if (!Number.isFinite(parsedCandidateId) || parsedCandidateId <= 0) {
        return res.status(400).json({ success: false, error: 'candidateId is required' });
      }
      if (!appointmentDate) {
        return res.status(400).json({ success: false, error: 'appointmentDate is required' });
      }

      const appointmentStart = new Date(String(appointmentDate));
      if (Number.isNaN(appointmentStart.getTime())) {
        return res.status(400).json({ success: false, error: 'appointmentDate is invalid' });
      }

      const candidate = await storage.getRecruitCandidateById(parsedCandidateId);
      if (!candidate) {
        return res.status(404).json({ success: false, error: 'Candidate not found' });
      }

      const ownerEmail = String(candidate.agentEmail || '').toLowerCase().trim();
      if (!ownerEmail || ownerEmail !== agentEmail) {
        return res.status(403).json({ success: false, error: 'Not authorized for this candidate' });
      }

      const stageId = Number(currentStageId || candidate.currentStageId || 0);
      const derivedStageName = RECRUIT_STAGES.find((s) => s.id === stageId)?.name || '';
      const stageNameNormalized = String(stageName || derivedStageName || '').toLowerCase();
      const isGroupOverview = stageId === 3 || stageNameNormalized.includes('overview');
      const appointmentType = isGroupOverview ? 'recruit_group_overview' : 'recruit_interview';
      const stageLabel = String(stageName || derivedStageName || (isGroupOverview ? 'Virtual Overview' : 'Interview')).trim();
      const stageLink = String(stageUrl || '').trim();
      const notes = String(appointmentNotes || '').trim();
      const stageTag = stageId > 0 ? `RecruitStageId=${stageId};RecruitStageName=${stageLabel || 'Unknown'}` : null;

      const updatePayload: any = {
        appointmentDate: appointmentStart,
        appointmentNotes: notes || null,
      };
      if (String(candidate.status || '').toLowerCase() === 'new' || String(candidate.status || '').toLowerCase() === 'contacted') {
        updatePayload.status = 'interview';
      }
      const updatedCandidate = await storage.updateRecruitCandidate(parsedCandidateId, updatePayload as any);

      const startIso = appointmentStart.toISOString();
      const endIso = new Date(appointmentStart.getTime() + 60 * 60 * 1000).toISOString();
      const candidateFullName = `${String(candidate.firstName || '').trim()} ${String(candidate.lastName || '').trim()}`.trim() || 'Recruit Candidate';

      const { data: existingRecruitAppt } = await supabaseAdmin
        .from('appointments')
        .select('id')
        .eq('agent_email', agentEmail)
        .eq('lead_id', parsedCandidateId as any)
        .in('appointment_type', ['recruit_interview', 'recruit_group_overview'])
        .neq('status', 'cancelled')
        .order('start_time', { ascending: false })
        .limit(1)
        .maybeSingle();

      const agentNameFromCandidate =
        `${String((candidate as any).agentFirstName || '').trim()} ${String((candidate as any).agentLastName || '').trim()}`.trim();

      const appointmentPayload = {
        title: `${isGroupOverview ? 'Recruit Group Overview' : 'Recruit Interview'} with ${candidateFullName}`,
        description: stageLabel ? `Recruit stage: ${stageLabel}` : null,
        appointment_type: appointmentType,
        start_time: startIso,
        end_time: endIso,
        duration: 60,
        timezone: 'America/New_York',
        agent_id: String(candidate.agentId || '').trim() || null,
        agent_email: agentEmail,
        agent_name: agentNameFromCandidate || agentEmail,
        lead_id: parsedCandidateId as any,
        lead_name: candidateFullName,
        lead_phone: String(candidate.phone || '').trim() || null,
        lead_email: String(candidate.email || '').trim() || null,
        meeting_platform: stageLink ? 'link' : 'recruit',
        status: 'scheduled',
        confirmation_status: 'pending',
        outcome: 'pending',
        notes: notes || null,
        internal_notes: [stageTag, stageLink ? `StageURL=${stageLink}` : null].filter(Boolean).join(' | ') || null,
        updated_at: new Date().toISOString(),
      } as any;

      let appointmentRecord: any = null;
      if (existingRecruitAppt?.id) {
        const { data: updatedAppt, error: updateApptError } = await supabaseAdmin
          .from('appointments')
          .update(appointmentPayload)
          .eq('id', existingRecruitAppt.id)
          .select('*')
          .single();
        if (updateApptError) throw updateApptError;
        appointmentRecord = updatedAppt;
      } else {
        const { data: createdAppt, error: createApptError } = await supabaseAdmin
          .from('appointments')
          .insert({
            ...appointmentPayload,
            created_at: new Date().toISOString(),
          })
          .select('*')
          .single();
        if (createApptError) throw createApptError;
        appointmentRecord = createdAppt;
      }

      let smsSent = false;
      if (sendSMS === true && candidate.phone && String(smsMessage || '').trim()) {
        smsSent = await smsService.sendSMS(String(candidate.phone), String(smsMessage).trim());
      }

      return res.json({
        success: true,
        candidate: updatedCandidate || candidate,
        appointment: appointmentRecord,
        smsSent,
      });
    } catch (error: any) {
      console.error('Failed to schedule recruit appointment:', error);
      return res.status(500).json({
        success: false,
        error: error?.message || 'Failed to schedule recruit appointment',
      });
    }
  });

  app.post("/api/recruit/candidates/:id(\\d+)/move-stage", async (req, res) => {
    try {
      const { id } = req.params;
      const { toStageId } = req.body;
      if (!toStageId) {
        return res.status(400).json({ success: false, message: 'toStageId is required' });
      }
      const stageId = typeof toStageId === 'string' ? parseInt(toStageId) : toStageId;
      if (!Number.isFinite(stageId) || stageId <= 0) {
        return res.status(400).json({ success: false, message: 'toStageId must be a valid positive number' });
      }
      const candidate = await storage.getRecruitCandidateById(parseInt(id));
      if (!candidate) {
        return res.status(404).json({ success: false, message: 'Candidate not found' });
      }
      const currentStageId = Number(candidate.currentStageId || 0);
      const isForwardMove = Number.isFinite(currentStageId) && currentStageId > 0 && stageId > currentStageId;
      if (isForwardMove && stageId !== 8) {
        const ownerEmail = String(candidate.agentEmail || '').toLowerCase().trim();
        const accountability = await buildRecruitStageAccountability(candidate, ownerEmail);
        const currentStage = accountability.find((s) => s.stageId === currentStageId);
        if (currentStage && !currentStage.isComplete) {
          return res.status(409).json({
            success: false,
            message: `Cannot move stages. Complete ${currentStage.stageName} appointment/resolution first.`,
            blockingStage: currentStage,
            accountability,
          });
        }
      }
      const updatedCandidate = await storage.updateRecruitCandidate(parseInt(id), {
        currentStageId: stageId,
        stageEnteredAt: new Date()
      });
      if (!updatedCandidate) {
        return res.status(404).json({ success: false, message: 'Candidate not found' });
      }
      if (stageId === 3 && candidate.phone && supabaseAdmin) {
        const { data: existingSession } = await supabaseAdmin
          .from('candidate_journey_sessions')
          .select('*')
          .eq('candidate_id', candidate.id)
          .single();
        if (!existingSession) {
          await supabaseAdmin.from('candidate_journey_sessions').insert({
            candidate_id: candidate.id,
            video_section_1_watched: false,
            video_section_2_watched: false,
            question_1_answered: false,
            question_2_answered: false,
            question_3_answered: false,
            created_at: new Date().toISOString()
          });
        }
        const journeyUrl = `${PRODUCTION_URL || PRODUCTION_BASE_URL}/recruit-journey?candidate=${candidate.id}&agent=${encodeURIComponent(candidate.agentEmail)}&name=${encodeURIComponent(candidate.firstName + ' ' + candidate.lastName)}&phone=${encodeURIComponent(candidate.phone)}`;
        const message = `Hi ${candidate.firstName}, this is AO Recruit! Click here to watch our Virtual Overview and connect with us: ${journeyUrl}`;
        await smsService.sendSMS(candidate.phone, message);
      }
      res.json({ success: true, message: 'Candidate stage updated', candidate: updatedCandidate });
    } catch (error: any) {
      console.error('Failed to move candidate stage:', error);
      res.status(500).json({ success: false, message: 'Failed to move candidate stage', error: error?.message });
    }
  });

  // Virtual Overview progress: candidates in Virtual Overview stage (stage id 3) with journey session progress
  app.get("/api/recruit/virtual-overview-progress", async (req, res) => {
    try {
      const agentEmail = (req.query.email as string) || (req as any).user?.email;
      if (!agentEmail) {
        return res.status(400).json({ success: false, message: 'Agent email required' });
      }
      if (!supabaseAdmin) {
        return res.json({ success: true, candidates: [] });
      }
      const VIRTUAL_OVERVIEW_STAGE_ID = 3; // matches default stages in GET /api/recruit/stages
      const { data: candidates, error } = await supabaseAdmin
        .from('recruit_candidates')
        .select('*')
        .eq('agent_email', agentEmail)
        .eq('current_stage_id', VIRTUAL_OVERVIEW_STAGE_ID);
      if (error) throw error;
      const candidatesWithProgress = await Promise.all(
        (candidates || []).map(async (candidate: any) => {
          const { data: journeySession } = await supabaseAdmin!
            .from('candidate_journey_sessions')
            .select('*')
            .eq('candidate_id', candidate.id)
            .maybeSingle();
          return {
            ...candidate,
            journeyProgress: journeySession || {
              video_section_1_watched: false,
              video_section_2_watched: false,
              question_1_answered: false,
              question_2_answered: false,
              question_3_answered: false,
            },
          };
        })
      );
      res.json({ success: true, candidates: candidatesWithProgress });
    } catch (error: any) {
      console.error('Virtual overview progress error:', error);
      res.status(500).json({ success: false, message: 'Failed to fetch virtual overview progress' });
    }
  });

  // Send SMS to a recruit candidate (AO Recruit texting)
  app.post("/api/recruit/candidates/sms", async (req, res) => {
    try {
      const agentEmail = (req.headers['x-user-email'] as string) || (req.headers['user-email'] as string) || (req as any).user?.email;
      if (!agentEmail) {
        return res.status(401).json({ success: false, error: 'Authentication required' });
      }
      const { candidateId, phone, message } = req.body;
      if (!phone || !message || !message.trim()) {
        return res.status(400).json({ error: 'Phone and message are required' });
      }
      const candidate = candidateId ? await storage.getRecruitCandidateById(Number(candidateId)) : null;
      if (candidateId && candidate && candidate.agentEmail !== agentEmail) {
        return res.status(403).json({ error: 'Not authorized to send SMS for this candidate' });
      }
      const sent = await smsService.sendSMS(phone, message.trim());
      if (!sent) {
        return res.status(500).json({ error: 'Failed to send SMS (Twilio not configured or send failed)' });
      }
      res.json({ success: true, message: 'SMS sent' });
    } catch (error: any) {
      console.error('Recruit SMS send failed:', error);
      res.status(500).json({ error: error?.message || 'Failed to send SMS' });
    }
  });

