  const LCB_STATS_CACHE_TTL_MS = 0; // No cache - using pre-aggregated live_call_boardt table for instant queries
  const lcbStatsCache = new Map<string, { data: any; expiresAt: number }>();

  // API endpoint to read agent_dial_metrics data - returns data in EXACT format Live Call Board expects
  // This is for verification/testing - shows what the Live Call Board SHOULD be displaying
  app.get("/api/agent-dial-metrics", checkMgaRgaAccess, async (req, res) => {
    try {
      const userEmail = (req.query.userEmail as string) || (req.headers['x-user-email'] as string);
      // For non-super-admins richiealtig@aoglobelife.com and cnsysop@aoglobelife.com, filter by hierarchy
      // Only chrislafond@aoglobelife.com and nateschoot@aoglobelife.com are true super admins who see all
      const isSysOp = userEmail?.toLowerCase() === 'chrislafond@aoglobelife.com' || userEmail?.toLowerCase() === 'nateschoot@aoglobelife.com';
      
      // Get date range: 5 AM - 9 PM PST for current day (same as Live Call Board)
      const now = new Date();
      const pstString = now.toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
      const utcString = now.toLocaleString('en-US', { timeZone: 'UTC' });
      const offsetMs = new Date(pstString).getTime() - new Date(utcString).getTime();
      const pstDate = new Date(pstString);
      const year = pstDate.getFullYear();
      const month = pstDate.getMonth();
      const day = pstDate.getDate();
      const start5AM = new Date(year, month, day, 5, 0, 0, 0);
      const todayStart = new Date(start5AM.getTime() - offsetMs);
      const end9PM = new Date(year, month, day, 21, 0, 0, 0);
      const todayEnd = new Date(end9PM.getTime() - offsetMs);
      
      const { 
        agentEmail, 
        startDate, 
        endDate, 
        eventType,
        includeRawData = 'false'
      } = req.query;
      
      if (!supabaseAdmin) {
        return res.status(500).json({ error: 'Database not initialized' });
      }
      
      // Use provided date range or default to today's PST range.
      // If caller provides YYYY-MM-DD, treat as whole UTC day bounds.
      const parseRangeDate = (value: unknown, isEnd = false): Date | null => {
        if (!value) return null;
        const raw = String(value).trim();
        if (!raw) return null;
        if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
          return new Date(`${raw}${isEnd ? 'T23:59:59.999Z' : 'T00:00:00.000Z'}`);
        }
        const dt = new Date(raw);
        return Number.isNaN(dt.getTime()) ? null : dt;
      };

      const parsedStart = parseRangeDate(startDate, false);
      const parsedEnd = parseRangeDate(endDate, true);
      const queryStart = parsedStart || todayStart;
      const queryEnd = parsedEnd || todayEnd;
      
      // Build query for agent_dial_metrics
      let dialsQuery = supabaseAdmin
        .from('agent_dial_metrics')
        .select('agent_email, event_type, event_timestamp, call_duration, disposition', { count: 'exact' })
        .gte('event_timestamp', queryStart.toISOString())
        .lt('event_timestamp', queryEnd.toISOString());
      
      // Filter by agent if provided
      if (agentEmail) {
        dialsQuery = dialsQuery.eq('agent_email', (agentEmail as string).toLowerCase());
      }
      
      // Filter by event type if provided
      if (eventType && ['dial', 'reach', 'booked', 'instant_presentation'].includes(eventType as string)) {
        dialsQuery = dialsQuery.eq('event_type', eventType as string);
      }
      
      const { data: metricsData, error, count } = await dialsQuery;
      
      if (error) {
        console.error('❌ Error fetching agent_dial_metrics:', error);
        return res.status(500).json({ error: 'Failed to fetch agent dial metrics', details: error.message });
      }
      
      // Group by agent and calculate stats (EXACT format Live Call Board expects)
      const agentStatsMap = new Map<string, {
        agentEmail: string;
        todayStats: {
          dialed: number;
          reached: number;
          booked: number;
        };
        totalRecords: number;
      }>();
      
      const bookedDispositions = new Set([
        'appointment',
        'appointment_set',
        'set_appointment',
        'booked',
        'qualified',
        'callback_scheduled',
        'instant_presentation',
        'sale',
        'meet',
      ]);
      const reachedDispositions = new Set([
        'interested',
        'booked',
        'appointment',
        'appointment_set',
        'set_appointment',
        'qualified',
        'callback_scheduled',
        'instant_presentation',
        'sale',
        'meet',
      ]);

      (metricsData || []).forEach((record: any) => {
        const email = record.agent_email?.toLowerCase();
        if (!email) return;
        
        if (!agentStatsMap.has(email)) {
          agentStatsMap.set(email, {
            agentEmail: email,
            todayStats: { dialed: 0, reached: 0, booked: 0 },
            totalRecords: 0
          });
        }
        
        const stats = agentStatsMap.get(email)!;
        stats.totalRecords++;
        
        const eventTypeValue = String(record.event_type || '').toLowerCase();
        const dispositionValue = String(record.disposition || '').toLowerCase().trim();
        const durationValue = Number(record.call_duration || 0);

        const isDial = eventTypeValue === 'dial';
        const isReach = eventTypeValue === 'reach'
          || eventTypeValue === 'instant_presentation'
          || (eventTypeValue === 'dial' && (reachedDispositions.has(dispositionValue) || durationValue > 55));
        const isBooked = eventTypeValue === 'booked'
          || eventTypeValue === 'instant_presentation'
          // Backward-compatible fix: historical rows sometimes stored booked as dial+disposition.
          || (eventTypeValue === 'dial' && bookedDispositions.has(dispositionValue));

        if (isDial) stats.todayStats.dialed++;
        if (isReach) stats.todayStats.reached++;
        if (isBooked) stats.todayStats.booked++;
      });
      
      // Convert to array format matching Live Call Board agents endpoint
      const agents = Array.from(agentStatsMap.values()).map(stat => ({
        email: stat.agentEmail,
        todayStats: stat.todayStats,
        _metrics: {
          totalRecords: stat.totalRecords,
          dateRange: {
            start: queryStart.toISOString(),
            end: queryEnd.toISOString()
          }
        }
      }));
      
      // Calculate totals (matching Live Call Board stats endpoint)
      const totalDials = Array.from(agentStatsMap.values()).reduce((sum, s) => sum + s.todayStats.dialed, 0);
      const totalReached = Array.from(agentStatsMap.values()).reduce((sum, s) => sum + s.todayStats.reached, 0);
      const totalBooked = Array.from(agentStatsMap.values()).reduce((sum, s) => sum + s.todayStats.booked, 0);
      
      const response: any = {
        success: true,
        dateRange: {
          start: queryStart.toISOString(),
          end: queryEnd.toISOString(),
          description: startDate || endDate ? 'Custom range' : `5 AM - 9 PM PST on ${year}-${month+1}-${day}`
        },
        totals: {
          totalDials,
          totalReached,
          totalBooked,
          totalAgents: agents.length,
          totalRecords: count || 0
        },
        agents: agents,
        filters: {
          agentEmail: agentEmail || 'all',
          eventType: eventType || 'all',
          startDate: queryStart.toISOString(),
          endDate: queryEnd.toISOString()
        }
      };
      
      // Include raw data if requested
      if (includeRawData === 'true') {
        response.rawData = metricsData || [];
      }
      
      res.json(response);
    } catch (error: any) {
      console.error('❌ Error in /api/agent-dial-metrics:', error);
      res.status(500).json({ error: 'Failed to fetch agent dial metrics', details: error.message });
    }
  });

