      const customStartDate = req.query.startDate as string | undefined;
      const customEndDate = req.query.endDate as string | undefined;
      
      // CRITICAL: Calculate date range FIRST, then include it in cache key to prevent stale data
      const { start: dateStart, end: dateEnd } = getDateRangeForTimePeriod(
        timePeriodValue as 'day' | 'week' | 'month' | 'realtime' | 'custom',
        customStartDate,
        customEndDate
      );
      
      // CRITICAL: Log both UTC and EST times to verify conversion is correct
      // NOTE: No cache - using pre-aggregated live_call_boardt table for instant queries
      console.log(`📅 Stats endpoint date range (${timePeriodValue}):`);
      console.log(`   UTC: ${dateStart.toISOString()} to ${dateEnd.toISOString()}`);
      console.log(`   EST: ${dateStart.toLocaleString('en-US', { timeZone: 'America/New_York' })} to ${dateEnd.toLocaleString('en-US', { timeZone: 'America/New_York' })}`);
      console.log(`   EST Date: ${dateStart.toLocaleDateString('en-US', { timeZone: 'America/New_York' })} to ${dateEnd.toLocaleDateString('en-US', { timeZone: 'America/New_York' })}`);
      if (!supabaseAdmin) {
        console.error('❌ supabaseAdmin is not initialized!');
        return res.status(500).json({ error: 'Database not initialized' });
      }
      
      // Sysops see ALL data (online, on-call, connects, etc.); same list as checkMgaRgaAccess.
      const isSysOp = !!userEmail && LIVE_CALL_BOARD_SYSOP_EMAILS.includes(userEmail.toLowerCase().trim());
      
