  app.post("/api/admin/reset-pending-leads", async (req, res) => {
    try {
      console.log('🔄 ADMIN: Resetting all agents to max 300 pending leads...');
      
      // Get all agents with assigned leads
      const { data: agents, error: agentsError } = await masterleadClient.from('masterlead')
        .select('cn_email')
        .not('cn_email', 'is', null)
        .in('cnresolution', ['pending', null]);

      if (agentsError) throw agentsError;

      // Get unique agent emails
      const uniqueAgents = [...new Set(agents.map(a => a.cn_email))];
      console.log(`👥 Found ${uniqueAgents.length} agents with pending leads`);

      let totalUnassigned = 0;
      let agentsProcessed = 0;

      for (const agentEmail of uniqueAgents) {
        // Count their current callable leads - EXCLUDING leads outside timezone restriction
        const currentPending = await countCallableLeads(supabaseAdmin, agentEmail);

        if (currentPending > 300) {
          const toUnassign = currentPending - 300;
          console.log(`📋 ${agentEmail}: ${currentPending} pending → Unassigning ${toUnassign} leads`);

          // Get the excess leads (oldest first) - ONLY pending, called, null, blank
          // CRITICAL: Exclude TaalkResolve=true leads (frozen leads)
          const { data: excessLeads } = await masterleadClient.from('masterlead')
            .select('id, currently_calling')
            .eq('cn_email', agentEmail)
            .or('TaalkResolve.is.null,TaalkResolve.eq.false')  // Exclude TaalkResolve=true leads (frozen)
            .or('cnresolution.is.null,cnresolution.eq.pending,cnresolution.eq.called,cnresolution.eq.')
            .eq('dnc', false)
            .or('currently_calling.is.null,currently_calling.eq.false') // NEVER touch leads being called
            .order('assigned_date', { ascending: true, nullsFirst: true })
            .limit(toUnassign);

          if (excessLeads && excessLeads.length > 0) {
            // Unassign them - Reset cnresolution back to pending
            const { error: unassignError } = await masterleadClient.from('masterlead')
              .update({
                previous_cn_email: agentEmail,
                last_assigned_date: new Date().toISOString(),
                cn_email: null,
                assigned_date: null,
                cnresolution: 'pending' // Reset back to pending when unassigning
              })
              .in('id', excessLeads.map(l => l.id));

            if (unassignError) throw unassignError;

            totalUnassigned += excessLeads.length;
            agentsProcessed++;
          }
        }
      }

      console.log(`✅ Reset complete: ${totalUnassigned} leads unassigned from ${agentsProcessed} agents`);
      res.json({
        success: true,
        agentsProcessed,
        totalUnassigned
      });
    } catch (error) {
      console.error('❌ Error resetting pending leads:', error);
      res.status(500).json({ error: 'Failed to reset pending leads' });
    }
  });

  // Get user's team role and MGAs they manage (for RGA)
  app.get("/api/live-call-board/user-team-info", async (req, res) => {
    try {
      const userEmail = req.query.email as string;
      if (!userEmail) {
        return res.status(400).json({ error: 'Email required' });
      }

      // Get user's associate_id from customers table
      const { data: userData } = await supabaseAdmin
        ?.from('customers')
        .select('associate_id, first_name, last_name')
        .eq('company_email', userEmail.toLowerCase())
        .maybeSingle();

      if (!userData) {
        return res.json({ role: null, mgaAssociateId: null, managedMGAs: [] });
      }

      // Check if this user is an MGA by seeing if any agents have them as MGA
      const { data: asMGA } = await supabaseAdmin
        ?.from('agent_hierarchy')
        .select('agent_associate_id')
        .eq('mga_associate_id', userData.associate_id)
        .limit(1);

      // Check if this user is an RGA by seeing if any agents have them as RGA
      const { data: asRGA } = await supabaseAdmin
        ?.from('agent_hierarchy')
        .select('agent_associate_id')
        .eq('rga_associate_id', userData.associate_id)
        .limit(1);

      const isMGA = asMGA && asMGA.length > 0;
      const isRGA = asRGA && asRGA.length > 0;

      if (!isMGA && !isRGA) {
        // Regular agent - return null
        return res.json({ role: null, mgaAssociateId: null, managedMGAs: [] });
      }

      const role = (isMGA && isRGA) ? 'BOTH' : (isMGA ? 'MGA' : 'RGA');
      const userRole = {
        associate_id: userData.associate_id,
        name: `${userData.first_name} ${userData.last_name}`.toUpperCase(),
        role,
        email: userEmail
      };

      let managedMGAs: any[] = [];

      // If user is an RGA, get all MGAs they manage
      if (userRole.role === 'RGA' || userRole.role === 'BOTH') {
        // Get all agents under this RGA, then find their unique MGAs
        const { data: agents } = await supabaseAdmin
          ?.from('agent_hierarchy')
          .select('mga_associate_id, mga_name')
          .eq('rga_associate_id', userRole.associate_id)
          .not('mga_associate_id', 'is', null);

        if (agents && agents.length > 0) {
          // Get unique MGAs
          const uniqueMGAs = new Map();
          agents.forEach(agent => {
            if (agent.mga_associate_id && agent.mga_name) {
              uniqueMGAs.set(agent.mga_associate_id, {
                associate_id: agent.mga_associate_id,
                name: agent.mga_name
              });
            }
          });
          managedMGAs = Array.from(uniqueMGAs.values());
        }
      }

      res.json({
        role: userRole.role,
        mgaAssociateId: userRole.role === 'MGA' || userRole.role === 'BOTH' ? userRole.associate_id : null,
        managedMGAs: managedMGAs
      });
    } catch (error) {
      console.error('❌ Error fetching user team info:', error);
      res.status(500).json({ error: 'Failed to fetch user team info' });
    }
  });

  // Get agent's licensed states
