  // Check user's credit status and VDP status
  // Credit status cache — 15s TTL per agent (credits rarely change mid-session)
  const _creditStatusCache = new Map<string, { expires: number; payload: any }>();
  const CREDIT_STATUS_TTL = 15_000;

  app.get("/api/user/credit-status", async (req, res) => {
    try {
      const userEmail = (req.query.email as string)?.toLowerCase()?.trim();
      if (!userEmail) return res.status(400).json({ error: 'Email required' });

      // Serve from cache if fresh
      const cached = _creditStatusCache.get(userEmail);
      if (cached && Date.now() < cached.expires) {
        return res.json(cached.payload);
      }

      // Fetch both in parallel
      const [creditRes, customerRes] = await Promise.all([
        supabaseAdmin?.from('user_credits').select('credits_remaining').eq('email', userEmail).maybeSingle(),
        supabaseAdmin?.from('customers').select('VDPACTIVE').eq('company_email', userEmail).maybeSingle(),
      ]);

      const creditsRemaining = (creditRes?.data as any)?.credits_remaining || 0;
      const vdpActive = (customerRes?.data as any)?.VDPACTIVE === 'ACTIVE';
      const vdpDisabledDueToCredits = !vdpActive && creditsRemaining < 0;

      const payload = { credits_remaining: creditsRemaining, vdpActive, vdpDisabledDueToCredits };
      _creditStatusCache.set(userEmail, { expires: Date.now() + CREDIT_STATUS_TTL, payload });
      res.json(payload);
    } catch (error) {
      console.error('❌ Error checking credit status:', error);
      res.status(500).json({ error: 'Failed to check credit status' });
    }
  });
  
