  // Get list of MGAs/RGAs for team filtering (merge directory + agent_hierarchy so no MGAs are missing)
  app.get("/api/live-call-board/teams", checkMgaRgaAccess, async (req, res) => {
    try {
      console.log('👥 Fetching MGA/RGA directory for team filtering...');
      
      const teamsMap = new Map<number, { associate_id: number; name: string; role: string; email: string | null }>();

      // 1) Load from mga_rga_directory when available
      const { data: dirTeams, error: dirError } = await supabaseAdmin
        .from('mga_rga_directory')
        .select('associate_id, name, role, email')
        .order('name', { ascending: true });
      
      if (!dirError && dirTeams?.length) {
        dirTeams.forEach((row: any) => {
          if (row.associate_id != null && row.name) {
            teamsMap.set(Number(row.associate_id), {
              associate_id: Number(row.associate_id),
              name: String(row.name).trim(),
              role: row.role === 'BOTH' ? 'BOTH' : row.role === 'RGA' ? 'RGA' : 'MGA',
              email: row.email || null
            });
          }
        });
      }

      // 2) Always merge in agent_hierarchy so MGAs/RGAs not in directory (e.g. Julia Washington) still appear
      const { data: mgaData } = await supabaseAdmin
        .from('agent_hierarchy')
        .select('mga_associate_id, mga_name')
        .not('mga_associate_id', 'is', null)
        .not('mga_name', 'is', null);
      const { data: rgaData } = await supabaseAdmin
        .from('agent_hierarchy')
        .select('rga_associate_id, rga_name')
        .not('rga_associate_id', 'is', null)
        .not('rga_name', 'is', null);

      [mgaData, rgaData].forEach((rows, idx) => {
        const isMga = idx === 0;
        const idKey = isMga ? 'mga_associate_id' : 'rga_associate_id';
        const nameKey = isMga ? 'mga_name' : 'rga_name';
        (rows || []).forEach((row: any) => {
          const id = Number(row[idKey]);
          const name = String(row[nameKey] || '').trim();
          if (!id || !name) return;
          const existing = teamsMap.get(id);
          if (existing) {
            if (existing.role !== 'BOTH' && ((isMga && existing.role === 'RGA') || (!isMga && existing.role === 'MGA'))) {
              existing.role = 'BOTH';
            }
          } else {
            teamsMap.set(id, {
              associate_id: id,
              name,
              role: isMga ? 'MGA' : 'RGA',
              email: null
            });
          }
        });
      });

      const teams = Array.from(teamsMap.values()).sort((a, b) => a.name.localeCompare(b.name));
      console.log(`✅ Returning ${teams.length} teams (${teams.filter(t => t.role === 'MGA' || t.role === 'BOTH').length} MGA, ${teams.filter(t => t.role === 'RGA' || t.role === 'BOTH').length} RGA)`);
      res.json(teams);
    } catch (error) {
      console.error('❌ Error fetching teams:', error);
      res.status(500).json({ error: 'Failed to fetch teams' });
    }
  });

  // Get active outbound calls from Call Connector Pro
